insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Path of Daggers', 'Robert Jordan', '0736645381', 'https://assets.hardcover.app/edition/30930988/4ce7c6ab-8d3c-4482-86e8-c84228a75c03.png', 'The Seanchan invasion force is in possession of Ebou Dar. Nynaeve, Elayne, and Aviendha head for Caemlyn and Elayne''s rightful throne, but on the way they discover an enemy much worse than the Seanchan.

In Illian, Rand vows to throw the Seanchan back as he did once before. But signs of madness are appearing among the Asha''man.

In Ghealdan, Perrin faces the intrigues of Whitecloaks, Seanchan invaders, the scattered Shaido Aiel, and the Prophet himself. Perrin''s beloved wife, Faile, may pay with her life, and Perrin himself may have to destroy his soul to save her.

Meanwhile the rebel Aes Sedai under their young Amyrlin, Egwene al''Vere, face an army that intends to keep them away from the White Tower. But Egwene is determined to unseat the usurper Elaida and reunite the Aes Sedai. She does not yet understand the price that others—and she herself—will pay.', 608, null, 1998, 205, (select id from series where hardcover_id = 1097), 8) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Storm of Swords', 'George R.R. Martin', '9877251574', 'https://assets.hardcover.app/book_mappings/7332349/5249dbcbc118ae4ea68c37295c8386f96c341c95.jpeg', 'The Seven Kingdoms are torn by strife as the three surviving contenders for the throne continue their struggle for power, Robb Stark defends his fledgling kingdom from the ravaging Greyjoys, Winterfell lies in ruins, Jon Snow confronts an escalating threat from behind the Wall, and Danerys Stormborn and her dragon allies continue to grow in power. Here is the third volume in George R. Martin''s magnificent cycle of novels that includes A Game of Thrones and A Clash of Kings. As a whole, this series comprises a genuine masterpiece of modern fantasy, bringing together the best the genre has to offer. Magic, mystery, intrigue, romance, and adventure fill these pages and transport us to a world unlike any we have ever experienced. Already hailed as a classic, George R. Martin''s stunning series is destined to stand as one of the great achievements of imaginative fiction. A Storm of Swords Of the five contenders for power, one is dead, another in disfavor, and still the wars rage as violently as ever, as alliances are made and broken. Joffrey, of House Lannister, sits on the Iron Throne, the uneasy ruler of the land of the Seven Kingdoms. His most bitter rival, Lord Stannis, stands defeated and disgraced, the victim of the jealous sorceress who holds him in her evil thrall. But young Robb, of House Stark, still rules the North from the fortress of Riverrun. Robb plots against his despised Lannister enemies, even as they hold his sister hostage at King''s Landing, the seat of the Iron Throne. Meanwhile, making her way across a blood-drenched continent is the exiled queen, Daenerys, mistress of the only three dragons still left in the world. But as opposing forces maneuver for the final titanic showdown, an army of barbaric wildlings arrives from the outermost line of civilization. In their vanguard is a horde of mythical Others--a supernatural army of the living dead whose animated corpses are unstoppable. As the future of the land hangs in the balance, no one will rest until the Seven Kingdoms have exploded in a veritable storm of swords.', 992, 2852, 2000, 236, (select id from series where hardcover_id = 981), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Game of Thrones', 'George R.R. Martin', '0553386794', 'https://assets.hardcover.app/edition/12841472/a63e7ea1-9064-4eb8-afb4-5372db40aed2.jpg', 'As Warden of the north, Lord Eddard Stark counts it a curse when King Robert bestows on him the office of the Hand. His honour weighs him down at court where a true man does what he will, not what he must ...and a dead enemy is a thing of beauty. 

The old gods have no power in the south, Stark''s family is split and there is treachery at court. Worse, the vengeance-mad heir of the deposed Dragon King has grown to maturity in exile in the Free Cities. He claims the Iron Throne.', 694, 2026, 1996, 644, (select id from series where hardcover_id = 981), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Breaking Dawn', 'Stephenie Meyer', '5170584687', 'https://assets.hardcover.app/edition/22419642/5253aa33134dfaf746b479bcdb37161c5f05a98f.jpeg', 'When you loved the one who was killing you, it left you no options. How could you run, how could you fight, when doing so would hurt that beloved one? If your life was all you had to give, how could you not give it? If it was someone you truly loved?

To be irrevocably in love with a vampire is both fantasy and nightmare woven into a dangerously heightened reality for Bella Swan. Pulled in one direction by her intense passion for Edward Cullen, and in another by her profound connection to werewolf Jacob Black, a tumultuous year of temptation, loss, and strife have led her to the ultimate turning point. Her imminent choice to either join the dark but seductive world of immortals or to pursue a fully human life has become the thread from which the fates of two tribes hangs.

This astonishing, breathlessly anticipated fourth book of The Twilight Saga illuminates the secrets and mysteries of this heart electrifying romantic epic.
 
“You too might fall in love with its suspense and moving sensitivity" (The Daily News Tribune)', 756, null, 2008, 654, (select id from series where hardcover_id = 5451), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('American Gods', 'Neil Gaiman', '0613913388', 'https://assets.hardcover.app/edition/12291130/1bb87eb105094cd7ae9eda1376da6939cfa6ad5f.jpeg', 'Released from prison, Shadow finds his world turned upside down. His wife has been killed; a stranger offers him a job and Shadow, with nothing to lose, accepts. But a storm is coming. Beneath the placid surface of everyday life, a war is being fought – and the prize is the very soul of America.

An inspired combination of mythology, adventure, and illusion, American Gods is a dark and kaleidoscopic journey deep into myth and across an America at once eerily familiar and utterly alien. It is, quite simply, a contemporary masterpiece.', 635, 1179, 2001, 657, (select id from series where hardcover_id = 1074), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Andromeda Strain', 'Michael Crichton', '0606141545', 'https://assets.hardcover.app/edition/23900636/615c83dbaa055f9294e3edd428f843f809272230.jpeg', 'The Andromeda Strain is a 1969 techno-thriller novel by Michael Crichton, his first novel under his own name and his sixth novel overall. It is written as a report documenting the efforts of a team of scientists investigating the outbreak of a deadly extraterrestrial microorganism in New Mexico. The Andromeda Strain appeared in the New York Times Best Seller list, establishing Michael Crichton as a genre writer.


----------
This work also contained in:

 - [The Andromeda Strain / Terminal Man](https://openlibrary.org/works/OL46874W)
 - [The Great Train Robbery / The Andromeda Strain](https://openlibrary.org/works/OL24159635W)
 - [Rising Sun / The Andromeda Strain / Binary](https://openlibrary.org/works/OL23658811W)', 331, null, 1969, 704, (select id from series where hardcover_id = 71862), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Raven Boys', 'Maggie Stiefvater', '0606320288', 'https://assets.hardcover.app/edition/30399794/4e1d3831-3a27-44cb-b4cc-0b360b807960.jpg', 'Every year, Blue Sargent stands next to her clairvoyant mother as the soon-to-be dead walk past. Blue never sees them--until this year, when a boy emerges from the dark and speaks to her. His name is Gansey, a rich student at Aglionby, the local private school. Blue has a policy of staying away from Aglionby boys. Known as Raven Boys, they can only mean trouble. But Blue is drawn to Gansey, in a way she can''t entirely explain. He is on a quest that has encompassed three other Raven Boys: Adam, the scholarship student who resents the privilege around him; Ronan, the fierce soul whose emotions range from anger to despair; and Noah, the taciturn watcher who notices many things but says very little. For as long as she can remember, Blue has been warned that she will cause her true love to die. She doesn''t believe in true love, and never thought this would be a problem. But as her life becomes caught up in the strange and sinister world of the Raven Boys, she''s not so sure anymore.', 468, null, 2012, 3288, (select id from series where hardcover_id = 3226), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rendezvous with Rama', 'Arthur C. Clarke', '8419260053', 'https://assets.hardcover.app/edition/20518146/c49aa24a1b0de1b88192d9bb59053ee7dd2af4fc.jpeg', 'Rama was first picked up by radar as asteroid 31/439 while still outside the orbit of Jupiter; and it was only when it was realised that it had a diameter of some twelve miles and that its course might completely upset the delicate balance of the solar system that scientists became at first intrigued and then worried. A space-probe was launched on a high-speed trajectory to intercept the mysterious intruder and to photograph it. Seven weeks after the probe’s launch, the pictures it transmitted brought to a halt the activities of most of mankind…', 288, null, 1973, 4720, (select id from series where hardcover_id = 1135), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red Sister', 'Mark Lawrence', '8071976954', 'https://assets.hardcover.app/edition/30407188/eb7eb0f0252bbe2507cef3c8f486e7e9b3ca6599.jpeg', '“I was born for killing – the gods made me to ruin”

At the Convent of Sweet Mercy young girls are raised to be killers. In a few the old bloods show, gifting talents rarely seen since the tribes beached their ships on Abeth. Sweet Mercy hones its novices’ skills to deadly effect: it takes ten years to educate a Red Sister in the ways of blade and fist.

But even the mistresses of sword and shadow don’t truly understand what they have purchased when Nona Grey is brought to their halls as a bloodstained child of eight, falsely accused of murder: guilty of worse.', 482, null, 2017, 6153, (select id from series where hardcover_id = 5499), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shōgun', 'James Clavell', '2253032549', 'https://assets.hardcover.app/external_data/925345/fcf14e4ecfc553f27f96cd74b6e27d9c52e25500.jpeg', 'After Englishman John Blackthorne is lost at sea, he awakens in a place few Europeans know of and even fewer have seen--Nippon. Thrust into the closed society that is seventeenth-century Japan, a land where the line between life and death is razor-thin, Blackthorne must negotiate not only a foreign people, with unknown customs and language, but also his own definitions of morality, truth, and freedom. As internal political strife and a clash of cultures lead to seemingly inevitable conflict, Blackthorne''s loyalty and strength of character are tested by both passion and loss, and he is torn between two worlds that will each be forever changed.

Powerful and engrossing, capturing both the rich pageantry and stark realities of life in feudal Japan, Shōgun is a critically acclaimed powerhouse of a book. Heart-stopping, edge-of-your-seat action melds seamlessly with intricate historical detail and raw human emotion. Endlessly compelling, this sweeping saga captivated the world to become not only one of the best-selling novels of all time but also one of the highest-rated television miniseries, as well as inspiring a nationwide surge of interest in the culture of Japan. Shakespearean in both scope and depth, Shōgun is, as the New York Times put it, "...not only something you read--you live it." Provocative, absorbing, and endlessly fascinating, there is only one: Shōgun.', 1125, null, 1975, 6705, (select id from series where hardcover_id = 5500), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Jurassic Park', 'Michael Crichton', '0394588169', 'https://assets.hardcover.app/editions/30401767/7336843016391221-81rBVCDfrgL._AC_UF1000,1000_QL80_.jpg', 'On a remote jungle island, genetic engineers have created a dinosaur game park.

An astonishing technique for recovering and cloning dinosaur DNA has been discovered. Now one of mankind''s most thrilling fantasies has come true and the first dinosaurs that the Earth has seen in the time of man emerge.

But, as always, there is a dark side to the fantasy and after a catastrophe destroys the park''s defence systems, the scientists and tourists are left fighting for survival...

With this masterful cross of science fiction and action-adventure, Michael Crichton created one of the biggest bestsellers of all time, turned by Steven Spielberg into the highest grossing blockbuster ever in 1993.', 448, 910, 1990, 9724, (select id from series where hardcover_id = 5455), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Xenocide', 'Orson Scott Card', '8490196915', 'https://assets.hardcover.app/edition/13717625/f0d7d0c0d2b70f6d072e7798acd6096d9048ec07.jpeg', 'On Lusitania, Ender finds a world where humans and pequeninos and the Hive Queen could all live together. However, Lusitania also harbors the descolada, a virus that kills all humans it infects, but which the pequeninos require in order to become adults. The Starways Congress so fears the effects of the descolada, should it escape from Lusitania, that they have ordered the destruction of the entire planet, and all who live there. With the Fleet on its way, a second xenocide seems inevitable.', 416, null, 1991, 9743, (select id from series where hardcover_id = 1059), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Death Cure', 'James Dashner', '0385738781', 'https://assets.hardcover.app/edition/17097412/f2b1ff99d57b802e812c8ac22e9c86ca36ad8efb.jpeg', 'Thomas knows that Wicked can''t be trusted, but they say the time for lies is over, that they''ve collected all they can from the Trials and now must rely on the Gladers, with full memories restored, to help them with their ultimate mission. It''s up to the Gladers to complete the blueprint for the cure to the Flare with a final voluntary test.
What Wicked doesn''t know is that something''s happened that no Trial or Variable could have foreseen. Thomas has remembered far more than they think. And he knows that he can''t believe a word of what Wicked says.
The time for lies is over. But the truth is more dangerous than Thomas could ever imagine.
Will anyone survive the Death Cure?', 354, null, 2011, 10265, (select id from series where hardcover_id = 1073), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Conjuring of Light', 'V. E. Schwab', '6020637247', 'https://assets.hardcover.app/edition/20773910/35e504459a9d8d7aa196f551babdbfc5ba5307be.jpeg', 'THE BALANCE OF POWER HAS FINALLY TIPPED....
The precarious equilibrium among four Londons has reached its breaking point. Once brimming with the red vivacity of magic, darkness casts a shadow over the Maresh Empire, leaving a space for another London to rise.

WHO WILL CRUMBLE?
Kell—once assumed to be the last surviving Antari—begins to waver under the pressure of competing loyalties. And in the wake of tragedy, can Arnes survive?

WHO WILL RISE?
Lila Bard, once a commonplace—but never common—thief, has survived and flourished through a series of magical trials. But now she must learn to control the magic, before it bleeds her dry. Meanwhile, the disgraced Captain Alucard Emery of the Night Spire collects his crew, attempting a race against time to acquire the impossible.

WHO WILL TAKE CONTROL?
And an ancient enemy returns to claim a crown while a fallen hero tries to save a world in decay.', 625, null, 2017, 10411, (select id from series where hardcover_id = 1040), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Goblin Emperor', 'Katherine Addison', '178108730X', 'https://assets.hardcover.app/edition/30400526/fa9ce571bfb5d2b8a1eb2ec6bf8de2ccb9071642.jpeg', 'The youngest, half-goblin son of the Emperor has lived his entire life in exile, distant from the Imperial Court and the deadly intrigue that suffuses it. But when his father and three sons in line for the throne are killed in an "accident," he has no choice but to take his place as the only surviving rightful heir.

Entirely unschooled in the art of court politics, he has no friends, no advisors, and the sure knowledge that whoever assassinated his father and brothers could make an attempt on his life at any moment.

Surrounded by sycophants eager to curry favor with the naïve new emperor, and overwhelmed by the burdens of his new life, he can trust nobody. Amid the swirl of plots to depose him, offers of arranged marriages, and the specter of the unknown conspirators who lurk in the shadows, he must quickly adjust to life as the Goblin Emperor. All the while, he is alone, and trying to find even a single friend... and hoping for the possibility of romance, yet also vigilant against the unseen enemies that threaten him, lest he lose his throne – or his life.', 447, null, 2014, 11855, (select id from series where hardcover_id = 122042), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Glass Castle', 'Jeannette Walls', '1419341049', 'https://assets.hardcover.app/book_mappings/7332926/f737c395fb5693a0ee8540f086885768f1f01df9.jpeg', 'The Glass Castle is a remarkable memoir of resilience and redemption, and a revelatory look into a family at once deeply dysfunctional and uniquely vibrant. When sober, Jeannette''s brilliant and charismatic father captured his children''s imagination, teaching them physics, geology, and how to embrace life fearlessly. But when he drank, he was dishonest and destructive. Her mother was a free spirit who abhorred the idea of domesticity and didn''t want the responsibility of raising a family.
The Walls children learned to take care of themselves. They fed, clothed, and protected one another, and eventually found their way to New York. Their parents followed them, choosing to be homeless even as their children prospered.
The Glass Castle is truly astonishing -- a memoir permeated by the intense love of a peculiar but loyal family.', 304, null, 2005, 12666, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Silmarillion', 'J.R.R. Tolkien, Christopher Tolkien', '081242302X', 'https://assets.hardcover.app/edition/29869537/8fe7967e-b111-4f19-a0c6-6b846304a3a6.jpg', 'The Silmarillion is an account of the Elder Days, of the First Age of Tolkien’s world. It is the ancient drama to which the characters in The Lord of the Rings look back, and in whose events some of them such as Elrond and Galadriel took part. The tales of The Silmarillion are set in an age when Morgoth, the first Dark Lord, dwelt in Middle-Earth, and the High Elves made war upon him for the recovery of the Silmarils, the jewels containing the pure light of Valinor.

Included in the book are several shorter works. The Ainulindale is a myth of the Creation and in the Valaquenta the nature and powers of each of the gods is described. The Akallabeth recounts the downfall of the great island kingdom of Númenor at the end of the Second Age and Of the Rings of Power tells of the great events at the end of the Third Age, as narrated in The Lord of the Rings.', 481, null, 1977, 16865, (select id from series where hardcover_id = 127396), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Player of Games', 'Iain M. Banks', '1857231465', 'https://assets.hardcover.app/edition/8982551/0272147c8b36ac34a953be0d80997e8e3cbe6e55.jpeg', 'The Culture - a human/machine symbiotic society - has thrown up many great Game Players, and one of the greatest is Gurgeh. Jernau Morat Gurgeh. The Player of Games. Master of every board, computer, and strategy.
Bored with success, Gurgeh travels to the Empire of Azad, cruel and incredibly wealthy, to try their fabulous game ... a game so complex, so like life itself, that the winner becomes emperor. Mocked, blackmailed, almost murdered, Gurgeh accepts the game, and with it the challenge of his life - a very possibly his death.', 309, null, 1988, 20256, (select id from series where hardcover_id = 1102), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gideon the Ninth', 'Tamsyn Muir', '8417347976', 'https://assets.hardcover.app/book_mappings/7332376/5bf3c29956bfa33ff0829ae4a136dd7c1e006543.jpeg', 'The Emperor needs necromancers.

The Ninth Necromancer needs a swordswoman.

Gideon has a sword, some dirty magazines, and no more time for undead nonsense.

Tamsyn Muir’s Gideon the Ninth unveils a solar system of swordplay, cut-throat politics, and lesbian necromancers. Her characters leap off the page, as skillfully animated as arcane revenants. The result is a heart-pounding epic science fantasy.

Brought up by unfriendly, ossifying nuns, ancient retainers, and countless skeletons, Gideon is ready to abandon a life of servitude and an afterlife as a reanimated corpse. She packs up her sword, her shoes, and her dirty magazines, and prepares to launch her daring escape. But her childhood nemesis won’t set her free without a service.

Harrowhark Nonagesimus, Reverend Daughter of the Ninth House and bone witch extraordinaire, has been summoned into action. The Emperor has invited the heirs to each of his loyal Houses to a deadly trial of wits and skill. If Harrowhark succeeds she will be become an immortal, all-powerful servant of the Resurrection, but no necromancer can ascend without their cavalier. Without Gideon’s sword, Harrow will fail, and the Ninth House will die.

Of course, some things are better left dead.', 448, 1010, 2019, 20941, (select id from series where hardcover_id = 2759), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Insurgent', 'Veronica Roth', '0007442920', 'https://assets.hardcover.app/edition/30404226/581908d44c3c82891ff1b1d0a9038e477bdc89d2.jpeg', 'One choice can transform you - or it can destroy you. But every choice has consequences, and as unrest surges in the factions all around her, Tris Prior must continue trying to save those she loves - and herself - while grappling with haunting questions of grief and forgiveness, identity and loyalty, politics and love.

Tris''s initiation day should have been marked by celebration and victory with her chosen faction; instead, the day ended with unspeakable horrors. War now looms as conflict between the factions and their ideologies grows. And in times of war, sides must be chosen, secrets will emerge, and choices will become even more irrevocable - and even more powerful. Transformed by her own decisions but also by haunting grief and guilt, radical new discoveries, and shifting relationships, Tris must fully embrace her Divergence, even if she does not know what she may lose by doing so.', 525, null, 2012, 20970, (select id from series where hardcover_id = 1489), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Troop', 'Nick Cutter', '1529452619', 'https://assets.hardcover.app/edition/30738194/868b2699-f6bc-4a8b-9164-badcc1d7e051.jpg', 'Once every year, Scoutmaster Tim Riggs leads a troop of boys into the Canadian wilderness for a weekend camping trip—a tradition as comforting and reliable as a good ghost story around a roaring bonfire.

But when an unexpected intruder stumbles upon their campsite—shockingly thin, disturbingly pale, and voraciously hungry—Tim and the boys are exposed to something far more frightening than any tale of terror. The human carrier of a bioengineered nightmare.

A horror that spreads faster than fear. A harrowing struggle for survival with no escape from the elements, the infected…or one another.', 528, null, 2014, 23801, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ready Player One', 'Ernest Cline', '8466663061', 'https://assets.hardcover.app/edition/31561015/c72731ad-c2bc-49c8-a087-66605cead82f.jpg', 'In the year 2045, reality is an ugly place. The only time Wade Watts really feels alive is when he’s jacked into the OASIS, a vast virtual world where most of humanity spends their days.

When the eccentric creator of the OASIS dies, he leaves behind a series of fiendish puzzles, based on his obsession with the pop culture of decades past. Whoever is first to solve them will inherit his vast fortune—and control of the OASIS itself. 

Then Wade cracks the first clue. Suddenly he’s beset by rivals who’ll kill to take this prize. The race is on—and the only way to survive is to win.
', 387, 940, 2008, 26363, (select id from series where hardcover_id = 1032), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Frankenstein', 'Mary Shelley, Siv Jansson', '9798363212567', 'https://assets.hardcover.app/edition/18780509/e353c2cafc8293db69a5771436ffc8a8779c26ab.jpeg', 'Mary Shelley (then Godwin) and Percy Bysshe Shelley were visiting their friend Lord Byron in Geneva one rainy summer. With the weather against them, they decided to spend their time writing ghost stories for each other. Frankenstein is Mary Shelley’s submission to their contest, later published anonymously in 1818.

Victor Frankenstein, a strange but brilliant scientist, discovers a method of imparting life to inanimate matter. The Monster is thus born: a hideous, 8-foot-tall creature of muscle, speed, and intellect. Frankenstein’s rejection of his appalling creation sends it into a spiral of despair, and Frankenstein’s life is never the same. ', 353, null, 1818, 28722, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Divine Comedy', 'Dante Alighieri, Allen Mandelbaum, Eugenio Montale, Peter Armour', '8420682888', 'https://assets.hardcover.app/edition/13043033/2aa47f6a47cb028dd5fafac0f5b8ffd81dd01d79.jpeg', 'Belonging in the immortal company of the great works of literature, Dante Alighieri’s poetic masterpiece, *The Divine Comedy* (Italian: *Divina Commedia),* is a moving human drama, an unforgettable visionary journey through the infinite torment of Hell, up the arduous slopes of Purgatory, and on to the glorious realm of Paradise—the sphere of universal harmony and eternal salvation.', 798, null, 1304, 30606, (select id from series where hardcover_id = 5935), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Colour Of Magic', 'Terry Pratchett', '0552157686', 'https://assets.hardcover.app/edition/30598805/04845bcc-a382-4cdc-9b69-30c21676392b.jpg', 'Somewhere on the frontier between thought and reality exists the Discworld, a parallel time and place which might sound and smell very much like our own, but which looks completely different. It plays by different rules. Certainly it refuses to succumb to the quaint notion that universes are ruled by pure logic and the harmony of numbers.
 
But just because the Disc is different doesn''t mean that some things don''t stay the same. Its very existence is about to be threatened by a strange new blight: the arrival of the first tourist, upon whose survival rests the peace and prosperity of the land. But if the person charged with maintaining that survival in the face of robbers, mercenaries and, well, Death is a spectacularly inept wizard, a little logic might turn out to be a very good idea.', 287, 478, 1983, 34693, (select id from series where hardcover_id = 1018), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Siege and Storm', 'Leigh Bardugo', '6098105340', 'https://assets.hardcover.app/edition/19109040/f0ab78034e071952650564bd231e8b410fe0174e.jpeg', 'Enter the Grishaverse with Book Two of the Shadow and Bone Trilogy by the #1 New York Times–bestselling author of Six of Crows and Crooked Kingdom.

Soldier. Summoner. Saint. Alina Starkov’s power has grown, but not without a price. She is the Sun Summoner―hunted across the True Sea, haunted by the lives she took on the Shadow Fold. But she and Mal can’t outrun their enemies for long.

The Darkling is more determined than ever to claim Alina’s magic and use it to take the Ravkan throne. With nowhere else to turn, Alina enlists the help of an infamous privateer and sets out to lead the Grisha army.

But as the truth of Alina''s destiny unfolds, she slips deeper into the Darkling’s deadly game of forbidden magic, and further away from her humanity. To save her country, Alina will have to choose between her power and the love she thought would always be her shelter. No victory can come without sacrifice―and only she can face the oncoming storm.', 435, null, 2013, 35941, (select id from series where hardcover_id = 1067), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Road', 'Cormac McCarthy', '6554481362', 'https://assets.hardcover.app/editions/642392/7620614454245640-cormacmcarthytheroad.jpg', 'A father and his son walk alone through burned America. Nothing moves in the ravaged landscape save the ash on the wind. It is cold enough to crack stones, and when the snow falls it is gray. The sky is dark. Their destination is the coast, although they don’t know what, if anything, awaits them there. They have nothing; just a pistol to defend themselves against the lawless bands that stalk the road, the clothes they are wearing, a cart of scavenged food—and each other.

The Road is the profoundly moving story of a journey. It boldly imagines a future in which no hope remains, but in which the father and his son, “each the other’s world entire,” are sustained by love. Awesome in the totality of its vision, it is an unflinching meditation on the worst and the best that we are capable of: ultimate destructiveness, desperate tenacity, and the tenderness that keeps two people alive in the face of total devastation.', 287, 399, 2006, 36087, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Tombs of Atuan', 'Ursula K. Le Guin', '0575033258', 'https://assets.hardcover.app/external_data/31545961/cc84f385a6a8c25807c98a5f74e8985a06518d53.jpeg', 'A wizard enters the underground domain of Ahra, high priestess of the Powers of the Earth, in an attempt to steal her palace''s greatest treasure.', 208, null, 1970, 37746, (select id from series where hardcover_id = 1170), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Throne of Glass', 'Sarah J. Maas', '3423760788', 'https://assets.hardcover.app/edition/30501042/9052e867e43511a1f2ec7dc8ce0e33d01faf7c6e.jpeg', 'In a land without magic, an assassin is summoned to the castle. She has no love for the vicious king who rules from his throne of glass, but she has not come to kill him. She has come to win her freedom. If she defeats twenty-three murderers, thieves, and warriors in a competition, she will be released from prison to serve as the King’s Champion.

Her name is Celaena Sardothien.

The Crown Prince will provoke her. The Captain of the Guard will protect her. And a princess from a faraway country will befriend her. But something rotten dwells in the castle, and it’s there to kill. When her competitors start dying mysteriously, one by one, Celaena’s fight for freedom becomes a fight for survival-and a desperate quest to root out the evil before it destroys her world.

Thrilling and fierce, Throne of Glass is the first book in the #1 New York Times bestselling series that has captivated readers worldwide.', 416, 780, 2012, 39629, (select id from series where hardcover_id = 5509), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Steelheart', 'Brandon Sanderson', '8490197776', 'https://assets.hardcover.app/edition/30431770/4b71c19ade53bbf69f4cff94b82738c6b7910cb9.jpeg', 'Ten years ago, Calamity came. It was a burst in the sky that gave ordinary men and women extraordinary powers. The awed public started calling them Epics. But Epics are no friend of man. With incredible gifts came the desire to rule. And to rule man you must crush his will.

Nobody fights the Epics...nobody but the Reckoners. A shadowy group of ordinary humans, they spend their lives studying Epics, finding their weaknesses, and then assassinating them.

And David wants in. He wants Steelheart — the Epic who is said to be invincible. The Epic who killed David''s father. For years, like the Reckoners, David''s been studying, and planning — and he has something they need. Not an object, but an experience.

He''s seen Steelheart bleed. And he wants revenge.', 386, null, 2013, 39657, (select id from series where hardcover_id = 1038), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foundryside', 'Robert Jackson Bennett', '1786487861', 'https://assets.hardcover.app/external_data/25758405/7b4646df52b608e328e41f8e75739b1d253710a2.jpeg', 'Sancia Grado is a thief, and a damn good one. And her latest target, a heavily guarded warehouse on Tevanne’s docks, is nothing her unique abilities can’t handle.

But unbeknownst to her, Sancia’s been sent to steal an artifact of unimaginable power, an object that could revolutionize the magical technology known as scriving. The Merchant Houses who control this magic--the art of using coded commands to imbue everyday objects with sentience--have already used it to transform Tevanne into a vast, remorseless capitalist machine. But if they can unlock the artifact’s secrets, they will rewrite the world itself to suit their aims.

Now someone in those Houses wants Sancia dead, and the artifact for themselves. And in the city of Tevanne, there’s nobody with the power to stop them.

To have a chance at surviving—and at stopping the deadly transformation that’s under way—Sancia will have to marshal unlikely allies, learn to harness the artifact’s power for herself, and undergo her own transformation, one that will turn her into something she could never have imagined.', 512, null, 2018, 41398, (select id from series where hardcover_id = 4975), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foundation''s Edge', 'Isaac Asimov', '0593159985', 'https://assets.hardcover.app/edition/30550458/c52ff1eb-8fc9-47fd-8547-4a973834ed91.jpg', 'After the defeat of the Mule by the Second Foundation, Terminus enjoys a period of prosperity and stability which is publicly attributed to the Seldon Plan, but which some feel is the work of the Second Foundation.  A search is begun to determine if the Second Foundation still exists.  Meanwhile, the Second Foundation finds that there is evidence of an independent force acting against the Mule to protect the Seldon Plan.  A search is launched to determine what this force is and if it is a threat.  The end result is a search for Earth (Terminus being the last planet settled by the galactic empire and Earth being the metaphoric opposite of first human planet settled).  A final three way confrontation results in a fateful decision and an open question.', 416, null, 1982, 46423, (select id from series where hardcover_id = 5450), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dragon Reborn', 'Robert Jordan', '1429960168', 'https://assets.hardcover.app/edition/31538508/a17f5bf2-58af-4479-8aa0-5438a7e96d51.png', 'Now a major TV series on Prime Video The third novel in the Wheel of Time series - one of the most influential and popular fantasy epics ever published. The Land is One with the Dragon - and the Dragon is One with the Land. The Shadow lies across the Pattern of the Age, and the Dark One has turned all his power against the prison that binds him. If it fails he will escape and nothing will stand in the storm that blows then . . . save the man that was born to battle the darkness: Rand al''Thor, the Dragon Reborn. But to wage his war Rand must find Callandor, ancient Sword of the Dragon . . . and the Forsaken will shatter the world to thwart him. ''Epic in every sense'' Sunday Times ''With the Wheel of Time, Jordan has come to dominate the world that Tolkien began to reveal'' New York Times ''[The] huge ambitious Wheel of Time series helped redefine the genre'' George R. R. Martin ''A fantasy phenomenon'' SFX The Wheel of Time series: Book 1: The Eye of the World Book 2: The Great Hunt Book 3: The Dragon Reborn Book 4: The Shadow Rising Book 5: The Fires of Heaven Book 6: Lord of Chaos Book 7: A Crown of Swords Book 8: The Path of Daggers Book 9: Winter''s Heart Book 10: Crossroads of Twilight Book 11: Knife of Dreams Book 12: The Gathering Storm Book 13: Towers of Midnight Book 14: A Memory of Light Prequel: New Spring Look out for the companion book: The World of Robert Jordan''s The Wheel of Time', 672, null, 1991, 48701, (select id from series where hardcover_id = 1097), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Speaker for the Dead', 'Orson Scott Card', '0812513509', 'https://assets.hardcover.app/edition/30506144/7e4f091e-a5b3-43c7-9197-31a1673404ce.jpeg', 'Ender Wiggin, the young military genius, discovers that a second alien war is inevitable and that he must dismiss his fears to make peace with humanity''s strange new brothers.', 323, null, 1986, 50772, (select id from series where hardcover_id = 1059), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Stranger in a Strange Land', 'Robert A. Heinlein, James Warhola', '0441788386', 'https://assets.hardcover.app/edition/30399191/2197129a-694a-4fa1-be9d-a850ae8196fc.jpg', 'Raised by Martians on Mars, Valentine Michael Smith is a human who has never seen another member of his species. Sent to Earth, he is a stranger who must learn what it is to be a man. But his own beliefs and his powers far exceed the limits of humankind, and as he teaches them about grokking and water-sharing, he also inspires a transformation that will alter Earth’s inhabitants forever...', 530, null, 1961, 52407, (select id from series where hardcover_id = 60565), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Deception Point', 'Dan Brown', '1416524886', 'https://assets.hardcover.app/editions/194827/9908714625976342.jpg', 'Deception Point is a 2001 mystery-thriller novel by American author Dan Brown. It is Brown''s third novel. It was published by Simon & Schuster.

The novel follows White House intelligence analyst Rachel Sexton''s involvement in corroborating NASA''s discovery of a meteorite that supposedly contains proof of extraterrestrial life, resembling the ALH84001 case. The discovery comes at a time close to the United States presidential election in which her father is running. The discovery will aid the campaign of her employer, the incumbent president of the United States, Zachary Herney, but put her further at odds with her already estranged father, Senator Sedgwick Sexton, a senator who is running for election. Sexton, accompanied by a team of experts, must uncover the authenticity of the meteorite which will either make or break the campaign of President Herney.

Contains:
[Deception Point [1/2]](https://openlibrary.org/works/OL25327019W)
[Deception Point [2/2]](https://openlibrary.org/works/OL30946570W)', 451, null, 2001, 52468, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Royal Assassin', 'Robin Hobb, Stephen Youll, John Howe', '9985314743', 'https://assets.hardcover.app/editions/18512423/6859632616769302.jpg', 'Fitz has survived his first hazardous mission as king’s assassin, but is left little more than a cripple. Battered and bitter, he vows to abandon his oath to King Shrewd, remaining in the distant mountains. But love and events of terrible urgency draw him back to the court at Buckkeep, and into the deadly intrigues of the royal family.

Renewing their vicious attacks on the coast, the Red-Ship Raiders leave burned-out villages and demented victims in their wake. The kingdom is also under assault from within, as treachery threatens the throne of the ailing king. In this time of great danger, the fate of the kingdom may rest in Fitz’s hands—and his role in its salvation may require the ultimate sacrifice.', 675, null, 1992, 54244, (select id from series where hardcover_id = 5513), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mort', 'Terry Pratchett', '0552173045', 'https://assets.hardcover.app/edition/30789219/1b67ab59d3729666faecdf207d0cec78bbf36913.jpeg', 'Death comes to us all. When he came to Mort, he offered him a job. In the Discworld, the Grim Reaper is a black-robed skeleton with glowing blue eyes and a scythe who’s fond of cats and eternally baffled by humanity. He yearns to experience what humanity really has to offer, but to do so, needs to hire help.

As Death’s apprentice, Mort will have free board, use of the company horse, and, best of all, another chance at life, because being dead isn’t compulsory. It’s a dream job—until Mort falls in love with Death’s daughter, Ysabell, and discovers that your boss can be a killer on your love life.

The Discworld novels can be read in any order but Mort is the first book in the Death series. ', 317, null, 1987, 55176, (select id from series where hardcover_id = 1018), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dark Tower', 'Stephen King', '0743538110', 'https://assets.hardcover.app/edition/30570135/d707a3575bc01a586865efed238b143e28d7405f.jpeg', 'The Dark Tower series tells the story of Roland Deschain, Mid-World’s last gunslinger, who is traveling southeast across Mid-World’s post-apocalyptic landscape, searching for the powerful but elusive magical edifice known as The Dark Tower. Located in the fey region of End-World, amid a sea of singing red roses, the Dark Tower is the nexus point of the time-space continuum. It is the heart of all worlds, but it is also under threat. Someone, or something, is using the evil technology of the Great Old Ones to destroy it.

In Roland’s where and when, the world has already begun to move on. Time and direction are in drift, and the fabric of reality is fraying. However, things are about to get much worse. The six invisible magnetic Beams, which maintain the alignment of time, space, size, and dimension, are weakening. Because of this, the Tower itself is foundering. Unless Roland can find a way to save the Beams and stabilize the Tower, all of reality will blink out of existence.

Inspired in equal parts by Robert Browning’s poem, “Childe Roland to the Dark Tower Came,” J.R.R. Tolkien’s Lord of the Rings, and Sergio Leone’s spaghetti Western classics, The Dark Tower series is an epic of Arthurian proportions. It is Stephen King’s magnum opus, and is the center of his amazing creative universe. ([source][1])

Contains:

 - [The Gunslinger][2]
 - [The Drawing of the Three][3]
 - [The Waste Lands][4]
 - [Wizard and Glass][5]
 - [Wolves of the Calla][6]
 - [Song of Susannah][7]
 - [The Dark Tower][8]


  [1]: https://stephenking.com/darktower/book/
  [2]: https://openlibrary.org/works/OL81628W
  [3]: https://openlibrary.org/works/OL81616W
  [4]: https://openlibrary.org/works/OL81625W
  [5]: https://openlibrary.org/works/OL149219W/Wizard_and_Glass
  [6]: https://openlibrary.org/works/OL81594W
  [7]: https://openlibrary.org/works/OL149200W
  [8]: https://openlibrary.org/works/OL149195W', 686, null, 2002, 55373, (select id from series where hardcover_id = 3413), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red Seas Under Red Skies', 'Scott Lynch', '1399625314', 'https://assets.hardcover.app/external_data/33125840/11fb07588dd20e3be91f29165c64230ed3067712.jpeg', 'In his highly acclaimed debut, The Lies of Locke Lamora, Scott Lynch took us on an adrenaline-fueled adventure with a band of daring thieves led by con artist extraordinaire Locke Lamora. Now Lynch brings back his outrageous hero for a caper so death-defying, nothing short of a miracle will pull it off.After a brutal battle with the underworld that nearly destroyed him, Locke and his trusted sidekick, Jean, fled the island city of their birth and landed on the exotic shores of Tal Verrar to nurse their wounds. But even at this westernmost edge of civilization, they can''t rest for long--and are soon back to what they do best: stealing from the undeserving rich and pocketing the proceeds for themselves. This time, however, they have targeted the grandest prize of all: the Sinspire, the most exclusive and heavily guarded gambling house in the world. Its nine floors attract the wealthiest clientele--and to rise to the top, one must impress with good credit, amusing behavior...and excruciatingly impeccable play. For there is one cardinal rule, enforced by Requin, the house''s cold-blooded master: it is death to cheat at any game at the Sinspire. Brazenly undeterred, Locke and Jean have orchestrated an elaborate plan to lie, trick, and swindle their way up the nine floors...straight to Requin''s teeming vault. Under the cloak of false identities, they meticulously make their climb--until they are closer to the spoils than ever. But someone in Tal Verrar has uncovered the duo''s secret. Someone from their past who has every intention of making the impudent criminals pay for their sins. Now it will take every ounce of cunning to save their mercenary souls. And even that may not be enough....From the Hardcover edition.', 640, null, 2007, 56778, (select id from series where hardcover_id = 1128), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dark Matter', 'Blake Crouch', '0451496418', 'https://assets.hardcover.app/book_mappings/7332342/e3c5928fc0a24ca97940c68f03dd2b503e42ba4f.jpeg', 'Those are the last words Jason Dessen hears before the kidnapper knocks him unconscious. 

Before he awakens to find himself strapped to a gurney, surrounded by strangers in hazmat suits.

Before a man he’s never met smiles down at him and says, “Welcome back, my friend.”

In this world he’s woken up to, Jason’s life is not the one he knows. His wife is not his wife. His son was never born. And Jason is not an ordinary college professor but a celebrated genius who has achieved something remarkable. Something impossible.

Is it this life or the other that’s the dream? And even if the home he remembers is real, how will Jason make it back to the family he loves?', 340, null, 2016, 57214, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Battle of the Labyrinth', 'Rick Riordan', '9632454901', 'https://assets.hardcover.app/editions/6040483/2714538691147541.jpg', 'Percy Jackson isn’t expecting freshman orientation to be any fun, but when a mysterious mortal acquaintance appears, pursued by demon cheerleaders, things quickly go from bad to worse.

Time is running out for Percy. War between the gods and the Titans is drawing near. Even Camp Half-Blood isn’t safe, as Kronos’ army prepares to invade its once impenetrable borders. To stop them, Percy and his friends must set out on a quest through the Labyrinth — a sprawling underground world with surprises and danger at every turn.

Along the way Percy will confront powerful enemies, find out the truth about the lost god Pan, and face the Titan lord Kronos’ most terrible secret. The final war begins… with the Battle of the Labyrinth.', 361, null, 2008, 58025, (select id from series where hardcover_id = 5193), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Clockwork Orange', 'Anthony Burgess, Blake Morrison', '8542813022', 'https://assets.hardcover.app/edition/24599945/a18266d2-3500-4641-99b3-035c7dc55d2a.jpg', 'Fifteen-year-old Alex and his three friends start an evening''s mayhem by hitting an old man, tearing up his books and stripping him of money and clothes.

Or rather Alex and his three droogs tolchock an old veck, razrez his books, pull off his outer platties and take a malenky bit of cutter.

For Alex''s confessions are written in ''nadsat'' - the teenage argot of a not-too-distant future.

Because of his delinquent excesses, Alex is jailed and made subject to ''Ludovico''s Technique,'' a chilling experiment in Reclamation Treatment...

Horror farce? Social prophecy? Penetrating study of human choice between good and evil? A Clockwork Orange is all three, dazzling proof of Anthony Burgess''s vast talents.', 144, null, 1962, 61179, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Martian Chronicles', 'Ray Bradbury', '0552097845', 'https://assets.hardcover.app/book_mappings/7332674/0acf6282b03c56c91ee95d99cdbc7075e595786f.jpeg', 'Soar above the fossil seas and crystal pillars of a dead world in the pages of Ray Bradbury’s The Martian Chronicles. A milestone of American literature, Bradbury’s classic collection of interconnected vignettes about life on the red planet diverges from the War of the Worlds theme, in which humanity must defend its shores against its neighbors, for in Bradbury’s prismatic vision, humanity is the conqueror, colonizing Mars to escape an Earth devastated by atomic war and environmental catastrophe.', 182, null, 1950, 64037, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Farseer Trilogy', 'Robin Hobb', '000879085X', 'https://assets.hardcover.app/external_data/4056453/95fea2bbebc7262a63006066102137067a314851.jpeg', 'The complete Farseer Trilogy by international bestselling author Robin Hobb. ‘In today’s crowded fantasy market Robin Hobb’s books are like diamonds in a sea of zircons’ George R. R. Martin', 2096, null, 1995, 65020, (select id from series where hardcover_id = 5513), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Man in the High Castle', 'Philip K. Dick', '1433214520', 'https://assets.hardcover.app/book_mappings/7332681/aa5b4dfefa5a601437734c17811e6547ed2dc5a9.jpeg', 'The Man in the High Castle is an alternate history novel by American writer Philip K. Dick. Published and set in 1962, the novel takes place fifteen years after an alternative ending to World War II, and concerns intrigues between the victorious Axis Powers—primarily, Imperial Japan and Nazi Germany—as they rule over the former United States, as well as daily life under the resulting totalitarian rule. The Man in the High Castle won the Hugo Award for Best Novel in 1963. Beginning in 2015, the book was adapted as a multi-season TV series, with Dick''s daughter, Isa Dick Hackett, serving as one of the show''s producers.

Reported inspirations include Ward Moore''s alternate Civil War history, Bring the Jubilee (1953), various classic World War II histories, and the I Ching (referred to in the novel). The novel features a "novel within the novel" comprising an alternate history within this alternate history wherein the Allies defeat the Axis (though in a manner distinct from the actual historical outcome).', 392, null, 1962, 66330, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dragon Republic', 'R.F. Kuang', '3641243882', 'https://assets.hardcover.app/edition/30570691/0c9364d1f32e79d0da2166297935e72f582bafed.jpeg', 'The war is over.

The war has just begun.

Three times throughout its history, Nikan has fought for its survival in the bloody Poppy Wars. Though the third battle has just ended, shaman and warrior Rin cannot forget the atrocity she committed to save her people. Now she is on the run from her guilt, the opium addiction that holds her like a vice, and the murderous commands of the fiery Phoenix—the vengeful god who has blessed Rin with her fearsome power.

Though she does not want to live, she refuses to die until she avenges the traitorous Empress who betrayed Rin’s homeland to its enemies. Her only hope is to join forces with the powerful Dragon Warlord, who plots to conquer Nikan, unseat the Empress, and create a new republic.

But neither the Empress nor the Dragon Warlord are what they seem. The more Rin witnesses, the more she fears her love for Nikan will force her to use the Phoenix’s deadly power once more.

Because there is nothing Rin won’t sacrifice to save her country . . . and exact her vengeance.', 672, null, 2019, 67543, (select id from series where hardcover_id = 985), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Time Machine', 'H.G. Wells', '044180263X', 'https://assets.hardcover.app/external_data/3506383/31160771ca684ebdee7bd21e6aeabfcec88b4bf7.jpeg', 'First published in 1895, The Time Machine won author H.G. Wells immediate recognition and has been regarded ever since as one of the great masterpieces in the literature of science fiction. It popularized the concept of time travel and introduced the concept of a "time machine" device that could travel forwards and backwards through the years. It is the story of one man’s astonishing journey beyond the conventional limits of the imagination. 

One of the most renowned works of science fiction, The Time Machine reflects on the adventures of The Time Traveler - a man who constructs a machine which allows him to explore what the future has to offer. When he courageously steps out of his machine for the first time, he finds himself in the year 802,701—and everything has changed. In this unfamiliar utopian age, creatures seem to dwell together in perfect harmony. Thinking he can study these marvelous beings and unearth their secret then return to his own time, he discovers that his only avenue of escape, his invention, has been stolen. 

Wells is generally credited with the popularization of the concept of time travel by using a vehicle that allows an operator to travel purposefully and selectively. The term "time machine", which was coined by Wells, is now universally used to refer to such a vehicle. The book has been adapted for a number of films and television shows, as well as inspiring other science fiction writers.', 144, null, 1895, 69589, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Host', 'Stephenie Meyer', '9735401312', 'https://assets.hardcover.app/book_mappings/7333241/236e11f29100bc86845aa02d83f22cfed591611c.jpeg', 'Melanie Stryder refuses to fade away. The earth has been invaded by a species that take over the minds of human hosts while leaving their bodies intact. Wanderer, the invading "soul" who has been given Melanie''s body, didn''t expect to find its former tenant refusing to relinquish possession of her mind.

As Melanie fills Wanderer''s thoughts with visions of Jared, a human who still lives in hiding, Wanderer begins to yearn for a man she''s never met. Reluctant allies, Wanderer and Melanie set off to search for the man they both love.', 619, null, 2005, 72948, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Eye of the World', 'Robert Jordan', '9780812500000', 'https://assets.hardcover.app/edition/30621010/97e433a0-efab-4de8-a7cc-23ad09a4df05.png', 'The Wheel of Time turns and Ages come and pass, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. What was, what will be, and what is, may yet fall under the Shadow.

Moiraine Damodred arrives in Emond’s Field on a quest to find the one prophesized to stand against The Dark One, a malicious entity sowing the seeds of chaos and destruction. When a vicious band of half-men, half beasts invade the village seeking their master’s enemy, Moiraine persuades Rand al’Thor and his friends to leave their home and enter a larger unimaginable world filled with dangers waiting in the shadows and in the light.', 804, 1975, 1990, 77104, (select id from series where hardcover_id = 1097), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Song of Achilles', 'Madeline Miller', '9537829359', 'https://assets.hardcover.app/editions/8933288/8719175186248367.jpg', 'Greece in the age of heroes. Patroclus, an awkward young prince, has been exiled to the kingdom of Phthia to be raised in the shadow of King Peleus and his golden son, Achilles. “The best of all the Greeks”—strong, beautiful, and the child of a goddess—Achilles is everything the shamed Patroclus is not. Yet despite their differences, the boys become steadfast companions. Their bond deepens as they grow into young men and become skilled in the arts of war and medicine—much to the displeasure and the fury of Achilles’ mother, Thetis, a cruel sea goddess with a hatred of mortals.

When word comes that Helen of Sparta has been kidnapped, the men of Greece, bound by blood and oath, must lay siege to Troy in her name. Seduced by the promise of a glorious destiny, Achilles joins their cause, and torn between love and fear for his friend, Patroclus follows. Little do they know that the Fates will test them both as never before and demand a terrible sacrifice.

Built on the groundwork of the Iliad, Madeline Miller’s page-turning, profoundly moving, and blisteringly paced retelling of the epic Trojan War marks the launch of a dazzling career.', 384, 674, 2011, 80378, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Arcanum Unbounded: The Cosmere Collection', 'Brandon Sanderson', '8490698643', 'https://assets.hardcover.app/edition/31276301/b5b1c6b758306caf9553430c4ccf576f29b9bd19.jpeg', 'The Cosmere Collection encompasses six worlds in all, explored across nine astonishing works of short fiction: Sel ("The Hope of Elantris" and "The Emperor''s Soul"); Scadrial ("The Eleventh Metal," "Allomancer Jak and the Pits of Eltania, Episodes Twenty-eight Through Thirty," and "Mistborn: Secret History"); Taldain ("White Sand"); Threnody (“Shadows for Silence in the Forests of Hell”); First of the Sun (“Sixth of the Dusk”); and Roshar ("Edgedancer").', 672, null, 2016, 80765, (select id from series where hardcover_id = 5497), 18) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Memory of Light', 'Brandon Sanderson, Robert Jordan', '0765325950', 'https://assets.hardcover.app/edition/30930986/6513264d-e025-4a8e-8fcc-1b6030110264.png', 'Since 1990, when Robert Jordan’s The Wheel of Time® burst on the world with its first book, The Eye of the World, readers have been anticipating the final scenes of this extraordinary saga, which has sold over forty million copies in over thirty languages.

When Robert Jordan died in 2007, all feared that these concluding scenes would never be written. But working from notes and partials left by Jordan, established fantasy writer Brandon Sanderson stepped in to complete the masterwork. With The Gathering Storm (Book 12) and Towers of Midnight (Book 13) behind him, both of which were # 1 New York Times hardcover bestsellers, Sanderson now re-creates the vision that Robert Jordan left behind.

Edited by Jordan’s widow, who edited all of Jordan’s books, A Memory of Light will delight, enthrall, and deeply satisfy all of Jordan’s legions of readers.

The Wheel of Time turns, and Ages come and pass.
What was, what will be, and what is,
may yet fall under the Shadow. 
Let the Dragon ride again on the winds of time.', 1056, null, 2013, 81913, (select id from series where hardcover_id = 1097), 14) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Diamond Age', 'Neal Stephenson', '014027037X', 'https://assets.hardcover.app/book_mappings/7332970/8f1a10cf5b82f7021430811bb32b40ea88b02552.jpeg', 'The story of an engineer who creates a device to raise a girl capable of thinking for herself reveals what happens when a young girl of the poor underclass obtains the device.', 536, null, 1995, 82662, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Invisible Man', 'H. G. Wells', '0785406840', 'https://assets.hardcover.app/edition/22973329/ac6f1edb9e39ab98149a8d59c0369fd8c421d6e6.jpeg', 'This book is the story of Griffin, a scientist who creates a serum to render himself invisible, and his descent into madness that follows.', 114, null, 1897, 87093, (select id from series where hardcover_id = 219517), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Brisingr', 'Christopher Paolini', '140704477X', 'https://assets.hardcover.app/book_mappings/7333159/b83de149678d483fb50308ff2dd32f3c58bb882d.jpeg', 'OATHS SWORN . . . loyalties tested . . . forces collide.Following the colossal battle against the Empire''s warriors on the Burning Plains, Eragon and his dragon, Saphira, have narrowly escaped with their lives. Still there is more at hand for the Rider and his dragon, as Eragon finds himself bound by a tangle of promises he may not be able to keep.First is Eragon''s oath to his cousin Roran: to help rescue Roran''s beloved, Katrina, from King Galbatorix''s clutches. But Eragon owes his loyalty to others, too. The Varden are in desperate need of his talents and strength--as are the elves and dwarves. When unrest claims the rebels and danger strikes from every corner, Eragon must make choices-- choices that take him across the Empire and beyond, choices that may lead to unimagined sacrifice.Eragon is the greatest hope to rid the land of tyranny. Can this once-simple farm boy unite the rebel forces and defeat the king?From the Hardcover edition.', 790, null, 2008, 87168, (select id from series where hardcover_id = 5464), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kings of the Wyld', 'Nicholas Eames', '9634700276', 'https://assets.hardcover.app/edition/30447628/23d6f2bd-115d-450f-a731-9fbcb59b04e8.jpg', 'Clay Cooper and his band were once the best of the best -- the meanest, dirtiest, most feared crew of mercenaries this side of the Heartwyld.

Their glory days long past, the mercs have grown apart and grown old, fat, drunk - or a combination of the three. Then an ex-bandmate turns up at Clay''s door with a plea for help. His daughter Rose is trapped in a city besieged by an enemy one hundred thousand strong and hungry for blood. Rescuing Rose is the kind of mission that only the very brave or the very stupid would sign up for.

It''s time to get the band back together for one last tour across the Wyld.', 422, null, 2017, 89506, (select id from series where hardcover_id = 4919), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Wish', 'Andrzej Sapkowski, Danusia Stok', '9723827514', 'https://assets.hardcover.app/external_data/45227371/e884c4a2b40fab63bff10f9e2213c3854952f4e8.jpeg', 'Geralt is a Witcher, a man whose magic powers, enhanced by long training and a mysterious elixir, have made him a brilliant fighter and a merciless assassin. Yet he is no ordinary killer. His sole purpose: to destroy the monsters that plague the world.

But not everything monstrous-looking is evil and not everything fair is good...and in every fairy tale there is a grain of truth.', 352, null, 1993, 89809, (select id from series where hardcover_id = 1808), 0.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Infinite Jest', 'David Foster Wallace', '0316306053', 'https://assets.hardcover.app/edition/32718880/2682231d-f875-4902-90f5-02f443b32150.jpg', 'The "grandly ambitious, wickedly comic" modern classic about the pursuit of happiness in America, now in a new 30th anniversary edition (Seattle Times). Set in an addicts'' halfway house and a tennis academy, and featuring the most endearingly screwed-up family to come along in recent fiction, Infinite Jest explores essential questions about what entertainment is and why it has come to so dominate our lives; about how our desire for entertainment affects our need to connect with other people; and about what the pleasures we choose say about who we are. Equal parts philosophical quest and screwball comedy, Infinite Jest bends every rule of fiction without sacrificing for a moment its own entertainment value. It is an exuberant, uniquely American exploration of the passions that make us human -- and one of those rare books that renew the idea of what a novel can do. "The next step in fiction...Edgy, accurate, and darkly witty...Think Beckett, think Pynchon, think Gaddis. Think." --Sven Birkerts, The Atlantic', 1104, null, 1985, 89871, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Spinning Silver', 'Naomi Novik', '1509899014', 'https://assets.hardcover.app/book_mappings/7332624/52dc8999dd9180d1f12b037bee9c921f8dc8e812.jpeg', 'NEW YORK TIMES BESTSELLER • “One of the year’s strongest fantasy novels” (NPR), an imaginative retelling of the Rumpelstiltskin fairy tale from the bestselling author of Uprooted.

NEBULA AND HUGO AWARD FINALIST • NAMED ONE OF PASTE’S BEST FANTASY BOOKS OF THE DECADE • ONE OF THE TEN BEST BOOKS OF THE YEAR: The New York Public Library

With the Nebula Award–winning Uprooted, Naomi Novik opened a brilliant new chapter in an already acclaimed career, delving into the magic of fairy tales to craft a love story that was both timeless and utterly of the now. Spinning Silver draws readers deeper into this glittering realm of fantasy, where the boundary between wonder and terror is thinner than a breath, and safety can be stolen as quickly as a kiss.

Miryem is the daughter and granddaughter of moneylenders, but her father’s inability to collect his debts has left his family on the edge of poverty—until Miryem takes matters into her own hands. Hardening her heart, the young woman sets out to claim what is owed and soon gains a reputation for being able to turn silver into gold. When an ill-advised boast draws the attention of the king of the Staryk—grim fey creatures who seem more ice than flesh—Miryem’s fate, and that of two kingdoms, will be forever altered. She will face an impossible challenge and, along with two unlikely allies, uncover a secret that threatens to consume the lands of humans and Staryk alike.
', 480, null, 2018, 92337, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Memory Called Empire', 'Arkady Martine', '1760785989', 'https://assets.hardcover.app/external_data/38085113/6cc9282322ce3e8ed1b63f98bf93f57dca7cda90.jpeg', 'Ambassador Mahit Dzmare arrives in the center of the multi-system Teixcalaanli Empire only to discover that her predecessor, the previous ambassador from their small but fiercely independent mining Station, has died. But no one will admit that his death wasn''t an accident—or that Mahit might be next to die, during a time of political instability in the highest echelons of the imperial court.

Now, Mahit must discover who is behind the murder, rescue herself, and save her Station from Teixcalaan''s unceasing expansion—all while navigating an alien culture that is all too seductive, engaging in intrigues of her own, and hiding a deadly technological secret—one that might spell the end of her Station and her way of life—or rescue it from annihilation.

Arkady Martine''s debut novel A Memory Called Empire is a fascinating space opera and an interstellar mystery adventure.', 464, null, 2019, 92482, (select id from series where hardcover_id = 5468), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Snow Crash', 'Neal Stephenson', '0613361628', 'https://assets.hardcover.app/editions/31794070/6698396023409903.jpg', 'In Snow Crash, Neal Stephenson rewires the cyberpunk genre, throwing you headfirst into a chaotic, corporatized future where governments have collapsed, the Metaverse reigns supreme, and everything—literally everything—is for sale. Hiro Protagonist, katana-wielding hacker and the world’s most overqualified pizza delivery guy, stumbles onto a digital virus that’s more than just code—it’s a weapon that targets minds, threatening the virtual and real worlds alike. With the help of a badass skateboarding courier named Y.T., Hiro races through a world of hyper-capitalist dystopia, ancient Sumerian mythology, and corporate warfare to stop an apocalypse no one else even sees coming. Wild, prophetic, and way too real, Snow Crash doesn’t just predict the future—it builds it.', 448, null, 1992, 92854, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('His Majesty''s Dragon', 'Naomi Novik', '0007219113', 'https://assets.hardcover.app/edition/22654972/564512b6-7131-4a06-9833-141fd6837d1d.tiff', 'Aerial combat brings a thrilling new dimension to the Napoleonic Wars as valiant warriors rise to Britain''s defense by taking to the skies . . . not aboard aircraft but atop the mighty backs of fighting dragons.When HMS Reliant captures a French frigate and seizes its precious cargo, an unhatched dragon egg, fate sweeps Capt. Will Laurence from his seafaring life into an uncertain future--and an unexpected kinship with a most extraordinary creature. Thrust into the rarified world of the Aerial Corps as master of the dragon Temeraire, he will face a crash course in the daring tactics of airborne battle. For as France''s own dragon-borne forces rally to breach British soil in Bonaparte''s boldest gambit, Laurence and Temeraire must soar into their own baptism of fire.', 336, null, 2005, 93077, (select id from series where hardcover_id = 4930), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Going Postal', 'Terry Pratchett', '8071972657', 'https://assets.hardcover.app/editions/30615143/2f7d0857-5926-4f7b-9122-8987f0f61ce4.jpg', 'A splendid send-up of government, the postal system, and everything that lies in between in this newest entry in Terry Pratchett’s internationally bestselling Discworld series. Convicted con man and forger Moist von Lipwig is given a choice: Face the hangman’s noose, or get Ankh Morpork’s ancient Post Office up and running efficiently! It was a tough decision . . . Now, the former criminal is facing really big problems. There’s tons of undelivered mail. Ghosts are talking to him. One of the postmen is 18,000 years old. And you really wouldn’t want to know what his new girlfriend can do with a shoe. To top it all off, shadowy characters don’t want the mail moved. Instead, they want him dead—deader than all those dead letters. (And here he’d thought that all he’d have to face was rain, snow, and gloom of night . . .)', 448, null, 2004, 94361, (select id from series where hardcover_id = 1018), 33) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foundation and Earth', 'Isaac Asimov', '0593159993', 'https://assets.hardcover.app/edition/30550457/29482031-b579-48a1-89fa-8fc3205087c5.jpg', 'Golan Trevize, former Councilman of the First Foundation, has chosen the future, and it is Gaia. A superorganism, Gaia is a holistic planet with a common consciousness so intensely united that every dewdrop, every pebble, every being, can speak for all—and feel for all. It is a realm in which privacy is not only undesirable, it is incomprehensible.

But is it the right choice for the destiny of mankind? While Trevize feels it is, that is not enough. He must know.

Trevize believes the answer lies at the site of humanity’s roots: fabled Earth . . . if it still exists. For no one is sure where the planet of Gaia’s first settlers is to be found in the immense wilderness of the Galaxy. Nor can anyone explain why no record of Earth has been preserved, no mention of it made anywhere in Gaia’s vast world-memory. It is an enigma Trevize is determined to resolve, and a quest he is determined to undertake, at any cost.', 378, null, 1986, 94363, (select id from series where hardcover_id = 5450), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Stories of Your Life and Others', 'Ted Chiang', '8389951525', 'https://assets.hardcover.app/edition/30448261/e263f538-788c-40fa-8160-73378ca2c00a.jpg', 'With his masterful first collection, multiple-award-winning author Ted Chiang deftly blends human emotion and scientific rationalism in eight remarkably diverse stories, all told in his trademark precise and evocative prose. From a soaring Babylonian tower that connects a flat Earth with the firmament above, to a world where angelic visitations are a wondrous and terrifying part of everyday life; from a neural modification that eliminates the appeal of physical beauty, to an alien language that challenges our very perception of time and reality. . . Chiang''s rigorously imagined fantasia invites us to question our understanding of the universe and our place in it.', 320, null, 2002, 94521, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ancillary Justice', 'Ann Leckie', '0316565172', 'https://assets.hardcover.app/book_mappings/7332484/7a16275c4094f457f84fa18e5818c3f746c42960.jpeg', 'On a remote, icy planet, the soldier known as Breq is drawing closer to completing her quest.

Breq is both more than she seems and less than she was. Years ago, she was Justice of Toren–a colossal starship with an artificial intelligence linking thousands of corpse soldiers in the service of the Radch, the empire that conquered the galaxy.

An act of treachery has ripped it all away, leaving her with only one fragile human body. And only one purpose–to revenge herself on Anaander Mianaai, many-bodied, near-immortal Lord of the Radch.', 396, null, 2013, 95034, (select id from series where hardcover_id = 993), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Armada', 'Ernest Cline, Ralph van der Aa', '8466658939', 'https://assets.hardcover.app/book_mappings/7332904/be14a0563a5936270c3149b471d82157bc24d1a9.jpeg', '"He vastly prefers the countless science-fiction movies, books, and videogames he''s spent his life consuming. And too often, he catches himself wishing that some fantastic, impossible, world-altering event could arrive to whisk him off on a grand spacefaring adventure. 

So when he sees the flying saucer, he''s sure his years of escapism have finally tipped over into madness. 

Especially because the alien ship he''s staring at is straight out of his favorite videogame, a flight simulator callled Armada—in which gamers just happen to be protecting Earth from alien invaders. 

As impossible as it seems, what Zack''s seeing is all too real. And it''s just the first in a blur of revlations that will force him to question everything he thought he knew about Earth''s history, its future, even his own life--and to play the hero for real, with humanity''s life in the balance. 

But even through the terror and exhilaration, he can''t help thinking: Doesn''t something about this scenario feel a little bit like . . .  well . . . fiction?"-- Provided by Amazon', 385, null, 2000, 96494, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sleeping Giants', 'Sylvain Neuvel', '1405941731', 'https://assets.hardcover.app/edition/30399454/1d6c479c90a9b6a818364b67ab8f7e6e93c57d4c.jpeg', 'A page-turning debut in the tradition of Michael Crichton, World War Z, and The Martian, Sleeping Giants is a thriller fueled by an earthshaking mystery—and a fight to control a gargantuan power. A girl named Rose is riding her new bike near her home in Deadwood, South Dakota, when she falls through the earth. She wakes up at the bottom of a square hole, its walls glowing with intricate carvings. But the firemen who come to save her peer down upon something even stranger: a little girl in the palm of a giant metal hand. Seventeen years later, the mystery of the bizarre artifact remains unsolved—its origins, architects, and purpose unknown. Its carbon dating defies belief; military reports are redacted; theories are floated, then rejected. But some can never stop searching for answers. Rose Franklin is now a highly trained physicist leading a top secret team to crack the hand’s code. And along with her colleagues, she is being interviewed by a nameless interrogator whose power and purview are as enigmatic as the provenance of the relic. What’s clear is that Rose and her compatriots are on the edge of unraveling history’s most perplexing discovery—and figuring out what it portends for humanity. But once the pieces of the puzzle are in place, will the result prove to be an instrument of lasting peace or a weapon of mass destruction? Praise for Sleeping Giants “As high-concept as it is, Sleeping Giants is a thriller through and through. . . . One of the most promising series kickoffs in recent memory, [and] a smart demonstration of how science fiction can honor its traditions and reverse-engineer them at the same time.”—NPR “Neuvel weaves a complex tapestry with ancient machinery buried in the Earth, shadow governments, and geopolitical conflicts. But the most surprising thing about the book may just be how compelling the central characters are in the midst of these larger-than-life concepts. . . . I can’t stop thinking about it.”—Chicago Review of Books “A remarkable debut . . . Reminiscent of Max Brooks’s World War Z, the story’s format effectively builds suspense.”—Library Journal (debut of the month) “This stellar debut novel . . . masterfully blends together elements of sci-fi, political thriller and apocalyptic fiction. . . . A page-turner of the highest order.”—Kirkus Reviews (starred review) Don’t miss any of The Themis Files by Sylvain Neuvel: SLEEPING GIANTS | WAKING GODS | ONLY HUMAN', 304, null, 2016, 96684, (select id from series where hardcover_id = 979), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Cruel Prince', 'Holly Black', '9669820634', 'https://assets.hardcover.app/external_data/3624207/454653c3d74c72b16751b4a4a67658016aeb9c8e.jpeg', '"And Cardan is even more beautiful than the rest. I hate him more than all the others. I hate him so much that sometimes when I look at him, I can hardly breathe.

Jude was seven years old when her parents were murdered and she and her two sisters were stolen away to live in the treacherous High Court of Faerie. Ten years later, Jude wants nothing more than to belong there, despite her mortality. But many of the fey despise humans. Especially Prince Cardan, the youngest and wickedest son of the High King.

To win a place at the Court, she must defy him--and face the consequences.

In doing so, she becomes embroiled in palace intrigues and deceptions, discovering her own capacity for bloodshed. But as civil war threatens to drown the Courts of Faerie in violence, Jude will need to risk her life in a dangerous alliance to save her sisters, and Faerie itself."-- Provided by Amazon', 384, null, 2018, 98065, (select id from series where hardcover_id = 5470), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Pillars of the Earth', 'Ken Follett', '2221190777', 'https://assets.hardcover.app/edition/32856871/bdab1721-61a6-454e-8e1e-05977ef697fe.jpg', 'The Pillars of the Earth tells the story of Philip, prior of Kingsbridge, a devout and resourceful monk driven to build the greatest Gothic cathedral the world has known . . . of Tom, the mason who becomes his architect—a man divided in his soul . . . of the beautiful, elusive Lady Aliena, haunted by a secret shame . . . and of a struggle between good and evil that will turn church against state and brother against brother.
 
A spellbinding epic tale of ambition, anarchy, and absolute power set against the sprawling medieval canvas of twelfth-century England, this is Ken Follett’s historical masterpiece.', 1008, null, 1989, 98094, (select id from series where hardcover_id = 1156), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('To Be Taught, If Fortunate', 'Becky Chambers', '1473697182', 'https://assets.hardcover.app/book/98275/b1c38ef2-c084-42a4-9e55-a9ef2288f84d.jpeg', 'A stand-alone science fiction novella from the award-winning, bestselling, critically-acclaimed author of the Wayfarer series.

At the turn of the twenty-second century, scientists make a breakthrough in human spaceflight. Through a revolutionary method known as somaforming, astronauts can survive in hostile environments off Earth using synthetic biological supplementations. They can produce antifreeze in subzero temperatures, absorb radiation and convert it for food, and conveniently adjust to the pull of different gravitational forces. With the fragility of the body no longer a limiting factor, human beings are at last able to journey to neighboring exoplanets long known to harbor life.

A team of these explorers, Ariadne O’Neill and her three crewmates, are hard at work in a planetary system fifteen light-years from Sol, on a mission to ecologically survey four habitable worlds. But as Ariadne shifts through both form and time, the culture back on Earth has also been transformed. Faced with the possibility of returning to a planet that has forgotten those who have left, Ariadne begins to chronicle the story of the wonders and dangers of her mission, in the hope that someone back home might still be listening.', 160, null, 2019, 98275, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Magician''s Nephew', 'C. S. Lewis, Pauline Baynes', '1998382168', 'https://assets.hardcover.app/edition/4601373/de03f9d19e5f9bc8150670c6ee1e2f28b5368887.jpeg', 'Digory let out a scream. “What''s happened to Polly?” “Congratulate me, my dear boy,” said Uncle Andrew, rubbing his hands. “My experiment has succeeded. The little girl''s gone – vanished – right out of this world.” When Digory and Polly discover Uncle Andrew''s secret workshop, they are tricked into touching some magic rings that take them right out of this world. But even Uncle Andrew doesn''t realise the wonders that lie ahead as they discover the gateway to the magical land of Narnia, where many thrilling adventures await them.', 208, null, 1950, 98899, (select id from series where hardcover_id = 5485), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Selection', 'Kiera Cass', '0606354883', 'https://assets.hardcover.app/external_data/60864575/2bb1cb5109e72f003cf72b53a67bd427274918e8.jpeg', '"The opportunity to escape a rigid caste system, live in a palace, and compete for the heart of gorgeous Prince Maxon. But for America Singer, being Selected is a nightmare. It means turning her back on her secret love with Aspen, who is a caste below her, and competing for a crown she doesn’t want.

Then America meets Prince Maxon—and realizes that the life she’s always dreamed of may not compare to a future she never imagined."-- Provided by Amazon', 327, null, 2012, 99293, (select id from series where hardcover_id = 1545), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Inferno', 'Dan Brown', '0385539851', 'https://assets.hardcover.app/edition/21477318/4d7cf319-eaab-4986-9915-e616f2afbc02.jpg', 'Harvard professor of symbology Robert Langdon awakens in an Italian hospital, disoriented and with no recollection of the past thirty-six hours, including the origin of the macabre object hidden in his belongings. With a relentless female assassin trailing them through Florence, he and his resourceful doctor, Sienna Brooks, are forced to flee.

Embarking on a harrowing journey, they must unravel a series of codes, which are the work of a brilliant scientist whose obsession with the end of the world is matched only by his passion for one of the most influential masterpieces ever written: Dante Alighieri’s The Inferno.', 461, null, 2013, 99335, (select id from series where hardcover_id = 1084), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Artemis', 'Andy Weir', '0553448137', 'https://assets.hardcover.app/edition/30426459/f167b2da-7e34-4e59-a0da-2233d70a61b7.jpg', 'Jasmine Bashara never signed up to be a hero. She just wanted to get rich. 
  
 Not crazy, eccentric-billionaire rich, like many of the visitors to her hometown of Artemis, humanity’s first and only lunar colony. Just rich enough to move out of her coffin-sized apartment and eat something better than flavored algae. Rich enough to pay off a debt she’s owed for a long time.
  
 So when a chance at a huge score finally comes her way, Jazz can’t say no. Sure, it requires her to graduate from small-time smuggler to full-on criminal mastermind. And it calls for a particular combination of cunning, technical skills, and large explosions—not to mention sheer brazen swagger. But Jazz has never run into a challenge her intellect can’t handle, and she figures she’s got the ‘swagger’ part down. 
  
 The trouble is, engineering the perfect crime is just the start of Jazz’s problems. Because her little heist is about to land her in the middle of a conspiracy for control of Artemis itself. 
  
 Trapped between competing forces, pursued by a killer and the law alike, even Jazz has to admit she’s in way over her head. She’ll have to hatch a truly spectacular scheme to have a chance at staying alive and saving her city. 
  
 Jazz is no hero, but she is a very good criminal. 
  
 That’ll have to do. 
  
 Propelled by its heroine’s wisecracking voice, set in a city that’s at once stunningly imagined and intimately familiar, and brimming over with clever problem-solving and heist-y fun, Artemis is another irresistible brew of science, suspense, and humor from #1 bestselling author Andy Weir.', 320, null, 2017, 99422, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hogfather', 'Terry Pratchett', '0061050466', 'https://assets.hardcover.app/edition/31705920/4cad55867a16934fbf7f35ce3765f333df828640.jpeg', '''Humans need fantasy to be human. To be the place where the falling angel meets the rising ape.'' ''Twas the night before Hogswatch and all through the house . . . something was missing. Superstition makes things work in the Discworld and undermining it can have consequences. When Death realizes that belief in the Hogfather is dangerously low, he decides to take on the job. But it''s just not right to find a seven-foot skeleton creeping down your chimney and trying to say ''ho, ho, ho''. It''s the last night of the year, the time is turning, and if Susan, gothic governess and Death''s granddaughter, doesn''t sort everything out by morning, there won''t be a morning. Ever again . . . ''Has the energy of The Hitchhiker''s Guide to the Galaxy and the inventiveness of Alice in Wonderland'' Sunday Times Hogfather is the fourth book in the Death series, but you can read the Discworld novels in any order.', 430, null, 1996, 100157, (select id from series where hardcover_id = 1018), 20) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Eldest', 'Christopher Paolini', '8934974055143', 'https://assets.hardcover.app/external_data/3410852/16191ac95bded352b519805189ea172b0c18306d.jpeg', 'Darkness falls… despair abounds… evil reigns… Eragon and his dragon, Saphira, have just saved the rebel state from destruction by the mighty forces of King Galbatorix. Now Eragon must travel to Ellésmera, land of the elves, for further training in the skills of the Dragon Rider: magic and swordsmanship. But chaos and betrayal plague him at every turn, and nothing is what it seems. Before long, Eragon doesn’t know whom he can trust.

Will the king’s dark hand strangle all resistance? Eragon may not escape with even his life. . . .', 679, null, 2005, 100660, (select id from series where hardcover_id = 5464), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hero of Ages', 'Brandon Sanderson', '8498727952', 'https://assets.hardcover.app/book_mappings/7332415/e3dcf34cb6632d5de4f946fbbd5d20558f3d69d6.jpeg', 'To end the Final Empire and restore freedom, Vin killed the Lord Ruler. But as a result, the Deepness--the lethal form of the ubiquitous mists--is back, along with increasingly heavy ashfalls and ever more powerful earthquakes. Humanity appears to be doomed unless Emperor Elend Venture can find clues left behind by the Lord Ruler that will allow him to save the world.', 572, 1046, 2008, 103241, (select id from series where hardcover_id = 10001), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fires of Heaven', 'Robert Jordan', '0748115382', 'https://assets.hardcover.app/edition/30930913/1037ffd1-07ee-4ae4-9c27-e69ca884cf05.png', 'The bonds and wards that hold the Great Lord of the Dark are slowly failing, but still his fragile prison holds. The Forsaken, immortal servants of the shadow, weave their snares and tighten their grip upon the realms of men, sure in the knowledge that their master will soon break free...
Rand al'' Thor, the Dragon Reborn, knows that he must strike at the Enemy, but his forces are divided by treachery and by ambition. Even the Aes Sedai, ancient guardians of the Light, are riven by civil war. Betrayed by his allies, pursued by his enemies and beset by the madness that comes to the male wielders of the One Power, Rand rides out to meet the foe.', 928, null, 1993, 104011, (select id from series where hardcover_id = 1097), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fool''s Errand', 'Robin Hobb', '902907003X', 'https://assets.hardcover.app/edition/31755235/9337537fbd8091f38d9bb8a489b2f3b4603445ea.jpeg', '“Hobb’s fans won’t be disappointed with this latest installment. Fool’s Errand lives up to the legacy of the Farseer trilogy.”—Monroe News-Star Fitz and the Fool are reunited in the first book in the Tawny Man Trilogy—“a stay-up-until-2:00 a.m.-to-finish type of book” (Publishers Weekly, starred review). For fifteen years, FitzChivalry Farseer has lived in self-imposed exile, assumed to be dead by almost all who once cared about him. But now, into his isolated life, visitors begin to arrive: Fitz’s mentor from his assassin days; a hedge-witch who foresees the return of a long-lost love; and the Fool, the former White Prophet, who beckons Fitz to fulfill his destiny. Then comes the summons he cannot ignore. Prince Dutiful, the young heir to the Farseer throne, has vanished. Fitz, possessed of magical skills both royal and profane, is the only one who can retrieve him in time for his betrothal ceremony, thus sparing the Six Duchies profound political embarrassment . . . or worse. But even Fitz does not suspect the web of treachery that awaits him—or how his loyalties will be tested to the breaking point.', 657, null, 2001, 104450, (select id from series where hardcover_id = 6035), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dawn ', 'Octavia E. Butler', '1472281063', 'https://assets.hardcover.app/edition/20434901/1b67d0d8-3454-4eeb-a67d-0b7992d961f7.jpg', 'Lilith Iyapo has just lost her husband and son when atomic fire consumes Earth—the last stage of the planet’s final war. Hundreds of years later Lilith awakes, deep in the hold of a massive alien spacecraft piloted by the Oankali—who arrived just in time to save humanity from extinction. They have kept Lilith and other survivors asleep for centuries, as they learned whatever they could about Earth. Now it is time for Lilith to lead them back to her home world, but life among the Oankali on the newly resettled planet will be nothing like it was before.

The Oankali survive by genetically merging with primitive civilizations—whether their new hosts like it or not. For the first time since the nuclear holocaust, Earth will be inhabited. Grass will grow, animals will run, and people will learn to survive the planet’s untamed wilderness. But their children will not be human. Not exactly.', 321, null, 1987, 104531, (select id from series where hardcover_id = 2631), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dirk Gently''s Holistic Detective Agency', 'Douglas Adams', '0743546520', 'https://assets.hardcover.app/edition/31582349/20361055d2c1297fb381f3623ef80aeebb73fe3d.jpeg', 'What do a dead cat, a computer whiz-kid, an Electric Monk who believes the world is pink, quantum mechanics, a Chronologist over two hundred years old, Samuel Taylor Coleridge (poet), and pizza have in common?

Apparently not much; until Dirk Gently, self-styled private investigator, sets out to prove the fundamental interconnectedness of all things by solving a mysterious murder, assisting a mysterious professor, unravelling a mysterious mystery, and eating a lot of pizza – not to mention saving the entire human race from extinction along the way (at no extra charge).

To find out more, read this book (better still, buy it then read it) – or contact Dirk Gently''s Holistic Detective Agency.', 282, null, 1987, 105676, (select id from series where hardcover_id = 2795), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Maze Runner', 'James Dashner', '1908435135', 'https://assets.hardcover.app/edition/18389345/d60336cd7d6335d702d08e76d8de476381fc65f1.jpeg', 'Sixteen-year-old Thomas wakes up with no memory in the middle of a maze and realizes he must work with the community in which he finds himself if he is to escape.', 386, null, 2009, 109009, (select id from series where hardcover_id = 1073), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Divergent', 'Veronica Roth', '8251682843', 'https://assets.hardcover.app/edition/22182301/7276222-L.jpg', '"Beatrice must choose between staying with her Abnegation family and transferring factions. Her choice will shock her community and herself. But the newly christened Tris also has a secret, one she''s determined to keep hidden, because in this world, what makes you different makes you dangerous."-- Provided by Amazon', 330, 671, 2011, 109344, (select id from series where hardcover_id = 1489), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Knife of Never Letting Go', 'Patrick Ness', '6020379280', 'https://assets.hardcover.app/edition/30399780/634fa5a948c443a2feb63a29bab7600305d735cf.jpeg', 'An unflinching novel about the impossible choices of growing up, by an award-winning writer.Imagine you''re the only boy in a town of men. And you can hear everything they think. And they can hear everything you think. Imagine you don''t fit in with their plans... Todd Hewitt is just one month away from the birthday that will make him a man. But his town has been keeping secrets from him. Secrets that are going to force him to run...', 512, null, 2008, 110466, (select id from series where hardcover_id = 1197), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Silver Chair', 'C. S. Lewis, Pauline Baynes', '000775499X', 'https://assets.hardcover.app/edition/23300509/a40d2deebd39afff8b15aff23e66e62765d228b3.jpeg', 'Jill and Eustace must rescue the Prince from the evil Witch.', 183, null, 1953, 110498, (select id from series where hardcover_id = 5485), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Contact', 'Carl Sagan', '0785787828', 'https://assets.hardcover.app/edition/30437772/51fbaf42-7413-424a-b4c9-a56d993e4148.jpeg', 'The future is here…in an adventure of cosmic dimension. When a signal is discovered that seems to come from far beyond our solar system, a multinational team of scientists decides to find the source. What follows is an eye-opening journey out to the stars to the most awesome encounter in human history. Who—or what—is out there? Why are they watching us? And what do they want with us?', 432, null, 1985, 111638, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadow Rising', 'Robert Jordan', '0312854315', 'https://assets.hardcover.app/edition/30553432/30381ad7-ca1f-4b9f-ba15-c797b5b18462.png', 'The seals of Shayol Ghul are weak now, and the Dark One reaches out. The Shadow is rising to cover humankind.

In Tar Valon, Min sees portents of hideous doom. Will the White Tower itself be broken?

In the Two Rivers, the Whitecloaks ride in pursuit of a man with golden eyes, and in pursuit of the Dragon Reborn.

In Cantorin, among the Sea Folk, High Lady Suroth plans the return of the Seanchan armies to the mainland.

In the Stone of Tear, the Lord Dragon considers his next move. It will be something no one expects, not the Black Ajah, not Tairen nobles, not Aes Sedai, not Egwene or Elayne or Nynaeve.

Against the Shadow rising stands the Dragon Reborn.....', 1024, null, 1992, 114913, (select id from series where hardcover_id = 1097), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sabriel', 'Garth Nix', '9722329421', 'https://assets.hardcover.app/external_data/61088220/ca7d70f51f4ca550f27c36c6fd2aa1d4b8e95b89.jpeg', 'For many years Sabriel has lived outside the walls of the Old Kingdom, away from the random power of Free Magic, and away from the Dead who won''t stay dead. But now her father, the Mage Abhorsen, is missing, and to find him Sabriel must cross back into that treacherous world - and face the power of her own extraordinary destiny.', 396, null, 1995, 118111, (select id from series where hardcover_id = 3510), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Watership Down', 'Richard Adams', '0241953235', 'https://assets.hardcover.app/external_data/60155887/68b7b72b5604732f67abc2d3d3316bd585eeb3fc.jpeg', 'A worldwide bestseller for more than fifty years, Watership Down is one of the most beloved novels of all time. Set in England’s Downs, a once idyllic rural landscape, this stirring tale follows a band of very special creatures on their flight from the intrusion of man and the certain destruction of their home. Led by a stouthearted pair of brothers, they journey from their native Sandleford Warren, through the harrowing trials posed by predators and adversaries, and toward the dream of a mysterious promised land and a more perfect society.', 385, null, 1972, 121583, (select id from series where hardcover_id = 5482), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Slaughterhouse-Five', 'Kurt Vonnegut', '0808514571', 'https://assets.hardcover.app/edition/17079379/6cd33f6e07aae9f2a3f5299de4fe48c07571dd66.jpeg', 'Slaughterhouse-Five, an American classic, is one of the world’s great antiwar books. Centering on the infamous World War II firebombing of Dresden, the novel is the result of what Kurt Vonnegut described as a twenty-three-year struggle to write a book about what he had witnessed as an American prisoner of war. It combines historical fiction, science fiction, autobiography, and satire in an account of the life of Billy Pilgrim, a barber’s son turned draftee turned optometrist turned alien abductee. As Vonnegut had, Billy experiences the destruction of Dresden as a POW. Unlike Vonnegut, he experiences time travel, or coming “unstuck in time.”

An instant bestseller, Slaughterhouse-Five made Kurt Vonnegut a cult hero in American literature, a reputation that only strengthened over time, despite his being banned and censored by some libraries and schools for content and language. But it was precisely those elements of Vonnegut’s writing—the political edginess, the genre-bending inventiveness, the frank violence, the transgressive wit—that have inspired generations of readers not just to look differently at the world around them but to find the confidence to say something about it. Authors as wide-ranging as Norman Mailer, John Irving, Michael Crichton, Tim O’Brien, Margaret Atwood, Elizabeth Strout, David Sedaris, Jennifer Egan, and J. K. Rowling have all found inspiration in Vonnegut’s words. Jonathan Safran Foer has described Vonnegut as “the kind of writer who made people—young people especially—want to write.” George Saunders has declared Vonnegut to be “the great, urgent, passionate American writer of our century, who offers us . . . a model of the kind of compassionate thinking that might yet save us from ourselves.”

Fifty years after its initial publication at the height of the Vietnam War, Vonnegut''s portrayal of political disillusionment, PTSD, and postwar anxiety feels as relevant, darkly humorous, and profoundly affecting as ever, an enduring beacon through our own era’s uncertainties.', 215, null, 1969, 122240, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('An Ember in the Ashes', 'Sabaa Tahir', '3641325773', 'https://assets.hardcover.app/edition/30506636/a927951df8ae0f58ae9c16ad81bd708168099e22.jpeg', 'Under the Martial Empire, defiance is met with death. Those who do not vow their blood and bodies to the Emperor risk the execution of their loved ones and the destruction of all they hold dear.

It is in this brutal world, inspired by ancient Rome, that Laia lives with her grandparents and older brother. The family ekes out an existence in the Empire’s impoverished backstreets. They do not challenge the Empire. They’ve seen what happens to those who do.

But when Laia’s brother is arrested for treason, Laia is forced to make a decision. In exchange for help from rebels who promise to rescue her brother, she will risk her life to spy for them from within the Empire’s greatest military academy.

There, Laia meets Elias, the school’s finest soldier—and secretly, its most unwilling. Elias wants only to be free of the tyranny he’s being trained to enforce. He and Laia will soon realize that their destinies are intertwined—and that their choices will change the fate of the Empire itself.', 481, null, 2015, 122632, (select id from series where hardcover_id = 1795), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Horse and His Boy', 'C. S. Lewis', '0007323085', 'https://assets.hardcover.app/edition/10394026/6da3ce38bb8389ac45abcda6f9037f99c9058a33.jpeg', 'The Horse and his Boy is a stirring and dramatic fantasy story that finds a young boy named Shasta on the run from his homeland with the talking horse, Bree. When the pair discover a deadly plot by the Calormen people to conquer the land of Narnia, the race is on to warn the inhabitants of the impending danger and to rescue them all from certain death.', 224, null, 1952, 125045, (select id from series where hardcover_id = 5485), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sparrow', 'Mary Doria Russell', '1407057030', 'https://assets.hardcover.app/book_mappings/7333094/3ecac6076e305cebd907d629e9d6d6e230ab0bbf.jpeg', 'The Sparrow is a novel about a remarkable man, a living saint, a life-long celibate and Jesuit priest, who undergoes an experience so harrowing and profound that it makes him question the existence of God. This experience--the first contact between human beings and intelligent extraterrestrial life--begins with a small mistake and ends in a horrible catastrophe.', 515, null, 1996, 131995, (select id from series where hardcover_id = 5522), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Never Let Me Go', 'Kazuo Ishiguro', '0739457950', 'https://assets.hardcover.app/book_mappings/7332369/addc181b29fba8c0bda914667f319c1cc2e74843.jpeg', 'It was a place of mercurial cliques and mysterious rules where teachers were constantly reminding their charges of how special they were.

Now, years later, Kathy is a young woman. Ruth and Tommy have reentered her life. And for the first time she is beginning to look back at their shared past and understand just what it is that makes them special—and how that gift will shape the rest of their time together.', 288, 580, 2000, 132314, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wyrd Sisters', 'Terry Pratchett', '1473200210', 'https://assets.hardcover.app/edition/31942478/43f5b81abef6c78efe556fcd573499e7b9ae0e3d.jpeg', 'Granny Weatherwax, Nanny Ogg, and Maigrat have fairy godmother-dom thrust upon them.', 271, null, 1988, 133650, (select id from series where hardcover_id = 1018), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadows of Self', 'Brandon Sanderson', '147320822X', 'https://assets.hardcover.app/book_mappings/7332804/bea1010aefbae37a106a79e85f9d60f70bc3fdc5.jpeg', 'Shadows of Self shows Mistborn’s society evolving as technology and magic mix, the economy grows, democracy contends with corruption, and religion becomes a growing cultural force, with four faiths competing for converts.

This bustling, optimistic, but still shaky society now faces its first instance of terrorism, crimes intended to stir up labor strife and religious conflict. Wax and Wayne, assisted by the lovely, brilliant Marasi, must unravel the conspiracy before civil strife stops Scadrial’s progress in its tracks.

Shadows of Self will give fans of The Alloy of Law everything they’ve been hoping for and, this being a Brandon Sanderson book, more, much more.', 376, 757, 2015, 135725, (select id from series where hardcover_id = 10825), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Second Foundation', 'Isaac Asimov', '504094781X', 'https://assets.hardcover.app/editions/30404895/4352386332856053.jpg', 'In the third book of the Foundation trilogy the secretly developed Second Foundation vies with a deadly mutant.', 254, null, 1952, 136548, (select id from series where hardcover_id = 5450), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fellowship of the Ring', 'J.R.R. Tolkien', '3608107134', 'https://assets.hardcover.app/edition/29029601/6d64b05efec0ccb215640b38d8c6bc4c712da0f5.jpeg', 'In ancient times the Rings of Power were crafted by the Elven-smiths, and Sauron, the Dark Lord, forged the One Ring, filling it with his own power so that he could rule all others. But the One Ring was taken from him, and though he sought it throughout Middle-earth, it remained lost to him. After many ages it fell into the hands of Bilbo Baggins, as told in The Hobbit.

In a sleepy village in the Shire, young Frodo Baggins finds himself faced with an immense task, as his elderly cousin Bilbo entrusts the Ring to his care. Frodo must leave his home and make a perilous journey across Middle-earth to the Cracks of Doom, there to destroy the Ring and foil the Dark Lord in his evil purpose.', 407, 1358, 1954, 139773, (select id from series where hardcover_id = 1130), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Stardust', 'Neil Gaiman', '0061793078', 'https://assets.hardcover.app/edition/30737789/6a01d7ae-02fb-4951-a33d-c319ce55b5d1.jpg', 'Tristran thorn promised to bring back a fallen star. So he sets out on a journey to fulfill the request of his beloved, the hauntingly beautiful Victoria Forester—and stumbles into the enchanted realm that lies beyond the wall of his English country town. Rich with adventure and magic, Stardust is one of master storyteller Neil Gaiman''s most beloved tales, and the inspiration for the hit movie.', 368, null, 1997, 142883, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Poppy War', 'R.F. Kuang', '0008239843', 'https://assets.hardcover.app/edition/30474703/a131f38041ff2c99c8667ca5fdf142f27da739ce.jpeg', '"To the test officials, who couldn’t believe a war orphan from Rooster Province could pass without cheating; to Rin’s guardians, who believed they’d finally be able to marry her off and further their criminal enterprise; and to Rin herself, who realized she was finally free of the servitude and despair that had made up her daily existence. That she got into Sinegard—the most elite military school in Nikan—was even more surprising.

But surprises aren’t always good.

Because being a dark-skinned peasant girl from the south is not an easy thing at Sinegard. Targeted from the outset by rival classmates for her color, poverty, and gender, Rin discovers she possesses a lethal, unearthly power—an aptitude for the nearly-mythical art of shamanism. Exploring the depths of her gift with the help of a seemingly insane teacher and psychoactive substances, Rin learns that gods long thought dead are very much alive—and that mastering control over those powers could mean more than just surviving school.

For while the Nikara Empire is at peace, the Federation of Mugen still lurks across a narrow sea. The militarily advanced Federation occupied Nikan for decades after the First Poppy War, and only barely lost the continent in the Second. And while most of the people are complacent to go about their lives, a few are aware that a Third Poppy War is just a spark away . . .

Rin’s shamanic powers may be the only way to save her people. But as she finds out more about the god that has chosen her, the vengeful Phoenix, she fears that winning the war may cost her humanity . . . and that it may already be too late."-- Provided by Amazon', 527, 1167, 2018, 143200, (select id from series where hardcover_id = 985), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ballad of Songbirds and Snakes', 'Suzanne Collins', '1760265330', 'https://assets.hardcover.app/edition/30399380/da2b22ed-27e3-495f-9a64-761fe230195c.jpg', 'It is the morning of the reaping that will kick off the tenth annual Hunger Games. In the Capitol, eighteen-year-old Coriolanus Snow is preparing for his one shot at glory as a mentor in the Games. The once-mighty house of Snow has fallen on hard times, its fate hanging on the slender chance that Coriolanus will be able to outcharm, outwit, and outmaneuver his fellow students to mentor the winning tribute. The odds are against him. He''s been given the humiliating assignment of mentoring the female tribute from District 12, the lowest of the low. Their fates are now completely intertwined - every choice Coriolanus makes could lead to favor or failure, triumph or ruin. Inside the arena, it will be a fight to the death. Outside the arena, Coriolanus starts to feel for his doomed tribute . . . and must weigh his need to follow the rules against his desire to survive no matter what it takes.', 541, null, 2020, 143390, (select id from series where hardcover_id = 1015), 0) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Bones', 'Cassandra Clare', '8804632356', 'https://assets.hardcover.app/book_mappings/7332620/060557a70ce979561a51d5d32bbadcdaf19ade05.jpeg', 'When Clary Fray heads out to the Pandemonium Club in New York City, she hardly expects to witness a murder. Much less a murder committed by three teenagers covered with odd markings. This is Clary''s first meeting with the Shadowhunters, warriors dedicated to ridding the earth of demons - and keeping the odd werewolves and vampires in line. It''s also her first meeting with gorgeous, golden-haired Jace. Within twenty-four hourse Clary is pulled into Jace''s world with a vengeance, when her mother disappears and Clary herself is attacked by a demon. But why would demons be interested in an ordinary mundane like Clary? And how did she suddenly get the Sight? The Shadowhunters would like to know...', 485, 824, 2007, 144062, (select id from series where hardcover_id = 5473), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Dance with Dragons', 'George R.R. Martin', '9610131840', 'https://assets.hardcover.app/external_data/60312701/d2c85ef45f183d295c497ecda8018b40d3974ffb.jpeg', 'Dubbed “the American Tolkien” by Time magazine, George R. R. Martin has earned international acclaim for his monumental cycle of epic fantasy. Now the #1 New York Times bestselling author delivers the fifth book in his landmark series—as both familiar faces and surprising new forces vie for a foothold in a fragmented empire. 

In the aftermath of a colossal battle, the future of the Seven Kingdoms hangs in the balance -- beset by newly emerging threats from every direction. In the east, Daenerys Targaryen, the last scion of House Targaryen, rules with her three dragons as queen of a city built on dust and death. But Daenerys has thousands of enemies, and many have set out to find her. As they gather, one young man embarks upon his own quest for the queen, with an entirely different goal in mind. 

Fleeing from Westeros with a prince on his head. Tyrion Lannister, too, is making his way to Daenerys. but his newest allies in this quest are not the rag-tag band they seem, and at their heart lies one who could undo Daenerys''s claim to Westeros forever.

Meanwhile, to the north lies the mammoth wall of ice and stone -- a structure only as strong as those guarding it. There, Jon Snow, 998th Lord Commander of the Night''s Watch, will face his greatest challenge. For he has powerful foes not only within the Watch but also beyond, in the land of the creature of ice.

From all corners, bitter conflicts reignite, intimate betrayals are perpetrated, and a grand cast of outlaws and priests, soldiers and skinchangers, nobles and slaves, will face seemingly insurmountable obstacles. Some will fail, others will grow in the strength of darkness. But in a time of rising restlessness, the tides of destiny and politics will lead inevitably to the greatest dance of all.', 1016, 2935, 2011, 144636, (select id from series where hardcover_id = 981), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Consider Phlebas', 'Iain M. Banks', '8932907765', 'https://assets.hardcover.app/edition/25245221/035c7c4e-7508-410f-9a6b-71e048c2daa6.jpg', 'The war raged across the galaxy. Billions had died, billions more were doomed. Moons, planets, the very stars themselves, faced destruction, cold-blooded, brutal, and worse, random. The Idirans fought for their Faith; the Culture for its moral right to exist. Principles were at stake. There could be no surrender.

Within the cosmic conflict, an individual crusade. Deep within a fabled labyrinth on a barren world, a Planet of the Dead proscribed to mortals, lay a fugitive Mind. Both the Culture and the Idirans sought it. It was the fate of Horza, the Changer, and his motley crew of unpredictable mercenaries, human and machine, actually to find it, and with it their own destruction.', 469, null, 1987, 148332, (select id from series where hardcover_id = 1102), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Assassin''s Quest', 'Robin Hobb', '0553565699', 'https://assets.hardcover.app/editions/23717929/7510996869893389.jpg', 'King Shrewd is dead at the hands of his son Regal. As is Fitz--or so his enemies and friends believe. But with the help of his allies and his beast magic, he emerges from the grave, deeply scarred in body and soul. The kingdom also teeters toward ruin: Regal has plundered and abandoned the capital, while the rightful heir, Prince Verity, is lost to his mad quest--perhaps to death. Only Verity''s return--or the heir his princess carries--can save the Six Duchies.

But Fitz will not wait. Driven by loss and bitter memories, he undertakes a quest: to kill Regal. The journey casts him into deep waters, as he discovers wild currents of magic within him--currents that will either drown him or make him something more than he was.', 757, null, 1997, 149300, (select id from series where hardcover_id = 5513), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Plague', 'Albert Camus, Stuart Gilbert', '3869749288', 'https://assets.hardcover.app/edition/2707798/7be060fefe972fcc6c85a3a65649d64d2517ad03.jpeg', 'The Plague (French: La Peste) is a novel by Albert Camus, published in 1947, that tells the story of a plague sweeping the French Algerian city of Oran. It asks a number of questions relating to the nature of destiny and the human condition. The characters in the book, ranging from doctors to vacationers to fugitives, all help to show the effects the plague has on a populace.', 296, null, 1947, 149844, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Long Walk', 'Richard Bachman, Stephen King', '0451087542', 'https://assets.hardcover.app/external_data/2082318/6eeb7adc669e9e6288c4d43cb0c6449b4695ab38.jpeg', 'In a dystopian near-future, America has fallen on hard times. Sixteen-year-old Ray Garraty is about to compete in the annual match of stamina and wits known as the Long Walk.

One hundred boys must keep a steady pace of four miles per hour day and night, without ever stopping. The winner gets ''The Prize'' - anything he wants for the rest of his life. But the rules of the Long Walk are harsh and the stakes could not be higher. There is no finish line-the winner is the last man standing. Contestants cannot receive any outside aid whatsoever. Slow down under the speed limit and you''re given a warning. Three warnings and you''re out of the game - forever.', 328, null, 1979, 149896, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Memory Police', 'Stephen    Snyder, Markus Juslin, Yoko Ogawa', '9189175166', 'https://assets.hardcover.app/external_data/45951583/f8c2899b7d2fbe2fef3ccce33df90c50c2d4c3e3.jpeg', '"Most of the island''s inhabitants are oblivious to these changes, while those few imbued with the power to recall the lost objects live in fear of the draconian Memory Police, who are committed to ensuring that what has disappeared remains forgotten.

When a young woman who is struggling to maintain her career as a novelist discovers that her editor is in danger from the Memory Police, she concocts a plan to hide him beneath her floorboards. As fear and loss close in around them, they cling to her writing as the last way of preserving the past."-- Provided by Amazon', 289, null, 1994, 150531, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Drawing of the Three', 'Stephen King', '5170805276', 'https://assets.hardcover.app/edition/30901138/35ba68fe-a797-4f29-9d5c-6ddf2944ad4d.png', 'The second leads to the 1960s and conflicted civil rights activist Odetta Holmes. The final door reveals Jack Mort, a deadly serial killer, in the 1970s. Mort is stalking Jake, the young boy Roland met in Mid-World.

As titanic forces gather, a savage struggle between underworld evil and otherworldly enemies threatens to bring an end to Roland''s journey toward the Dark Tower...', 454, null, 1980, 151239, (select id from series where hardcover_id = 3413), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Scanner Darkly', 'Philip K. Dick', '0547572174', 'https://assets.hardcover.app/edition/30394702/7993da38a2aae32e2eafb8e00959310ece90b37b.jpeg', 'Substance D is not known as Death for nothing. It is the most toxic drug ever to find its way on to the streets of LA. It destroys the links between the brain''s two hemispheres, causing, first, disorientation and then complete and irreversible brain damage.

The undercover narcotics agent who calls himself Bob Arctor is desperate to discover the ultimate source of supply. But to find any kind of lead he has to pose as a user and, inevitably, without realising what is happening, Arctor is soon as addicted as the junkies he works among...', 189, null, 1977, 152062, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Queen of Shadows', 'Sarah J. Maas', '3423717076', 'https://assets.hardcover.app/external_data/60670456/1876238af5e412691576aea3dd52f14d12025e19.jpeg', 'Celaena Sardothien has embraced her identity as Aelin Galathynius, Queen of Terrasen. But before she can reclaim her throne, she must fight.

She will fight for her cousin, a warrior prepared to die for her. She will fight for her friend, a young man trapped in an unspeakable prison. And she will fight for her people, enslaved to a brutal king and awaiting their lost queen’s triumphant return.

Everyone Aelin loves has been taken from her. Everything she holds dear is in danger. But she has the heart of a queen-and that heart beats for vengeance.

In this fourth book in the Throne of Glass series, no one will escape the queen’s wrath.', 672, null, 2015, 153090, (select id from series where hardcover_id = 5509), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Voyage of the Dawn Treader', 'C. S. Lewis, Pauline Baynes', '9574553280', 'https://assets.hardcover.app/edition/29896864/06841872ce614fb2cbded9e6f2204ddcd1d10d51.jpeg', 'Lucy, Edmund, and their cousin travel back to Narnia through a painting where they board a ship named "The Dawn Treader." They find King Caspian and a mouse on the ship and they find mystical creatures and go on a mission that will decide Narnia''s fate!', 256, null, 1951, 154097, (select id from series where hardcover_id = 5485), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mostly Harmless', 'Douglas Adams, Dirk Maggs', '3453082303', 'https://assets.hardcover.app/edition/31618989/b5ba4f72-8f87-411e-8839-1340296c6395.jpg', 'However, instead of being disheartened, Arthur Dent makes the terrible mistake of starting to enjoy life a bit—and immediately all hell breaks loose.

Hell takes a number of forms: there’s the standard Ford Prefect version, in the shape of an all-new edition of The Hitchhiker’s Guide to the Galaxy, and a totally unexpected manifestation in the form of a teenage girl who startles Arthur Dent by being his daughter when he didn’t even know he had one. 

Can Arthur save the Earth from total multidimensional obliteration? Can he save the Guide from a hostile alien takeover? Can he save his daughter, Random, from herself? Of course not. He never works out exactly what is going on. Will you?', 250, null, 1992, 154964, (select id from series where hardcover_id = 3400), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ender''s Game', 'Orson Scott Card', '9662665226', 'https://assets.hardcover.app/external_data/61075411/dd7e2678859a7230551382016b03219be682e693.jpeg', 'In order to develop a secure defense against a hostile alien race''s next attack, government agencies breed child geniuses and train them as soldiers. A brilliant young boy, Andrew "Ender" Wiggin lives with his kind but distant parents, his sadistic brother Peter, and the person he loves more than anyone else, his sister Valentine. Peter and Valentine were candidates for the soldier-training program but didn''t make the cut—young Ender is the Wiggin drafted to the orbiting Battle School for rigorous military training.

Ender''s skills make him a leader in school and respected in the Battle Room, where children play at mock battles in zero gravity. Yet growing up in an artificial community of young soldiers Ender suffers greatly from isolation, rivalry from his peers, pressure from the adult teachers, and an unsettling fear of the alien invaders. His psychological battles include loneliness, fear that he is becoming like the cruel brother he remembers, and fanning the flames of devotion to his beloved sister.

Is Ender the general Earth needs? But Ender is not the only result of the genetic experiments. The war with the Buggers has been raging for a hundred years, and the quest for the perfect general has been underway for almost as long. Ender''s two older siblings are every bit as unusual as he is, but in very different ways. Between the three of them lie the abilities to remake a world. If, that is, the world survives.', 256, null, 1985, 158268, (select id from series where hardcover_id = 1059), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sea of Monsters', 'Rick Riordan', '1423131960', 'https://assets.hardcover.app/edition/30839331/387676ce-5017-4afe-834b-78d2d4980f6d.jpg', 'When Thalia’s tree is mysteriously poisoned, the magical borders of Camp Half-Blood begin to fail. Now Percy and his friends have just days to find the only magic item powerful to save the camp before it is overrun by monsters. The catch: they must sail into the Sea of Monsters to find it. Along the way, Percy must stage a daring rescue operation to save his old friend Grover, and he learns a terrible secret about his own family, which makes him question whether being the son of Poseidon is an honor or a curse.', 279, 476, 2006, 159698, (select id from series where hardcover_id = 5193), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Legend', 'Marie Lu', '6072409083', 'https://assets.hardcover.app/editions/30399822/9f124db3-f031-43b4-b714-0657ce818d0c-A1MEgpPSzIL._AC_UF1000,1000_QL80_.jpg', 'What was once the western United States is now home to the Republic, a nation perpetually at war with its neighbors. Born into an elite family in one of the Republic''s wealthiest districts, fifteen-year-old June is a prodigy being groomed for success in the Republic''s highest military circles. Born into the slums, fifteen-year-old Day is the country''s most wanted criminal. But his motives may not be as malicious as they seem.

From very different worlds, June and Day have no reason to cross paths - until the day June''s brother, Metias, is murdered and Day becomes the prime suspect. Caught in the ultimate game of cat and mouse, Day is in a race for his family''s survival, while June seeks to avenge Metias''s death. But in a shocking turn of events, the two uncover the truth of what has really brought them together, and the sinister lengths their country will go to keep its secrets.

Full of nonstop action, suspense, and romance, this novel is sure to move readers as much as it thrills.', 352, null, 2010, 168987, (select id from series where hardcover_id = 5717), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Piranesi', 'Susanna Clarke', '3453321987', 'https://assets.hardcover.app/editions/30480426/ec301cb7-b118-48fd-aa3a-5d336e61c182.jpg', 'Piranesi’s house is no ordinary building: its rooms are infinite, its corridors endless, its walls are lined with thousands upon thousands of statues, each one different from all the others. Within the labyrinth of halls an ocean is imprisoned; waves thunder up staircases, rooms are flooded in an instant. But Piranesi is not afraid; he understands the tides as he understands the pattern of the labyrinth itself. He lives to explore the house.

There is one other person in the house—a man called The Other, who visits Piranesi twice a week and asks for help with research into A Great and Secret Knowledge. But as Piranesi explores, evidence emerges of another person, and a terrible truth begins to unravel, revealing a world beyond the one Piranesi has always known.', 245, 419, 2019, 175280, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Catching Fire', 'Suzanne Collins', '8055121729', 'https://assets.hardcover.app/edition/7988314/dbef0f7db3fc4a6157550d5f7cc01563af40315c.jpeg', 'The second novel in the worldwide bestselling series by Suzanne Collins, now an acclaimed film series starring Jennifer Lawrence

Against all odds, Katniss has won the Hunger Games. She and fellow District 12 tribute Peeta Mellark are miraculously still alive. Katniss should be relieved, happy even. After all, she has returned to her family and her longtime friend, Gale. Yet nothing is the way Katniss wishes it to be. Gale holds her at an icy distance. Peeta has turned his back on her completely. And there are whispers of a rebellion against the Capitol.

Much to her shock, Katniss has fueled an unrest she''s afraid she cannot stop. And what scares her even more is that she''s not entirely convinced she should try. As time draws near for Katniss and Peeta to visit the districts on the Capitol''s cruel Victory Tour, the stakes are higher than ever. If they can''t prove they are lost in their love for each other, the consequences will be horrifying.', 391, null, 2009, 175780, (select id from series where hardcover_id = 1015), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fool Moon', 'Jim Butcher', '1480581127', 'https://assets.hardcover.app/edition/2186537/8dd35c83467742c885281970f3d8b8300c1f4b9d.jpeg', 'You’d think there’d be a little more action for the only professional wizard listed in the Chicago phone book. But lately, Harry Dresden hasn’t been able to dredge up any kind of work: magical, mundane, or menial.
 
Just when it looks like he can’t afford his next meal, a murder comes along that requires his particular brand of supernatural expertise. There’s a brutally mutilated corpse, and monstrous animal markings at the scene. Not to mention that the killing took place on the night of a full moon. Harry knows exactly where this case is headed. Take three guesses—and the first two don’t count...', 432, null, 2001, 183010, (select id from series where hardcover_id = 990), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Empire of Storms', 'Sarah J. Maas', '3423717890', 'https://assets.hardcover.app/edition/30825891/3c2ede158a5324ac9d331e2a29f6e5c35a073071.jpeg', 'The long path to the throne has only just begun for Aelin Galathynius as war looms on the horizon. Loyalties have been broken and bought, friends have been lost and gained, and those who possess magic find themselves increasingly at odds with those who don’t.

With her heart sworn to the warrior-prince by her side and her fealty pledged to the people she is determined to save, Aelin will delve into the depths of her power to protect those she loves. But as monsters emerge from the horrors of the past, dark forces stand poised to claim her world. The only chance for salvation lies in a desperate quest that may take more from Aelin than she has to give, a quest that forces her to choose what-and who-she’s willing to sacrifice for the sake of peace.

Kingdoms collide in this fifth book in the #1 New York Times bestselling Throne of Glass series.', 689, null, 2016, 183545, (select id from series where hardcover_id = 5509), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gathering Storm', 'Brandon Sanderson, Robert Jordan', '1429960833', 'https://assets.hardcover.app/edition/30594677/ca616ce8-a676-45da-b06f-7881ef52b5e4.png', 'In this epic novel, Robert Jordan’s international bestselling series begins its dramatic conclusion. Rand al’Thor, the Dragon Reborn, struggles to unite a fractured network of kingdoms and alliances in preparation for the Last Battle. As he attempts to halt the Seanchan encroachment northward, wishing he could form at least a temporary truce with the invaders, his allies watch in terror the shadow that seems to be growing within the heart of the Dragon Reborn himself.

Egwene al’Vere, the Amyrlin Seat of the rebel Aes Sedai, is a captive of the White Tower and subject to the whims of their tyrannical leader. As days tick toward the Seanchan attack she knows is imminent, Egwene works to hold together the disparate factions of Aes Sedai while providing leadership in the face of increasing uncertainty and despair. Her fight will prove the mettle of the Aes Sedai, and her conflict will decide the future of the White Tower, and possibly the world itself.

The Wheel of Time turns, and Ages come and pass. What was, what will be, and what is, may yet fall under the Shadow.', 848, null, 2009, 183698, (select id from series where hardcover_id = 1097), 12) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Childhood''s End', 'Arthur C. Clarke, Adam Roberts', '9955754109', 'https://assets.hardcover.app/edition/30528803/96583837-b539-45fa-b119-bff278b67fcf.jpeg', 'The Overlords appeared suddenly over every city—intellectually, technologically, and militarily superior to humankind. Benevolent, they made few demands: unify earth, eliminate poverty, and end war. With little rebellion, humankind agreed, and a golden age began. But at what cost? With the advent of peace, man ceases to strive for creative greatness, and a malaise settles over the human race. To those who resist, it becomes evident that the Overlords have an agenda of their own. As civilization approaches the crossroads, will the Overlords spell the end for humankind . . . or the beginning?', 277, null, 1953, 184949, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Crooked Kingdom', 'Leigh Bardugo', '1250409004', 'https://assets.hardcover.app/editions/15324026/454101783196428.jpg', 'Kaz Brekker and his crew have just pulled off a heist so daring even they didn''t think they''d survive. But instead of divvying up a fat reward, they''re right back to fighting for their lives. Double-crossed and badly weakened, the crew is low on resources, allies, and hope. As powerful forces from around the world descend on Ketterdam to root out the secrets of the dangerous drug known as jurda parem, old rivals and new enemies emerge to challenge Kaz''s cunning and test the team''s fragile loyalties. A war will be waged on the city''s dark and twisting streets - a battle for revenge and redemption that will decide the fate of the Grisha world.', 546, null, 2016, 186373, (select id from series where hardcover_id = 1061), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Calculating Stars', 'Mary Robinette Kowal', '8835710723', 'https://assets.hardcover.app/external_data/59520925/c638096fefa701e5b4431d2818ff3c80e5c2c489.jpeg', 'On a cold spring night in 1952, a huge meteorite fell to earth and obliterated much of the east coast of the United States, including Washington D.C. The ensuing climate cataclysm will soon render the earth inhospitable for humanity, as the last such meteorite did for the dinosaurs. This looming threat calls for a radically accelerated effort to colonize space, and requires a much larger share of humanity to take part in the process. Elma York’s experience as a WASP pilot and mathematician earns her a place in the International Aerospace Coalition’s attempts to put man on the moon, as a calculator. But with so many skilled and experienced women pilots and scientists involved with the program, it doesn’t take long before Elma begins to wonder why they can’t go into space, too. Elma’s drive to become the first Lady Astronaut is so strong that even the most dearly held conventions of society may not stand a chance against her.', 384, null, 2018, 186438, (select id from series where hardcover_id = 1141), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Silent Patient', 'Alex Michaelides', '5041053111', 'https://assets.hardcover.app/edition/30408097/283e4f71-ecbc-4e2c-8876-6fdfad786456.jpg', 'Alicia Berenson’s life is seemingly perfect. A famous painter married to an in-demand fashion photographer, she lives in a grand house with big windows overlooking a park in one of London’s most desirable areas. One evening her husband Gabriel returns home late from a fashion shoot, and Alicia shoots him five times in the face, and then never speaks another word.

Alicia’s refusal to talk, or give any kind of explanation, turns a domestic tragedy into something far grander, a mystery that captures the public imagination and casts Alicia into notoriety. The price of her art skyrockets, and she, the silent patient, is hidden away from the tabloids and spotlight at the Grove, a secure forensic unit in North London.

Theo Faber is a criminal psychotherapist who has waited a long time for the opportunity to work with Alicia. His determination to get her to talk and unravel the mystery of why she shot her husband takes him down a twisting path into his own motivations—a search for the truth that threatens to consume him....', 290, 514, 2018, 187993, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foundation', 'Isaac Asimov', '0373195206', 'https://assets.hardcover.app/edition/16870525/0814d2fc4cb8a9f953d08d35fc4fb94b616dc96d.jpeg', 'One of the great masterworks of science fiction, the Foundation novels of Isaac Asimov are unsurpassed for their unique blend of nonstop action, daring ideas, and extensive world-building. 

The story of our future begins with the history of Foundation and its greatest psychohistorian: Hari Seldon.  For twelve thousand years the Galactic Empire has ruled supreme. Now it is dying.  Only Hari Seldon, creator of the revolutionary science of psychohistory, can see into the future--a dark age of ignorance, barbarism, and warfare that will last thirty thousand years. To preserve knowledge and save mankind, Seldon gathers the best minds in the Empire--both scientists and scholars--and brings them to a bleak planet at the edge of the Galaxy to serve as a beacon of hope for future generations. He calls his sanctuary the Foundation.

But soon the fledgling Foundation finds itself at the mercy of corrupt warlords rising in the wake of the receding Empire. And mankind''s last best hope is faced with an agonizing choice: submit to the barbarians and live as slaves--or take a stand for freedom and risk total destruction.', 272, null, 1951, 188628, (select id from series where hardcover_id = 5450), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Annihilation', 'Jeff VanderMeer', '615544224X', 'https://assets.hardcover.app/edition/30917897/4af3d5db-12c3-4209-a3bc-be7d08467412.jpg', '"Nature has reclaimed the last vestiges of human civilization. The first expedition returned with reports of a pristine, Edenic landscape; the second expedition ended in mass suicide; the third expedition in a hail of gunfire as its members turned on one another. The members of the eleventh expedition returned as shadows of their former selves, and within weeks, all had died of cancer. In Annihilation, the first volume of Jeff VanderMeer''s Southern Reach trilogy, we join the twelfth expedition.

The group is made up of four women: an anthropologist; a surveyor; a psychologist, the de facto leader; and our narrator, a biologist. Their mission is to map the terrain, record all observations of their surroundings and of one another, and, above all, avoid being contaminated by Area X itself.

They arrive expecting the unexpected, and Area X delivers―they discover a massive topographic anomaly and life forms that surpass understanding―but it''s the surprises that came across the border with them and the secrets the expedition members are keeping from one another that change everything."-- Provided by Amazon', 208, null, 2014, 192491, (select id from series where hardcover_id = 1089), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('I, Robot', 'Isaac Asimov', '364113207X', 'https://assets.hardcover.app/edition/12373277/509ae6a85955acc6ed96febacdcbffb105f0ebea.jpeg', 'This classic science fiction masterwork by Isaac Asimov weaves stories about robots, humanity, and the deep questions of existence into a novel of shocking intelligence and heart. 

“A must-read for science-fiction buffs and literature enjoyers alike.”— The Guardian 
I, Robot , the first and most widely read book in Asimov’s Robot series, forever changed the world’s perception of artificial intelligence. Here are stories of robots gone mad, of mind-reading robots, and robots with a sense of humor. Of robot politicians, and robots who secretly run the world—all told with the dramatic blend of science fact and science fiction that has become Asimov’s trademark. 
The Three Laws of Robotics:
1) A robot may not injure a human being or, through inaction, allow a human being to come to harm.
2) A robot must obey orders given to it by human beings except where such orders would conflict with the First Law.
3) A robot must protect its own existence as long as such protection does not conflict with the First or Second Law. 
With these three, simple directives, Isaac Asimov formulated the laws governing robots’ behavior. In I, Robot , Asimov chronicles the development of the robot from its primitive origins in the present to its ultimate perfection in the not-so-distant future—a future in which humanity itself may be rendered obsolete. 

I, Robot is a fixup novel of science fiction short stories or essays by American writer Isaac Asimov. The stories originally appeared in the American magazines Super Science Stories and Astounding Science Fiction between 1940 and 1950 and were then compiled into a book for stand-alone publication by Gnome Press in 1950, in an initial edition of 5,000 copies. The stories are woven together by a framing narrative in which the fictional Dr. Susan Calvin tells each story to a reporter (who serves as the narrator) in the 21st century. Although the stories can be read separately, they share a theme of the interaction of humans, robots, and morality, and when combined they tell a larger story of Asimov''s fictional history of robotics.

Contains:
"Introduction" (the initial portion of the framing story or linking text)
"Robbie" (1940, 1950)
"Runaround" (1942)
"Reason" (1941)
"Catch That Rabbit" (1944)
"Liar!" (1941)
"Little Lost Robot" (1947)
"Escape!" (1945)
"Evidence" (1946)
"The Evitable Conflict" (1950)', 256, 546, 1940, 192946, (select id from series where hardcover_id = 1044), 0.1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Way of Shadows', 'Brent Weeks', '1400162866', 'https://assets.hardcover.app/external_data/25852439/e2e91f3f9265226e40f9667f576c1961c3980de7.jpeg', 'For Durzo Blint, assassination is an art. And he is the city''s most accomplished artist, his talents required from alleyway to courtly boudoir.
For Azoth, survival is precarious. Something you never take for granted. As a guild rat, he''s grown up in the slums, and learned the hard way to judge people quickly - and to take risks. Risks like apprenticing himself to Durzo Blint.
But to be accepted, Azoth must turn his back on his old life and embrace a new identity and name. As Kylar Stern, he must learn to navigate the assassins'' world of dangerous politics and strange magics - and cultivate a flair for death.', 395, null, 2008, 196346, (select id from series where hardcover_id = 5535), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mark of Athena', 'Rick Riordan', '9794337404', 'https://assets.hardcover.app/editions/30729803/7832699493593036.jpg', 'Annabeth is terrified. Just when she''s about to be reunited with Percy—after six months of being apart, thanks to Hera—it looks like Camp Jupiter is preparing for war. As Annabeth and her friends Jason, Piper, and Leo fly in on the Argo II, she can''t blame the Roman demigods for thinking the ship is a Greek weapon. With its steaming bronze dragon figurehead, Leo''s fantastical creation doesn''t appear friendly. Annabeth hopes that the sight of their praetor Jason on deck will reassure the Romans that the visitors from Camp Half-Blood are coming in peace.

And that''s only one of her worries. In her pocket, Annabeth carries a gift from her mother that came with an unnerving command: Follow the Mark of Athena. Avenge me. Annabeth already feels weighed down by the prophecy that will send seven demigods on a quest to find—and close—the Doors of Death. What more does Athena want from her?

Annabeth''s biggest fear, though, is that Percy might have changed. What if he''s now attached to Roman ways? Does he still need his old friends? As the daughter of the goddess of war and wisdom, Annabeth knows she was born to be a leader—but never again does she want to be without Seaweed Brain by her side

Narrated by four different demigods, The Mark of Athena is an unforgettable journey across land and sea to Rome, where important discoveries, surprising sacrifices, and unspeakable horrors await. Climb aboard the Argo II, if you dare. . . .', 604, null, 2012, 196511, (select id from series where hardcover_id = 5670), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Night Watch', 'Terry Pratchett', '3442545366', 'https://assets.hardcover.app/edition/31519121/4d88695273a0fd31a37f570468a539619181b039.jpeg', 'One moment, Sir Sam Vimes is in his old patrolman form, chasing a sweet-talking psychopath across the rooftops of Ankh-Morpork. The next, he''s lying naked in the street, having been sent back thirty years courtesy of a group of time-manipulating monks who won''t leave well enough alone. This Discworld is a darker place that Vimes remembers too well, three decades before his title, fortune, beloved wife, and impending first child. Worse still, the murderer he''s pursuing has been transported back also. Worst of all, it''s the eve of a fabled street rebellion that needlessly destroyed more than a few good (and not so good) men. Sam Vimes knows his duty, and by changing history he might just save some worthwhile necks—though it could cost him his own personal future. Plus there''s a chance to steer a novice watchman straight and teach him a valuable thing or three about policing, an impressionable young copper named Sam Vimes.', 484, null, 2002, 197349, (select id from series where hardcover_id = 1018), 29) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ruin and Rising', 'Leigh Bardugo', '162779221X', 'https://assets.hardcover.app/editions/30400871/bd1f832c-a01e-41f2-ab04-e074aaab8f67-ruin_and_rising.jpg', 'The Darkling rules Ravka from his shadow throne. Now the nation''s fate rests with a broken Sun Summoner, a disgraced tracker, and the shattered remnants of a once-great magical army.

Deep in an ancient network of tunnels and caverns, a weakened Alina must submit to the dubious protection of the Apparat and the zealots who worship her as a Saint. Yet her plans lie elsewhere, with the hunt for the elusive firebird and the hope that an outlaw prince still survives.

Alina will have to forge new alliances and put aside old rivalries as she and Mal race to find the last of Morozova''s amplifiers. But as she begins to unravel the Darkling''s secrets, she reveals a past that will forever alter her understanding of the bond they share and the power she wields. The firebird is the one thing that stands between Ravka and destruction—and claiming it could cost Alina the very future she’s fighting for.', 422, null, 2014, 198069, (select id from series where hardcover_id = 1067), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Subtle Knife', 'Philip Pullman', '5551171205', 'https://assets.hardcover.app/edition/23053099/70ad7fb9f2b1b74743346ae62b71673e5204fdad.jpeg', 'Lost in a new world, Lyra finds Will—a boy on the run, a murderer—a worthy and welcome ally. For this is a world where soul-eating Specters stalk the streets and witches share the skies with troops of angels.

Each is searching—Lyra for the meaning of Dark Matter, Will for his missing father—but what they find instead is a deadly secret, a knife of untold power. And neither Lyra nor Will suspects how tightly their lives, their loves, their destinies are bound together...until they are split apart.', null, null, 1995, 198704, (select id from series where hardcover_id = 1025), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadow of the Torturer', 'Gene Wolfe', '9731022201', 'https://assets.hardcover.app/edition/13931620/82857c69ee621b866457bd4d8406b7636fcbcd0b.jpeg', 'The Shadow of the Torturer is the first volume in the four-volume series, The Book of the New Sun. It is the tale of young Severian, an apprentice in the Guild of Torturers on the world called Urth, exiled for committing the ultimate sin of his profession -- showing mercy toward his victim -- and follows subsequent journey out of his home city of Nessus.', 276, null, 1980, 202147, (select id from series where hardcover_id = 1172), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Seveneves', 'Neal Stephenson', '0062334514', 'https://assets.hardcover.app/editions/6575988/9743380492518420.jpg', '"What would happen if the world were ending? A catastrophic event renders the earth a ticking time bomb. In a feverish race against the inevitable, nations around the globe band together to devise an ambitious plan to ensure the survival of humanity far beyond our atmosphere, in outer space. But the complexities and unpredictability of human nature coupled with unforeseen challenges and dangers threaten the intrepid pioneers, until only a handful of survivors remain . . . Five thousand years later, their progeny--seven distinct races now three billion strong--embark on yet another audacious journey into the unknown . . . to an alien world utterly transformed by cataclysm and time: Earth" --', 867, null, 2015, 202496, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Recursion', 'Blake Crouch', '1984886894', 'https://assets.hardcover.app/external_data/31968027/91983cb00d2a53d0c88cf8b9eacf2d7714428465.jpeg', 'Reality is broken.
 
At first, it looks like a disease. An epidemic that spreads through no known means, driving its victims mad with memories of a life they never lived. But the force that’s sweeping the world is no pathogen. It’s just the first shock wave, unleashed by a stunning discovery—and what’s in jeopardy is not our minds but the very fabric of time itself.
 
In New York City, Detective Barry Sutton is closing in on the truth—and in a remote laboratory, neuroscientist Helena Smith is unaware that she alone holds the key to this mystery . . . and the tools for fighting back.
 
Together, Barry and Helena will have to confront their enemy—before they, and the world, are trapped in a loop of ever-growing chaos.', 329, 647, 2018, 202782, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Storm Front', 'Jim Butcher', '5389249046', 'https://assets.hardcover.app/edition/5769057/2e530f75ff71f188b9bd260763bd3b09d5fb0455.jpeg', 'In the first novel in the #1 New York Times bestselling Dresden Files series, Harry Dresden’s investigation of a grisly double murder pulls him into the darkest depths of magical Chicago… As a professional wizard, Harry Dresden knows firsthand that the “everyday” world is actually full of strange and magical things—and most of them don’t play well with humans. And those that do enjoy playing with humans far too much. He also knows he’s the best at what he does. Technically, he’s the only at what he does. But even though Harry is the only game in town, business—to put it mildly—stinks. So when the Chicago P.D. bring him in to consult on a double homicide committed with black magic, Harry''s seeing dollar signs. But where there''s black magic, there''s a black mage behind it. And now that mage knows Harry''s name... “A great series—fast-paced, vividly realized and with a hero/narrator who’s excellent company.”—Cinescape', 372, null, 2000, 203347, (select id from series where hardcover_id = 990), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Uglies', 'Scott Westerfeld', '0606224327', 'https://assets.hardcover.app/editions/30714503/3417959155055859.jpg', 'Everybody gets to be supermodel gorgeous. What could be wrong with that?

Tally is about to turn sixteen, and she can''t wait. Not for her license -- for turning pretty. In Tally''s world, your sixteenth birthday brings an operation that turns you from a repellent ugly into a stunningly attractive pretty and catapults you into a high-tech paradise where your only job is to have a really great time. In just a few weeks Tally will be there.

But Tally''s new friend Shay isn''t sure she wants to be pretty. She''d rather risk life on the outside. When Shay runs away, Tally learns about a whole new side of the pretty world -- and it isn''t very pretty. The authorities offer Tally the worst choice she can imagine: find her friend and turn her in, or never turn pretty at all. The choice Tally makes changes her world forever.', 432, null, 2005, 203914, (select id from series where hardcover_id = 5729), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ultimate Hitchhiker''s Guide: Five Complete Novels and One Story', 'Douglas Adams', '0307291812', 'https://assets.hardcover.app/edition/32211836/420aa8b8-11bc-47c0-87ab-adaed744d9d5.jpg', 'In one complete volume, here are the five classic novels from Douglas Adams’s beloved Hitchhiker series.

Now celebrating the pivotal 42nd anniversary of The Hitchhiker’s Guide to the Galaxy, soon to be a Hulu original series!

The Hitchhiker’s Guide to the Galaxy (Nominated as one of America’s best-loved novels by PBS’s The Great American Read)
Seconds before the Earth is demolished for a galactic freeway, Arthur Dent is saved by Ford Prefect, a researcher for the revised Guide. Together they stick out their thumbs to the stars and begin a wild journey through time and space.

The Restaurant at the End of the Universe
The moment before annihilation at the hands of warmongers is a curious time to crave tea. It could only happen to the cosmically displaced Arthur Dent and his comrades as they hurtle across the galaxy in a desperate search for a place to eat.

Life, the Universe and Everything
The unhappy inhabitants of planet Krikkit are sick of looking at the night sky– so they plan to destroy it. The universe, that is. Now only five individuals can avert Armageddon: mild-mannered Arthur Dent and his stalwart crew.

So Long, and Thanks for All the Fish
Back on Earth, Arthur Dent is ready to believe that the past eight years were all just a figment of his stressed-out imagination. But a gift-wrapped fishbowl with a cryptic inscription thrusts him back to reality. So to speak.

Mostly Harmless
Just when Arthur Dent makes the terrible mistake of starting to enjoy life, all hell breaks loose. Can he save the Earth from total obliteration? Can he save the Guide from a hostile alien takeover? Can he save his daughter from herself?

Includes the bonus story “Young Zaphod Plays It Safe”', 815, null, 1979, 205829, (select id from series where hardcover_id = 3400), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pyramids', 'Terry Pratchett', '345304505X', 'https://assets.hardcover.app/edition/31535942/0f6852af0991774597ac442370ec8a0fe7a879fc.jpeg', 'It''s bad enough being new on the job, but Teppic hasn''t a clue as to what a pharaoh is supposed to do. After all, he''s been trained at Ankh-Morpork''s famed assassins'' school, across the sea from the Kingdom of the Sun.First, there''s the monumental task of building a suitable resting place for Dad -- a pyramid to end all pyramids. Then there are the myriad administrative duties, such as dealing with mad priests, sacred crocodiles, and marching mummies. And to top it all off, the adolescent pharaoh discovers deceit, betrayal -- not to mention aheadstrong handmaiden -- at the heart of his realm.', 381, null, 1989, 206170, (select id from series where hardcover_id = 1018), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kafka on the Shore', 'Haruki Murakami, Philip Gabriel', '8483103567', 'https://assets.hardcover.app/editions/31645214/7751038927873328.jpg', 'Kafka on the Shore is powered by two remarkable characters: a teenage boy, Kafka Tamura, who runs away from home either to escape a gruesome oedipal prophecy or to search for his long missing mother and sister; and an aging simpleton called Nakata, who never recovered from a wartime affliction and now is drawn toward Kafka for reasons that, like the most basic activities of daily life, he cannot fathom.', 467, null, 2001, 207877, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Three-Body Problem', 'Liu Cixin', '6073829205', 'https://assets.hardcover.app/edition/30400656/a042ea0a-127c-4e98-8202-f20519445ec3.jpg', 'An alien civilization on the brink of destruction captures the signal and plans to invade Earth. 

Meanwhile, on Earth, different camps start forming, planning to either welcome the superior beings and help them take over a world seen as corrupt, or to fight against the invasion. 

The result is a science fiction masterpiece of enormous scope and vision.', 400, 806, 2006, 208339, (select id from series where hardcover_id = 1584), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Deadhouse Gates', 'Steven Erikson', '849069785X', 'https://assets.hardcover.app/external_data/31056327/8fc6b39dc7078d31b77760359d3b6c4b2d82675a.jpeg', 'The second book in Steven Erikson''s thrilling epic fantasy series chronicling the ill-fated Malazan Empire.Weakened by events in Darujhistan, the Malazan Empire teeters on the brink of anarchy. In the vast dominion of Seven Cities, in the Holy Desert Raraku, the seer Sha''ik gathers an army around her in preparation for the long-prophesied uprising named the Whirlwind. Unprecedented in its size and savagery, it will embroil in one of the bloodiest conflicts it has ever known: a maelstrom of fanaticism and bloodlust that will shape destinies and give birth to legends... In the Otataral mines, Felisin, youngest daughter of the disgraced House of Paran, dreams of revenge against the sister who sentenced her to a life of slavery. Escape leads her to raraku, where her soul will be reborn and her future made clear. The now-outlawed Bridgeburners, Fiddler and the assassin Kalam, have vowed to return the once god-possessed Apsalar to her homeland, and to confront and kill the Empress Laseen, but events will overtake them too. Meanwhile, Coltaine, the charismatic commander of the Malaz 7th Army, will lead his battered, war-weary troops in a last, valient running battle to save the lives of thirty thousand refugees and, in so doing, secure an illustrious place in the Empire''s chequered history. And into this blighted land come two ancient wanderers, Mappo and his half-Jaghut companion Icarium, bearers of a devastating secret that threatens to break free of its chains... Set in a brilliantly-realized world ravaged by anarchy and dark, uncontrollable magic, Deadhouse Gates is the thrilling, brutal second chapter in the Malazan Book of the Fallen. A powerful novel of war, intrigue and betrayal, it confirms Steven Erikson as a storyteller of breathtaking skill, imagination and originality - a new master of epic fantasy.', 614, null, 1999, 210733, (select id from series where hardcover_id = 1167), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Jonathan Strange & Mr Norrell', 'Susanna Clarke', '9113012800', 'https://assets.hardcover.app/external_data/59342910/297877e178ee1ed56c8954c96a234c4e4f513255.jpeg', 'Published in 2004, it is an alternative history set in 19th-century England around the time of the Napoleonic Wars. Its premise is that magic once existed in England and has returned with two men: Gilbert Norrell and Jonathan Strange. Centred on the relationship between these two men, the novel investigates the nature of "Englishness" and the boundaries between reason and unreason, Anglo-Saxon and Anglo-Dane, and Northern and Southern English cultural tropes/stereotypes. It has been described as a fantasy novel, an alternative history, and a historical novel. It inverts the Industrial Revolution conception of the North-South divide in England: in this book the North is romantic and magical, rather than rational and concrete.', 1006, 1920, 2004, 212183, (select id from series where hardcover_id = 205155), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harrow the Ninth', 'Tamsyn Muir', '8418037067', 'https://assets.hardcover.app/edition/30399888/871f1aec814ab2be17e090ce1ee07387fa40c2be.jpeg', '"She answered the Emperor''s call.

She arrived with her arts, her wits, and her only friend.

In victory, her world has turned to ash.

After rocking the cosmos with her deathly debut, Tamsyn Muir continues the story of the penumbral Ninth House in Harrow the Ninth, a mind-twisting puzzle box of mystery, murder, magic, and mayhem. Nothing is as it seems in the halls of the Emperor, and the fate of the galaxy rests on one woman''s shoulders.

Harrowhark Nonagesimus, last necromancer of the Ninth House, has been drafted by her Emperor to fight an unwinnable war. Side-by-side with a detested rival, Harrow must perfect her skills and become an angel of undeath ― but her health is failing, her sword makes her nauseous, and even her mind is threatening to betray her.

Sealed in the gothic gloom of the Emperor''s Mithraeum with three unfriendly teachers, hunted by the mad ghost of a murdered planet, Harrow must confront two unwelcome questions: is somebody trying to kill her? And if they succeeded, would the universe be better off?"', 512, null, 2019, 215901, (select id from series where hardcover_id = 2759), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Green Mile', 'Stephen King', '1416524339', 'https://assets.hardcover.app/edition/30401557/2b801416527f2e35e41847f12269ba6cc1671fd4.jpeg', 'Set in the 1930s at the Cold Mountain Penitentiary''s death-row facility, The Green Mile is the riveting and tragic story of John Coffey, a giant, preternaturally gentle inmate condemned to death for the rape and murder of twin nine-year-old girls. It is a story narrated years later by Paul Edgecomb, the ward superintendent compelled to help every prisoner spend his last days peacefully and every man walk the green mile to execution with his humanity intact.

Edgecomb has sent seventy-eight inmates to their date with "old sparky," but he''s never encountered one like Coffey -- a man who wants to die, yet has the power to heal. And in this place of ultimate retribution, Edgecomb discovers the terrible truth about Coffey''s gift, a truth that challenges his most cherished beliefs -- and ours.

Originally published in 1996 in six self-contained monthly installments, The Green Mile is an astonishingly rich and complex novel that delivers over and over again. Each individual volume became a huge success when first published, and all six were on the New York Times bestseller list simultaneously. Three years later, when Frank Darabont made The Green Mile into an award-winning movie starring Tom Hanks and Michael Clarke Duncan, the book returned to the bestseller list -- and stayed there for months.', 512, null, 1996, 216592, (select id from series where hardcover_id = 5737), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wizard''s First Rule', 'Terry Goodkind', '0606315748', 'https://assets.hardcover.app/book_mappings/7333156/d71bc6a97e9ec408e63f130067a87b7825ef8801.jpeg', 'In the aftermath of the brutal murder of his father, Richard Cypher encounters a mysterious woman, Kahlan Amnell, in his forest sanctuary. She seeks his help...and more. His world, his very beliefs, are shattered when ancient debts come due with thundering violence. 

In their darkest hour, Kahlan calls upon Richard to reach beyond his sword--- to invoke within himself something more noble. Neither knows that the rules of battle have just changed...or that their time has run out. 

This is the beginning. One book. One Rule. Witness the birth of a legend.', 848, null, 1994, 217326, (select id from series where hardcover_id = 1078), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lightning Thief', 'Rick Riordan', '0141335912', 'https://assets.hardcover.app/edition/11185124/b076b406ccdf683e9fb871f8aa24c041ae354514.jpeg', 'Twelve-year-old Percy Jackson is on the most dangerous quest of his life. With the help of a satyr and a daughter of Athena, Percy must journey across the United States to catch a thief who has stolen the original weapon of mass destruction — Zeus’ master bolt. Along the way, he must face a host of mythological enemies determined to stop him. Most of all, he must come to terms with a father he has never known, and an Oracle that has warned him of betrayal by a friend.', 377, null, 2005, 219252, (select id from series where hardcover_id = 5193), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Graceling', 'Kristin Cashore', '0606079939', 'https://assets.hardcover.app/edition/7513418/9f1de0ccf8982c09d8ea1dad7336537382fecb98.jpeg', 'In a world where some people are born with extreme and often-feared skills called Graces, Katsa struggles for redemption from her own horrifying Grace, the Grace of killing, and teams up with another young fighter to save their land from a corrupt king.', 492, null, 2008, 226864, (select id from series where hardcover_id = 2520), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gunslinger', 'Stephen King', '8581050212', 'https://assets.hardcover.app/books/229579/2367228096182994.png', 'Roland is a haunting figure, a loner, on a spellbinding journey toward the mysterious Dark Tower, in a desolate world which frighteningly echoes our own.

On his quest, Roland begins a friendship with a kid from New York named Jake, encounters an alluring woman and faces an agonising choice between damnation and salvation as he pursues the Man in Black.

JOIN THE QUEST FOR THE DARK TOWER...', 238, null, 1982, 229579, (select id from series where hardcover_id = 3413), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kindred', 'Octavia E. Butler', '1035409682', 'https://assets.hardcover.app/edition/16413369/dbcdcc21-3f5d-4b6c-96b3-2899bc57b00b.jpg', '"Dana''s 26th birthday celebration ends when she''s ripped from 1976 California and thrust onto a Maryland slave plantation in 1815. Her mission: keep alive the white boy who will grow up to assault her ancestor—because without him, she''ll never be born.

Every trip back grows more dangerous. Dana feels the lash, wears the chains, endures the daily terror that defined millions of lives. She can''t just read about slavery''s horrors—she lives them, bleeds from them, nearly breaks under them.

Butler doesn''t let you observe from a safe distance. You''re trapped in Dana''s skin as she navigates impossible choices: submit to survive, or resist and risk everything. You''ll feel her desperation as she fights to preserve her humanity while the plantation''s brutality threatens to consume her."-- Provided by Amazon', 288, null, 1979, 230671, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heretics of Dune', 'Frank Herbert', '3453310993', 'https://assets.hardcover.app/external_data/34012594/456aa8e348ebe788a666073fce75256b5550286f.jpeg', 'Leto Atreides, the God Emperor of Dune, is dead. In the fifteen hundred years since his passing, the Empire has fallen into ruin. The great Scattering saw millions abandon the crumbling civilization and spread out beyond the reaches of known space. The planet Arrakis—now called Rakis—has reverted to its desert climate, and its great sandworms are dying. Now the Lost Ones are returning home in pursuit of power. And as these factions vie for control over the remnants of the Empire, a girl named Sheeana rises to prominence in the wastelands of Rakis, sending religious fervor throughout the galaxy. For she possesses the abilities of the Fremen sandriders—fulfilling a prophecy foretold by the late God Emperor....', 562, null, 1984, 235277, (select id from series where hardcover_id = 1150), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Twenty Thousand Leagues Under the Sea', 'Jules Verne', '0822492334', 'https://assets.hardcover.app/external_data/61022899/633d2619467522d36677861d0fba58398714a23d.jpeg', 'Prompted by disturbing reports of an enormous sea monster, marine biologist Pierre Aronnax joins an expedition to find and destroy it. After barely surviving an attack on the creature, the voyagers discover that their quarry is in fact a remarkably advanced submarine, the Nautilus . Its creator, Captain Nemo, is driven by a thirst for knowledge and by a hatred of civilization—and he refuses to let his “guests” leave. As Aronnax and his companions plot to escape, they are taken on a whirlwind tour of undersea marvels, including volcanoes, a giant squid, and the ruins of Atlantis.  Twenty Thousand Leagues Under the Sea  is just as gripping and fantastical a read as it was a century and a half ago, when Jules Verne first imagined traveling beyond the bounds of the possible.', 270, null, 1866, 236440, (select id from series where hardcover_id = 5681), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Small Gods', 'Terry Pratchett', '0061440728', 'https://assets.hardcover.app/edition/30581217/1d7dd4d0-6acd-4b05-923f-458450aec7a6.jpg', 'Religion is a competitive business in the Discworld. Everyone has their own opinion and their own gods of every shape and size—all fighting for faith, followers, and a place at the top. So when the great god Om accidentally manifests as a lowly tortoise, stripped of all divine power, it’s clear he’s become less important than he realized.

Om needs an acolyte and fast. Enter Brutha, the Chosen One—or at least the only One available. He’s a simple lad whose highest ambition is tending his melon patch—until he hears the voice of a god calling his name. A small god for sure. But bossy as Hell.

Brutha wants peace, justice, and love—but that’s hard to achieve in a world where religion means power, money is worshipped, and corruption reigns supreme. . . .', 384, null, 1992, 239373, (select id from series where hardcover_id = 1018), 13) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Collapsing Empire', 'John Scalzi', '310490541X', 'https://assets.hardcover.app/edition/15325920/4ebb8fa2-9652-4760-909e-a50df058734c.jpg', 'Our universe is ruled by physics. Faster than light travel is impossible—until the discovery of The Flow, an extradimensional field available at certain points in space-time, which can take us to other planets around other stars.

Riding The Flow, humanity spreads to innumerable other worlds. Earth is forgotten. A new empire arises, the Interdependency, based on the doctrine that no one human outpost can survive without the others. It’s a hedge against interstellar war—and, for the empire’s rulers, a system of control.

The Flow is eternal—but it’s not static. Just as a river changes course, The Flow changes as well. In rare cases, entire worlds have been cut off from the rest of humanity. When it’s discovered that the entire Flow is moving, possibly separating all human worlds from one another forever, three individuals—a scientist, a starship captain, and the emperox of the Interdependency—must race against time to discover what, if anything, can be salvaged from an interstellar empire on the brink of collapse.', 336, null, 2017, 240343, (select id from series where hardcover_id = 1142), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Wrinkle in Time', 'Madeleine L''Engle', '1417784601', 'https://assets.hardcover.app/edition/15420559/f668168e8bfa89b8530b0a17fd213b267f2b9b2a.jpeg', 'It was a dark and stormy night; Meg Murry, her small brother Charles Wallace, and her mother had come down to the kitchen for a midnight snack when they were upset by the arrival of a most disturbing stranger.

"Wild nights are my glory," the unearthly stranger told them. "I just got caught in a downdraft and blown off course. Let me sit down for a moment, and then I''ll be on my way. Speaking of ways, by the way, there is such a thing as a tesseract."

A tesseract (in case the reader doesn''t know) is a wrinkle in time. To tell more would rob the reader of the enjoyment of Miss L''Engle''s unusual book. A Wrinkle in Time, winner of the Newberry Medal in 1963, is the story of the adventures in space and time of Meg, Charles Wallace, and Calvin O''Keefe (athlete, student, and one of the most popular boys in high school). They are in search of Meg''s father, a scientist who disappeared while engaged in secret work for the government on the tesseract problem.', 256, 387, 1962, 240793, (select id from series where hardcover_id = 1029), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Best Served Cold', 'Joe Abercrombie', '8073321610', 'https://assets.hardcover.app/external_data/29658586/3d32fa4da167fff60fceaacccddda4d805b4f817.jpeg', 'War may be hell, but for Monza Murcatto, a solider of considerable fortune; it''s a damn good way of making money too.  Her victories have made her popular - a shade too popular for her employer''s taste. Betrayed and left for dead, Murcatto''s reward is a broken body and a burning hunger for vengeance. Whatever the cost, seven men must die.

Duke Orso imagines that he can become king by ending the civil wars that have devastated Styria, but he errs by trying to kill his overly popular general, mercenary Monza Murcatto. Recovering from her massive injuries and mourning her murdered brother, Monza vows vengeance on Orso and half a dozen of his accomplices.

"Joe Abercrombie takes the grand tradition of high fantasy literature and drags it down into the gutter, in the best possible way." --- Time
"Abercrombie is both fiendishly inventive and solidly convincing, especially when sprinkling his appallingly vivid combat scenes with humor so dark that it''s almost ultraviolet." --- Publishers Weekly
"A satisfyingly brutal fantasy quest. BEST SERVED COLD? Modern fantasy doesn''t get much hotter than this." --- Dave Bradley, SFX
"Abercrombie has written the finest epic fantasy trilogy in recent memory. He''s one writer that no one should miss." --- Junot Diaz on The First Law Trilogy', 672, null, 2009, 242555, (select id from series where hardcover_id = 6014), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Overstory', 'Richard Powers', '2749158842', 'https://assets.hardcover.app/edition/30401461/19567cead6be7afe3c46572b7219daa6620b892b.jpeg', 'WINNER OF THE PULITZER PRIZE NEW YORK TIMES BESTSELLER An Air Force loadmaster in the Vietnam War is shot out of the sky, then saved by falling into a banyan. An artist inherits a hundred years of photographic portraits, all of the same doomed American chestnut. A hard-partying undergraduate in the late 1980s electrocutes herself, dies, and is sent back into life by creatures of air and light. A hearing- and speech-impaired scientist discovers that trees are communicating with one another. These four, and five other strangers—each summoned in different ways by trees—are brought together in a last and violent stand to save the continent’s few remaining acres of virgin forest. In his twelfth novel, National Book Award winner Richard Powers delivers a sweeping, impassioned novel of activism and resistance that is also a stunning evocation of—and paean to—the natural world. From the roots to the crown and back to the seeds, The Overstory unfolds in concentric rings of interlocking fables that range from antebellum New York to the late twentieth-century Timber Wars of the Pacific Northwest and beyond, exploring the essential conflict on this planet: the one taking place between humans and nonhumans. There is a world alongside ours—vast, slow, interconnected, resourceful, magnificently inventive, and almost invisible to us. This is the story of a handful of people who learn how to see that world and who are drawn up into its unfolding catastrophe. The Overstory is a book for all readers who despair of humanity’s self-imposed separation from the rest of creation and who hope for the transformative, regenerating possibility of a homecoming. If the trees of this earth could speak, what would they tell us? "Listen. There’s something you need to hear."', 502, null, 2018, 243129, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('This Is How You Lose the Time War', 'Amal El-Mohtar, Max Gladstone', '1529405238', 'https://assets.hardcover.app/external_data/44204908/47b512a8e31cb3c55f8957b2659c59be05a2dbc5.jpeg', 'Thus begins an unlikely correspondence between two rival agents hellbent on securing the best possible future for their warring factions. Now, what began as a taunt, a battlefield boast, becomes something more. Something epic. Something romantic. Something that could change the past and the future.

Except the discovery of their bond would mean the death of each of them. There’s still a war going on, after all. And someone has to win. That’s how war works, right?

Cowritten by two beloved and award-winning sci-fi writers, This Is How You Lose the Time War is an epic love story spanning time and space.', 198, 256, 2019, 249097, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pines', 'Blake Crouch', '1491537264', 'https://assets.hardcover.app/external_data/33721590/15ab710963284ef73162b8bb16ef707e2c20d522.jpeg', 'The first book of the smash-hit Wayward Pines trilogy, from the New York Times bestselling author of Dark Matter, Recursion, and Upgrade

One way in. No way out.

Secret Service agent Ethan Burke arrives in Wayward Pines, Idaho, with a mission: locate two federal agents who went missing in the bucolic town one month earlier. But within minutes of his arrival, Ethan is involved in a violent accident. He comes to in a hospital, with no ID, no cell phone, and no briefcase.

As the days pass, Ethan’s investigation turns up more questions than answers: Why can’t he get any phone calls through to his wife and son in the outside world? Why doesn’t anyone believe he is who he says he is? And what is the purpose of the electrified fences surrounding the town? Are they meant to keep the residents in? Or something else out?

Each step closer to the truth takes Ethan farther from the world he knew, from the man he was, until he must face a horrifying fact—he may never get out of Wayward Pines alive.

The nail-bitingly suspenseful opening installment in Blake Crouch’s blockbuster Wayward Pines trilogy, Pines is at once a brilliant mystery tale and the first step into a genre-bending saga of suspense, science fiction, and horror.', 307, null, 2012, 250488, (select id from series where hardcover_id = 1125), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ubik', 'Philip K. Dick', '3518069403', 'https://assets.hardcover.app/edition/15201655/3a3ac8a5b4fb400fce9deca373a8dd6a6fad248a.jpeg', 'Ubik, written in 1966 and published in 1969, is one of Philip K. Dick''s masterpieces (The Three Stigmata of Plamer Eldritch is another one). Ubik is the first novel to introduce spiritual elements that will culminate in his last novels VALIS, the Divine Invasion and the Transmigration of Timothy Archer. According to movie industry rumor Ubik could be the next big PKD movie project. Philip K. Dick himself wrote a screenplay for Ubik in 1974 but it was never made into a movie. PKD was hoping that it would by sending "the novel to the agent of Victoria Principal- whom he revered - in hope that she''d wind up reading it."(Tim Powers in the introduction to Ubik: The Screenplay). Ubik was expanded and adapted from the short story "What the Dead Men Say" published in Worlds of Tomorrow in 1964.
Ubik is one of the most published books of Philip K Dick in the world.', 242, null, 1969, 253601, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('I Am Legend', 'Richard Matheson', '1433203286', 'https://assets.hardcover.app/edition/30399490/cbdd9c050c0af555c27cb18f9b86428081bbb7c5.jpeg', 'Robert Neville is the last living man on Earth ... but he is not alone. Every other man, woman and child on the planet has become a vampire, and they are hungry for Neville''s blood.

By day he is the hunter, stalking the undead through the ruins of civilisation. By night, he barricades himself in his home and prays for the dawn.

How long can one man survive like this?', 160, null, 1954, 255573, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Knight of the Seven Kingdoms', 'George R.R. Martin, Gary Gianni', '1101923326', 'https://assets.hardcover.app/edition/30399407/3d466fe8c7780d917b49b3fdb16193376fb8a0c4.jpeg', '"Taking place nearly a century before the events of A Game of Thrones, A Knight of the Seven Kingdoms compiles the first three official prequel novellas to George R. R. Martin''s ongoing masterwork, A Song of Ice and Fire. These never-before-collected adventures recount an age when the Targaryen line still holds the Iron Throne, and the memory of the last dragon has not yet passed from living consciousness. Before Tyrion Lannister and Podrick Payne, there was Dunk and Egg. A young, naïve but ultimately courageous hedge knight, Ser Duncan the Tall towers above his rivals--in stature if not experience. Tagging along is his diminutive squire, a boy called Egg--whose true name is hidden from all he and Dunk encounter. Though more improbable heroes may not be found in all of Westeros, great destinies lay ahead for these two... as do powerful foes, royal intrigue, and outrageous exploits" -- Dust jacket flap.', 355, null, 1998, 256089, (select id from series where hardcover_id = 1055), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('They Both Die at the End', 'Adam Silvera', '222121823X', 'https://assets.hardcover.app/edition/30399800/5968f19fbb41c089dcd4dd870b28afe74dd67d7b.jpeg', '"On September 5, a little after midnight, Death-Cast calls Mateo Torrez and Rufus Emeterio to give them some bad news: They’re going to die today.

Mateo and Rufus are total strangers, but, for different reasons, they’re both looking to make a new friend on their End Day. The good news: There’s an app for that. It’s called the Last Friend, and through it, Rufus and Mateo are about to meet up for one last great adventure—to live a lifetime in a single day."-- Provided by Amazon', 384, null, 2014, 256277, (select id from series where hardcover_id = 11346), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Atlas Shrugged', 'Ayn Rand, Leonard Peikoff', '0451132157', 'https://assets.hardcover.app/book_mappings/7332596/2fa893c1afc323f67e0706b831d0eb9f417ac97e.jpeg', 'Set in a near-future U.S.A. whose economy is collapsing as a result of the mysterious disappearance of leading innovators and industrialists, this novel presents an astounding panorama of human life-from the productive genius who becomes a worthless playboy...to the great steel industrialist who does not know that he is working for his own destruction...to the philosopher who becomes a pirate...to the woman who runs a transcontinental railroad...to the lowest track worker in her train tunnels.

Peopled by larger-than-life heroes and villains, charged with towering questions of good and evil, Atlas Shrugged is a philosophical revolution told in the form of an action thriller.', 946, null, 1957, 257153, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Anathem', 'Neal Stephenson', '364104412X', 'https://assets.hardcover.app/editions/30402165/1328834015406049.jpg', 'Having lived in a monastery since childhood away from the violent upheavals of the outside world, Raz becomes one of a group of formerly cloistered scholars who are appointed by a fear-driven higher power to avert an impending catastrophe. By the author of Cryptonomicon. 250,000 first printing.', 1092, null, 2008, 258729, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wool', 'Hugh Howey', '2330037376', 'https://assets.hardcover.app/editions/30399206/224453795040747.jpg', 'The world outside has grown toxic, the view of it limited, talk of it forbidden. The remnants of humanity live underground in a single silo.

But there are always those who hope, who dream. These are the dangerous people, the residents who infect others with their optimism. Their punishment is simple. They are given the very thing they want: They are allowed to go outside. 

After the previous sheriff leaves the silo in a terrifying ritual, Juliette, a mechanic from the down deep, is suddenly and inexplicably promoted to the head of law enforcement. With newfound power and with little regard for the customs she is supposed to abide, Juliette uncovers hints of a sinister conspiracy. Tugging this thread may uncover the truth . . . or it could kill every last human alive.', 584, 900, 2014, 260468, (select id from series where hardcover_id = 1034), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Invisible Man', 'Ralph Ellison', '0451027221', 'https://assets.hardcover.app/external_data/4049609/10ca8857cf6647f99bdf87774a74d27b849b2ede.jpeg', 'Invisible Man is the story of a young black man from the South who does not fully understand racism in the world. Filled with hope about his future, he goes to college, but gets expelled for showing one of the white benefactors the real and seamy side of black existence. He moves to Harlem and becomes an orator for the Communist party, known as the Brotherhood. In his position, he is both threatened and praised, swept up in a world he does not fully understand. As he works for the organization, he encounters many people and situations that slowly force him to face the truth about racism and his own lack of identity. As racial tensions in Harlem continue to build, he gets caught up in a riot that drives him to a manhole. In the darkness and solitude of the manhole, he begins to understand himself - his invisibility and his identity. He decides to write his story down (the body of the novel) and when he is finished, he vows to enter the world again.', 610, null, 1952, 261317, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red Mars', 'Kim Stanley Robinson', '0606297723', 'https://assets.hardcover.app/edition/30400653/ad16d6b9d667b7e2323184b60bdb1bcafbbe1650.jpeg', 'Red Mars is the first novel of the Mars trilogy, published in 1992. It follows the beginnings of the colonization of Mars, from the arrival of the First Hundred to the First Martian Revolution.', 592, null, 1992, 261494, (select id from series where hardcover_id = 1114), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Giver', 'Lois Lowry', '060635977X', 'https://assets.hardcover.app/book_mappings/7332318/b23de44fadf6eca2f7196c4aa3efbec84b748a35.jpeg', 'In a world with no poverty, no crime, no sickness and no unemployment, and where every family is happy, 12-year-old Jonas is chosen to be the community''s Receiver of Memories. Under the tutelage of the Elders and an old man known as the Giver, he discovers the disturbing truth about his utopian world and struggles against the weight of its hypocrisy. With echoes of Brave New World, in this 1994 Newbery Medal winner, Lowry examines the idea that people might freely choose to give up their humanity in order to create a more stable society. Gradually Jonas learns just how costly this ordered and pain-free society can be, and boldly decides he cannot pay the price.', 205, null, 1993, 262039, (select id from series where hardcover_id = 5782), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Record of a Spaceborn Few', 'Becky Chambers', '1473647630', 'https://assets.hardcover.app/editions/30452112/1390368926954764.jpg', 'Centuries after the last humans left Earth, the Exodus Fleet is a living relic, a place many are from but few outsiders have seen. Humanity has finally been accepted into the galactic community, but while this has opened doors for many, those who have not yet left for alien cities fear that their carefully cultivated way of life is under threat.', 368, null, 2018, 263418, (select id from series where hardcover_id = 1092), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ender''s Shadow', 'Orson Scott Card', '8498725917', 'https://assets.hardcover.app/edition/16140085/ed4ea5b883a7b8b2e82502463848422a9950d62f.jpeg', 'When Bean is sent to Battle School, he is constantly compared to the great Ender Wiggin, but Bean knows things Ender doesn''t even dream of. And Bean knows that he can help Ender.', 469, null, 1999, 264175, (select id from series where hardcover_id = 5616), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Passage', 'Justin Cronin', '0606321829', 'https://assets.hardcover.app/edition/31491370/0663ea7c-e44a-4794-aff4-cca65220e930.jpg', 'First, the unthinkable: a security breach at a secret U.S. government facility unleashes the monstrous product of a chilling military experiment. Then, the unspeakable: a night of chaos and carnage gives way to sunrise on a nation, and ultimately a world, forever altered. All that remains for the stunned survivors is the long fight ahead and a future ruled by fear--of darkness, of death, of a fate far worse.

As civilization swiftly crumbles into a primal landscape of predators and prey, two people flee in search of sanctuary. FBI agent Brad Wolgast is a good man haunted by what he''s done in the line of duty. Six-year-old orphan Amy Harper Bellafonte is a refugee from the doomed scientific project that has triggered apocalypse. Wolgast is determined to protect her from the horror set loose by her captors, but for Amy, escaping the bloody fallout is only the beginning of a much longer odyssey--spanning miles and decades--toward the time an place where she must finish what should never have begun.

With The Passage, award-winning author Justin Cronin has written both a relentlessly suspenseful adventure and an epic chronicle of human endurance in the face of unprecedented catastrophe and unimaginable danger. Its inventive storytelling, masterly prose, and depth of human insight mark it as a crucial and transcendent work of modern fiction.', 784, null, 2010, 264602, (select id from series where hardcover_id = 5550), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Klara and the Sun', 'Kazuo Ishiguro', '0593319923', 'https://assets.hardcover.app/external_data/59592031/11d4c25aa782acfbff944edbec1e89a6dbdbaace.jpeg', '"Klara and the Sun, the first novel by Kazuo Ishiguro since he was awarded the Nobel Prize in Literature, tells the story of Klara, an Artificial Friend with outstanding observational qualities, who, from her place in the store, watches carefully the behavior of those who come in to browse, and of those who pass on the street outside. She remains hopeful that a customer will soon choose her.

Klara and the Sun is a thrilling book that offers a look at our changing world through the eyes of an unforgettable narrator, and one that explores the fundamental question: what does it mean to love?

In its award citation in 2017, the Nobel committee described Ishiguro''s books as "novels of great emotional force" and said he has "uncovered the abyss beneath our illusory sense of connection with the world.""', 320, null, 2019, 266607, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dispossessed', 'Ursula K. Le Guin', '0785764038', 'https://assets.hardcover.app/external_data/34556756/b42d445b8b1012883042532cc6e0872d23f45bb3.jpeg', 'The story takes place on the fictional planet Urras and its moon Anarres (since Anarres is massive enough to hold an atmosphere, this is often described as a double planet system). In order to forestall an anarcho-syndical workers'' rebellion, the major Urrasti states gave the revolutionaries the right to live on Anarres, along with a guarantee of non-interference, approximately two hundred years before the events of The Dispossessed.[2] Before this, Anarres had had no permanent settlements apart from some mining.

The protagonist Shevek is a physicist attempting to develop a General Temporal Theory. The physics of the book describes time as having a much deeper, more complex structure than we understand it. It incorporates not only mathematics and physics, but also philosophy and ethics. The meaning of the theories in the book weaves nicely into the plot, not only describing abstract physical concepts, but the ups and downs of the characters'' lives, and the transformation of the Anarresti society. An oft-quoted saying in the book is "true journey is return." [3].

Anarres is in theory a society without government or coercive authoritarian institutions. Yet in pursuing research that deviates from his society''s current consensus understanding, Shevek begins to come up against very real obstacles. Shevek gradually develops an understanding that the revolution which brought his world into being is stagnating, and power structures are beginning to exist where there were none before. He therefore embarks on the risky journey to the original planet, Urras, seeking to open dialog between the worlds and to spread his theories freely outside of Anarres. The novel details his struggles on both Urras and his homeworld of Anarres.

The book also explores the Sapir-Whorf Hypothesis, that language shapes thinking, and thus, culture. The language spoken on the anarchist planet Anarres, Pravic, is a constructed language that reflects many aspects of the philosophical foundations of utopian anarchism. For instance, the use of the possessive case is strongly discouraged. In one scene, Shevek''s daughter, meeting him for the first time, offers him "You can share the handkerchief I use,"[4] rather than "you may borrow my handkerchief", thus conveying the idea that the handkerchief is not owned by the girl, merely carried by her.[5]
Cover of first paperback edition

The Dispossessed looks into the mechanisms that may be developed by an anarchist society, but also the dangers of centralization and bureaucracy that might easily take over such society without the continuation of revolutionary ideology. Part of its power is that it gives a spectrum of fairly well-developed characters, who illustrate many types of personalities, all educated in an environment that measures a person not by what he owns, but by what he can do, and how he relates to other human beings. Possibly the best example of this is the character of Takver, the hero''s partner, who exemplifies many virtues: loyalty, love of life and living things, perseverance, and desire for a true partnership with another person.

The work is sometimes said to represent one of the few modern revivals of the utopian genre, [6] and there are certainly many characteristics of a utopian novel found in this book. Most obviously, Shevek is an outsider in Urras, following the "traveler" convention common in utopian literature. All of the characters portrayed in the novel have a certain spirituality or intelligence, there are no nondescript characters. It is also true to say that there are aspects of Anarres that are utopian: it is presented as a pure society that adheres to its own theories and ideals, which are starkly juxtaposed with Urras society.

However, the work is subtitled "An Ambiguous Utopia", and one of the major themes of the work is the ambiguity of different notions of utopia. Anarres is not presented as a perfect society, even within the constraints of what might define an anarchist utopia. Bureaucracy, stagnation, and power structures have problematized the revolution, as Shevek understands through the course of the novel. Moreover, Le Guin has painted a very stark picture of the natural and environmental constraints on society. Anarres citizens are forced to contend with a relatively sparse and unfruitful world. Hardship caused by lack of resources is a prominent theme, reflected in the title of the novel. Anarres citizens are dispossessed not just by political choice, but by the very lack of resources to possess. Here, again, Le Guin draws a contrast with the natural wealth of Urras, and the competitive behaviors this fosters. Le Guin''s foreword to the novel notes that her anarchism is closely akin to that of Pyotr Kropotkin''s, whose Mutual Aid closely assessed the influence of the natural world on competition and cooperation.[7] Le Guin''s use of realism in this aspect of the work further problematizes — ambiguates — a simple utopian interpretation of the work. Anarres is not a perfect society, and Le Guin shows that no such thing is possible.', 400, null, 1974, 267204, (select id from series where hardcover_id = 1123), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Do Androids Dream of Electric Sheep?', 'Philip K. Dick', '2808016727', 'https://assets.hardcover.app/editions/24366858/2403087114756371-912qCxdgTRL._SL1500_.jpg', 'By 2021, the World War has killed millions, driving entire species into extinction and sending mankind off-planet. Those who remain covet any living creature, and for people who can’t afford one, companies built incredibly realistic simulacra: horses, birds, cats, sheep. They’ve even built humans. Immigrants to Mars receive androids so sophisticated they are indistinguishable from true men or women. Fearful of the havoc these artificial humans can wreak, the government bans them from Earth. Driven into hiding, unauthorized androids live among human beings, undetected. Rick Deckard, an officially sanctioned bounty hunter, is commissioned to find rogue androids and “retire” them. But when cornered, androids fight back—with lethal force.', 223, null, 1968, 268150, (select id from series where hardcover_id = 1047), 0) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Clockwork Angel', 'Cassandra Clare', '0606377379', 'https://assets.hardcover.app/book_mappings/7333204/0c24452580e63487847c683544bcccdd36eee423.jpeg', 'When Tessa Gray crosses the ocean to find her brother, her destination is England, the time is the reign of Queen Victoria, and something terrifying is waiting for her in London''s Downworld, where vampires, warlocks, and other supernatural folk stalk the gaslit streets. Only the Shadowhunters, warriors dedicated to ridding the world of demons, keep order amidst the chaos.

Kidnapped by a secret organization called The Pandemonium Club, Tessa learns that she herself is a Downworlder with a rare ability: the power to transform into another person. What’s more, the Magister, the shadowy figure who runs the Club, will stop at nothing to claim Tessa''s power for his own.

Friendless and hunted, Tessa takes refuge with the Shadowhunters of the London Institute, who swear to find her brother if she will use her power to help them. She soon finds herself fascinated by—and torn between—two best friends: James, whose fragile beauty hides a deadly secret, and Will, whose caustic wit and volatile moods keep everyone in his life at arm’s length…everyone, that is, but Tessa. As their search draws them deep into the heart of an arcane plot that threatens to destroy the Shadowhunters, Tessa realizes that she may need to choose between saving her brother and helping her new friends save the world…and that love may be the most dangerous magic of all.', 500, null, 2010, 268938, (select id from series where hardcover_id = 5756), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lathe of Heaven', 'Ursula K. Le Guin', '1626812624', 'https://assets.hardcover.app/edition/32173903/b14c6db5-747e-4f80-8aac-4b7153b88973.jpg', 'During a time racked by war and environmental catastrophe, George Orr discovers his dreams alter reality. George is compelled to receive treatment from Dr. William Haber, an ambitious sleep psychiatrist who quickly grasps the immense power George holds. After becoming adept at manipulating George’s dreams to reshape the world, Haber seeks the same power for himself. George—with some surprising help—must resist Haber’s attempts, which threaten to destroy reality itself.

A classic of the science fiction genre, The Lathe of Heaven is prescient in its exploration of the moral risks when overwhelming power is coupled with techno-utopianism.', 192, null, 1971, 270051, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Anansi Boys', 'Neil Gaiman', '3453408349', 'https://assets.hardcover.app/edition/30405360/5b8af6b551d3e2b7d4794cee245c5c0a0a3f891c.jpeg', 'Fat Charlie Nancy’s normal life ended the moment his father dropped dead on a Florida karaoke stage. Charlie didn’t know his dad was a god. And he never knew he had a brother. Now brother Spider is on his doorstep—about to make Fat Charlie’s life more interesting . . . and a lot more dangerous.', 412, null, 2005, 270086, (select id from series where hardcover_id = 1074), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Graveyard Book', 'Neil Gaiman, Dave McKean', '0061709123', 'https://assets.hardcover.app/edition/16321570/df5c953e1f2c786260b83256cb195f852eec23a4.jpeg', 'Nobody Owens, known to his friends as Bod, is a perfectly normal boy. Well, he would be perfectly normal if he didn''t live in a graveyard, being raised and educated by ghosts, with a solitary guardian who belongs to neither the world of the living nor the world of the dead.

There are dangers and adventures for Bod in the graveyard: the strange and terrible menace of the Sleer; a gravestone entrance to a desert that leads to the city of ghouls; friendship with a witch, and so much more.

But it is in the land of the living that real danger lurks, for it is there that the man Jack lives and he has already killed Bod''s family.

A deliciously dark masterwork by bestselling author Neil Gaiman, with illustrations by award-winning Dave McKean.', 320, null, 2007, 270087, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Baptism of Fire', 'Andrzej Sapkowski, David   French', '5171203733', 'https://assets.hardcover.app/edition/31606033/1858883a-c331-4757-b4bf-ade7b192c661.jpg', 'The Wizards Guild has been shattered by a coup and, in the uproar, Geralt was seriously injured. The Witcher is supposed to be a guardian of the innocent, a protector of those in need, a defender against powerful and dangerous monsters that prey on men in dark times. But now that dark times have fallen upon the world, Geralt is helpless until he has recovered from his injuries. 

While war rages across all of the lands, the future of magic is under threat and those sorcerers who survive are determined to protect it. It''s an impossible situation in which to find one girl--Ciri, the heiress to the throne of Cintra, has vanished--until a rumor places her in the Niflgaard court, preparing to marry the Emperor. Injured or not, Geralt has a rescue mission on his hands.', 416, null, 1996, 270888, (select id from series where hardcover_id = 1808), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Farewell to Arms', 'Ernest Hemingway', '1850890331', 'https://assets.hardcover.app/external_data/3309645/ba66bced530b505b7730d34cbcb25fe85f2568ce.jpeg', '"Their romance begins tentatively, built on moments of solace in an otherwise shattered world. But as their connection deepens, it becomes a beacon of hope and escape—a fragile sanctuary from the horrors around them. Their love story is passionate yet fraught with obstacles, as both the war and their inner struggles threaten to pull them apart.

     Hemingway’s stark, unadorned prose cuts to the core, rendering every moment vivid and deeply felt. He weaves a narrative that not only captures the grit and terror of battle but also illuminates the tenderness and vulnerability of two people daring to love in an unforgiving world. Themes of loyalty, sacrifice, disillusionment, and the unyielding passage of fate are woven seamlessly into a story that is as gripping as it is profoundly human.

     As Frederic grapples with the meaning of duty, honor, and personal survival, A Farewell to Arms confronts the universal questions that arise in times of conflict: How do we hold onto our humanity when surrounded by inhumanity? And can love truly triumph in a world overshadowed by death and despair?"-- Provided by Amazon', 352, null, 1929, 271546, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Breakfast of Champions', 'Kurt Vonnegut', '1602591644', 'https://assets.hardcover.app/editions/8338232/1627766390142986.jpg', 'Breakfast Of Champions is vintage Vonnegut. One of his favorite characters, aging writer Kilgore Trout, finds to his horror that a Midwest car dealer is taking his fiction as truth. The result is murderously funny satire as Vonnegut looks at war, sex, racism, success, politics, and pollution in America and reminds us how to see the truth.From the Trade Paperback edition.', 320, null, 1973, 274620, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Cursed Child', 'John Tiffany, Jack Thorne, J.K. Rowling', '6127498503', 'https://assets.hardcover.app/book_mappings/7332623/8966b25d369e08596714f87891935994faa28843.jpeg', 'Being Harry Potter has never been easy. And it isn’t much easier now, as we catch up with him nineteen years after the Battle of Hogwarts.

These days, Harry is a husband, father of three school-age children, and an overworked employee at the Ministry of Magic.

While he struggles with a personal history that refuses to stay in the past, his youngest son Albus must grapple with the weight of the family legacy he never asked for.

As past and present fuse ominously, both father and son learn the uncomfortable truth: sometimes, darkness comes from unexpected places.

Harry Potter and the Cursed Child is the eighth story in the Harry Potter series and the first official Harry Potter story to be presented on stage.

Based on an original new story by J.K. Rowling, John Tiffany and Jack Thorne, the play was scripted by Jack and directed by John.

It received its world premiere in London’s West End on 30 July 2016.', 320, null, 2016, 279285, (select id from series where hardcover_id = 1185), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Princess Bride', 'William Goldman', '0727816748', 'https://assets.hardcover.app/external_data/38050345/ece50c1bc265bc00502c50cf098c72adaa89e48c.jpeg', 'What happens when the most beautiful girl in the world marries the handsomest prince of all time and he turns out to be...well...a lot less than the man of her dreams?

As a boy, William Goldman claims, he loved to hear his father read the "S. Morgenstern classic, The Princess Bride. But as a grown-up he discovered that the boring parts were left out of good old Dad''s recitation, and only the "good parts" reached his ears.

Now Goldman does Dad one better. He''s reconstructed the "Good Parts Version" to delight wise kids and wide-eyed grownups everywhere.

What''s it about? Fencing. Fighting. True Love. Strong Hate. Harsh Revenge. A Few Giants. Lots of Bad Men. Lots of Good Men. Five or Six Beautiful Women. Beasties Monstrous and Gentle. Some Swell Escapes and Captures. Death, Lies, Truth, Miracles, and a Little Sex.

In short, it''s about everything.

Eventually to be adapted for the silver screen, THE PRINCESS BRIDE was originally a beautifully simple, insightfully comic story of what happens when the most beautiful girl in the world marries the handsomest prince in the world--and he turnsout to be a son of a bitch. Guaranteed to entertain both young and old alike by combining scenes of rowsing fantasy with hilarious reality, THE PRINCESS BRIDE secures Goldman''s place as a master storyteller.', 456, null, 1973, 283102, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Crown of Midnight', 'Sarah J. Maas', '3423716525', 'https://assets.hardcover.app/external_data/46404294/17f2308696bfb704d2cdc2b1837a8802f55412dd.jpeg', 'Celaena Sardothien won a brutal contest to become the King’s Champion. But she is far from loyal to the crown. Though she goes to great lengths to hide her secret, her deadly charade becomes more difficult when she realizes she is not the only one seeking justice. Her search for answers ensnares those closest to her, and no one is safe from suspicion-not the Crown Prince Dorian; not Chaol, the Captain of the Guard; not even her best friend, Nehemia, a princess with a rebel heart.

Then, one terrible night, the secrets they have all been keeping lead to an unspeakable tragedy. As Celaena’s world shatters, she will be forced to decide once and for all where her true loyalties lie . . . and what she is willing to fight for.

The second book in the #1 New York Times bestselling Throne of Glass series returns readers to a land destroyed by liars, where one woman’s truth is the only thing that can save them all.', 449, null, 2013, 283659, (select id from series where hardcover_id = 5509), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hundred Thousand Kingdoms', 'N. K. Jemisin', '1841498173', 'https://assets.hardcover.app/edition/2655605/8a5ae4352c060073f2a594922b544d89babea2d8.jpeg', 'Yeine Darr is an outcast from the barbarian north.  But when her mother dies under mysterious circumstances, she is summoned to the majestic city of Sky.  There, to her shock, Yeine is named an heiress to the king.  But the throne of the Hundred Thousand Kingdoms is not easily won, and Yeine is thrust into a vicious power struggle with cousins she never knew she had.  As she fights for her life, she draws ever closer to the secrets of her mother''s death and her family''s bloody history.With the fate of the world hanging in the balance, Yeine will learn how perilous it can be when love and hate - and gods and mortals - are bound inseparably together.', 432, null, 2010, 284741, (select id from series where hardcover_id = 1375), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Inheritance', 'Christopher Paolini', '037584631X', 'https://assets.hardcover.app/edition/3256329/f9a2d62bdee70e71f5847cbe601d7678726a5a6f.jpeg', 'Not so very long ago, Eragon—Shadeslayer, Dragon Rider—was nothing more than a poor farm boy, and his dragon, Saphira, only a blue stone in the forest. Now the fate of an entire civilization rests on their shoulders.

Long months of training and battle have brought victories and hope, but they have also brought heartbreaking loss. And still, the real battle lies ahead: they must defeat Galbatorix. There will be no second chances. The Rider and his dragon have come further than anyone dared to hope. But can they topple the evil king and restore justice to Alagaësia? And if so, at what cost?', 880, null, 2011, 286414, (select id from series where hardcover_id = 5464), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Martian', 'Andy Weir', '3837127516', 'https://assets.hardcover.app/editions/21716111/5323176149970177.jpg', 'After a dust storm nearly kills him and forces his crew to evacuate the planet while thinking him dead, Mark finds himself stranded on Mars'' surface, completely alone. with no way to signal Earth that he''s alive. And even if he could get word out, his supplies would be gone years before a rescue could arrive.

Chances are, though, Mark won''t have time to starve to death. The damaged machinery, unforgiving environment, or plain-old "human error" are much more likely to kill him first. But Mark''s not ready to quit. Armed with nothing but his ingenuity and his engineering skills—and a gallows sense of humor that proves to be his greatest source of strength—he embarks on a dogged quest to stay alive, using his botany expertise to grow food and even hatch- ing a mad plan to contact NASA back on Earth.

As he overcomes one seemingly insurmountable obstacle after the next, Mark begins to let himself believe he might make it off the planet alive.

But Mars has plenty of surprises in store for him yet.

Grounded in real, present-day science from the first page to the last. yet propelled by a brilliantly ingenious plot that surprises the reader again and again, The Martian is a truly remarkable thriller: an impossible-to- put-down suspense novel that manages tc read like a real-life survival tale.', 385, 659, 2011, 292354, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Leaves', 'Mark Z. Danielewski', '1417709049', 'https://assets.hardcover.app/edition/30496249/35f243520f8801a93728f653e67f68a31b7b47fc.jpeg', 'House of Leaves is an epistolary fiction and metafiction novel focusing on a fictional documentary film titled the Navidson Record, presented as a story within a story discussed in a handwritten monograph recovered by the primary narrator, Johnny Truant. The narrative makes heavy use of multiperspectivity as Truant''s footnotes chronicle his efforts to transcribe the manuscript, which itself reveals the Navidson Record''s supposed narrative through transcriptions and analysis depicting a story of a family who discovers a larger-on-the-inside labyrinth in their house.', 709, null, 1999, 301814, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Twilight', 'Stephenie Meyer', '1546008128', 'https://assets.hardcover.app/edition/19228247/0e4edc828d09c7efd08df09e37b04aab3f4026dd.jpeg', 'Isabella Swan''s move to Forks, a small, perpetually rainy town in Washington, could have been the most boring move she ever made. But once she meets the mysterious and alluring Edward Cullen, Isabella''s life takes a thrilling and terrifying turn.

Up until now, Edward has managed to keep his vampire identity a secret in the small community he lives in, but now nobody is safe, especially Isabella, the person Edward holds most dear. The lovers find themselves balanced precariously on the point of a knife -- between desire and danger.

Deeply romantic and extraordinarily suspenseful, Twilight captures the struggle between defying our instincts and satisfying our desires. This is a love story with bite.', 544, 773, 2005, 302088, (select id from series where hardcover_id = 5451), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Perdido Street Station', 'China Miéville', '8466660852', 'https://assets.hardcover.app/edition/30422680/843c4447-94b2-4ba0-814d-91102129455f.jpg', 'Beneath the towering bleached ribs of a dead, ancient beast lies New Crobuzon, a squalid city where humans, Re-mades, and arcane races live in perpetual fear of Parliament and its brutal militia. The air and rivers are thick with factory pollutants and the strange effluents of alchemy, and the ghettos contain a vast mix of workers, artists, spies, junkies, and whores. In New Crobuzon, the unsavory deal is stranger to none—not even to Isaac, a brilliant scientist with a penchant for Crisis Theory.

Isaac has spent a lifetime quietly carrying out his unique research. But when a half-bird, half-human creature known as the Garuda comes to him from afar, Isaac is faced with challenges he has never before fathomed. Though the Garuda''s request is scientifically daunting, Isaac is sparked by his own curiosity and an uncanny reverence for this curious stranger.

While Isaac''s experiments for the Garuda turn into an obsession, one of his lab specimens demands attention: a brilliantly colored caterpillar that feeds on nothing but a hallucinatory drug and grows larger—and more consuming—by the day. What finally emerges from the silken cocoon will permeate every fiber of New Crobuzon—and not even the Ambassador of Hell will challenge the malignant terror it invokes . . .

A magnificent fantasy rife with scientific splendor, magical intrigue, and wonderfully realized characters, told in a storytelling style in which Charles Dickens meets Neal Stephenson, Perdido Street Station offers an eerie, voluptuously crafted world that will plumb the depths of every reader''s imagination.', 867, 1449, 2000, 305782, (select id from series where hardcover_id = 1117), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lovely Bones', 'Alice Sebold', '0330544608', 'https://assets.hardcover.app/edition/6760075/c831b07e0a1ab1b885901bba86fceb5aeca5efee.jpeg', '"My name was Salmon, like the fish; first name, Susie. I was fourteen when I was murdered on December 6, 1973."

So begins the story of Susie Salmon, who is adjusting to her new home in heaven, a place that is not at all what she expected, even as she is watching life on earth continue without her -- her friends trading rumors about her disappearance, her killer trying to cover his tracks, her grief-stricken family unraveling. Out of unspeakable tragedy and loss, The Lovely Bones succeeds, miraculously, in building a tale filled with hope, humor, suspense, even joy.', 352, null, 2002, 306454, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Scythe', 'Neal Shusterman', '8416858497', 'https://assets.hardcover.app/external_data/29353414/47343a2fd959964d0f01aa6ce204bb4e2465e101.jpeg', 'A world with no hunger, no disease, no war, no misery: humanity has conquered all those things, and has even conquered death. Now Scythes are the only ones who can end life—and they are commanded to do so, in order to keep the size of the population under control.

Citra and Rowan are chosen to apprentice to a scythe—a role that neither wants. These teens must master the “art” of taking life, knowing that the consequence of failure could mean losing their own.

Scythe is the first novel of a thrilling new series by National Book Award–winning author Neal Shusterman in which Citra and Rowan learn that a perfect world comes only with a heavy price.', 464, null, 2016, 308655, (select id from series where hardcover_id = 5557), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Old Man''s War', 'John Scalzi', '5041637938', 'https://assets.hardcover.app/edition/18117782/5a87dd758427401aad14591ca552a763123f9b2b.jpeg', 'John Perry did two things on his 75th birthday. First he visited his wife''s grave. Then he joined the army.

The good news is that humanity finally made it into interstellar space. The bad news is that planets fit to live on are scarce-- and alien races willing to fight us for them are common. So: we fight. To defend Earth, and to stake our own claim to planetary real estate. Far from Earth, the war has been going on for decades: brutal, bloody, unyielding.

Earth itself is a backwater. The bulk of humanity''s resources are in the hands of the Colonial Defense Force. Everybody knows that when you reach retirement age, you can join the CDF. They don''t want young people; they want people who carry the knowledge and skills of decades of living. You''ll be taken off Earth and never allowed to return. You''ll serve two years at the front. And if you survive, you''ll be given a generous homestead stake of your own, on one of our hard-won colony planets.

John Perry is taking that deal. He has only the vaguest idea what to expect. Because the actual fight, light-years from home, is far, far harder than he can imagine--and what he will become is far stranger.', 320, 595, 2005, 309315, (select id from series where hardcover_id = 1048), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Grave Peril', 'Jim Butcher', '3734163374', 'https://assets.hardcover.app/editions/30117722/3852046485953567.jpg', 'Now in hardcover from the New York Times bestselling author of The Dresden Files.Harry Dresden''s faced some pretty terrifying foes during his career. Giant scorpions. Oversexed vampires. Psychotic werewolves. All par for the course for Chicago''s only professional wizard.But in all of Harry''s years of supernatural sleuthing, he''s never faced anything like this: the spirit world''s gone postal. All over Chicago, ghosts are causing trouble—and not just of the door-slamming, ''boo''- shouting variety. These ghosts are tormented, violent, and deadly.Someone—or something—is stirring them up to wreak unearthly havoc. But why? And why do so many of the victims have ties to Harry? If Harry doesn''t figure it out soon, he could wind up a ghost himself.', 465, null, 1995, 309362, (select id from series where hardcover_id = 990), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cinder', 'Marissa Meyer', '8418359226', 'https://assets.hardcover.app/edition/31488774/c0c1665bbdda7b13ca56950b8aea7472a410e941.jpeg', 'Humans and androids crowd the raucous streets of New Beijing. A deadly plague ravages the population. From space, a ruthless lunar people watch, waiting to make their move. No one knows that Earth''s fate hinges on one girl. . . .

Cinder, a gifted mechanic, is a cyborg. She''s a second-class citizen with a mysterious past, reviled by her stepmother and blamed for her stepsister''s illness. But when her life becomes intertwined with the handsome Prince Kai''s, she suddenly finds herself at the center of an intergalactic struggle, and a forbidden attraction. Caught between duty and freedom, loyalty and betrayal, she must uncover secrets about her past in order to protect her world''s future.

With high-stakes action and a smart, resourceful heroine, Cinder is a Cinderella retelling that is at once classic and strikingly original.', 390, null, 2012, 309809, (select id from series where hardcover_id = 5558), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Caves of Steel', 'Isaac Asimov', '0606192727', 'https://assets.hardcover.app/external_data/4209294/f26810b4fdc819234c93fd46af13d46c434b034a.jpeg', '"A Del Rey book." 

It was bad enough when Lije Baley, a simple plainclothes cop, was ordered to solve a totally baffling mystery - the murder of a prominent Spacer. It was worse when he found that the smug, self-satisfied Spacers were behind the pressure to provide an impossibly quick solution.

But then Lije discovered the worst of all bad news. The Spacers, distrusting all Earthmen, insisted he must work with an investigator of their choice. And that investigator turned out to be R. Daneel Olivaw. R stood for robot--and Lije hated and feared robots deeply, bitterly and pathologically.

Issac Asimov''s The Naked Sun and The Caves of Steel are two of the most famous science-fiction novels ever. They are set long after mankind - aided by the positronic robot - has colonized the worlds of other suns. This is a time of growing concern between Earthmen and Spacers. Lije Baley, who is filled with all Earths prejudice agains robots and Spacers, must learn to work together with a seemingly human robot to solve apparently impossible crimes that threaten the fragile link between Earth and Space.', 272, null, 1953, 312167, (select id from series where hardcover_id = 1044), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dune', 'Frank Herbert, Brian Herbert', '8417347623', 'https://assets.hardcover.app/editions/30426415/8362709973192601-9780441013593-us.jpg', 'Set on the desert planet Arrakis, Dune is the story of the boy Paul Atreides, heir to a noble family tasked with ruling an inhospitable world where the only thing of value is the “spice” melange, a drug capable of extending life and enhancing consciousness. Coveted across the known universe, melange is a prize worth killing for...

When House Atreides is betrayed, the destruction of Paul’s family will set the boy on a journey toward a destiny greater than he could ever have imagined. And as he evolves into the mysterious man known as Muad’Dib, he will bring to fruition humankind’s most ancient and unattainable dream.', 704, 1262, 1965, 312460, (select id from series where hardcover_id = 1150), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow and Bone', 'Leigh Bardugo', '1250048117', 'https://assets.hardcover.app/editions/30503452/2167790222047428.jpeg', 'Discover the adventure that started it all and meet Alina, Mal, and the Darkling in Shadow and Bone from #1 bestselling author, Leigh Bardugo.

Soldier. Summoner. Saint. Orphaned and expendable, Alina Starkov is a soldier who knows she may not survive her first trek across the Shadow Fold―a swath of unnatural darkness crawling with monsters. But when her regiment is attacked, Alina unleashes dormant magic not even she knew she possessed.

Now Alina will enter a lavish world of royalty and intrigue as she trains with the Grisha, her country’s magical military elite―and falls under the spell of their notorious leader, the Darkling. He believes Alina can summon a force capable of destroying the Shadow Fold and reuniting their war-ravaged country, but only if she can master her untamed gift.

As the threat to the kingdom mounts and Alina unlocks the secrets of her past, she will make a dangerous discovery that could threaten all she loves and the very future of a nation.

Welcome to Ravka . . . a world of science and superstition where nothing is what it seems.', 411, null, 2012, 312762, (select id from series where hardcover_id = 1067), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Senlin Ascends', 'Josiah Bancroft', '0356510816', 'https://assets.hardcover.app/editions/31447064/2316150514620865.jpg', 'The Tower of Babel is the greatest marvel of the Silk Age. Immense as a mountain, the ancient Tower holds unnumbered ringdoms, warring and peaceful, stacked one on the other like the layers of a cake.

Thomas Senlin, the mild-mannered headmaster of a small village school, is drawn to the Tower by scientific curiosity and the grandiose promises of a guidebook. The luxurious Baths of the Tower seem an ideal destination for a honeymoon, but soon after arriving, Senlin loses Marya in the crowd. Senlin’s search for Marya carries him through madhouses, ballrooms, and burlesque theaters. He must survive betrayal, assassination, and the long guns of a flying fortress.

But if he hopes to ever find his wife, Thomas Senlin must do more than survive. This quiet man of letters must become a man of action.', 371, null, 2013, 313034, (select id from series where hardcover_id = 5772), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Neuromancer', 'William Gibson', '9612310203', 'https://assets.hardcover.app/editions/30401722/203725739738019-PxOL.jpg', 'Case was the sharpest data-thief in the matrix—until he crossed the wrong people and they crippled his nervous system, banishing him from cyberspace. Now a mysterious new employer has recruited him for a last-chance run at an unthinkably powerful artificial intelligence. With a dead man riding shotgun and Molly, a mirror-eyed street-samurai, to watch his back, Case is ready for the adventure that upped the ante on an entire genre of fiction.

Neuromancer was the first fully-realized glimpse of humankind’s digital future—a shocking vision that has challenged our assumptions about technology and ourselves, reinvented the way we speak and think, and forever altered the landscape of our imaginations.', 271, null, 1984, 313448, (select id from series where hardcover_id = 19911), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Eragon', 'Christopher Paolini', '881706162X', 'https://assets.hardcover.app/editions/30399869/8816624490580869-91JrDpvTiML._SL1500_.jpg', 'When fifteen-year-old Eragon finds a polished blue stone in the forest, he thinks it is the lucky discovery of a poor farm boy. But when the stone brings a dragon hatchling, Eragon soon realizes he has stumbled upon a legacy nearly as old as the Empire itself.

Overnight his simple life is shattered, and, gifted with only an ancient sword, a loyal dragon, and sage advice from an old storyteller, Eragon is soon swept into a dangerous tapestry of magic, glory, and power. Now his choices could save—or destroy—the Empire.', 518, null, 2002, 316971, (select id from series where hardcover_id = 5464), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gardens of the Moon', 'Steven Erikson', '8490696675', 'https://assets.hardcover.app/editions/30500398/1876069679358250.jpeg', 'The Malazan Empire simmers with discontent, bled dry by interminable warfare, bitter infighting and bloody confrontations with the formidable Anomander Rake and his Tiste Andii, ancient and implacable sorcerers. Even the imperial legions, long inured to the bloodshed, yearn for some respite. Yet Empress Laseen''s rule remains absolute, enforced by her dread Claw assassins. 

For Sergeant Whiskeyjack and his squad of Bridgeburners, and for Tattersail, surviving cadre mage of the Second Legion, the aftermath of the siege of Pale should have been a time to mourn the many dead. But Darujhistan, last of the Free Cities of Genabackis, yet holds out. It is to this ancient citadel that Laseen turns her predatory gaze. 

However, it would appear that the Empire is not alone in this great game. Sinister, shadowbound forces are gathering as the gods themselves prepare to play their hand... 

Conceived and written on a panoramic scale, Gardens of the Moon is epic fantasy of the highest order--an enthralling adventure by an outstanding new voice.', 499, null, 1999, 319998, (select id from series where hardcover_id = 1167), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Uprooted', 'Naomi Novik', '9504957390', 'https://assets.hardcover.app/edition/30399522/17a809dbce6e6922d131fe75b357f75eef12392b.jpeg', 'Agnieszka loves her valley home, her quiet village, the forests and the bright shining river. But the corrupted Wood stands on the border, full of malevolent power, and its shadow lies over her life.

Her people rely on the cold, driven wizard known only as the Dragon to keep its powers at bay. But he demands a terrible price for his help: one young woman handed over to serve him for ten years, a fate almost as terrible as falling to the Wood.

The next choosing is fast approaching, and Agnieszka is afraid. She knows—everyone knows—that the Dragon will take Kasia: beautiful, graceful, brave Kasia, all the things Agnieszka isn’t, and her dearest friend in the world. And there is no way to save her.

But Agnieszka fears the wrong things. For when the Dragon comes, it is not Kasia he will choose.', 438, null, 2015, 320166, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('If We Were Villains', 'M.L. Rio', '3328100539', 'https://assets.hardcover.app/book_mappings/7332896/3d6f1c74c62f208ce1605c61bab47389b771bcbd.jpeg', 'On the day Oliver Marks is released from jail, the man who put him there is waiting at the door. Detective Colborne wants to know the truth, and after ten years, Oliver is finally ready to tell it.

A decade ago: Oliver is one of seven young Shakespearean actors at Dellecher Classical Conservatory, a place of keen ambition and fierce competition. In this secluded world of firelight and leather-bound books, Oliver and his friends play the same roles onstage and off: hero, villain, tyrant, temptress, ingénue, extras.

But in their fourth and final year, good-natured rivalries turn ugly, and on opening night real violence invades the students’ world of make-believe. In the morning, the fourth-years find themselves facing their very own tragedy, and their greatest acting challenge yet: convincing the police, each other, and themselves that they are innocent.

If We Were Villains was named one of Bustle''s Best Thriller Novels of the Year, and Mystery Scene says, "A well-written and gripping ode to the stage...A fascinating, unorthodox take on rivalry, friendship, and truth."', 368, null, 2017, 321898, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sourcery', 'Terry Pratchett', '0613572785', 'https://assets.hardcover.app/edition/30773761/5aef81ac-7d0f-4526-985d-d9a27a20e803.jpg', '''It''s vital to remember who you really are . . . it isn''t a good idea to rely on other people or things to do it for you, you see. They always get it wrong.'' An eighth son of an eighth son is born, a wizard squared, a source of magic. A sourcerer. Unseen University, the Discworld''s most magical establishment, has finally got its wish: the emergence of a wizard more powerful than ever before. You''d think they would have been a little more careful what they wished for . . . As the sourcerer takes over the University and sets his sights on the rest of the world, only one wizard manages to escape his influence. Unfortunately for everyone, it''s Rincewind. Once again the cowardly wizard must embark on a quest: to deliver a precious artefact - the very embodiment of magic itself - halfway across the Disc to safety. If he doesn''t make it, the death of all wizardry is at hand. And the end of the world, depending on who you listen to. ''One of our greatest fantasists, and beyond a doubt the funniest'' George R.R. Martin ''May well be considered his masterpiece . . . Humour such as his is an endangered species'' The Times Sourcery is the third book in the Wizards series, but you can read the Discworld novels in any order.', 336, null, 1988, 325229, (select id from series where hardcover_id = 1018), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Closed and Common Orbit', 'Becky Chambers', '9791036001260', 'https://assets.hardcover.app/editions/30402676/8224997564885397.jpg', 'A Publishers Weekly "Best Books of 2017" pick! Nominated for the 2017 Hugo Award for Best Novel! Shortlisted for the 2017 Arthur C. Clarke Award! Winner of the Prix Julia-Verlanger! Embark on an exciting, adventurous, and dangerous journey through the galaxy with the motley crew of the spaceship Wayfarer in this fun and heart-warming space opera—the sequel to the acclaimed The Long Way to a Small, Angry Planet. Lovelace was once merely a ship’s artificial intelligence. When she wakes up in a new body, following a total system shut-down and reboot, she has no memory of what came before. As Lovelace learns to negotiate the universe and discover who she is, she makes friends with Pepper, an excitable engineer, who’s determined to help her learn and grow. Together, Pepper and Lovey will discover that no matter how vast space is, two people can fill it together. The Long Way to a Small, Angry Planet introduced readers to the incredible world of Rosemary Harper, a young woman with a restless soul and secrets to keep. When she joined the crew of the Wayfarer, an intergalactic ship, she got more than she bargained for—and learned to live with, and love, her rag-tag collection of crewmates. A Closed and Common Orbit is the stand-alone sequel to that beloved debut novel, and is perfect for fans of Firefly, Joss Whedon, Mass Effect, and Star Wars.', 384, null, 2016, 325996, (select id from series where hardcover_id = 1092), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Philosopher''s Stone', 'J.K. Rowling', '8478884459', 'https://assets.hardcover.app/edition/2667580/06168492-bf52-4333-9ac6-66ed21907865.jpg', 'Harry Potter has never been the star of a Quidditch team, scoring points while riding a broom far above the ground. He knows no spells, has never helped to hatch a dragon, and has never worn a cloak of invisibility.

All he knows is a miserable life with the Dursleys, his horrible aunt and uncle, and their abominable son, Dudley - a great big swollen spoiled bully. Harry''s room is a tiny closet at the foot of the stairs, and he hasn''t had a birthday party in eleven years.

But all that is about to change when a mysterious letter arrives by owl messenger: a letter with an invitation to an incredible place that Harry - and anyone who reads about him - will find unforgettable.

For it''s there that he finds not only friends, aerial sports, and magic in everything from classes to meals, but a great destiny that''s been waiting for him... if Harry can survive the encounter.', 309, 521, 1997, 328491, (select id from series where hardcover_id = 1185), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Alloy of Law', 'Brandon Sanderson', '8419260215', 'https://assets.hardcover.app/book_mappings/7332580/a023478571f1bbf153f3e671c56cd0cc6c5182c3.jpeg', '"Three hundred years after the events of the Mistborn trilogy, Scadrial is on the verge of modernity, with railroads to supplement the canals, electric lighting in the streets and the homes of the wealthy, and the first steel-framed skyscrapers racing for the clouds. Kelsier, Vin, Elend, Sazed, Spook, and the rest are now part of history--or religion. Yet even as science and technology are reaching new heights, the old magics of Allomancy and Feruchemy continue to play a role in this reborn world. Out in the frontier lands known as the Roughs, they are crucial tools for the brave men and women attempting to establish order and justice. One such is Waxillium Ladrian, a rare Twinborn who can Push on metals with hisAllomancy and use Feruchemy to become lighter or heavier at will. After twenty years in the Roughs, Wax has been forced by family tragedy to return to the metropolis of Elendel. Now he must reluctantly put away his guns and assume the duties and dignity incumbent upon the head of a noble house. Or so he thinks, until he learns the hard way that the mansions and elegant tree-lined streets of the city can be even more dangerous than the dusty plains of the Roughs."--', 325, 648, 2011, 330249, (select id from series where hardcover_id = 10825), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Ashes', 'Cassandra Clare', '0606106405', 'https://assets.hardcover.app/external_data/1086138/d24e76ed5ae762e76795ea16a1c24297c3e167f7.jpeg', 'Clary Fray just wishes that her life would go back to normal. But what''s normal when you''re a demon-slaying Shadowhunter, your mother is in a magically induced coma, and you can suddenly see Downworlders like werewolves, vampires, and faeries? If Clary left the world of the Shadowhunters behind, it would mean more time with her best friend, Simon, who''s becoming more than a friend. But the Shadowhunting world isn''t ready to let her go -- especially her handsome, infuriating, newfound brother, Jace. And Clary''s only chance to help her mother is to track down rogue Shadowhunter Valentine, who is probably insane, certainly evil—and also her father.

To complicate matters, someone in New York City is murdering Downworlder children. Is Valentine behind the killings—and if he is, what is he trying to do? When the second of the Mortal Instruments, the Soul-Sword, is stolen, the terrifying Inquisitor arrives to investigate and zooms right in on Jace. How can Clary stop Valentine if Jace is willing to betray everything he believes in to help their father?

In this breathtaking sequel to City of Bones, Cassandra Clare lures her readers back into the dark grip of New York City''s Downworld, where love is never safe and power becomes the deadliest temptation.', 411, null, 2007, 332243, (select id from series where hardcover_id = 5473), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cloud Atlas', 'David Mitchell', '0812984420', 'https://assets.hardcover.app/book_mappings/7332476/6f64bd9cf3ea5cf6fd5ab88786fd2b0955e17d67.jpeg', 'Cloud Atlas begins in 1850 with Adam Ewing, an American notary voyaging from the Chatham Isles to his home in California. Along the way, Ewing is befriended by a physician, Dr. Goose, who begins to treat him for a rare species of brain parasite. . . .

Abruptly, the action jumps to Belgium in 1931, where Robert Frobisher, a disinherited bisexual composer, contrives his way into the household of an infirm maestro who has a beguiling wife and a nubile daughter. . . . From there we jump to the West Coast in the 1970s and a troubled reporter named Luisa Rey, who stumbles upon a web of corporate greed and murder that threatens to claim her life. . . . And onward, with dazzling virtuosity, to an inglorious present-day England; to a Korean superstate of the near future where neocapitalism has run amok; and, finally, to a postapocalyptic Iron Age Hawaii in the last days of history.

But the story doesn’t end even there. The narrative then boomerangs back through centuries and space, returning by the same route, in reverse, to its starting point. Along the way, Mitchell reveals how his disparate characters connect, how their fates intertwine, and how their souls drift across time like clouds across the sky.', 509, null, 2003, 332566, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Revelation Space', 'Alastair Reynolds', '0575068760', 'https://assets.hardcover.app/edition/30403064/4e9e1e28-0984-4971-b69a-6667ef862e2d.jpg', 'Nine hundred thousand years ago, something annihilated the Amarantin civilization just as it was on the verge of discovering space flight. Now one scientist, Dan Sylveste, will stop at nothing to solve the Amarantin riddle before ancient history repeats itself. With no other resources at his disposal, Sylveste forges a dangerous alliance with the cyborg crew of the starship Nostalgia for Infinity. But as he closes in on the secret, a killer closes in on him because the Amarantin were destroyed for a reason. And if that reason is uncovered, the universe-and reality itself-could be irrevocably altered.', 596, null, 2000, 332660, (select id from series where hardcover_id = 5563), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The War of the Worlds', 'H. G. Wells', '1892062909', 'https://assets.hardcover.app/external_data/510523/5234b3cc37b46e79732c37d3954c1d1e38defa60.jpeg', 'The War of the Worlds is the first-person narrative of an unnamed protagonist in Surrey and that of his younger brother in London as Earth is invaded by Martians. Written between 1895 and 1897, it is one of the earliest stories that detail a conflict between mankind and an extraterrestrial race. The novel is one of the most commented-on works in the science fiction canon.

The narrator, a philosophically inclined author, struggles to return to his wife while seeing the Martians lay waste to the southern country outside London. Book One also imparts the experience of his brother, also unnamed, who describes events as they deteriorate in the capital, forcing him to escape the Martian onslaught by boarding a paddle steamer near Tilling ham, on the Essex coast.', 245, null, 1898, 335598, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Redshirts', 'John Scalzi', '1469299178', 'https://assets.hardcover.app/edition/30399438/3dcf82e134a998e9be5065a6c43a4e6ceb30a75f.jpeg', 'Ensign Andrew Dahl has just been assigned to the Universal Union Capital Ship Intrepid, flagship of the Universal Union since the year 2456. It’s a prestige posting, and Andrew is thrilled all the more to be assigned to the ship’s Xenobiology laboratory.

Life couldn’t be better…until Andrew begins to pick up on the fact that:
(1) every Away Mission involves some kind of lethal confrontation with alien forces
(2) the ship’s captain, its chief science officer, and the handsome Lieutenant Kerensky always survive these confrontations
(3) at least one low-ranked crew member is, sadly, always killed.

Not surprisingly, a great deal of energy below decks is expended on avoiding, at all costs, being assigned to an Away Mission. Then Andrew stumbles on information that completely transforms his and his colleagues’ understanding of what the starship Intrepid really is…and offers them a crazy, high-risk chance to save their own lives.', 318, null, 2012, 336161, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Aristotle and Dante Discover the Secrets of the Universe', 'Benjamin Alire Sáenz', '8367815823', 'https://assets.hardcover.app/edition/32059402/e10016c7-9fba-4667-aa2e-ae1dc9faf79e.jpg', 'Aristotle is an angry teen with a brother in prison. Dante is a know-it-all who has an unusual way of looking at the world. When the two meet at the swimming pool, they seem to have nothing in common. But as the loners start spending time together, they discover that they share a special friendship—the kind that changes lives and lasts a lifetime. And it is through this friendship that Ari and Dante will learn the most important truths about themselves and the kind of people they want to be.', 368, null, 2012, 336232, (select id from series where hardcover_id = 1399), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Alchemist', 'Paulo Coelho', '8858765737', 'https://assets.hardcover.app/editions/30399646/6724991536065856.jpg', 'Combining magic, mysticism, wisdom and wonder into an inspiring tale of self-discovery, The Alchemist has become a modern classic, selling millions of copies around the world and transforming the lives of countless readers across generations.

Paulo Coelho''s masterpiece tells the mystical story of Santiago, an Andalusian shepherd boy who yearns to travel in search of a worldly treasure. His quest will lead him to riches far different—and far more satisfying—than he ever imagined. Santiago''s journey teaches us about the essential wisdom of listening to our hearts, of recognizing opportunity and learning to read the omens strewn along life''s path, and, most importantly, to follow our dreams.', 181, null, 1988, 337236, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Around the World in Eighty Days', 'Jules Verne, Henry Frith', '2092703390', 'https://assets.hardcover.app/external_data/61911333/fb0269566478f75747dfda5d2cbd3cdbf86ebbcf.jpeg', 'In 1872 Phileas Fogg wins a bet by traveling around the world in seventy-nine days, twenty-three hours, and fifty-seven minutes.', 297, null, 1872, 338756, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Elantris', 'Brandon Sanderson', '8490694109', 'https://assets.hardcover.app/edition/30769393/ad110a295160ddfaf3ad12d1ee06f8193bb09d2e.jpeg', 'Elantris was the capital of Arelon: gigantic, beautiful, literally radiant, filled with benevolent beings who used their powerful magical abilities for the benefit of all. Yet each of these demigods was once an ordinary person until touched by the mysterious transforming power of the Shaod. Ten years ago, without warning, the magic failed. Elantrians became wizened, leper-like, powerless creatures, and Elantris itself dark, filthy, and crumbling.

Arelon''s new capital, Kae, crouches in the shadow of Elantris. Princess Sarene of Teod arrives for a marriage of state with Crown Prince Raoden, hoping—based on their correspondence—to also find love. She finds instead that Raoden has died and she is considered his widow. Both Teod and Arelon are under threat as the last remaining holdouts against the imperial ambitions of the ruthless religious fanatics of Fjordell. So Sarene decides to use her new status to counter the machinations of Hrathen, a Fjordell high priest who has come to Kae to convert Arelon and claim it for his emperor and his god.

But neither Sarene nor Hrathen suspect the truth about Prince Raoden. Stricken by the same curse that ruined Elantris, Raoden was secretly exiled by his father to the dark city. His struggle to help the wretches trapped there begins a series of events that will bring hope to Arelon, and perhaps reveal the secret of Elantris itself.

A rare epic fantasy that doesn''t recycle the classics and that is a complete and satisfying story in one volume, Elantris is fleet and fun, full of surprises and characters to care about. It''s also the wonderful debut of a welcome new star in the constellation of fantasy.', 656, null, 2005, 338931, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wicked: The Life and Times of the Wicked Witch of the West', 'Gregory Maguire', '9639943185', 'https://assets.hardcover.app/edition/19104484/0a9c25c0e836e63bf1cf2d2a69aa9e19a2c1b104.jpeg', 'A fable for adults on the subject of destiny and free will by a writer of children''s books. It tells the story of Elphaba before she became the Wicked Witch of the West in the land of Oz. The novel traces her career as nun, nurse, pro-democracy activist and animal rights defender.', 519, null, 1995, 340060, (select id from series where hardcover_id = 1082), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heir to the Empire', 'Timothy Zahn', '5041752699', 'https://assets.hardcover.app/external_data/217056/83d0b50cbf8552fbad1f63fe59841adc86c1664d.jpeg', 'It''s five years after Return of the Jedi: the Rebel Alliance has destroyed the Death Star, defeated Darth Vader and the Emperor, and driven out the remnants of the old Imperial Starfleet to a distant corner of the galaxy. Princess Leia and Han Solo are married and expecting Jedi Twins. And Luke Skywalker has become the first in a long-awaited line of Jedi Knights. 

But thousand of light-years away, the last of the emperor''s warlords has taken command of the shattered Imperial Fleet, readied it for war, and pointed it at the fragile heart of the new Republic. For this dark warrior has made two vital discoveries that could destroy everything the courageous men and women of the Rebel Alliance fought so hard to build. The explosive confrontation that results is a towering epic of action, invention, mystery, and spectacle on a galactic scale--in short, a story worthy of the name Star Wars.', 528, null, 1991, 340125, (select id from series where hardcover_id = 1110), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Eclipse', 'Stephenie Meyer', '5171366225', 'https://assets.hardcover.app/edition/23971221/6317e6baf6450aa00d280b9d0e4076f83e07f2ee.jpeg', 'As Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge, Bella once again finds herself surrounded by danger. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob—knowing that her decision has the potential to ignite the ageless struggle between vampire and werewolf.

With her graduation quickly approaching, Bella has one more decision to make: life or death?', 628, null, 2006, 342900, (select id from series where hardcover_id = 5451), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Fallen Angels', 'Cassandra Clare, Ed Westwick, Molly C. Quinn', '0606269088', 'https://assets.hardcover.app/external_data/1469472/e8780d2a7787b49056561621242b48a479858102.jpeg', 'The Mortal War is over, and sixteen-year-old Clary Fray is back home in New York, excited about all the possibilities before her. She’s training to become a Shadowhunter and to use her unique power. Her mother is getting married to the love of her life. Downworlders and Shadowhunters are at peace at last. And—most importantly of all—she can finally call Jace her boyfriend.

But nothing comes without a price.

Someone is murdering Shadowhunters, provoking tensions between Downworlders and Shadowhunters that could lead to a second, bloody war. Clary’s best friend, Simon, can’t help her—his mother just found out that he’s a vampire, and now he’s homeless. When Jace begins to pull away from her without explaining why, Clary is forced to delve into the heart of a mystery whose solution reveals her worst nightmare: she herself has set in motion a terrible chain of events that could lead to her losing everything she loves. Even Jace.

The stakes are higher than ever in the #1 New York Times bestselling fourth installment of the Mortal Instruments series.', 448, null, 2010, 343351, (select id from series where hardcover_id = 5473), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The First Fifteen Lives of Harry August', 'Claire North', '8763841045', 'https://assets.hardcover.app/edition/30566209/1382656f-d88f-4ebd-bd72-1be12faec58f.jpg', 'Wildly original, funny and moving, The First Fifteen Lives of Harry August is an extraordinary story of a life lived again and again from World Fantasy Award-winning author Claire North.

Harry August is on his deathbed. Again.

No matter what he does or the decisions he makes, when death comes, Harry always returns to where he began, a child with all the knowledge of a life he has already lived a dozen times before. Nothing ever changes.

Until now.

As Harry nears the end of his eleventh life, a little girl appears at his bedside. "I nearly missed you, Doctor August," she says. "I need to send a message."

This is the story of what Harry does next, and what he did before, and how he tries to save a past he cannot change and a future he cannot allow.', 328, null, 2014, 345034, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foundation and Empire', 'Isaac Asimov', '0553452614', 'https://assets.hardcover.app/edition/8692763/eff62819-e469-44f6-af08-4f7982e62546.jpg', 'Led by its founding father, the psychohistorian Hari Seldon, and utilizing science and technology, the Foundation survived the greed and barbarism of its neighboring warrior-planets. Now cleverness and courage may not be enough. For the Empire—the mightiest force in the Galaxy—is even more dangerous in its death throes. Even worse, a mysterious entity called the Mule has appeared with powers beyond anything humanly conceivable. Who—or what—is the Mule? And how is humanity to defend itself against this invulnerable avatar of annihilation?

Filled with nail-biting suspense, nonstop action, and cutting-edge speculation, Foundation and Empire is the story of humanity’s perpetual struggle against the darkness that forever threatens to overwhelm the light—and of how the courage of even a determined few can make all the difference in the universe.', 216, null, 2000, 347189, (select id from series where hardcover_id = 5450), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Alice''s Adventures in Wonderland / Through the Looking-Glass', 'Lewis Carroll, John Tenniel, Martin Gardner', '1454937939', 'https://assets.hardcover.app/external_data/33686436/2b79f8eb2bbf2e260d5e9489b1b60a7ec5b612f0.jpeg', 'A very real little girl named Alice follows a remarkable rabbit down a rabbit hole and steps through a looking-glass to come face to face with some of the strangest adventures and some of the oddest characters in all literature. The crusty Duchess, the Mad Hatter, the weeping Mock Turtle, the diabolical Queen of Hearts, the Cheshire-Cat, Tweedledum and Tweedledee--each one is more eccentric, and more entertaining, than the last. And all of them could only have come from the pen of Lewis Carroll, one of the few adults ever to enter successfully the children''s world of make-believe--a wonderland where the impossible becomes possible, the unreal, real...where the heights of adventure are limited only by the depths of imagination.
--back cover

Contains:

 - [Alice''s Adventures in Wonderland](https://openlibrary.org/works/OL8193508W)
 - [Through the Looking Glass, and What Alice Found There][2]

  [2]: https://openlibrary.org/works/OL15298516W', 239, null, 1871, 347503, (select id from series where hardcover_id = 5751), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cosmos', 'Carl Sagan, Paulo Geiger', '286374075X', 'https://assets.hardcover.app/edition/30405706/2ff2b3f7c52439133219623498812f604d38ca68.jpeg', 'This book is about science in its broadest human context, how science and civilization grew up together. It is the story of our long journey of discovery and the forces and individuals who helped to shape modern science, including Democritus, Hypatia, Kepler, Newton, Huygens, Champollion, Lowell and Humason. The book also explores spacecraft missions of discovery of the nearby planets, the research in the Library of ancient Alexandria, the human brain, Egyptian hieroglyphics, the origin of life, the death of the Sun, the evolution of galaxies and the origins of matter, suns and worlds. The author retraces the fifteen billion years of cosmic evolution that have transformed matter into life and consciousness, enabling the cosmos to wonder about itself. He considers the latest findings on life elsewhere and how we might communicate with the beings of other worlds. ~ WorldCat.org', 450, null, 1980, 349240, (select id from series where hardcover_id = 219692), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Roadside Picnic', 'Arkady Strugatsky, Boris Strugatsky, Olena Bormashenko, Ursula K. Le Guin', '0575079789', 'https://assets.hardcover.app/external_data/4101590/7876863131b73b500e9bfc0b0827a7aa971b510c.jpeg', 'Red Schuhart is a stalker, one of those young rebels who are compelled, in spite of extreme danger, to venture illegally into the Zone to collect the mysterious artifacts that the alien visitors left scattered around. His life is dominated by the place and the thriving black market in the alien products. But when he and his friend Kirill go into the Zone together to pick up a “full empty,” something goes wrong. And the news he gets from his girlfriend upon his return makes it inevitable that he’ll keep going back to the Zone, again and again, until he finds the answer to all his problems.

First published in 1972, Roadside Picnic is still widely regarded as one of the greatest science fiction novels, despite the fact that it has been out of print in the United States for almost thirty years.', 226, null, 1972, 350457, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mr. Penumbra''s 24-Hour Bookstore', 'Robin Sloan', '1611736099', 'https://assets.hardcover.app/book_mappings/7332685/5dd0f57f4912eb3be809f0daea088bb9834a07c8.jpeg', 'The Great Recession has shuffled Clay Jannon away from life as a San Francisco web-design drone and into the aisles of Mr. Penumbra''s 24-Hour Bookstore, but after a few days on the job, Clay discovers that the store is more curious than either its name or its gnomic owner might suggest. The customers are few, and they never seem to buy anything; instead, they "check out" large, obscure volumes from strange corners of the store. Suspicious, Clay engineers an analysis of the clientele''s behavior, seeking help from his variously talented friends, but when they bring their findings to Mr. Penumbra, they discover the bookstore''s secrets extend far beyond its walls.', 306, null, 2012, 350896, (select id from series where hardcover_id = 2945), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Golden Compass', 'Philip Pullman', '1407154168', 'https://assets.hardcover.app/editions/19151716/902688047208777-119322.jpg', 'Lyra is rushing to the cold, far North, where witch clans and armored bears rule. North, where the Gobblers take the children they steal—including her friend Roger. North, where her fearsome uncle Asriel is trying to build a bridge to a parallel world.

Can one small girl make a difference in such great and terrible endeavors? This is Lyra: a savage, a schemer, a liar, and as fierce and true a champion as Roger or Asriel could want.

But what Lyra doesn''t know is that to help one of them will be to betray the other...

A masterwork of storytelling and suspense, Philip Pullman''s award-winning The Golden Compass is the first in the His Dark Materials series, which continues with The Subtle Knife and The Amber Spyglass.', 399, null, 1995, 355708, (select id from series where hardcover_id = 1025), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Gathering of Shadows', 'V. E. Schwab', '5171388210', 'https://assets.hardcover.app/edition/23017524/4ad6ffed08df838c3c653c66844d270c26b768de.jpeg', 'Four months have passed since the shadow stone fell into Kell''s possession. Four months since his path crossed with Delilah Bard. Four months since Rhy was wounded and the Dane twins fell, and the stone was cast with Holland''s dying body through the rift, and into Black London. In many ways, things have almost returned to normal, though Rhy is more sober, and Kell is now plagued by his guilt. Restless, and having given up smuggling, Kell is visited by dreams of ominous magical events, waking only to think of Lila, who disappeared from the docks like she always meant to do. 

As Red London finalizes preparations for the Element Games-an extravagant international competition of magic, meant to entertain and keep healthy the ties between neighboring countries-a certain pirate ship draws closer, carrying old friends back into port. But while Red London is caught up in the pageantry and thrills of the Games, another London is coming back to life, and those who were thought to be forever gone have returned. After all, a shadow that was gone in the night reappears in the morning, and so it seems Black London has risen again-and so to keep magic''s balance, another London must fall.', 512, null, 2015, 358274, (select id from series where hardcover_id = 1040), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gravity''s Rainbow', 'Thomas Pynchon', '8779171885', 'https://assets.hardcover.app/editions/4647782/8271945363577893-gravitysrainbow.jpg', 'Enigmatic American author Thomas Pynchon''s classic novel, Gravity''s Rainbow. Set primarily in Europe at the end of World War II, the novel centers on the design, production and dispatch of V-2 rockets by the German military. In particular, it features the quest undertaken by several characters to uncover the secret of a mysterious device, the Schwarzgerät ("black device"), which is slated to be installed in a rocket with the serial number "00000". 

Traversing a wide range of knowledge, Gravity''s Rainbow crosses boundaries between high and low culture, between literary propriety and profanity, and between science and speculative metaphysics.', 760, null, 1973, 360347, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Canticle for Leibowitz', 'Walter M. Miller Jr.', '0808520938', 'https://assets.hardcover.app/external_data/830792/f98d28247f254c645efdc996244e1b5a5813b62e.jpeg', 'From here the story spans centuries of ignorance, violence, and barbarism, viewing through a sharp, satirical eye the relentless progression of a human race damned by its inherent humanness to recelebrate its grand foibles and repeat its grievous mistakes. 

Seriously funny, stunning, and tragic, eternally fresh, imaginative, and altogether remarkable, A Canticle for Leibowitz retains its ability to enthrall and amaze. It is now, as it always has been, a masterpiece.', 313, null, 1959, 361784, (select id from series where hardcover_id = 1080), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Magician: Apprentice', 'Raymond E. Feist', '0007552009', 'https://assets.hardcover.app/editions/4903336/9517432288522652.jpg', 'An orphaned kitchen boy named Pug becomes selected as the Kingdom of Midkemia''s apprentice to the local sorcerer.  A rift opens between this world and another and a great war rages between the two. Pug is captured and a secret magic within him discovered as that war between the two planets continues.  There is great magic, fantasy and personal connections between memorable characters.', 512, null, 1982, 362031, (select id from series where hardcover_id = 1060), 1.1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red Queen', 'Victoria Aveyard', '9542817525', 'https://assets.hardcover.app/edition/30399645/9957e40c-9c25-407e-99a2-e9bbb7bcecf7.jpg', '"Mare is a Red, scraping by as a thief in a poor, rural village, until a twist of fate throws her in front of the Silver court. Before the king, princes, and all the nobles, she discovers she has an ability of her own.

To cover up this impossibility, the king forces her to play the role of a lost Silver princess and betroths her to one of his own sons. As Mare is drawn further into the Silver world, she risks everything and uses her new position to help the Scarlet Guard--a growing Red rebellion--even as her heart tugs her in an impossible direction. One wrong move can lead to her death, but in the dangerous game she plays, the only certainty is betrayal."-- Provided by Amazon', 400, null, 2015, 362965, (select id from series where hardcover_id = 1204), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Altered Carbon', 'Richard K. Morgan', '2914370423', 'https://assets.hardcover.app/edition/30854603/fcf5039465f821ba21aeffa9fdd9db135e1d4e58.jpeg', 'The colonies are linked together by the occasional sub light colony ship voyages and hyperspatial data-casting. Human consciousness is digitally freighted between the stars and downloaded into bodies as a matter of course.

But some things never change. So when ex-envoy, now-convict Takeshi Kovacs has his consciousness and skills downloaded into the body of a nicotine-addicted ex-thug and presented with a catch-22 offer, he really shouldn''t be surprised. 

Contracted by a billionaire to discover who murdered his last body, Kovacs is drawn into a terrifying conspiracy that stretches across known space and to the very top of society.', 471, null, 2002, 363651, (select id from series where hardcover_id = 5569), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dragonbone Chair', 'Tad Williams', '3608938664', 'https://assets.hardcover.app/edition/30683794/2d6e20c6-daf2-4541-a092-9be12ea682fe.jpg', 'A war fueled by the powers of dark sorcery is about to engulf the peaceful land of Osten Ard—for Prester John, the High King, lies dying. And with his death, the Storm King, the undead ruler of the elf-like Sithi, seizes the chance to regain his lost realm through a pact with the newly ascended king. Knowing the consequences of this bargain, the king’s younger brother joins with a small, scattered group of scholars, the League of the Scroll, to confront the true danger threatening Osten Ard.
 
Simon, a kitchen boy from the royal castle unknowingly apprenticed to a member of this League, will be sent on a quest that offers the only hope of salvation, a deadly riddle concerning long-lost swords of power. Compelled by fate and perilous magics, he must leave the only home he’s ever known and face enemies more terrifying than Osten Ard has ever seen, even as the land itself begins to die.', 668, null, 1988, 363974, (select id from series where hardcover_id = 5526), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lost Hero', 'Rick Riordan', '8580570085', 'https://assets.hardcover.app/editions/30400844/4230457135207555.jpg', 'Jason has a problem. He doesn’t remember anything before waking up on a school bus holding hands with a girl.  Apparently, she’s his girlfriend Piper, his best friend is a kid named Leo, and they’re all students in the Wilderness School, a boarding school for “bad kids.”  What he did to end up here, Jason has no idea—except that everything seems very wrong.

Piper has a secret.  Her father has been missing for three days, and her vivid nightmares reveal that he’s in terrible danger.  Now, her boyfriend doesn’t recognize her, and when a freak storm and strange creatures attack during a school field trip, she, Jason, and Leo are whisked away to someplace called Camp Half-Blood.  What is going on?

Leo has a way with tools.  His new cabin at Camp Half-Blood is filled with them.  Seriously, the place beats the Wilderness School hands down, with its weapons, training, monsters, and fine-looking girls.  What’s troubling is the "curse" everyone keeps talking about, and that a camper’s gone missing.  Weirdest of all, his bunkmates insist they are all—including Leo—related to a god.', 576, null, 2010, 365337, (select id from series where hardcover_id = 5670), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Tales of Beedle the Bard', 'J.K. Rowling', '2070623440', 'https://assets.hardcover.app/edition/20756612/b77dde8be5b807546b9b8eee749c7b008a08139b.jpeg', 'A collection fairy tales for young wizards and witches, with each story followed by observations on Wizarding history, personal reminiscences, and information on the story''s key elements by Hogwarts headmaster, Albus Dumbledore.

Wizard and the Hopping Pot --
Fountain of Fair Fortune --
Warlock''s hairy heart --
Babbitty Rabbitty and her cackling stump --
Tale of the three brothers.', 105, null, 1994, 366623, (select id from series where hardcover_id = 5441), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Prince Caspian', 'C. S. Lewis, Pauline Baynes', '9561308150', 'https://assets.hardcover.app/edition/31553048/be37c81c-5193-4654-86e7-f641b69a8ab2.jpg', 'Narnia . . . where animals talk . . . where trees walk . . . where a battle is about to begin.

A prince denied his rightful throne gathers an army in a desperate attempt to rid his land of a false king. But in the end, it is a battle of honor between two men alone that will decide the fate of an entire world.

Prince Caspian is the fourth book in C.S. Lewis’s The Chronicles of Narnia, a series that has become part of the canon of classic literature, drawing readers of all ages into a magical land with unforgettable characters for over fifty years. This is a stand-alone novel, but if you would like to see more of Lucy and Edmund’s adventures, read The Voyage of the Dawn Treader, the fifth book in The Chronicles of Narnia.', 223, null, 1950, 367930, (select id from series where hardcover_id = 5485), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mistborn: The Final Empire', 'Brandon Sanderson', '8466659943', 'https://assets.hardcover.app/external_data/31614753/800579f7d675e7d2cd01043ddc57eb6ff724a6a5.jpeg', 'For a thousand years the ash fell and no flowers bloomed. For a thousand years the Skaa slaved in misery and lived in fear. For a thousand years the Lord Ruler, the "Sliver of Infinity," reigned with absolute power and ultimate terror, divinely invincible. Then, when hope was so long lost that not even its memory remained, a terribly scarred, heart-broken half-Skaa rediscovered it in the depths of the Lord Ruler''s most hellish prison. Kelsier "snapped" and found in himself the powers of a Mistborn. A brilliant thief and natural leader, he turned his talents to the ultimate caper, with the Lord Ruler himself as the mark.

Kelsier recruited the underworld''s elite, the smartest and most trustworthy allomancers, each of whom shares one of his many powers, and all of whom relish a high-stakes challenge. Then Kelsier reveals his ultimate dream, not just the greatest heist in history, but the downfall of the divine despot.

But even with the best criminal crew ever assembled, Kel''s plan looks more like the ultimate long shot, until luck brings a ragged girl named Vin into his life. Like him, she''s a half-Skaa orphan, but she''s lived a much harsher life. Vin has learned to expect betrayal from everyone she meets. She will have to learn trust if Kel is to help her master powers of which she never dreamed.

Brandon Sanderson, fantasy''s newest master tale-spinner and author of the acclaimed debut Elantris, dares to turn a genre on its head by asking a simple question: What if the prophesied hero failed to defeat the Dark Lord? The answer will be found in the Misborn Trilogy, a saga of surprises that begins with the book in your hands. Fantasy will never be the same again.', 541, 1479, 2003, 369692, (select id from series where hardcover_id = 10001), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fall of Hyperion', 'Dan Simmons', '9985302427', 'https://assets.hardcover.app/edition/30556303/c6ae174a950034142815ab5d5b030f30027c8502.jpeg', 'The mysterious Time Tombs are opening and the Shrike that has risen from them may well control the fate of all mankind. The Ousters are laying seige to the Hegemony of Man and the AIs we created have turned against us to build the Ultimate Intelligence: God. The God of Machines. His genesis could mean annihilation for man.

Something is drawing the hegemony, the Ousters, the AIs, the entire universe to the Shrike.', 530, null, 1989, 369986, (select id from series where hardcover_id = 1049), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Solaris', 'Stanisław Lem, Steve Cox, Joanna Kilmartin', '3423101776', 'https://assets.hardcover.app/edition/15545828/c908afb9139ca70866af560bfdd021c655ad53f3.jpeg', 'The cult-classic by Stanislaw Lem that spawned the movie is now available for your Kindle! Until now the only English edition was a 1970 version, which was translated from French and which Lem himself described as a "poor translation." This wonderful new English translation (by Bill Johnston) of Lem''s classic Solaris is a must-have for fans of Lem''s classic novel.

Telling of humanity''s encounter with an alien intelligence on the planet Solaris, the 1961 novel is a cult classic, exploring the ultimate futility of attempting to communicate with extra-terrestrial life.

When Kris Kelvin arrives at the planet Solaris to study the ocean that covers its surface, he finds a painful, hitherto unconscious memory embodied in the living physical likeness of a long-dead lover. Others examining the planet, Kelvin learns, are plagued with their own repressed and newly corporeal memories. The Solaris ocean may be a massive brain that creates these incarnate memories, though its purpose in doing so is unknown, forcing the scientists to shift the focus of their quest and wonder if they can truly understand the universe without first understanding what lies within their hearts.', 222, null, 1961, 372267, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Da Vinci Code', 'Dan Brown', '5550155184', 'https://assets.hardcover.app/editions/30400169/2520023766251547.jpeg', 'The Da Vinci Code is a 2003 mystery thriller novel by Dan Brown. It is Brown''s second novel to include the character Robert Langdon: the first was his 2000 novel Angels & Demons. 

The Da Vinci Code follows "symbologist" Robert Langdon and cryptologist Sophie Neveu after a murder in the Louvre Museum in Paris causes them to become involved in a battle between the Priory of Sion and Opus Dei over the possibility of Jesus Christ and Mary Magdalene having had a child together.', 489, null, 2003, 373163, (select id from series where hardcover_id = 1084), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('So Long, and Thanks for All the Fish', 'Douglas Adams', '5784103148', 'https://assets.hardcover.app/edition/30718523/4dde8ed400d88f55a9f6b631c909d8dc0ebcfb8e.jpeg', 'There is a knack to flying. The knack lies in learning how to throw yourself at the ground and miss. It''s not an easy thing to do, and Arthur Dent thinks he''s the only human who''s been able to master this nifty little trick – until he meets Fenchurch, the woman of his dreams.

Fenchurch once realized how the world could be made a good and happy place. Unfortunately, she''s forgotten. Convinced that the secret lies within God''s Final Message to His Creation, they go in search of it. And, in a dramatic break with tradition, actually find it . . .', 208, null, 1984, 373728, (select id from series where hardcover_id = 3400), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Godfather', 'Mario Puzo', '158788772X', 'https://assets.hardcover.app/edition/9396774/e96c6707ecc4dd4371457a4af71d72eb255b2d16.jpeg', 'The Godfather is the Mafia leader Vito Corleone, a benevolent despot who stops at nothing to gain and hold power. Set in Long Island, Hollywood and Sicily, this is a story of a feudal society within society which does not hesitate to consolidate its power.', 479, null, 1961, 373776, (select id from series where hardcover_id = 5808), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Darker Shade of Magic', 'V. E. Schwab', '9507323651', 'https://assets.hardcover.app/edition/12484409/ad3c96ba221d6245bff0c0c777d825b012d74ec9.jpeg', 'Kell is one of the last Atari - magicians with a rare, coveted ability to travel between parallel Londons: Red, Grey, White, and, once upon a time, Black. 

Kell was raised in Arnes - Red London - and officially serves the Maresh empire as an ambassador, traveling between the frequent bloody regime changes in White London and the court of George III in the dullest of Londons, the one without any magic left to see. 

Unofficially, Kell is a smuggler, servicing people willing to pay for even the smallest glimpses of a world they''ll never see. It''s a defiant hobby with dangerous consequences, which Kell is now seeing firsthand. 

After an exchange goes awry, Kell escapes to Grey London and runs into Delilah Bard, a cutpurse with lofty aspirations. She first robs him, then saves him from a deadly enemy, and finally forces Kell to spirit her to another world for a proper adventure. 

Now perilous magic is afoot, and treachery lurks at every turn. To save all of the worlds, they''ll first need to stay alive.', 413, 694, 2014, 374090, (select id from series where hardcover_id = 1040), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Words of Radiance', 'Brandon Sanderson', '8490691789', 'https://assets.hardcover.app/edition/419923/7428154-L.jpg', 'Expected by his enemies to die the miserable death of a military slave, Kaladin survived to be given command of the royal bodyguards, a controversial first for a low-status "darkeyes." Now he must protect the king and Dalinar from every common peril as well as the distinctly uncommon threat of the Assassin, all while secretly struggling to master remarkable new powers that are somehow linked to his honorspren, Syl.

The Assassin, Szeth, is active again, murdering rulers all over the world of Roshar, using his baffling powers to thwart every bodyguard and elude all pursuers. Among his prime targets is Highprince Dalinar, widely considered the power behind the Alethi throne. His leading role in the war would seem reason enough, but the Assassin''s master has much deeper motives.

Brilliant but troubled Shallan strives along a parallel path. Despite being broken in ways she refuses to acknowledge, she bears a terrible burden: to somehow prevent the return of the legendary Voidbringers and the civilization-ending Desolation that will follow. The secrets she needs can be found at the Shattered Plains, but just arriving there proves more difficult than she could have imagined.

Meanwhile, at the heart of the Shattered Plains, the Parshendi are making an epochal decision. Hard pressed by years of Alethi attacks, their numbers ever shrinking, they are convinced by their war leader, Eshonai, to risk everything on a desperate gamble with the very supernatural forces they once fled. The possible consequences for Parshendi and humans alike, indeed, for Roshar itself, are as dangerous as they are incalculable.', 1088, 2893, 2010, 374131, (select id from series where hardcover_id = 997), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('2001: A Space Odyssey', 'Arthur C. Clarke', '0451134699', 'https://assets.hardcover.app/external_data/32368894/0e0fa6d7d783f711048d81894eff76a18bb6d30f.jpeg', 'From the savannas of Africa at the dawn of mankind to the rings of Saturn as man ventures to the outer rim of our solar system, 2001: A Space Odyssey is a journey unlike any other.

This allegory about humanity’s exploration of the universe—and the universe’s reaction to humanity—is a hallmark achievement in storytelling that follows the crew of the spacecraft Discovery as they embark on a mission to Saturn. Their vessel is controlled by HAL 9000, an artificially intelligent supercomputer capable of the highest level of cognitive functioning that rivals—and perhaps threatens—the human mind.

Grappling with space exploration, the perils of technology, and the limits of human power, 2001: A Space Odyssey continues to be an enduring classic of cinematic scope.', 221, null, 1968, 374134, (select id from series where hardcover_id = 1095), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Brave New World', 'Aldous Huxley', '1998114449', 'https://assets.hardcover.app/edition/3299811/3e542fb1d6aed92c0f4e9cd0ac9b2f6892ca97a3.jpeg', '"Aldous Huxley''s profoundly important classic of world literature, Brave New World is a searching vision of an unequal, technologically-advanced future where humans are genetically bred, socially indoctrinated, and pharmaceutically anesthetized to passively uphold an authoritarian ruling order–all at the cost of our freedom, full humanity, and perhaps also our souls. “A genius [who] who spent his life decrying the onward march of the Machine” (The New Yorker), Huxley was a man of incomparable talents: equally an artist, a spiritual seeker, and one of history’s keenest observers of human nature and civilization. Brave New World, his masterpiece, has enthralled and terrified millions of readers, and retains its urgent relevance to this day as both a warning to be heeded as we head into tomorrow and as thought-provoking, satisfying work of literature."-- Provided by Amazon', 332, null, 1932, 374328, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Return of the King', 'J.R.R. Tolkien', '8324133089', 'https://assets.hardcover.app/edition/10474552/44475d80-8c89-492e-bf73-6d1a17254249.jpg', 'As the shadow of Mordor grows across the land, the Companions of the Ring have become involved in separate adventures. Aragorn, revealed as the hidden heir of the ancient Kings of the West, has joined with the Riders of Rohan against the forces of Isengard and takes part in the desperate battle of the Hornburg. Merry and Pippin, captured by Orcs, escape into Fangorn Forest and there encounter the Ents.

Gandalf has miraculously returned and defeated the evil wizard, Saruman. Sam has left his master for dead after a battle with the giant spider, Shelob; but Frodo is still alive—now in the foul hands of the Orcs.

Meanwhile, the armies of the Dark Lord are massing as the One Ring draws ever nearer to the Cracks of Doom.', 323, null, 1950, 374541, (select id from series where hardcover_id = 1130), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Moon Is a Harsh Mistress', 'Robert A. Heinlein', '042503013X', 'https://assets.hardcover.app/external_data/47670148/ba8a20f9629f7b2644ea6196d3684497fd333bb5.jpeg', 'It is the late 21st Century and the Moon has been colonized -- as a giant, open, prison.  Every aspect of life is overseen by the Federated Nations "Lunar Authority"; until one day when a self-aware Super-Computer, a Jack of all Trades Technician, an Anarchist Professor, and a beautiful Blonde Revolutionary decide to change their world.  The conspirators'' plans go along beautifully...for a while.

TANSTAAFL! There ain''t no such thing as a free lunch! Robert A. Heinlein was the most influential science fiction writer of his era, an influence so large that, as Samuel R. Delany notes, "modern critics attempting to wrestle with that influence feel themselves dealing with an object rather like the sky or an ocean." He won the Hugo Award for best novel four times, a record that still stands. The Moon Is a Harsh Mistress was the last of these Hugo-winning novels, and it is widely considered his finest work. It is a tale of revolution, of the rebellion of the former Lunar penal colony against the Lunar Authority that controls it from Earth. It is the tale of the disparate people -- a computer technician, a vigorous young female agitator, and an elderly academic -- who become the rebel movement''s leaders. And it is the story of Mike, the supercomputer whose sentience is known only to this inner circle, and who for reasons of his own is committed to the revolution''s ultimate success. The Moon Is a Harsh Mistress is one of the high points of modern science fiction, a novel bursting with politics, humanity, passion, innovative technical speculation, and a firm belief in the pursuit of human freedom. - Back cover.', 288, null, 1963, 374771, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Night Circus', 'Erin Morgenstern', '0307938905', 'https://assets.hardcover.app/edition/30445612/3e8445ce-8b26-4138-a49e-b4274e670bef.jpg', 'The circus arrives without warning. No announcements precede it. It is simply there, when yesterday it was not. Within the black-and-white striped canvas tents is an utterly unique experience full of breathtaking amazements. It is called Le Cirque des Rêves, and it is only open at night.

But behind the scenes, a fierce competition is underway: a duel between two young magicians, Celia and Marco, who have been trained since childhood expressly for this purpose by their mercurial instructors. Unbeknownst to them both, this is a game in which only one can be left standing. Despite the high stakes, Celia and Marco soon tumble headfirst into love, setting off a domino effect of dangerous consequences, and leaving the lives of everyone, from the performers to the patrons, hanging in the balance.', 512, 820, 2011, 375064, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Glass', 'Cassandra Clare', '0606377336', 'https://assets.hardcover.app/edition/6566224/2eebae14a108931beac118e9e0ec9261d824b16b.jpeg', 'To save her mother’s life, Clary must travel to the City of Glass, the ancestral home of the Shadowhunters—never mind that entering the city without permission is against the Law, and breaking the Law could mean death. To make things worse, she learns that Jace does not want her there, and Simon has been thrown in prison by the Shadowhunters, who are deeply suspicious of a vampire who can withstand sunlight.

As Clary uncovers more about her family’s past, she finds an ally in mysterious Shadowhunter Sebastian. With Valentine mustering the full force of his power to destroy all Shadowhunters forever, their only chance to defeat him is to fight alongside their eternal enemies. But can Downworlders and Shadowhunters put aside their hatred to work together? While Jace realizes exactly how much he’s willing to risk for Clary, can she harness her newfound powers to help save the Glass City—whatever the cost?

Love is a mortal sin and the secrets of the past prove deadly as Clary and Jace face down Valentine in the third installment of bestselling series the Mortal Instruments.', 541, null, 2009, 375396, (select id from series where hardcover_id = 5473), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadow of the Wind', 'Carlos Ruiz Zafón, Lucia Graves', '8408095595', 'https://assets.hardcover.app/book_mappings/7332507/488f5702a797385ab4e5532825d2e11aebde45da.jpeg', 'Barcelona, 1945: A city slowly heals in the aftermath of the Spanish Civil War, and Daniel, an antiquarian book dealer’s son who mourns the loss of his mother, finds solace in a mysterious book entitled The Shadow of the Wind, by one Julián Carax. But when he sets out to find the author’s other works, he makes a shocking discovery: someone has been systematically destroying every copy of every book Carax has written. In fact, Daniel may have the last of Carax’s books in existence. Soon Daniel’s seemingly innocent quest opens a door into one of Barcelona’s darkest secrets—an epic story of murder, madness, and doomed love.

____
Un amanecer de 1945, un muchacho es conducido por su padre a un misterioso lugar oculto en el corazón de la ciudad vieja: el Cementerio de los Libros Olvidados. Allí, Daniel Sempere encuentra un libro maldito que cambia el rumbo de su vida y le arrastra a un laberinto de intrigas y secretos enterrados en el alma oscura de la ciudad. La Sombra del Viento es un misterio literario ambientado en la Barcelona de la primera mitad del siglo xx, desde los últimos esplendores del Modernismo hasta las tinieblas de la posguerra.

Aunando las técnicas del relato de intriga y suspense, la novela histórica y la comedia de costumbres, La Sombra del Viento es sobre todo una trágica historia de amor cuyo eco se proyecta a través del tiempo. Con gran fuerza narrativa, el autor entrelaza tramas y enigmas a modo de muñecas rusas en un inolvidable relato sobre los secretos del corazón y el embrujo de los libros cuya intriga se mantiene hasta la última página.

Todavía recuerdo aquel amanecer en que mi padre me llevó por primera vez a visitar El Cementerio de los Libros Olvidados.', 487, null, 2001, 375470, (select id from series where hardcover_id = 101029), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Life, the Universe and Everything', 'Douglas Adams', '2072454220', 'https://assets.hardcover.app/edition/30601721/312f39d2-5c8c-45a3-96de-89bb0c5f6471.jpg', 'The universe, that is. Now only five individuals stand between the killer robots of Krikkit and their goal of total annihilation.

They are Arthur Dent, a mild-mannered space and time traveler who tries to learn how to fly by throwing himself at the ground and missing; Ford Prefect, his best friend, who decides to go insane to see if he likes it; Slartibartfast, the indomitable vice president of the Campaign for Real Time, who travels in a ship powered by irrational behavior; Zaphod Beeblebrox, the two-headed, three-armed ex-president of the galaxy; and Trillian, the sexy space cadet who is torn between a persistent Thunder God and a very depressed Beeblebrox.

How will it all end? Will it end? Only this stalwart crew knows as they try to avert “universal” Armageddon and save life as we know it—and don’t know it!', 240, null, 1982, 375813, (select id from series where hardcover_id = 3400), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fahrenheit 451', 'Ray Bradbury', '2701156319', 'https://assets.hardcover.app/edition/6336191/3d353406f14fd36043a8bdfb8c3288f90ee4f96c.jpeg', 'Guy Montag is a fireman. His job is to burn books, which are forbidden, being the source of all discord and unhappiness. Even so, Montag is unhappy; there is discord in his marriage. Are books hidden in his house? The Mechanical Hound of the Fire Department, armed with a lethal hypodermic, escorted by helicopters, is ready to track down those dissidents who defy society to preserve and read books.

The classic dystopian novel of a post-literate future, Fahrenheit 451 stands alongside Orwell’s 1984 and Huxley’s Brave New World as a prophetic account of Western civilization’s enslavement by the media, drugs and conformity.

Bradbury’s powerful and poetic prose combines with uncanny insight into the potential of technology to create a novel which, decades on from first publication, still has the power to dazzle and shock.', 227, 309, 1963, 375938, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Prisoner of Azkaban', 'J.K. Rowling', '1439520615', 'https://assets.hardcover.app/edition/28780168/0012cc5a-9e3a-48d4-95b6-d91f484de17a.jpg', 'For twelve long years, the dread fortress of Azkaban held an infamous prisoner named Sirius Black. Convicted of killing thirteen people with a single curse, he was said to be the heir apparent to the Dark Lord, Voldemort.

Now he has escaped, leaving only two clues as to where he might be headed: Harry Potter''s defeat of You-Know-Who was Black''s downfall as well. And the Azkaban guards heard Black muttering in his sleep, "He''s at Hogwarts . . . he''s at Hogwarts."

Harry Potter isn''t safe, not even within the walls of his magical school, surrounded by his friends. Because on top of it all, there may well be a traitor in their midst.', 448, 708, 1999, 376219, (select id from series where hardcover_id = 1185), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Library at Mount Char', 'Scott Hawkins', '1735483451', 'https://assets.hardcover.app/external_data/45044937/01e4711d937ef835a3aef2b5f54e06524d25bdfd.jpeg', 'Carolyn''s not so different from the other people around her. She likes guacamole and cigarettes and steak. She knows how to use a phone. Clothes are a bit tricky, but everyone says nice things about her outfit with the Christmas sweater over the gold bicycle shorts.

After all, she was a normal American herself once.

That was a long time ago, of course. Before her parents died. Before she and the others were taken in by the man they called Father.

In the years since then, Carolyn hasn''t had a chance to get out much. Instead, she and her adopted siblings have been raised according to Father''s ancient customs. They''ve studied the books in his Library and learned some of the secrets of his power. And sometimes, they''ve wondered if their cruel tutor might secretly be God.

Now, Father is missing—perhaps even dead—and the Library that holds his secrets stands unguarded. And with it, control over all of creation.

As Carolyn gathers the tools she needs for the battle to come, fierce competitors for this prize align against her, all of them with powers that far exceed her own.

But Carolyn has accounted for this. And Carolyn has a plan. The only trouble is that in the war to make a new God, she''s forgotten to protect the things that make her human.', 400, null, 2015, 376472, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Strange the Dreamer', 'Laini Taylor', '8420486000', 'https://assets.hardcover.app/book_mappings/7332810/78310eff70e58a3a3f5e6af2e60e21b9e30b82a9.jpeg', 'The dream chooses the dreamer, not the other way around–and Lazlo Strange, war orphan and junior librarian, has always feared that his dream chose poorly. Since he was five years old, he’s been obsessed with the mythic lost city of Weep, but it would take someone braver than he to cross half the world in search of it. Then a stunning opportunity presents itself, in the form of a hero called the Godslayer and a band of legendary warriors, and he has to seize his chance or lose his dream forever.

What happened in Weep two hundred years ago to cut it off from the rest of the world? And who is the blue-skinned goddess who appears in Lazlo’s dreams?

In this sweeping and breathtaking novel by National Book Award finalist Laini Taylor, author of the New York Times bestselling Daughter of Smoke & Bone trilogy, the shadow of the past is as real as the ghosts who haunt the citadel of murdered gods. Fall into a mythical world of dread and wonder, moths and nightmares, love and carnage.

The answers await in Weep.
([source][1])


  [1]: https://www.lbyr.com/titles/laini-taylor/strange-the-dreamer/9780316341646/', 544, null, 2016, 376651, (select id from series where hardcover_id = 5575), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Institute', 'Stephen King', '1982150785', 'https://assets.hardcover.app/edition/4573759/5b590f4dfbddce10eb8f8e939da33b9c8bf525ee.jpeg', 'Luke Ellis, a super-smart twelve-year-old with an exceptional gift, is the latest in a long line of kids abducted and taken to a secret government facility, hidden deep in the forest in Maine.

Here, kids with special talents - telekinesis and telepathy - like Luke''s new friends Kalisha, Nick and Iris, are subjected to a series of experiments.

There seems to be no hope of escape. Until Luke teams up with an even younger boy whose powers of telepathy are off the scale.

Meanwhile, far away in a small town in South Carolina, former cop Tim Jamieson, looking for the quiet life, has taken a job working for the local sheriff. He doesn''t know he''s about to take on the biggest case of his career...
--back cover', 496, null, 2019, 376832, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Feast for Crows', 'George R.R. Martin', '0449011887', 'https://assets.hardcover.app/edition/2789048/8570883-L.jpg', 'Few books have captivated the imagination and won the devotion and praise of readers and critics everywhere as has George R. R. Martin’s monumental epic cycle of high fantasy. Now, in A Feast for Crows, Martin delivers the long-awaited fourth book of his landmark series, as a kingdom torn asunder finds itself at last on the brink of peace . . . only to be launched on an even more terrifying course of destruction.


It seems too good to be true. After centuries of bitter strife and fatal treachery, the seven powers dividing the land have decimated one another into an uneasy truce. Or so it appears. . . . With the death of the monstrous King Joffrey, Cersei is ruling as regent in King’s Landing. Robb Stark’s demise has broken the back of the Northern rebels, and his siblings are scattered throughout the kingdom like seeds on barren soil. Few legitimate claims to the once desperately sought Iron Throne still exist—or they are held in hands too weak or too distant to wield them effectively. The war, which raged out of control for so long, has burned itself out. 

But as in the aftermath of any climactic struggle, it is not long before the survivors, outlaws, renegades, and carrion eaters start to gather, picking over the bones of the dead and fighting for the spoils of the soon-to-be dead. Now in the Seven Kingdoms, as the human crows assemble over a banquet of ashes, daring new plots and dangerous new alliances are formed, while surprising faces—some familiar, others only just appearing—are seen emerging from an ominous twilight of past struggles and chaos to take up the challenges ahead. 

It is a time when the wise and the ambitious, the deceitful and the strong will acquire the skills, the power, and the magic to survive the stark and terrible times that lie before them. It is a time for nobles and commoners, soldiers and sorcerers, assassins and sages to come together and stake their fortunes . . . and their lives. For at a feast for crows, many are the guests—but only a few are the survivors.', 1106, null, 2005, 377011, (select id from series where hardcover_id = 981), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lord of Chaos', 'Robert Jordan', '1593976836', 'https://assets.hardcover.app/edition/30930933/2efe9faf-fc54-4581-864f-d4f32a5e5938.png', 'On the slopes of Shayol Ghul, the Myrddraal swords are forged, and the sky is not the sky of this world ...

In Salidar the White Tower in exile prepares an embassy to Caemlyn, where Rand Al''Thor, the Dragon Reborn, holds the throne -- and where an unexpected visitor may change the world ...

In Emond''s Field, Perrin Goldeneyes, Lord of the Two Rivers, feels the pull of ta''veren to ta''veren and prepares to march ...

Morgase of Caemlyn finds a most unexpected, and quite unwelcome, ally ...

And south lies Illian, where Sammael holds sway ...', 1040, null, 1994, 377085, (select id from series where hardcover_id = 1097), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Waste Lands', 'Stephen King', '9170024227', 'https://assets.hardcover.app/external_data/61198827/59dfae01fabd988d3e941e0fd2953dab4c8f1c66.jpeg', 'Now they exist in different worlds, paradoxically sharing memories. Roland, Susannah and Eddie must try to draw Jake into Mid-World then follow the Path of the Beam through an urban waste land to the Dark Tower.

Pursued by the Ageless Stranger, Roland and his friends cross a desert of damnation in this macabre new world as revelations begin to unfold about who - and what - is driving him forward.', 584, null, 1991, 377090, (select id from series where hardcover_id = 3413), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Left Hand of Darkness', 'Ursula K. Le Guin', '3453164156', 'https://assets.hardcover.app/edition/9212187/1c8d9135d0b8e7d1debe202c85e2229cc3f586b0.jpeg', 'A lone human ambassador is sent to the icebound planet of Winter, a world without sexual prejudice, where the inhabitants’ gender is fluid. His goal is to facilitate Winter’s inclusion in a growing intergalactic civilization. But to do so he must bridge the gulf between his own views and those of the strange, intriguing culture he encounters...

Embracing the aspects of psychology, society, and human emotion on an alien world, The Left Hand of Darkness stands as a landmark achievement in the annals of intellectual science fiction.', 304, null, 1969, 377842, (select id from series where hardcover_id = 1123), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lord of the Rings', 'J.R.R. Tolkien', '0544273443', 'https://assets.hardcover.app/external_data/41547254/141872f0e71efe38f937b72879a5dea52e502db5.jpeg', 'Originally published from 1954 through 1956, J.R.R. Tolkien''s richly complex series ushered in a new age of epic adventure storytelling. A philologist and illustrator who took inspiration from his work, Tolkien invented the modern heroic quest novel from the ground up, creating not just a world, but a domain, not just a lexicon, but a language, that would spawn countless imitators and lead to the inception of the epic fantasy genre. Today, THE LORD OF THE RINGS is considered "the most influential fantasy novel ever written." (THE ENCYCLOPEDIA OF FANTASY)

During his travels across Middle-earth, the hobbit Bilbo Baggins had found the Ring. But the simple band of gold was far from ordinary; it was in fact the One Ring - the greatest of the ancient Rings of Power. Sauron, the Dark Lord, had infused it with his own evil magic, and when it was lost, he was forced to flee into hiding.

But now Sauron''s exile has ended and his power is spreading anew, fueled by the knowledge that his treasure has been found. He has gathered all the Great Rings to him, and will stop at nothing to reclaim the One that will complete his dominion. The only way to stop him is to cast the Ruling Ring deep into the Fire-Mountain at the heart of the land of Mordor--Sauron''s dark realm.

Fate has placed the burden in the hands of Frodo Baggins, Bilbo''s heir...and he is resolved to bear it to its end. Or his own. ', 1178, null, 1959, 377938, (select id from series where hardcover_id = 1130), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Golden Son', 'Pierce Brown', '5389084608', 'https://assets.hardcover.app/editions/30404982/b5150007-bf09-4937-8d32-ecf89f136342.jpg', 'As a Red, Darrow grew up working the mines deep beneath the surface of Mars, enduring backbreaking labor while dreaming of the better future he was building for his descendants. But the Society he faithfully served was built on lies. Darrow’s kind have been betrayed and denied by their elitist masters, the Golds—and their only path to liberation is revolution. And so Darrow sacrifices himself in the name of the greater good for which Eo, his true love and inspiration, laid down her own life. He becomes a Gold, infiltrating their privileged realm so that he can destroy it from within.

A lamb among wolves in a cruel world, Darrow finds friendship, respect, and even love—but also the wrath of powerful rivals. To wage and win the war that will change humankind’s destiny, Darrow must confront the treachery arrayed against him, overcome his all-too-human desire for retribution—and strive not for violent revolt but a hopeful rebirth. Though the road ahead is fraught with danger and deceit, Darrow must choose to follow Eo’s principles of love and justice to free his people.

He must live for more.', 466, 1143, 2015, 378044, (select id from series where hardcover_id = 1033), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Song of Susannah', 'Stephen King', '1508219176', 'https://assets.hardcover.app/edition/30738153/6a1b1d95-89de-49c1-ad73-9459177be194.jpg', 'Susannah has used the power of Black Thirteen to get to New York where she can give birth to a child fated to grow up as Roland''s nemesis. Jake and Father Callahan set out to break her date with destiny and to find Calvin Tower, owner of the vacant lot where a magical rose grows - a rose that must be saved at all costs.

Meanwhile, Roland and Eddie tumble into Maine in the Summer of 1977. Here they are greeted by the gangster Balazar and must face their maker, a man called Stephen King...', 436, null, 2004, 378244, (select id from series where hardcover_id = 3413), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wolves of the Calla', 'Stephen King', '7020062369', 'https://assets.hardcover.app/edition/30745316/81b9022cc5439be14e5e6ce9a77717b75ecece7c.jpeg', 'Tracking their every move is a group of farmers from the town of Calla Bryn Sturgis. The trackers have been warned that the Wolves, a band of masked riders, are about to gallop out of the dark land of Thunderclap and raid their town. And they want to enlist the help of the four gunslingers.

How can Roland and his tet both protect the innocent community and return to New York to save our world''s incarnation of the Dark Tower from the machinations of the evil Sombra Corporation?', 770, null, 2003, 378293, (select id from series where hardcover_id = 3413), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Son of Neptune', 'Rick Riordan', '0141335734', 'https://assets.hardcover.app/edition/30400859/009dfef5d4047459368207b84ee126ad4fed0da3.jpeg', 'Percy is confused. When he awoke from his long sleep, he didn''t know much more than his name. His brain fuzz is lingering, even after the wolf Lupa told him he is a demigod and trained him to fight with the pen/sword in his pocket. Somehow Percy manages to make it to a camp for half-bloods, despite the fact that he has to keep killing monsters along the way. But the camp doesn''t ring any bells with him. The only thing he can recall from his past is another name: Annabeth.

Hazel is supposed to be dead. When she lived before, she didn''t do a very good job of it. Sure, she was an obedient daughter, even when her mother was possessed by greed. But that was the problem-when the Voice took over her mother and commanded Hazel to use her "gift" for an evil purpose, Hazel couldn''t say no. Now, because of her mistake, the future of the world is at risk. Hazel wishes she could ride away from it all on the stallion that appears in her dreams.

Frank is a klutz. His grandmother says he is descended from heroes and can be anything he wants to be, but he doesn''t see it. He doesn''t even know who his father is. He keeps hoping Apollo will claim him, because the only thing he is good at is archery-although not good enough to win camp war games. His bulky physique makes him feel like an ox, especially in front of Hazel, his closest friend at camp. He trusts her completely-enough to share his secret he holds close to his heart.

Beginning at the "other" camp for half-bloods and extending as far as the land beyond the gods, this breathtaking second installment in the Heroes of Olympus series introduces new demigods, revives fearsome monsters, and features other remarkable creatures, all destined to play a part in the Prophecy of Seven.', 521, null, 2011, 378596, (select id from series where hardcover_id = 5670), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wizard And Glass', 'Stephen King', '7532149196', 'https://assets.hardcover.app/edition/30901117/b2ee80c6-959d-40e4-99f9-6619a2794e63.jpg', 'In a terrifying journey where hidden dangers lurk at every junction, the pilgrims find themselves stranded in an alternate version of Topeka, Kansas, that has been ravaged by a superflu virus.

While following the deserted highway toward a distant glass palace, Roland recounts his tragic story about a seaside town called Hambry, where he fell in love with a girl named Susan Delgado and where he and his old tet-mates Alain and Cuthbert battled the forces of an evil harrier who ignited Mid-World''s final war.', 864, null, 1997, 378914, (select id from series where hardcover_id = 3413), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Name of the Wind', 'Patrick Rothfuss', '3608938788', 'https://assets.hardcover.app/editions/19454574/9509867934646082.jpg', 'Told in Kvothe''s own voice, this is the tale of the magically gifted young man who grows to be the most notorious wizard his world has ever seen.

The intimate narrative of his childhood in a troupe of traveling players, his years spent as a near-feral orphan in a crime-ridden city, his daringly brazen yet successful bid to enter a legendary school of magic, and his life as a fugitive after the murder of a king form a gripping coming-of-age story unrivaled in recent literature.

A high-action story written with a poet''s hand, The Name of the Wind is a masterpiece that will transport readers into the body and mind of a wizard.', 661, null, 2007, 379217, (select id from series where hardcover_id = 988), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shatter Me', 'Tahereh Mafi', '9898864753', 'https://assets.hardcover.app/editions/30460178/627316130272577.jpg', 'One touch is all it takes. One touch, and Juliette Ferrars can leave a fully grown man gasping for air. One touch, and she can kill.

No one knows why Juliette has such incredible power. It feels like a curse, a burden that one person alone could never bear. But The Reestablishment sees it as a gift, sees her as an opportunity. An opportunity for a deadly weapon.

Juliette has never fought for herself before. But when she’s reunited with the one person who ever cared about her, she finds a strength she never knew she had.

Includes a special sneak peek of This Woven Kingdom, the first book in Tahereh Mafi’s bestselling fantasy series inspired by Persian folklore!', 339, null, 2011, 379288, (select id from series where hardcover_id = 1064), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Starship Troopers', 'Robert A. Heinlein', '0785787283', 'https://assets.hardcover.app/edition/1171105/654e83c9-d29f-4556-940e-b3514b227333.jpg', 'Johnnie Rico never really intended to join up—and definitely not the infantry. But now that he’s in the thick of it, trying to get through combat training harder than anything he could have imagined, he knows everyone in his unit is one bad move away from buying the farm in the interstellar war the Terran Federation is waging against the Arachnids.

Because everyone in the Mobile Infantry fights. And if the training doesn’t kill you, the Bugs are more than ready to finish the job...', 288, null, 1959, 379327, (select id from series where hardcover_id = 75924), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sphere', 'Michael Crichton', '0785758968', 'https://assets.hardcover.app/external_data/24066168/cf39583c47d31e3b3b58a264252e078190c5bc02.jpeg', 'In the middle of the South Pacific, a thousand feet below the surface, a huge vessel is unearthed. Rushed to the scene is a team of American scientists who descend together into the depths to investigate the astonishing discovery. What they find defies their imaginations and mocks their attempts at logical explanation. It is a spaceship, but apparently it is undamaged by its fall from the sky. And, most startling, it appears to be at least three hundred years old, containing a terrifying and destructive force that must be controlled at all costs.', 335, null, 1962, 379388, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The City of Brass', 'S. A. Chakraborty', '237876099X', 'https://assets.hardcover.app/edition/30400336/3e426305-0273-4007-ad29-55d686eed763.jpg', 'On the streets of eighteenth-century Cairo, Nahri is a con woman of unsurpassed skill. She makes her living swindling Ottoman nobles, hoping to one day earn enough to change her fortunes. But when Nahri accidentally summons Dara, an equally sly, darkly mysterious djinn warrior, during one of her cons, she learns that even the cleverest of schemes can have deadly consequences.

Forced to flee Cairo, Dara and Nahri journey together across hot, windswept sands teeming with creatures of fire and rivers where the mythical marid sleep, past ruins of once-magnificent human metropolises and mountains where the circling birds of prey are more than what they seem, to Daevabad, the legendary city of brass.

It’s a city steeped in magic and fire, where blood can be as dangerous as any spell; a city where old resentments run deep and the royal court rules with a tenuous grip; a city to which Nahri is irrevocably bound—and where her very presence threatens to ignite a war that has been simmering for centuries.', 532, null, 2017, 379619, (select id from series where hardcover_id = 1628), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Two Towers', 'J.R.R. Tolkien', '6020332276', 'https://assets.hardcover.app/edition/25616931/cd5d5770785ed7174f4649b06ff4feb6cbdb800e.jpeg', 'Frodo and his Companions of the Ring have been beset by danger during their quest to prevent the Ruling Ring from falling into the hands of the Dark Lord by destroying it in the Cracks of Doom. They lost the wizard Gandalf in the Mines of Moria. And Boromir, seduced by the power of the Ring, tried to seize it by force. While Frodo and Sam made their escape, the rest of the company was attacked by Orcs.

Now they continue their journey alone down the great River Anduin—alone, that is, save for the mysterious creeping figure that follows wherever they go.', 323, 1247, 1954, 379631, (select id from series where hardcover_id = 1130), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Digital Fortress', 'Dan Brown', '1593973594', 'https://assets.hardcover.app/edition/22081967/89d70876-40e2-4826-9095-d5568746f4b5.jpg', 'When the NSA''s invincible code-breaking machine encounters a mysterious code it cannot break, the agency calls its head cryptographer, Susan Fletcher, a brilliant and beautiful mathematician. What she uncovers sends shock waves through the corridors of power. The NSA is being held hostage...not by guns or bombs, but by a code so ingeniously complex that if released it would cripple U.S. intelligence.

Caught in an accelerating tempest of secrecy and lies, Susan Fletcher battles to save the agency she believes in. Betrayed on all sides, she finds herself fighting not only for her country but for her life, and in the end, for the life of the man she loves.

From the underground hallways of power to the skyscrapers of Tokyo to the towering cathedrals of Spain, a desperate race unfolds. It is a battle for survival--a crucial bid to destroy a creation of inconceivable genius...an impregnable code-writing formula that threatens to obliterate the post-cold war balance of power. Forever.', 384, null, 1998, 379753, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Discovery of Witches', 'Deborah Harkness', '1472258231', 'https://assets.hardcover.app/edition/14846265/ec59a99bd5b11e161f1f16a31e49e82f9c08e2bf.jpeg', 'When historian Diana Bishop opens an alchemical manuscript in the Bodleian Library, it''s an unwelcome intrusion of magic into her carefully ordered life. Though Diana is a witch of impeccable lineage, the violent death of her parents while she was still a child convinced her that human fear is more potent than any witchcraft. Now Diana has unwittingly exposed herself to a world she''s kept at bay for years; one of powerful witches, creative, destructive daemons and long-lived vampires. 

Sensing the significance of Diana''s discovery, the creatures gather in Oxford, among them the enigmatic Matthew Clairmont, a vampire geneticist. Diana is inexplicably drawn to Matthew and, in a shadowy world of half-truths and old enmities, ties herself to him without fully understanding the ancient line they are crossing.

As they begin to unlock the secrets of the manuscript and their feelings for each other deepen, so the fragile balance of peace unravels.', 579, null, 2011, 379979, (select id from series where hardcover_id = 5579), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Scarlet', 'Marissa Meyer', '8484418928', 'https://assets.hardcover.app/external_data/41551089/68ce1d7e9088f431355decebf647474e84b04bae.jpeg', 'Cinder, the cyborg mechanic, returns in the second thrilling installment of Marissa Meyer''s bestselling Lunar Chronicles. She''s trying to break out of prison--even though if she succeeds, she''ll be the Commonwealth''s most wanted fugitive.

Halfway around the world, Scarlet Benoit''s grandmother is missing. It turns out there are many things Scarlet doesn''t know about her grandmother or the grave danger she has lived in her whole life. When Scarlet encounters Wolf, a street fighter who may have information as to her grandmother''s whereabouts, she is loath to trust this stranger, but is inexplicably drawn to him, and he to her. As Scarlet and Wolf unravel one mystery, they encounter another when they meet Cinder. Now, all of them must stay one step ahead of the vicious Lunar Queen Levana, who will do anything for the handsome Prince Kai to become her husband, her king, her prisoner.', 452, null, 2013, 380006, (select id from series where hardcover_id = 5558), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Starless Sea', 'Erin Morgenstern', '9791036611919', 'https://assets.hardcover.app/edition/32856775/06ef8c15-260c-465e-be69-b17c44bdd453.jpg', 'The entryways that lead to this sanctuary are often hidden, sometimes on forest floors, sometimes in private homes, sometimes in plain sight. But those who seek will find. Their doors have been waiting for them.

Zachary Ezra Rawlins is searching for his door, though he does not know it. He follows a silent siren song, an inexplicable knowledge that he is meant for another place. When he discovers a mysterious book in the stacks of his campus library he begins to read, entranced by tales of lovelorn prisoners, lost cities, and nameless acolytes. Suddenly a turn of the page brings Zachary to a story from his own childhood impossibly written in this book that is older than he is.

A bee, a key, and a sword emblazoned on the book lead Zachary to two people who will change the course of his life: Mirabel, a fierce, pink-haired painter, and Dorian, a handsome, barefoot man with shifting alliances. These strangers guide Zachary through masquerade party dances and whispered back room stories to the headquarters of a secret society where doorknobs hang from ribbons, and finally through a door conjured from paint to the place he has always yearned for. Amid twisting tunnels filled with books, gilded ballrooms, and wine-dark shores Zachary falls into an intoxicating world soaked in romance and mystery. But a battle is raging over the fate of this place and though there are those who would willingly sacrifice everything to protect it, there are just as many intent on its destruction. As Zachary, Mirabel, and Dorian venture deeper into the space and its histories and myths, searching for answers and each other, a timeless love story unspools, casting a spell of pirates, painters, lovers, liars, and ships that sail upon a Starless Sea.', 499, null, 2019, 380187, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Furies of Calderon', 'Jim Butcher', '281120654X', 'https://assets.hardcover.app/book_mappings/7333352/0b93a87a56855e7f6e771d6dc4e022e75c4c2a09.jpeg', 'In this extraordinary fantasy epic, the #1 New York Times bestselling author of the Dresden Files leads readers into a world where the fate of the realm rests on the shoulders of a boy with no power to call his own...

For a thousand years, the people of Alera have united against the aggressive and threatening races that inhabit the world, using their unique bond with the furies—elementals of earth, air, fire, water, wood, and metal. But in the remote Calderon Valley, the boy Tavi struggles with his lack of furycrafting. At fifteen, he has no wind fury to help him fly, no fire fury to light his lamps. Yet as the Alerans’ most savage enemy—the Marat horde—return to the Valley, Tavi’s courage and resourcefulness will be a power greater than any fury, one that could turn the tides of war...', 516, null, 2004, 380212, (select id from series where hardcover_id = 975), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ocean at the End of the Lane', 'Neil Gaiman', '0606385320', 'https://assets.hardcover.app/book_mappings/7332367/f23aac20ca501a73b6f2b348485f015091d1e361.jpeg', 'A middle-aged man returns to his childhood home to attend a funeral. Although the house he lived in is long gone, he is drawn to the farm at the end of the road, where, when he was seven, he encountered a most remarkable girl, Lettie Hempstock, and her mother and grandmother. He hasn''t thought of Lettie in decades, and yet as he sits by the pond (a pond that she''d claimed was an ocean) behind the ramshackle old farmhouse, the unremembered past comes flooding back. And it is a past too strange, too frightening, too dangerous to have happened to anyone, let alone a small boy.

Forty years earlier, a man committed suicide in a stolen car at this farm at the end of the road. Like a fuse on a firework, his death lit a touchpaper and resonated in unimaginable ways. The darkness was unleashed, something scary and thoroughly incomprehensible to a little boy. And Lettie—magical, comforting, wise beyond her years—promised to protect him, no matter what.

A groundbreaking work from a master, The Ocean at the End of the Lane is told with a rare understanding of all that makes us human, and shows the power of stories to reveal and shelter us from the darkness inside and out. It is a stirring, terrifying, and elegiac fable as delicate as a butterfly''s wing and as menacing as a knife in the dark.', 304, 382, 2013, 380549, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lies of Locke Lamora', 'Scott Lynch', '2352940273', 'https://assets.hardcover.app/edition/14655125/9aab1cd2-201a-4312-813b-d5118c1e8bc2.jpg', 'An orphan’s life is harsh—and often short—in the mysterious island city of Camorr. But young Locke Lamora dodges relentless danger, becoming a thief under the tutelage of a gifted con artist. As leader of the band of light-fingered brothers known as the Gentlemen Bastards, Locke is soon infamous, fooling even the underworld’s most feared ruler. But in the shadows lurks someone still more ambitious and deadly. Faced with a bloody coup that threatens to destroy everyone and everything that holds meaning in his mercenary life, Locke vows to beat the enemy at his own brutal game—or die trying.', 722, null, 2006, 380764, (select id from series where hardcover_id = 1128), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wise Man''s Fear', 'Patrick Rothfuss', '1423389433', 'https://assets.hardcover.app/edition/1842039/b82cc5dd-45a2-49d6-972c-f48168aa6e90.jpg', 'My name is Kvothe.
I have stolen princesses back from sleeping barrow kings. I burned down the town of Trebon. I have spent the night with Felurian and left with both my sanity and my life. I was expelled from the University at a younger age than most people are allowed in. I tread paths by moonlight that others fear to speak of during day. I have talked to Gods, loved women, and written songs that make the minstrels weep.
You may have heard of me.

So begins the tale of a hero told from his own point of view — a story unequaled in fantasy literature. Now in The Wise Man''s Fear, an escalating rivalry with a powerful member of the nobility forces Kvothe to leave the University and seek his fortune abroad. Adrift, penniless, and alone, he travels to Vintas, where he quickly becomes entangled in the politics of courtly society. While attempting to curry favor with a powerful noble, Kvothe uncovers an assassination attempt, comes into conflict with a rival arcanist, and leads a group of mercenaries into the wild, in an attempt to solve the mystery of who (or what) is waylaying travelers on the King''s Road.

All the while, Kvothe searches for answers, attempting to uncover the truth about the mysterious Amyr, the Chandrian, and the death of his parents. Along the way, Kvothe is put on trial by the legendary Adem mercenaries, is forced to reclaim the honor of the Edema Ruh, and travels into the Fae realm. There he meets Felurian, the faerie woman no man can resist, and who no man has ever survived ... until Kvothe.

In The Wise Man''s Fear, Kvothe takes his first steps on the path of the hero and learns how difficult life can be when a man becomes a legend in his own time.', 1007, 2569, 2011, 381332, (select id from series where hardcover_id = 988), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pandora''s Star', 'Peter F. Hamilton', '1447291689', 'https://assets.hardcover.app/edition/30399413/9556d2a5fb98c3efc372519107b1c3a61510fc6d.jpeg', 'Critics have compared the engrossing space operas of Peter F. Hamilton to the classic sagas of such sf giants as Isaac Asimov and Frank Herbert. But Hamilton''s bestselling fiction--powered by a fearless imagination and world-class storytelling skills--has also earned him comparison to Tolstoy and Dickens. Hugely ambitious, wildly entertaining, philosophically stimulating: the novels of Peter F. Hamilton will change the way you think about science fiction. Now, with Pandora''s Star, he begins a new multivolume adventure, one that promises to be his most mind-blowing yet. The year is 2380. The Intersolar Commonwealth, a sphere of stars some four hundred light-years in diameter, contains more than six hundred worlds, interconnected by a web of transport "tunnels" known as wormholes. At the farthest edge of the Commonwealth, astronomer Dudley Bose observes the impossible: Over one thousand light-years away, a star . . . vanishes. It does not go supernova. It does not collapse into a black hole. It simply disappears. Since the location is too distant to reach by wormhole, a faster-than-light starship, the Second Chance, is dispatched to learn what has occurred and whether it represents a threat. In command is Wilson Kime, a five-time rejuvenated ex-NASA pilot whose glory days are centuries behind him.Opposed to the mission are the Guardians of Selfhood, a cult that believes the human race is being manipulated by an alien entity they call the Starflyer. Bradley Johansson, leader of the Guardians, warns of sabotage, fearing the Starflyer means to use the starship''s mission for its own ends,.Pursued by a Commonwealth special agent convinced the Guardians are crazy but dangerous, Johansson flees. But the danger is not averted. Aboard the Second Chance, Kime wonders if his crew has been infiltrated. Soon enough, he will have other worries. A thousand light-years away, something truly incredible is waiting: a deadly discovery whose unleashing will threaten to destroy the Commonwealth . . . and humanity itself.  Could it be that Johansson was right?From the Hardcover edition.', 1156, null, 2004, 381445, (select id from series where hardcover_id = 1138), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wicked King', 'Holly Black, Caitlin Kelly', '3570165280', 'https://assets.hardcover.app/external_data/28441353/d8cdeb01394f701525c7ca5ac743d3a9a589a63c.jpeg', 'As seneschal to High King Cardan, Jude must fight to keep control of the Faerie throne while her younger brother, Oak, enjoys the childhood she never knew.', null, null, 2015, 381829, (select id from series where hardcover_id = 5470), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Deathly Hallows', 'J.K. Rowling', '870217328X', 'https://assets.hardcover.app/editions/14019917/7017379795452299-58613224.jpg', 'As he climbs into the sidecar of Hagrid’s motorbike and takes to the skies, leaving Privet Drive for the last time, Harry Potter knows that Lord Voldemort and the Death Eaters are not far behind. The protective charm that has kept Harry safe until now is now broken, but he cannot keep hiding. The Dark Lord is breathing fear into everything Harry loves, and to stop him Harry will have to find and destroy the remaining Horcruxes. The final battle must begin – Harry must stand and face his enemy.', 784, 1296, 2007, 382143, (select id from series where hardcover_id = 1185), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Interview with the Vampire', 'Anne Rice', '8850258690', 'https://assets.hardcover.app/edition/22881580/fd1018848b2681b800fc5c9ceab1595878885e6d.jpeg', 'In a darkened room a young man sits telling the macabre and eerie story of his life - the story of a vampire, gifted with eternal life, cursed with an exquisite craving for human blood.

Here are the confessions of a vampire. Hypnotic, shocking, and chillingly erotic, this is a novel of mesmerizing beauty and astonishing force --- a story of danger and flight, of love and loss, of suspense and resolution, and of the extraordinary power of the senses. It is a novel only Anne Rice could write.', 356, null, 1976, 382589, (select id from series where hardcover_id = 4718), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Goblet of Fire', 'J.K. Rowling, Mary GrandPré', '1408824108', 'https://assets.hardcover.app/editions/28458058/1771665257940243-49130.jpg', 'Harry Potter is midway through his training as a wizard and his coming of age. Harry wants to get away from the pernicious Dursleys and go to the International Quidditch Cup. He wants to find out about the mysterious event that''s supposed to take place at Hogwarts this year, an event involving two other rival schools of magic, and a competition that hasn''t happened for a hundred years. He wants to be a normal, fourteen-year-old wizard. But unfortunately for Harry Potter, he''s not normal - even by wizarding standards. And in his case, different can be deadly.

Paperback edition of the fourth Harry Potter novel.', 734, null, 2000, 383236, (select id from series where hardcover_id = 1185), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Blade Itself', 'Joe Abercrombie', '3453320905', 'https://assets.hardcover.app/external_data/25818704/6d4c4406902175a5fe5292e8a64df7e6180f1712.jpeg', 'Logen Ninefingers, infamous barbarian, has finally run out of luck. Caught in one feud too many, he''s on the verge of becoming a dead barbarian -- leaving nothing behind him but bad songs, dead friends, and a lot of happy enemies.

Nobleman, dashing officer, and paragon of selfishness, Captain Jezal dan Luthar has nothing more dangerous in mind than fleecing his friends at cards and dreaming of glory in the fencing circle. But war is brewing, and on the battlefields of the frozen North they fight by altogether bloodier rules.

Inquisitor Glokta, cripple turned torturer, would like nothing better than to see Jezal come home in a box. But then Glokta hates everyone: cutting treason out of the Union one confession at a time leaves little room for friendship. His latest trail of corpses may lead him right to the rotten heart of government, if he can stay alive long enough to follow it.

Enter the wizard, Bayaz. A bald old man with a terrible temper and a pathetic assistant, he could be the First of the Magi, he could be a spectacular fraud, but whatever he is, he''s about to make the lives of Logen, Jezal, and Glokta a whole lot more difficult.

Murderous conspiracies rise to the surface, old scores are ready to be settled, and the line between hero and villain is sharp enough to draw blood.', 536, 1335, 2006, 383404, (select id from series where hardcover_id = 1083), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('11/22/63', 'Stephen King', '8401352487', 'https://assets.hardcover.app/edition/23959086/a129e91093231fcfa21c51c2195fcae2e4a56969.jpeg', 'On November 22, 1963, three shots rang out in Dallas, President Kennedy died, and the world changed. What if you could change it back? Stephen King’s heart-stoppingly dramatic new novel is about a man who travels back in time to prevent the JFK assassination—a thousand page tour de force.

Following his massively successful novel Under the Dome, King sweeps readers back in time to another moment—a real life moment—when everything went wrong: the JFK assassination. And he introduces readers to a character who has the power to change the course of history.


Jake Epping is a thirty-five-year-old high school English teacher in Lisbon Falls, Maine, who makes extra money teaching adults in the GED program. He receives an essay from one of the students—a gruesome, harrowing first person story about the night 50 years ago when Harry Dunning’s father came home and killed his mother, his sister, and his brother with a hammer. Harry escaped with a smashed leg, as evidenced by his crooked walk.

Not much later, Jake’s friend Al, who runs the local diner, divulges a secret: his storeroom is a portal to 1958. He enlists Jake on an insane—and insanely possible—mission to try to prevent the Kennedy assassination. So begins Jake’s new life as George Amberson and his new world of Elvis and JFK, of big American cars and sock hops, of a troubled loner named Lee Harvey Oswald and a beautiful high school librarian named Sadie Dunhill, who becomes the love of Jake’s life—a life that transgresses all the normal rules of time.

A tribute to a simpler era and a devastating exercise in escalating suspense, 11/22/63 is Stephen King at his epic best.', 740, null, 2011, 383587, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Circe', 'Madeline Miller', '7521722132', 'https://assets.hardcover.app/editions/187333/9694237244087422-circe.jpg', 'In the house of Helios, god of the sun and mightiest of the Titans, a daughter is born. But Circe is a strange child -- not powerful, like her father, nor viciously alluring like her mother. Turning to the world of mortals for companionship, she discovers that she does possess power -- the power of witchcraft, which can transform rivals into monsters and menace the gods themselves.

Threatened, Zeus banishes her to a deserted island, where she hones her occult craft, tames wild beasts and crosses paths with many of the most famous figures in all of mythology, including the Minotaur, Daedalus and his doomed son Icarus, the murderous Medea, and, of course, wily Odysseus.

But there is danger, too, for a woman who stands alone, and Circe unwittingly draws the wrath of both men and gods, ultimately finding herself pitted against one of the most terrifying and vengeful of the Olympians. To protect what she loves most, Circe must summon all her strength and choose, once and for all, whether she belongs with the gods she is born from, or the mortals she has come to love.

With unforgettably vivid characters, mesmerizing language, and page-turning suspense, Circe is a triumph of storytelling, an intoxicating epic of family rivalry, palace intrigue, love and loss, as well as a celebration of indomitable female strength in a man''s world.', 400, 728, 2018, 383598, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Magicians', 'Lev Grossman', '0452295769', 'https://assets.hardcover.app/edition/29845101/af734872740e159dee1d91fe84be9a8063aa58ea.jpeg', 'Quentin Coldwater is brilliant but miserable. A senior in high school, he’s still secretly preoccupied with a series of fantasy novels he read as a child, set in a magical land called Fillory. Imagine his surprise when he finds himself unexpectedly admitted to a very secret, very exclusive college of magic in upstate New York, where he receives a thorough and rigorous education in the craft of modern sorcery.

He also discovers all the other things people learn in college: friendship, love, sex, booze, and boredom. Something is missing, though. Magic doesn’t bring Quentin the happiness and adventure he dreamed it would. After graduation he and his friends make a stunning discovery: Fillory is real. But the land of Quentin’s fantasies turns out to be much darker and more dangerous than he could have imagined. His childhood dream becomes a nightmare with a shocking truth at its heart.

At once psychologically piercing and magnificently absorbing, The Magicians boldly moves into uncharted literary territory, imagining magic as practiced by real people, with their capricious desires and volatile emotions. Lev Grossman creates an utterly original world in which good and evil aren’t black and white, love and sex aren’t simple or innocent, and power comes at a terrible price.', 417, null, 2009, 384419, (select id from series where hardcover_id = 1041), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('New Spring', 'Robert Jordan', '1559279524', 'https://assets.hardcover.app/edition/30931096/54c9913c-528a-417c-974c-10a045a26a92.png', 'Since its debut in 1990, The Wheel of Time® by Robert Jordan has captivated millions of readers around the globe with its scope, originality, and compelling characters.

The Wheel of Time turns and Ages come and go, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. In the Third Age, an Age of Prophecy, the World and Time themselves hang in the balance. What was, what will be, and what is, may yet fall under the Shadow.

For three days battle has raged in the snow around the great city of Tar Valon. In the city, a Foretelling of the future is uttered. On the slopes of Dragonmount, the immense mountain that looms over the city, is born an infant prophesied to change the world. That child must be found before the forces of the Shadow have an opportunity to kill him.

Moiraine Damodred, a young Accepted soon to be raised to Aes Sedai, and Lan Mandragoran, a soldier fighting in the battle, are set on paths that will bind their lives together. But those paths are filled with complications and dangers, for Moiraine, of the Royal House of Cairhien, whose king has just died, and Lan, considered the uncrowned king of a nation long dead, find their lives threatened by the plots of those seeking power.

"New Spring" related some of these events, in compressed form; New Spring: The Novel tells the whole story.', 416, null, 2004, 384434, (select id from series where hardcover_id = 1097), 0) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blindsight', 'Peter Watts', '3453523644', 'https://assets.hardcover.app/book_mappings/7333230/0c3d4d7893e47e39bcbde68fcb6c343a2be66a24.jpeg', '*Two months since the stars fell...*

Two months since sixty-five thousand alien objects clenched around the Earth like a luminous fist, screaming to the heavens as the atmosphere burned them to ash. Two months since that moment of brief, bright surveillance by agents unknown. 

Two months of silence while a world holds its breath. 

Now some half-derelict space probe, sparking fitfully past Neptune''s orbit, hears a whisper from the edge of the solar system: a faint signal sweeping the cosmos like a lighthouse beam. Whatever''s out there isn''t talking to us. It''s talking to some distant star, perhaps. Or perhaps to something closer, something *en route.* 

So who do you send to force introductions on an intelligence with motives unknown, maybe unknowable? Who do you send to meet the alien when the alien doesn''t want to meet? 

You send a linguist with multiple personalities, her brain surgically partitioned into separate, sentient processing cores. You send a biologist so radically interfaced with machinery that he sees X-rays and tastes ultrasound, so compromised by grafts and splices that he no longer feels his own flesh. You send a pacifist warrior in the faint hope she won''t be needed, and a fainter hope that she''ll do any good if she is needed. You send a monster to command them all, an extinct hominid predator once called "vampire," recalled from the grave with the voodoo of recombinant genetics and the blood of sociopaths. And you send a synthesist—an informational topologist with half his mind gone—as an interface between *here* and *there,* a conduit through which the Dead Center might hope to understand the Bleeding Edge. 

You send them all to the edge of interstellar space, praying you can trust such freaks and retrofits with the fate of a world. You fear they may be more alien than the thing they''ve been sent to find. 

But you''d give anything for that to be true, if you only knew what was waiting for them....', 384, null, 2006, 384771, (select id from series where hardcover_id = 1161), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Under the Dome', 'Stephen King', '3453266285', 'https://assets.hardcover.app/edition/4556114/f9aeb7c5a9598fbef92833b6ee1465fe72381019.jpeg', 'Under the Dome is a 2009 science fiction novel by the American author, Stephen King. Under the Dome is the 58th book published by Stephen King, and it is his 48th novel. The novel focuses on a small Maine town, and tells an intricate, multi-character, alternating perspective story of how the town''s inhabitants contend with the calamity of being suddenly cut off from the outside world by an impassable, invisible glass dome-like barrier that seemingly falls out of the sky, transforming the community into a domed city.

----------
Contains:

 - [Under the Dome 1/2](https://openlibrary.org/works/OL18003966W/Under_the_Dome_1_2)
 - [Under the Dome 2/2](https://openlibrary.org/works/OL18168854W/Under_the_Dome_2_2)', 880, null, 2009, 384966, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Restaurant at the End of the Universe', 'Douglas Adams', '837359423X', 'https://assets.hardcover.app/edition/30391528/85b67e92-1dc0-40bb-be5d-4988afdfb511.jpg', 'Join the cosmically displaced Arthur Dent and his uncommon comrades in arms in their desperate search for a place to eat, as they hurtle across space powered by pure improbability.

Among Arthur’s motley shipmates are Ford Prefect, a longtime friend and expert contributor to The Hitchhiker’s Guide to the Galaxy; Zaphod Beeblebrox, the three-armed, two-headed ex-president of the galaxy; Tricia McMillan, a fellow Earth refugee who’s gone native (her name is Trillian now); and Marvin, the moody android. Their destination? The ultimate hot spot for an evening of apocalyptic entertainment and fine dining, where the food speaks for itself (literally).

Will they make it? The answer: hard to say. But bear in mind that The Hitchhiker’s Guide deleted the term “Future Perfect” from its pages, since it was discovered not to be!', 205, 347, 1980, 384991, (select id from series where hardcover_id = 3400), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Norse Mythology', 'Neil Gaiman', '006266364X', 'https://assets.hardcover.app/editions/30400951/5286491007216958.jpg', 'Neil Gaiman has long been inspired by ancient mythology in creating the fantastical realms of his fiction. Now he turns his attention back to the source, presenting a bravura rendition of the great northern tales.

In Norse Mythology, Gaiman stays true to the myths in envisioning the major Norse pantheon: Odin, the highest of the high, wise, daring, and cunning; Thor, Odin’s son, incredibly strong yet not the wisest of gods; and Loki―son of a giant―blood brother to Odin and a trickster and unsurpassable manipulator.

Gaiman fashions these primeval stories into a novelistic arc that begins with the genesis of the legendary nine worlds and delves into the exploits of deities, dwarfs, and giants. Once, when Thor’s hammer is stolen, Thor must disguise himself as a woman―difficult with his beard and huge appetite―to steal it back. More poignant is the tale in which the blood of Kvasir―the most sagacious of gods―is turned into a mead that infuses drinkers with poetry. The work culminates in Ragnarok, the twilight of the gods and rebirth of a new time and people.

Through Gaiman’s deft and witty prose emerge these gods with their fiercely competitive natures, their susceptibility to being duped and to duping others, and their tendency to let passion ignite their actions, making these long-ago myths breathe pungent life again.', 301, null, 1996, 385427, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Warbreaker', 'Brandon Sanderson', '8415389884', 'https://assets.hardcover.app/edition/28188510/d2bfa4645e6a05879e663f2b72264dc150610210.jpeg', 'From #1 New York Times bestselling author Brandon Sanderson, Warbreaker is the story of two sisters, who happen to be princesses, the God King one of them has to marry, the lesser god who doesn''t like his job, and the immortal who''s still trying to undo the mistakes he made hundreds of years ago. Their world is one in which those who die in glory return as gods to live confined to a pantheon in Hallandren''s capital city and where a power known as BioChromatic magic is based on an essence known as breath that can only be collected one unit at a time from individual people. By using breath and drawing upon the color in everyday objects, all manner of miracles and mischief can be accomplished. It will take considerable quantities of each to resolve all the challenges facing Vivenna and Siri, princesses of Idris; Susebron the God King; Lightsong, reluctant god of bravery, and mysterious Vasher, the Warbreaker.', 593, 1070, 2009, 385491, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Warded Man: Book One of The Demon Cycle', 'Peter V. Brett', '8375744670', 'https://assets.hardcover.app/edition/31298570/dd6d5c59a345c575f4267a75a4751c2045cc2d57.jpeg', 'As darkness falls, the demons will rise: This first book in the Demon Cycle series by New York Times bestselling author Peter V. Brett has been “justifiably a fan favorite for fifteen years” (Robin Hobb). The time has come to stand against the night. At sunset, the corelings rise—demons who well up from the ground like hellish steam, taking on fearsome form and substance. Immune to mortal weapons, they burn with a consuming hatred of humanity. For hundreds of years corelings have terrorized the night, slowly culling the human herd that shelters behind magical wards—symbols of power whose origins are lost in myth and mystery. It was not always this way. Once, men and women battled the corelings on equal terms. Once, under the leadership of the legendary Deliverer, and armed with powerful wards that were not merely shields but weapons, they took the battle to the demons. Now those days are gone. The fighting wards are lost. Night by night, the demons grow stronger, while human numbers dwindle. With hope for the future fading, three young survivors of vicious demon attacks will dare the impossible, stepping beyond the crumbling safety of the wards to risk everything in a desperate quest to regain the secrets of the past. Includes a bonus Demon Cycle novella: The Great Bazaar Don’t miss any of the thrilling novels in Peter V. Brett’s Demon Cycle THE WARDED MAN • THE DESERT SPEAR • THE DAYLIGHT WAR • THE SKULL THRONE • THE CORE', 590, null, 2008, 385978, (select id from series where hardcover_id = 5555), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Way of Kings', 'Brandon Sanderson', '8466657665', 'https://assets.hardcover.app/edition/3134360/a18d937805a28e3214a556442c8d33f41c02f2cb.jpeg', 'From #1 New York Times bestselling author Brandon Sanderson, The Way of Kings, book one of The Stormlight Archive begins an incredible new saga of epic proportion.

Roshar is a world of stone and storms. Uncanny tempests of incredible power sweep across the rocky terrain so frequently that they have shaped ecology and civilization alike. Animals hide in shells, trees pull in branches, and grass retracts into the soilless ground. Cities are built only where the topography offers shelter.

It has been centuries since the fall of the ten consecrated orders known as the Knights Radiant, but their Shardblades and Shardplate remain: mystical swords and suits of armor that transform ordinary men into near-invincible warriors. Men trade kingdoms for Shardblades. Wars were fought for them, and won by them.

One such war rages on a ruined landscape called the Shattered Plains. There, Kaladin, who traded his medical apprenticeship for a spear to protect his little brother, has been reduced to slavery. In a war that makes no sense, where ten armies fight separately against a single foe, he struggles to save his men and to fathom the leaders who consider them expendable.

Brightlord Dalinar Kholin commands one of those other armies. Like his brother, the late king, he is fascinated by an ancient text called The Way of Kings. Troubled by over-powering visions of ancient times and the Knights Radiant, he has begun to doubt his own sanity.

Across the ocean, an untried young woman named Shallan seeks to train under an eminent scholar and notorious heretic, Dalinar''s niece, Jasnah. Though she genuinely loves learning, Shallan''s motives are less than pure. As she plans a daring theft, her research for Jasnah hints at secrets of the Knights Radiant and the true cause of the war.

The result of over ten years of planning, writing, and world-building, The Way of Kings is but the opening movement of the Stormlight Archive, a bold masterpiece in the making.

Speak again the ancient oaths:

Life before death.
Strength before weakness.
Journey before Destination.

and return to men the Shards they once bore.

The Knights Radiant must stand again.', 1007, 2730, 2010, 386446, (select id from series where hardcover_id = 997), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Complete Chronicles of Narnia', 'C. S. Lewis, Pauline Baynes', '0694524662', 'https://assets.hardcover.app/external_data/4096279/3579d5cec25ee3510801631c073170b2993e7274.jpeg', 'The book that has it all is The Lion, the Witch and the Wardrobe, written in 1949 by Clive Staples Lewis. But Lewis did not stop there. Six more books followed, and together they became known as The Chronicles of Narnia.
For the past fifty years, The Chronicles of Narnia have transcended the fantasy genre to become part of the canon of classic literature. Each of the seven books is a masterpiece, drawing the reader into a land where magic meets reality, and the result is a fictional world whose scope has fascinated generations.
Deceptively simple and direct, The Chronicles of Narnia continue to captivate fans with adventures, characters, and truths that speak to readers of all ages, even fifty years after they were first published.', 768, null, 1956, 386658, (select id from series where hardcover_id = 5485), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cryptonomicon', 'Neal Stephenson', '0434009539', 'https://assets.hardcover.app/book_mappings/7332619/2b8c686e09d465bb1b8aa2fd9531be4d6842e9a1.jpeg', 'In 1942, Lawrence Pritchard Waterhouse—mathematical genius and young Captain in the U.S. Navy—is assigned to detachment 2702. It is an outfit so secret that only a handful of people know it exists, and some of those people have names like Churchill and Roosevelt. The mission of Waterhouse and Detachment 2702—commanded by Marine Raider Bobby Shaftoe-is to keep the Nazis ignorant of the fact that Allied Intelligence has cracked the enemy''s fabled Enigma code. It is a game in this work of historical fiction, a cryptographic chess match between Waterhouse and his German counterpart, translated into action by the gung-ho Shaftoe and his forces.

Fast-forward to the present, where Waterhouse''s crypto-hacker grandson, Randy, is attempting to create a "data haven" in Southeast Asia—a place where encrypted data can be stored and exchanged free of repression and scrutiny. As governments and multinationals attack the endeavor, Randy joins forces with Shaftoe''s tough-as-nails granddaughter, Amy, to secretly salvage a sunken Nazi submarine that holds the key to keeping the dream of a data haven afloat. But soon their scheme brings to light a massive conspiracy with its roots in Detachment 2702 linked to an unbreakable Nazi code called Arethusa. And it will represent the path to unimaginable riches and a future of personal and digital liberty...or to universal totalitarianism reborn.

A breathtaking tour de force, and Neal Stephenson''s most accomplished and affecting work to date, this techno-thriller, Cryptonomicon, is profound and prophetic, hypnotic and hyper-driven, as it leaps forward and back between World War II and the World Wide Web, hinting all the while at a dark day-after-tomorrow. It is a work of great art, thought and creative daring; the product of a truly iconoclastic imagination working with white-hot intensity.', 1152, null, 1999, 386719, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of Dune', 'Frank Herbert', '8381880475', 'https://assets.hardcover.app/edition/30825973/a2fec259-e3b1-4d17-8755-2bbe0af30ca9.jpg', 'The science fiction masterpiece continues in the "major event,"( Los Angeles Times) Children of Dune. With millions of copies sold worldwide, Frank Herbert''s Dune novels stand among the major achievements of the human imagination and one of the most significant sagas in the history of literary science fiction. The Children of Dune are twin siblings Leto and Ghanima Atreides, whose father, the Emperor Paul Muad''Dib, disappeared in the deserts of Arrakis. Like their father, they possess supernormal abilities—making them valuable to their aunt Alia, who rules the Empire. If Alia can obtain the secrets of the twins'' prophetic visions, her rule will be absolute. But the twins have their own plans for their destiny.', 623, 1020, 1975, 427314, (select id from series where hardcover_id = 1150), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cat''s Cradle', 'Kurt Vonnegut', '0440011442', 'https://assets.hardcover.app/edition/32794786/6985d5d6-29c1-44ba-b303-36fd50b12b6c.jpg', 'One of Vonnegut''s major works, a young writer decides to interview the children of a scientist primarily responsible for the creation of the atomic bomb. This is an apocalyptic tale of the planet''s ultimate fate, featuring a cast of unlikely heroes.', 306, 431, 1963, 427315, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('To Sleep in a Sea of Stars', 'Christopher Paolini', '9402315322', 'https://assets.hardcover.app/external_data/47331268/031e59a77fdabb399693765253a5d63dfd067450.jpeg', 'Now a New York Times and USA Today bestseller! Winner of Best Science Fiction in the 2020 Goodreads Choice Awards! To Sleep in a Sea of Stars is a brand new epic novel from #1 New York Times bestselling author of Eragon, Christopher Paolini. 

Kira Navárez dreamed of life on new worlds. Now she''s awakened a nightmare. During a routine survey mission on an uncolonized planet, Kira finds an alien relic. At first she''s delighted, but elation turns to terror when the ancient dust around her begins to move.

As war erupts among the stars, Kira is launched into a galaxy-spanning odyssey of discovery and transformation. First contact isn''t at all what she imagined, and events push her to the very limits of what it means to be human.

While Kira faces her own horrors, Earth and its colonies stand upon the brink of annihilation. Now, Kira might be humanity''s greatest and final hope...', 880, null, 2019, 427334, (select id from series where hardcover_id = 5474), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Assassin''s Apprentice', 'Robin Hobb', '8374804475', 'https://assets.hardcover.app/editions/30407451/9092249423146916.jpg', 'Born on the wrong side of the sheets, Fitz, son of Chivalry Farseer, is a royal bastard, cast out into the world, friendless and lonely. Only his magical link with animals - the old art known as the Wit - gives him solace and companionship. But the Wit, if used too often, is a perilous magic, and one abhorred by the nobility.

So when Fitz is finally adopted into the royal household, he must give up his old ways and embrace a new life of weaponry, scribing, courtly manners; and how to kill a man secretly, as he trains to become a royal assassin.', 400, 1039, 1995, 427336, (select id from series where hardcover_id = 5513), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Great Hunt', 'Robert Jordan', '1590073630', 'https://assets.hardcover.app/edition/30593252/5f9c2489-6c08-41de-8228-9cc11dc5e229.png', 'NOW A MAJOR TV SERIES ON PRIME VIDEO The second novel in the Wheel of Time series - one of the most influential and popular fantasy epics ever published. The Forsaken are loose, the Horn of Valere has been found and the Dead are rising from their dreamless sleep. The Prophecies are being fulfilled - but Rand al''Thor, the shepherd the Aes Sedai have proclaimed as the Dragon Reborn, desperately seeks to escape his destiny. Rand cannot run for ever. With every passing day the Dark One grows in strength and strives to shatter his ancient prison, to break the Wheel, to bring an end to Time and sunder the weave of the Pattern. And the Pattern demands the Dragon. ''Epic in every sense'' Sunday Times ''With the Wheel of Time, Jordan has come to dominate the world that Tolkien began to reveal'' New York Times ''[The] huge ambitious Wheel of Time series helped redefine the genre'' George R. R. Martin ''A fantasy phenomenon'' SFX The Wheel of Time series: Book 1: The Eye of the World Book 2: The Great Hunt Book 3: The Dragon Reborn Book 4: The Shadow Rising Book 5: The Fires of Heaven Book 6: Lord of Chaos Book 7: A Crown of Swords Book 8: The Path of Daggers Book 9: Winter''s Heart Book 10: Crossroads of Twilight Book 11: Knife of Dreams Book 12: The Gathering Storm Book 13: Towers of Midnight Book 14: A Memory of Light Prequel: New Spring Look out for the companion book: The World of Robert Jordan''s The Wheel of Time', 720, null, 1990, 427352, (select id from series where hardcover_id = 1097), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('God Emperor of Dune', 'Frank Herbert', '0593955730', 'https://assets.hardcover.app/external_data/30542666/b90d2d32426e5bf180573b4e97421db3307c93e0.jpeg', 'Millennia have passed on Arrakis, and the once-desert planet is green with life. Leto Atreides, the son of the world’s savior, the Emperor Paul Muad’Dib, is still alive but far from human. To preserve humanity’s future, he sacrificed his own by merging with a sandworm, granting him near immortality as God Emperor of Dune for the past thirty-five hundred years. Leto’s rule is not a benevolent one. His transformation has made not only his appearance but his morality inhuman. A rebellion, led by Siona, a member of the Atreides family, has risen to oppose the despot’s rule. But Siona is unaware that Leto’s vision of a Golden Path for humanity requires her to fulfill a destiny she never wanted—or could possibly conceive....', 436, null, 1981, 427363, (select id from series where hardcover_id = 1150), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Clash of Kings', 'George R.R. Martin', '9780007447839', 'https://assets.hardcover.app/edition/7441206/83b941d8f996468d946641f3674e9b26461a3ddc.jpeg', 'A comet the color of blood and flame cuts across the sky. And from the ancient citadel of Dragonstone to the forbidding shores of Winterfell, chaos reigns. Six factions struggle for control of a divided land and the Iron Throne of the Seven Kingdoms, preparing to stake their claims through tempest, turmoil, and war. It is a tale in which brother plots against brother and the dead rise to walk in the night. Here a princess masquerades as an orphan boy; a knight of the mind prepares a poison for a treacherous sorceress; and wild men descend from the Mountains of the Moon to ravage the countryside. Against a backdrop of incest and fratricide, alchemy and murder, victory may go to the men and women possessed of the coldest steel . . . and the coldest hearts. For when kings clash, the whole land trembles.', 770, null, 1998, 427374, (select id from series where hardcover_id = 981), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Well of Ascension', 'Brandon Sanderson', '841803727X', 'https://assets.hardcover.app/book_mappings/7332358/43f95ab5370016fe0b2eddf9adee5f338850e6c4.jpeg', 'From #1 New York Times bestselling author Brandon Sanderson, the Mistborn series is a heist story of political intrigue and magical, martial-arts action. The impossible has been accomplished. 

The Lord Ruler -- the man who claimed to be god incarnate and brutally ruled the world for a thousand years -- has been vanquished. 

But Kelsier, the hero who masterminded that triumph, is dead too, and now the awesome task of building a new world has been left to his young protégé, Vin, the former street urchin who is now the most powerful Mistborn in the land, and to the idealistic young nobleman she loves. As Kelsier''s protégé and slayer of the Lord Ruler she is now venerated by a budding new religion, a distinction that makes her intensely uncomfortable. 

Even more worrying, the mists have begun behaving strangely since the Lord Ruler died, and seem to harbor a strange vaporous entity that haunts her. Stopping assassins may keep Vin''s Mistborn skills sharp, but it''s the least of her problems. Luthadel, the largest city of the former empire, doesn''t run itself, and Vin and the other members of Kelsier''s crew, who lead the revolution, must learn a whole new set of practical and political skills to help. 

It certainly won''t get easier with three armies – one of them composed of ferocious giants – now vying to conquer the city, and no sign of the Lord Ruler''s hidden cache of atium, the rarest and most powerful allomantic metal. As the siege of Luthadel tightens, an ancient legend seems to offer a glimmer of hope. But even if it really exists, no one knows where to find the Well of Ascension or what manner of power it bestows. ', 590, 1737, 2007, 427383, (select id from series where hardcover_id = 10001), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Forever War', 'Joe Haldeman', '9781436121170', 'https://assets.hardcover.app/editions/26853601/8a803516-635c-40a4-b430-a682a15f7a58-tforeverwar.jpg', 'Private William Mandella is a hero in spite of himself -- a reluctant conscript drafted into an elite military unit, and propelled through space and time to fight in a distant thousand-year conflict. He never wanted to go to war, but the leaders on Earth have drawn a line in the interstellar sand -- despite the fact that their fierce alien enemy is unknowable, unconquerable, and very far away. 

So Mandella will perform his duties without rancor and even rise up through the military''s ranks... if he survives. But the true test of his mettle will come when he returns to Earth. Because of the time dilation caused by space travel the loyal soldier is aging months, while his home planet is aging centuries -- and the difference will prove the saying: you never can go home..', 203, 558, 1974, 427389, (select id from series where hardcover_id = 1111), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dune Messiah', 'Frank Herbert', '902906739X', 'https://assets.hardcover.app/edition/24211570/08ad8362f4da9c08a76f6d08aeab822336b97c35.jpeg', 'Dune Messiah continues the story of Paul Atreides, better known—and feared—as the man christened Muad’Dib. As Emperor of the known universe, he possesses more power than a single man was ever meant to wield. 

Worshipped as a religious icon by the fanatical Fremen, Paul faces the enmity of the political houses he displaced when he assumed the throne—and a conspiracy conducted within his own sphere of influence. 

And even as House Atreides begins to crumble around him from the machinations of his enemies, the true threat to Paul comes to his lover, Chani, and the unborn heir to his family’s dynasty...', 304, 540, 1965, 427393, (select id from series where hardcover_id = 1150), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Wizard of Earthsea', 'Ursula K. Le Guin', '0881037559', 'https://assets.hardcover.app/edition/30492202/e9af25c4b09bf983578e1eabdca87c593f1d5452.jpeg', 'A boy grows to manhood while attempting to subdue the evil he unleashed on the world as an apprentice to the Master Wizard.', 251, 438, 1968, 427401, (select id from series where hardcover_id = 1170), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Outlander', 'Diana Gabaldon', '0553393693', 'https://assets.hardcover.app/edition/32259804/8dc6325f-ea56-498d-94df-053658a7b4e2.jpg', 'Unrivaled storytelling. Unforgettable characters. Rich historical detail. These are the hallmarks of Diana Gabaldon’s work. Her New York Times bestselling Outlander novels have earned the praise of critics and captured the hearts of millions of fans. Here is the story that started it all, introducing two remarkable characters, Claire Beauchamp Randall and Jamie Fraser, in a spellbinding novel of passion and history that combines exhilarating adventure with a love story for the ages.

Scottish Highlands, 1945. Claire Randall, a former British combat nurse, is just back from the war and reunited with her husband on a second honeymoon when she walks through a standing stone in one of the ancient circles that dot the British Isles. Suddenly she is a Sassenach—an “outlander”—in a Scotland torn by war and raiding clans in the year of Our Lord,  1743.
 
Claire is catapulted into the intrigues of a world that threatens her life, and may shatter her heart. Marooned amid danger, passion, and violence, Claire learns her only chance of safety lies in Jamie Fraser, a gallant young Scots warrior. What begins in compulsion becomes urgent need, and Claire finds herself torn between two very different men, in two irreconcilable lives.', 882, null, 1991, 427404, (select id from series where hardcover_id = 1162), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Light Fantastic', 'Terry Pratchett', '055216660X', 'https://assets.hardcover.app/edition/30538267/4b7c4f8610e1ca3d0380203ca485a06bd65174ea.jpeg', 'It needs a hero, and fast.

What it doesn''t need is Rincewind, an inept and cowardly wizard who is still recovering from the trauma of falling off the edge of the world. Or Twoflower, the well-meaning tourist whose luggage has a mind (and legs) of its own.

Which is a shame, because that''s all there is . . .', 285, null, 1986, 427416, (select id from series where hardcover_id = 1018), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ringworld', 'Larry Niven', '9010017184', 'https://assets.hardcover.app/external_data/39800924/d9adf2af51cb8a9e6a3b643d647c2ff9d95f1ecd.jpeg', 'The artefact is a circular ribbon of matter six hundred million miles long and ninety million miles in radius. Pierson''s puppeteers, the aliens who discovered it, are understandably wary of encountering the builders of such an immense structure and have assembled a team of two humans, a mad puppeteer and a kzin, a huge cat-like alien, to explore it. But a crash landing on the vast edifice forces the crew on a desperate and dangerous trek across the Ringworld.', 288, null, 1970, 427450, (select id from series where hardcover_id = 2940), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Girl with All the Gifts', 'M. R. Carey', '9896650985', 'https://assets.hardcover.app/external_data/45046247/c2c59429fe55dba2dc1d71fbc0c888514e7c1e02.jpeg', 'Melanie is a very special girl. Dr Caldwell calls her "our little genius."
Every morning, Melanie waits in her cell to be collected for class. When they come for her, Sergeant keeps his gun pointing at her while two of his people strap her into the wheelchair. She thinks they don''t like her. She jokes that she won''t bite, but they don''t laugh.
Melanie loves school. She loves learning about spelling and sums and the world outside the classroom and the children''s cells. She tells her favorite teacher all the things she''ll do when she grows up. Melanie doesn''t know why this makes Miss Justineau look sad.
THE GIRL WITH ALL THE GIFTS is a sensational thriller, perfect for fans of Stephen King, Justin Cronin and Neil Gaiman.', 461, null, 2014, 427451, (select id from series where hardcover_id = 1021), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Morning Star', 'Pierce Brown', '6053439169', 'https://assets.hardcover.app/book_mappings/7332844/702879986b75f035349c34acad3d94f88bb737ed.jpeg', 'Darrow would have lived in peace, but his enemies brought him war. The Gold overlords demanded his obedience, hanged his wife, and enslaved his people. But Darrow is determined to fight back. Risking everything to transform himself and breach Gold society, Darrow has battled to survive the cutthroat rivalries that breed Society’s mightiest warriors, climbed the ranks, and waited patiently to unleash the revolution that will tear the hierarchy apart from within.

Finally, the time has come.

But devotion to honor and hunger for vengeance run deep on both sides. Darrow and his comrades-in-arms face powerful enemies without scruple or mercy. Among them are some Darrow once considered friends. To win, Darrow will need to inspire those shackled in darkness to break their chains, unmake the world their cruel masters have built, and claim a destiny too long denied—and too glorious to surrender.', 524, 1310, 2016, 427456, (select id from series where hardcover_id = 1033), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Firefight', 'Brandon Sanderson', '1511359935', 'https://assets.hardcover.app/external_data/44174346/05bebf64e9fa5c3f09a3841ab1685c57684181ec.jpeg', 'David Charleston has lived for one purpose: to kill Steelheart, the supremely powerful, seemingly invincible Epic who murdered his father. Now Steelheart is dead and David is beginning to question everything that he—and the world—understands about the superhumans they call Epics.

David’s suspicions are the reason he follows Prof to the flooded city once known as New York. But what he finds there could be what ultimately ends him. The truth might just burn deepest of all. . . .', 332, null, 2014, 427458, (select id from series where hardcover_id = 1038), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hyperion', 'Dan Simmons', '8466658033', 'https://assets.hardcover.app/edition/30428122/3c2f0e295e374546dcee4d94bd25197589d8484a.jpeg', 'A stunning tour de force filled with transcendent awe and wonder, Hyperion is a masterwork of science fiction that resonates with excitement and invention, the first volume in a remarkable epic by the multiple-award-winning author of The Hollow Man. On the world called Hyperion, beyond the reach of galactic law, waits a creature called the Shrike. There are those who worship it. There are those who fear it. And there are those who have vowed to destroy it. In the Valley of the Time Tombs, where huge, brooding structures move backward through time, the Shrike waits for them all. On the eve of Armageddon, with the entire galaxy at war, seven pilgrims set forth on a final voyage to Hyperion seeking the answers to the unsolved riddles of their lives. Each carries a desperate hope—and a terrible secret. And one may hold the fate of humanity in his hands. Praise for Dan Simmons and Hyperion “Dan Simmons has brilliantly conceptualized a future 700 years distant. In sheer scope and complexity it matches, and perhaps even surpasses, those of Isaac Asimov and James Blish.”—The Washington Post Book World “An unfailingly inventive narrative . . . generously conceived and stylistically sure-handed.”—The New York Times Book Review “Simmons’s own genius transforms space opera into a new kind of poetry.”—The Denver Post “An essential part of any science fiction collection.”—Booklist', 492, 1244, 1989, 427460, (select id from series where hardcover_id = 1049), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Station Eleven', 'Emily St. John Mandel', '8025715949', 'https://assets.hardcover.app/external_data/47671286/cde65e40092722f63a5b9a29a672d12bc75ae19b.jpeg', 'Kirsten Raymonde will never forget the night Arthur Leander, the famous Hollywood actor, had a heart attack on stage during a production of King Lear. That was the night when a devastating flu pandemic arrived in the city, and within weeks, civilization as we know it came to an end.

Twenty years later, Kirsten moves between the settlements of the altered world with a small troupe of actors and musicians. They call themselves The Traveling Symphony, and they have dedicated themselves to keeping the remnants of art and humanity alive. But when they arrive in St. Deborah by the Water, they encounter a violent prophet who will threaten the tiny band’s existence. And as the story takes off, moving back and forth in time, and vividly depicting life before and after the pandemic, the strange twist of fate that connects them all will be revealed.', 333, 641, 2014, 427463, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Fire Upon the Deep', 'Vernor Vinge', '9731431497', 'https://assets.hardcover.app/edition/29849617/06ae5eb360de4cbfe986689a915820d18b594c5d.jpeg', 'After a spaceship crashes in unknown and unfriendly territory, two young children, the only survivors, are left to fend for themselves, but with time being of the essence, a rescue plan must be put into place quickly before the clock runs out on their lives. Reissue.', 613, null, 1992, 427468, (select id from series where hardcover_id = 1134), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red Rising', 'Pierce Brown', '8525058548', 'https://assets.hardcover.app/editions/26096001/3897005112280259.jpg', '“I live for you,” I say sadly.
Eo kisses my cheek. “Then you must live for more.”

Darrow is a Red, a member of the lowest caste in the color-coded society of the future. Like his fellow Reds, he works all day, believing that he and his people are making the surface of Mars livable for future generations. Yet he toils willingly, trusting that his blood and sweat will one day result in a better world for his children.

But Darrow and his kind have been betrayed. Soon he discovers that humanity reached the surface generations ago. Vast cities and lush wilds spread across the planet. Darrow—and Reds like him—are nothing more than slaves to a decadent ruling class.

Inspired by a longing for justice, and driven by the memory of lost love, Darrow sacrifices everything to infiltrate the legendary Institute, a proving ground for the dominant Gold caste, where the next generation of humanity’s overlords struggle for power.  He will be forced to compete for his life and the very future of civilization against the best and most brutal of Society’s ruling class. There, he will stop at nothing to bring down his enemies . . . even if it means he has to become one of them to do so.', 382, 972, 2014, 427473, (select id from series where hardcover_id = 1033), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blood Rites', 'Jim Butcher', '0451459873', 'https://assets.hardcover.app/edition/16648734/915c098c1ede74a0cf7837e938e1bd6af0dee763.jpeg', 'Harry Dresden has had worse assignments than going undercover on the set of an adult film. Like fleeing a burning building full of enraged demon-monkeys, for instance. Or going toe-to-leaf with a walking plant monster. Still, there’s something more troubling than usual about his newest case. The film’s producer believes he’s the target of a sinister curse—but it’s the women around him who are dying, in increasingly spectacular ways.
 
Harry’s doubly frustrated because he only got involved with this bizarre mystery as a favor to Thomas—his flirtatious, self-absorbed vampire acquaintance of dubious integrity. Thomas has a personal stake in the case Harry can’t quite figure out, until his investigation leads him straight to the vampire’s oversexed, bite-happy family. Now, Harry’s about to discover that Thomas’ family tree has been hiding a shocking secret: a revelation that will change Harry’s life forever.', 372, null, 2004, 427480, (select id from series where hardcover_id = 990), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Deadly Education', 'Naomi Novik', '6077482064', 'https://assets.hardcover.app/edition/23382500/d2861121a8e6dd8a33fdb7be5632c7bcd0e3232a.jpeg', 'Everyone loves Orion Lake. Everyone else, that is. As far as I’m concerned, he can keep his flashy combat magic to himself. I’m not joining his pack of adoring fans.

I don’t need help surviving the Scholomance, even if they do. Forget the hordes of monsters and cursed artefacts. I’m probably the most dangerous thing in the place. Just give me a chance and I’ll level mountains and kill untold millions, making myself the dark queen of the world.

At least, that’s what the world expects. Most of the other students in here would be delighted if Orion killed me, like one more evil thing that’s crawled out of the drains. Sometimes I think they want me to turn into the evil witch they assume I am. The school certainly does.

But the Scholomance isn’t getting what it wants from me. And neither is Orion Lake. I may not be anyone’s idea of the shining hero, but I’m going to make it out of this place alive, and I’m not going to slaughter thousands to do it, either.

Although I’m giving serious consideration to just one.', 320, null, 2020, 427507, (select id from series where hardcover_id = 1031), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Slow Regard of Silent Things', 'Patrick Rothfuss', '3608960201', 'https://assets.hardcover.app/edition/30403854/f7be273ee9f04186c54cc2ec806b49b896da22e6.jpeg', 'Deep below the University, there is a dark place. Few people know of it: a broken web of ancient passageways and abandoned rooms. A young woman lives there, tucked among the sprawling tunnels of the Underthing, snug in the heart of this forgotten place.

Her name is Auri, and she is full of mysteries.

The Slow Regard of Silent Things is a brief, bittersweet glimpse of Auri’s life, a small adventure all her own. At once joyous and haunting, this story offers a chance to see the world through Auri’s eyes. And it gives the reader a chance to learn things that only Auri knows....

In this book, Patrick Rothfuss brings us into the world of one of The Kingkiller Chronicle’s most enigmatic characters. Full of secrets and mysteries, The Slow Regard of Silent Things is the story of a broken girl trying to live in a broken world.', 176, null, 2014, 427521, (select id from series where hardcover_id = 988), 2.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rhythm of War', 'Brandon Sanderson', '8835705762', 'https://assets.hardcover.app/edition/26332868/ca7c2f58-409f-4dbf-8d69-7d94cf302d5f.jpg', 'The eagerly awaited sequel to the #1 New York Times bestselling Oathbringer, from epic fantasy author Brandon Sanderson.

After forming a coalition of human resistance against the enemy invasion, Dalinar Kholin and his Knights Radiant have spent a year fighting a protracted, brutal war. Neither side has gained an advantage, and the threat of a betrayal by Dalinar''s crafty ally Taravangian looms over every strategic move.

Now, as new technological discoveries by Navani Kholin''s scholars begin to change the face of the war, the enemy prepares a bold and dangerous operation. The arms race that follows will challenge the very core of the Radiant ideals, and potentially reveal the secrets of the ancient tower that was once the heart of their strength.

At the same time that Kaladin Stormblessed must come to grips with his changing role within the Knights Radiant, his Windrunners face their own problem: As more and more deadly enemy Fused awaken to wage war, no more honorspren are willing to bond with humans to increase the number of Radiants. Adolin and Shallan must lead the coalition’s envoy to the honorspren stronghold of Lasting Integrity and either convince the spren to join the cause against the evil god Odium, or personally face the storm of failure.', 1232, 3447, 2020, 427522, (select id from series where hardcover_id = 997), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Death''s End', 'Cixin Liu, Ken Liu', '8417347143', 'https://assets.hardcover.app/edition/31417003/d020132a-e7a8-46ef-a70c-58b1e2042d0e.jpg', 'Half a century after the Doomsday Battle, the uneasy balance of Dark Forest Deterrence keeps the Trisolaran invaders at bay. Earth enjoys unprecedented prosperity due to the infusion of Trisolaran knowledge. With human science advancing daily and the Trisolarans adopting Earth culture, it seems that the two civilizations will soon be able to co-exist peacefully as equals without the terrible threat of mutually assured annihilation. But the peace has also made humanity complacent.

Cheng Xin, an aerospace engineer from the early twenty-first century, awakens from hibernation in this new age. She brings with her knowledge of a long-forgotten program dating from the beginning of the Trisolar Crisis, and her very presence may upset the delicate balance between two worlds. Will humanity reach for the stars or die in its cradle?', 605, 1731, 2008, 427523, (select id from series where hardcover_id = 1584), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Invisible Life of Addie LaRue', 'V. E. Schwab', '6254102064', 'https://assets.hardcover.app/edition/9887800/25a0234922dc176711a9f418e70af29bc5a6153c.jpeg', 'France, 1714: in a moment of desperation, a young woman makes a Faustian bargain to live forever—and is cursed to be forgotten by everyone she meets.

Thus begins the extraordinary life of Addie LaRue, and a dazzling adventure that will play out across centuries and continents, across history and art, as a young woman learns how far she will go to leave her mark on the world.

But everything changes when, after nearly 300 years, Addie stumbles across a young man in a hidden bookstore and he remembers her name.', 448, 1050, 2020, 427524, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lock In', 'John Scalzi', '0765375869', 'https://assets.hardcover.app/edition/15917903/5b5ba520-277c-4926-9deb-084f93de7124.jpg', 'Not too long from today, a new, highly contagious virus makes its way across the globe. Most who get sick experience nothing worse than flu, fever and headaches. But for the unlucky one percent - and nearly five million souls in the United States alone - the disease causes "Lock In": Victims fully awake and aware, but unable to move or respond to stimulus. The disease affects young, old, rich, poor, people of every color and creed. The world changes to meet the challenge.

A quarter of a century later, in a world shaped by what''s now known as "Haden''s syndrome," rookie FBI agent Chris Shane is paired with veteran agent Leslie Vann. The two of them are assigned what appears to be a Haden-related murder at the Watergate Hotel, with a suspect who is an "integrator" - someone who can let the locked in borrow their bodies for a time. If the Integrator was carrying a Haden client, then naming the suspect for the murder becomes that much more complicated.

But "complicated" doesn''t begin to describe it. As Shane and Vann began to unravel the threads of the murder, it becomes clear that the real mystery - and the real crime - is bigger than anyone could have imagined. The world of the locked in is changing, and with the change comes opportunities that the ambitious will seize at any cost. The investigation that began as a murder case takes Shane and Vann from the halls of corporate power to the virtual spaces of the locked in, and to the very heart of an emerging, surprising new human culture. It''s nothing you could have expected.', 336, null, 2001, 427527, (select id from series where hardcover_id = 1120), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Illuminae', 'Amie Kaufman, Jay Kristoff', '0606398473', 'https://assets.hardcover.app/edition/20297838/6e68204f-276b-49b9-af44-94a11e6eae4a.jpg', 'This afternoon, her planet was invaded.

The year is 2575, and two rival megacorporations are at war over a planet that’s little more than an ice-covered speck at the edge of the universe. Too bad nobody thought to warn the people living on it. With enemy fire raining down on them, Kady and Ezra—who are barely even talking to each other—are forced to fight their way onto one of the evacuating fleet, with an enemy warship in hot pursuit.

But their problems are just getting started. A deadly plague has broken out and is mutating, with terrifying results; the fleet’s AI, which should be protecting them, may actually be their enemy; and nobody in charge will say what’s really going on. As Kady hacks into a tangled web of data to find the truth, it’s clear only one person can help her bring it all to light: the ex-boyfriend she swore she’d never speak to again!

Told through a fascinating dossier of hacked documents—including emails, schematics, military files, IMs, medical reports, interviews, and more—Illuminae is the first book in a heart-stopping, high-octane trilogy about lives interrupted, the price of truth, and the courage of everyday heroes.', 599, null, 2013, 427536, (select id from series where hardcover_id = 1081), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Artificial Condition', 'Martha Wells', '1250326877', 'https://assets.hardcover.app/external_data/43328916/fa176120b21cfbaafcd9a26fe6f4252433a53f1f.jpeg', 'It has a dark past -- one in which a number of humans were killed. A past that caused it to christen itself "Murderbot."

But it has only vague memories of the massacre that spawned that title, and it wants to know more.

Teaming up with a Research Transport vessel named ART (you don''t want to know what the "A" stands for), Murderbot heads to the mining facility where it went rogue.

What it discovers will forever change the way it thinks...', 159, 201, 2018, 427537, (select id from series where hardcover_id = 1053), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Edgedancer', 'Brandon Sanderson', '3837148688', 'https://assets.hardcover.app/book_mappings/7333293/897b29378e456c460dd2e965e1d4c58203863197.jpeg', 'Three years ago, Lift asked a goddess to stop her from growing older—a wish she believed was granted. Now, in Edgedancer, the barely teenage nascent Knight Radiant finds that time stands still for no one. Although the young Azish emperor granted her safe haven from an executioner she knows only as Darkness, court life is suffocating the free-spirited Lift, who can’t help heading to Yeddaw when she hears the relentless Darkness is there hunting people like her with budding powers. The downtrodden in Yeddaw have no champion, and Lift knows she must seize this awesome responsibility.', 272, null, 2016, 427544, (select id from series where hardcover_id = 997), 2.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of Time', 'Adrian Tchaikovsky', '6586015626', 'https://assets.hardcover.app/editions/30400632/1512151722488735-25563522.jpg', 'Adrian Tchaikovsky''s Arthur C. Clarke Award-winning novel Children of Time is the epic story of humanity''s battle for survival on a terraformed planet.

The last remnants of the human race left a dying Earth, desperate to find a new home among the stars. Following in the footsteps of their ancestors, they discover the greatest treasure of the past age -- a world terraformed and prepared for human life.

But all is not right in this new Eden. In the long years since the planet was abandoned, the work of its architects has borne disastrous fruit. The planet is not waiting for them, pristine and unoccupied. New masters have turned it from a refuge into mankind''s worst nightmare.

Now two civilizations are on a collision course, both testing the boundaries of what they will do to survive. As the fate of humanity hangs in the balance, who are the true heirs of this new Earth? ', 600, 991, 2013, 427553, (select id from series where hardcover_id = 1017), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rogue Protocol', 'Martha Wells', '1250292387', 'https://assets.hardcover.app/book_mappings/7332654/d29ec327867b45eaa6838d359475917d6e9cabbc.jpeg', 'Sci-fi’s favorite antisocial A.I. is back on a mission. The case against the too-big-to-fail GrayCris Corporation is floundering, and more importantly, authorities are beginning to ask more questions about where Dr. Mensah''s SecUnit is.

And Murderbot would rather those questions went away. For good.', 160, 226, 2018, 427560, (select id from series where hardcover_id = 1053), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ready Player Two', 'Ernest Cline', '8418037083', 'https://assets.hardcover.app/external_data/59507419/9a7d6e61e5dae150c6265ddf37731f4226ddffdb.jpeg', 'AN UNEXPECTED QUEST. TWO WORLDS AT STAKE. ARE YOU READY?

Days after winning OASIS founder James Halliday’s contest, Wade Watts makes a discovery that changes everything.

Hidden within Halliday’s vaults, waiting for his heir to find, lies a technological advancement that will once again change the world and make the OASIS a thousand times more wondrous—and addictive—than even Wade dreamed possible.
 
With it comes a new riddle, and a new quest—a last Easter egg from Halliday, hinting at a mysterious prize.
 
And an unexpected, impossibly powerful, and dangerous new rival awaits, one who’ll kill millions to get what he wants.
 
Wade’s life and the future of the OASIS are again at stake, but this time the fate of humanity also hangs in the balance.', 400, null, 2019, 427565, (select id from series where hardcover_id = 1032), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dust', 'Hugh Howey', '1620510928', 'https://assets.hardcover.app/edition/31619630/a86db4a7-f149-4539-9220-86876e8173a9.jpg', '"Jules knows what her predecessors created. She knows they are the reason life has to be lived in this way.

And she won''t stand for it.

But Jules no longer has supporters. And there is far more to fear than the toxic world beyond her walls.

A poison is growing from within Silo 18.

One that cannot be stopped."-- Provided by Amazon', 483, null, 2013, 427570, (select id from series where hardcover_id = 1034), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Project Hail Mary', 'Andy Weir', '6586080932', 'https://assets.hardcover.app/editions/3274049/8741341047797682-91mYu67RfUL._SL1500_.jpg', 'Ryland Grace is the sole survivor on a desperate, last-chance mission—and if he fails, humanity and the earth itself will perish.

Except that right now, he doesn’t know that. He can’t even remember his own name, let alone the nature of his assignment or how to complete it.

All he knows is that he’s been asleep for a very, very long time. And he’s just been awakened to find himself millions of miles from home, with nothing but two corpses for company.

His crewmates dead, his memories fuzzily returning, Ryland realizes that an impossible task now confronts him. Hurtling through space on this tiny ship, it’s up to him to puzzle out an impossible scientific mystery—and conquer an extinction-level threat to our species.

And with the clock ticking down and the nearest human being light-years away, he’s got to do it all alone.

Or does he? ', 476, 971, 2021, 427578, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Saga, Vol. 1', 'Fiona Staples, Brian K. Vaughan', '952011159X', 'https://assets.hardcover.app/book_mappings/7332766/bb26e1d17b6545939d90f898bf3d25328f56c9b2.jpeg', 'Winner of the 2013 Hugo award for Best Graphic Story! When two soldiers from opposite sides of a never-ending galactic war fall in love, they risk everything to bring a fragile new life into a dangerous old universe. From New York Times bestselling writer Brian K. Vaughan (Y: The Last Man, Ex Machina) and critically acclaimed artist Fiona Staples (Mystery Society, North 40), Saga is the sweeping tale of one young family fighting to find their place in the worlds. Fantasy and science fiction are wed like never before in this sexy, subversive drama for adults. This specially priced volume collects the first six issues of the smash-hit series The Onion A.V. Club calls "the emotional epic Hollywood wishes it could make." Voted one of the top graphic novels of the year by the NYT, IGN, the Examiner, and SF Weekly. Voted Best Comic of the year by MTV Geek and Best New Series by Paradox Comics. Voted a finalist in the GoodReads Best GN of 2012 contest. Named one of Time Magazine''s top 10 graphic novels for 2013', 160, null, 2012, 427608, (select id from series where hardcover_id = 5476), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Leviathan Wakes', 'James S.A. Corey', '0373814240', 'https://assets.hardcover.app/editions/31795264/8326503637087890.jpg', 'Humanity has colonized the solar system—Mars, the Moon, the Asteroid Belt and beyond—but the stars are still out of our reach.

Jim Holden is XO of an ice miner making runs from the rings of Saturn to the mining stations of the Belt. When he and his crew stumble upon a derelict ship, the Scopuli, they find themselves in possession of a secret they never wanted. A secret that someone is willing to kill for—and kill on a scale unfathomable to Jim and his crew. War is brewing in the system unless he can find out who left the ship and why.

Detective Miller is looking for a girl. One girl in a system of billions, but her parents have money and money talks. When the trail leads him to the Scopuli and rebel sympathizer Holden, he realizes that this girl may be the key to everything.

Holden and Miller must thread the needle between the Earth government, the Outer Planet revolutionaries, and secretive corporations—and the odds are against them. But out in the Belt, the rules are different, and one small ship can change the fate of the universe.​', 571, 1149, 2009, 427621, (select id from series where hardcover_id = 1026), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Emperor''s Soul', 'Brandon Sanderson', '3453315243', 'https://assets.hardcover.app/book_mappings/7333103/a5cdfb9aef3a85408913dbc601b2f16801482e3c.jpeg', 'The Emperor''s Soul showcases a fascinating magic system as the clock ticks down for a condemned criminal. When Shai is caught replacing the Moon Scepter with her nearly flawless forgery, she must bargain for her life. An assassin has left the Emperor Ashravan without consciousness, a circumstance concealed only by the death of his wife. If the emperor does not emerge after his hundred-day mourning period, the rule of the Heritage Faction will be forfeit and the empire will fall into chaos. Shai is given an impossible task: to create—to Forge—a new soul for the emperor in less than one hundred days. But her soul-Forgery is considered an abomination by her captors. She is confined to a tiny, dirty chamber, guarded by a man who hates her, spied upon by politicians, and trapped behind a door sealed in her own blood. Shai''s only possible ally is the emperor''s most loyal councillor, Gaotona, who struggles to understand her true talent. Time is running out for Shai. Forging, while deducing the motivations of her captors, she needs a perfect plan to escape…', 175, null, 2012, 427626, (select id from series where hardcover_id = 996), 1.75) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Little Hatred', 'Joe Abercrombie', '0316341878', 'https://assets.hardcover.app/edition/31484700/3d645e0f6fb69d943ba8b7abdb6b518580b93f8a.jpeg', 'From New York Times bestselling author Joe Abercrombie comes the first book in a new blockbuster fantasy trilogy where the age of the machine dawns, but the age of magic refuses to die. The chimneys of industry rise over Adua and the world seethes with new opportunities. But old scores run deep as ever. On the blood-soaked borders of Angland, Leo dan Brock struggles to win fame on the battlefield, and defeat the marauding armies of Stour Nightfall. He hopes for help from the crown. But King Jezal''s son, the feckless Prince Orso, is a man who specializes in disappointments. Savine dan Glokta - socialite, investor, and daughter of the most feared man in the Union - plans to claw her way to the top of the slag-heap of society by any means necessary. But the slums boil over with a rage that all the money in the world cannot control. The age of the machine dawns, but the age of magic refuses to die. With the help of the mad hillwoman Isern-i-Phail, Rikke struggles to control the blessing, or the curse, of the Long Eye. Glimpsing the future is one thing, but with the guiding hand of the First of the Magi still pulling the strings, changing it will be quite another... For more from Joe Abercrombie, check out: The First Law TrilogyThe Blade ItselfBefore They Are HangedLast Argument of Kings Best Served ColdThe HeroesRed Country The Shattered Sea TrilogyHalf a KingHalf a WorldHalf a War', 474, null, 2019, 427662, (select id from series where hardcover_id = 2839), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Theft of Swords', 'Michael J. Sullivan', '3608960120', 'https://assets.hardcover.app/edition/30597810/d51ab4d9-ae3b-4171-ad89-b1aba0b0441d.jpg', 'There''s no ancient evil to defeat or orphan destined for greatness, just unlikely heroes and classic adventure. Royce Melborn, a skilled thief, and his mercenary partner, Hadrian Blackwater, are two enterprising rogues who end up running for their lives when they''re framed for the murder of the king. Trapped in a conspiracy that goes beyond the overthrow of a tiny kingdom, their only hope is unraveling an ancient mystery before it''s too late.', 691, null, 2008, 427664, (select id from series where hardcover_id = 5843), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Jade City', 'Fonda Lee', '1478993855', 'https://assets.hardcover.app/edition/19597711/1c216658-2a3e-4d79-876c-83218ace27f4.jpg', '"Jade is the lifeblood of the island of Kekon. It has been mined, traded, stolen, and killed for—and for centuries, honorable Green Bone warriors like the Kaul family have used it to enhance their magical abilities and defend the island from foreign invasion.

Now, the war is over and a new generation of Kauls vies for control of Kekon''s bustling capital city. They care about nothing but protecting their own, cornering the jade market, and defending the districts under their protection. Ancient tradition has little place in this rapidly changing nation.

When a powerful new drug emerges that lets anyone—even foreigners—wield jade, the simmering tension between the Kauls and the rival Ayt family erupts into open violence. The outcome of this clan war will determine the fate of all Green Bones—and of Kekon itself."-- Provided by Amazon', 540, 1147, 2016, 427666, (select id from series where hardcover_id = 1085), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Rage of Dragons', 'Evan Winter', '0356512940', 'https://assets.hardcover.app/external_data/61053625/c97600c0614cdf8806ae48b508552384b600d297.jpeg', 'Game of Thrones meets Gladiator in this debut epic fantasy about a world caught in an eternal war, and the young man who will become his people''s only hope for survival. The Omehi people have been fighting an unwinnable war for almost two hundred years. The lucky ones are born gifted. One in every two thousand women has the power to call down dragons. One in every hundred men is able to magically transform himself into a bigger, stronger, faster killing machine. Everyone else is fodder, destined to fight and die in the endless war. Young, gift-less Tau knows all this, but he has a plan of escape. He''s going to get himself injured, get out early, and settle down to marriage, children, and land. Only, he doesn''t get the chance. Those closest to him are brutally murdered, and his grief swiftly turns to anger. Fixated on revenge, Tau dedicates himself to an unthinkable path. He''ll become the greatest swordsman to ever live, a man willing to die a hundred thousand times for the chance to kill the three who betrayed him. The Rage of Dragons launches a stunning and powerful debut epic fantasy series that readers are already calling "the best fantasy book in years." The BurningThe Rage of Dragons', 528, null, 2017, 427673, (select id from series where hardcover_id = 1144), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Iron Gold', 'Pierce Brown', '1473646553', 'https://assets.hardcover.app/edition/17101586/fc907b5ac7e2ad5cbed835a3ba21ec56b342407e.jpeg', 'A decade ago Darrow was the hero of the revolution he believed would break the chains of the Society. But the Rising has shattered everything: Instead of peace and freedom, it has brought endless war. Now he must risk all he has fought for on one last desperate mission. Darrow still believes he can save everyone, but can he save himself?
                 
And throughout the worlds, other destinies entwine with Darrow’s to change his fate forever: 
                 
A young Red girl flees tragedy in her refugee camp, and achieves for herself a new life she could never have imagined.
                 
An ex-soldier broken by grief is forced to steal the most valuable thing in the galaxy—or pay with his life.
                 
And Lysander au Lune, the heir in exile to the Sovereign, wanders the stars with his mentor, Cassius, haunted by the loss of the world that Darrow transformed, and dreaming of what will rise from its ashes.
                 
Red Rising was the story of the end of one universe. Iron Gold is the story of the creation of a new one. Witness the beginning of a stunning new saga of tragedy and triumph from masterly New York Times bestselling author Pierce Brown.', 624, null, 2018, 427678, (select id from series where hardcover_id = 1033), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('1Q84', 'Haruki Murakami, Jay Rubin, Philip Gabriel', '0307476464', 'https://assets.hardcover.app/editions/28550547/2665591638920066.jpg', 'The year is 1984 and the city is Tokyo. A young woman named Aomame follows a taxi driver’s enigmatic suggestion and begins to notice puzzling discrepancies in the world around her.

She has entered, she realizes, a parallel existence, which she calls 1Q84 —“Q is for ‘question mark.’ A world that bears a question.” Meanwhile, an aspiring writer named Tengo takes on a suspect ghostwriting project. He becomes so wrapped up with the work and its unusual author that, soon, his previously placid life begins to come unraveled.', 1184, null, 2009, 427687, (select id from series where hardcover_id = 1116), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Binti', 'Nnedi Okorafor, Robin Miles', '0765385252', 'https://assets.hardcover.app/edition/18641585/c3a44b4dbdfa9d2c29a603bc1d4acc44c43dad76.jpeg', 'Collected for the first time in an omnibus edition, the Hugo- and Nebula-award-winning Binti trilogy, the story of one extraordinary girl''s journey from her home to distant Oomza University.

In her Hugo- and Nebula-winning novella, Nnedi Okorafor introduced us to Binti, a young Himba girl with the chance of a lifetime: to attend the prestigious Oomza University. Despite her family''s concerns, Binti''s talent for mathematics and her aptitude with astrolabes make her a prime candidate to undertake this interstellar journey.

But everything changes when the jellyfish-like Medusae attack Binti''s spaceship, leaving her the only survivor. Now, Binti must fend for herself, alone on a ship full of the beings who murdered her crew, with five days until she reaches her destination.

There is more to the history of the Medusae--and their war with the Khoush--than first meets the eye. If Binti is to survive this voyage and save the inhabitants of the unsuspecting planet that houses Oomza Uni, it will take all of her knowledge and talents to broker the peace.

Collected now for the first time in omnibus form, follow Binti''s story in this groundbreaking sci-fi trilogy.', 96, null, 2015, 427712, (select id from series where hardcover_id = 1012), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Stairs', 'Robert Jackson Bennett', '1470360195', 'https://assets.hardcover.app/editions/31829349/8c584b62-d277-4316-9c55-5d0db6a4ea88.jpg', 'The city of Bulikov once wielded the powers of the gods to conquer the world, enslaving and brutalizing millions — until its divine protectors were killed. Now, Bulikov’s history has been censored and erased, its citizens subjugated. But the surreal landscape of the city itself, forever altered by the thousands of miracles its guardians once worked upon it, stands as a haunting reminder of its former supremacy.

Into this broken city steps Shara Thivani. Officially, the unassuming young woman is just another junior diplomat sent by Bulikov’s oppressors. Unofficially, she is one of her country’s most accomplished spies, dispatched — along with her terrifying “secretary”, Sigrud — to solve a murder.

But as Shara pursues the killer, she starts to suspect that the beings who ruled this terrible place may not be as dead as they seem, and that Bulikov’s cruel reign may not yet be over.

A tale of vast conspiracies, dead gods, and buried histories, City of Stairs is at once a gripping spy novel and a stunningly original work of fantasy.', 465, null, 2014, 427716, (select id from series where hardcover_id = 1069), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ninth House', 'Leigh Bardugo', '1473227992', 'https://assets.hardcover.app/edition/18053577/b79e8519f00a941e86a5a5e069c9b411423ca1ec.jpeg', 'Galaxy “Alex” Stern is the most unlikely member of Yale’s freshman class. Raised in the Los Angeles hinterlands by a hippie mom, Alex dropped out of school early and into a world of shady drug-dealer boyfriends, dead-end jobs, and much, much worse. In fact, by age twenty, she is the sole survivor of a horrific, unsolved multiple homicide. Some might say she’s thrown her life away. But at her hospital bed, Alex is offered a second chance: to attend one of the world’s most prestigious universities on a full ride. What’s the catch, and why her?

Still searching for answers, Alex arrives in New Haven tasked by her mysterious benefactors with monitoring the activities of Yale’s secret societies. Their eight windowless “tombs” are the well-known haunts of the rich and powerful, from high-ranking politicos to Wall Street’s biggest players. But their occult activities are more sinister and more extraordinary than any paranoid imagination might conceive. They tamper with forbidden magic. They raise the dead. And, sometimes, they prey on the living.', 480, 982, 2019, 427736, (select id from series where hardcover_id = 1145), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Skyward', 'Brandon Sanderson', '8417347283', 'https://assets.hardcover.app/edition/30095628/5c92d3d2227ee5e279961695e463779a9e7508ed.jpeg', 'Now pilots are the heroes of what''s left of the human race, and becoming one has always been Spensa''s dream. Since she was a little girl, she has imagined soaring skyward and proving her bravery. But her fate is intertwined with that of her father''s—a pilot himself who was killed years ago when he abruptly deserted his team, leaving Spensa the daughter of a coward, her chances of attending Flight School slim to none.

No one will let Spensa forget what her father did, yet fate works in mysterious ways. Flight school might be a long shot, but she is determined to fly. And an accidental discovery in a long-forgotten cavern might just provide her with a way to claim the stars.', 510, null, 2018, 427749, (select id from series where hardcover_id = 999), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mythos: The Greek Myths Retold', 'Stephen Fry', '6064006331', 'https://assets.hardcover.app/edition/1960834/597ab304a959f37d1e4e054a5bbc5989a67f256b.jpeg', 'Here are the thrills, grandeur, and unabashed fun of the Greek myths, stylishly retold by Stephen Fry. The legendary writer, actor, and comedian breathes life into ancient tales, from Pandora''s box to Prometheus''s fire, and transforms the adventures of Zeus and the Olympians into emotionally resonant and deeply funny stories, without losing any of their original wonder. Classical artwork inspired by the myths and learned notes from the author offer rich cultural context.', 448, null, 2017, 427797, (select id from series where hardcover_id = 1122), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hitchhiker''s Guide to the Galaxy', 'Douglas Adams', '0739322206', 'https://assets.hardcover.app/edition/21490281/d9b48333ac7a69ebe0aa5573fe0ff032e6f97508.jpeg', 'Seconds before Earth is demolished to make way for a galactic freeway, Arthur Dent is plucked off the planet by his friend Ford Prefect, a researcher for the revised edition of The Hitchhiker’s Guide to the Galaxy who, for the last fifteen years, has been posing as an out-of-work actor.

Together, this dynamic pair began a journey through space aided by a galaxyful of fellow travelers: Zaphod Beeblebrox—the two-headed, three-armed ex-hippie and totally out-to-lunch president of the galaxy; Trillian (formerly Tricia McMillan), Zaphod’s girlfriend, whom Arthur tried to pick up at a cocktail party once upon a time zone; Marvin, a paranoid, brilliant, and chronically depressed robot; and Veet Voojagig, a former graduate student obsessed with the disappearance of all the ballpoint pens he’s bought over the years.

Where are these pens? Why are we born? Why do we die? For all the answers, stick your thumb to the stars!', 199, 351, 1996, 427798, (select id from series where hardcover_id = 3400), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fifth Season', 'N.K. Jemisin', '0356511936', 'https://assets.hardcover.app/editions/30436469/70e6b452-e137-4ff2-8d6f-d83a2c852070.jpg', 'It starts with the great red rift across the heart of the world''s sole continent, spewing ash that blots out the sun. It starts with death, with a murdered son and a missing daughter. It starts with betrayal, and long dormant wounds rising up to fester.

This is the Stillness, a land long familiar with catastrophe, where the power of the earth is wielded as a weapon. And where there is no mercy.

Read the first book in the critically acclaimed, three-time Hugo award-winning trilogy by NYT bestselling author N. K. Jemisin.', 468, 927, 2015, 427825, (select id from series where hardcover_id = 1001), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Time Traveler''s Wife', 'Audrey Niffenegger', '022407394X', 'https://assets.hardcover.app/edition/1104034/f16c4834b7c6848ab953fd27b4223e32a7276788.jpeg', 'Audrey Niffenegger''s innovative debut, The Time Traveler''s Wife, is the story of Clare, a beautiful art student, and Henry, an adventuresome librarian, who have known each other since Clare was six and Henry was thirty-six, and were married when Clare was twenty-three and Henry thirty-one. Impossible but true, because Henry is one of the first people diagnosed with Chrono-Displacement Disorder: periodically his genetic clock resets and he finds himself misplaced in time, pulled to moments of emotional gravity in his life, past and future. His disappearances are spontaneous, his experiences unpredictable, alternately harrowing and amusing.', 522, null, 2003, 427835, (select id from series where hardcover_id = 257341), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dark Forest', 'Cixin Liu, Joel Martinsen', '849069799X', 'https://assets.hardcover.app/edition/16274655/1df47024-edcb-43d9-bd6e-f1b48e024db5.jpg', 'This near-future trilogy is the first chance for English-speaking listeners to experience this multiple-award-winning phenomenon from Cixin Liu, China''s most beloved science fiction author.

In The Dark Forest, Earth is reeling from the revelation of a coming alien invasion - in just four centuries'' time. The aliens'' human collaborators may have been defeated, but the presence of the sophons, the subatomic particles that allow Trisolaris instant access to all human information, means that Earth''s defense plans are totally exposed to the enemy. Only the human mind remains a secret. This is the motivation for the Wallfacer Project, a daring plan that grants four men enormous resources to design secret strategies, hidden through deceit and misdirection from Earth and Trisolaris alike.

Three of the Wallfacers are influential statesmen and scientists, but the fourth is a total unknown. Luo Ji, an unambitious Chinese astronomer and sociologist, is baffled by his new status. All he knows is that he''s the one Wallfacer that Trisolaris wants dead.', 513, 1356, 2008, 427838, (select id from series where hardcover_id = 1584), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Eleventh Metal', 'Brandon Sanderson', '8374806818', 'https://assets.hardcover.app/editions/30399261/48ddf400-36a3-47c6-963e-539c8e0875a5.jpg', '"This story was written specifically for the Mistborn Adventure Game, a tabletop RPG. Please keep in mind that the story was intended to help a GM bring his players up to speed on the world if they haven’t read the books. There are a few goodies for those who want to know more about Kelsier, but this story is not meant to stand wholly on its own."
- Brandon Sanderson', 21, null, 2012, 427844, (select id from series where hardcover_id = 10001), 0.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lost Metal', 'Brandon Sanderson', '8418037741', 'https://assets.hardcover.app/external_data/60987563/93e411dc55a6e9763635437407af2309d749fc4a.jpeg', 'For years, frontier lawman turned big-city senator Waxillium Ladrian has hunted the shadowy organization the Set―with his late uncle and his sister among their leaders―since they started kidnapping people with the power of Allomancy in their bloodlines. When Detective Marasi Colms and her partner Wayne find stockpiled weapons bound for the Outer City of Bilming, this opens a new lead. Conflict between Elendel and the Outer Cities only favors the Set, and their tendrils now reach to the Elendel Senate―whose corruption Wax and Steris have sought to expose―and Bilming is even more entangled.

After Wax discovers a new type of explosive that can unleash unprecedented destruction and realizes that the Set must already have it, an immortal kandra serving Scadrial’s god, Harmony, reveals that Bilming has fallen under the influence of another god: Trell, worshipped by the Set. And Trell isn’t the only factor at play from the larger Cosmere―Marasi is recruited by offworlders with strange abilities who claim their goal is to protect Scadrial...at any cost.

Wax must choose whether to set aside his rocky relationship with God and once again become the Sword that Harmony has groomed him to be. If no one steps forward to be the hero Scadrial needs, the planet and its millions of people will come to a sudden and calamitous ruin.', 507, 1126, 2022, 427863, (select id from series where hardcover_id = 10825), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Obelisk Gate', 'N. K. Jemisin', '8417347070', 'https://assets.hardcover.app/edition/30390634/8cb652965bdca668eb7999fd142eff5ca9cd0e5e.jpeg', 'Essun''s missing daughter grows more powerful every day, and her choices may destroy the world in this "magnificent" Hugo Award winner and NYT Notable Book. (NPR) The season of endings grows darker, as civilization fades into the long cold night. Essun -- once Damaya, once Syenite, now avenger -- has found shelter, but not her daughter. Instead there is Alabaster Tenring, destroyer of the world, with a request. But if Essun does what he asks, it would seal the fate of the Stillness forever. Far away, her daughter Nassun is growing in power -- and her choices will break the world. N. K. Jemisin''s award winning trilogy continues in the sequel to The Fifth Season.', 407, null, 2016, 427868, (select id from series where hardcover_id = 1001), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Vengeful', 'V. E. Schwab', '3596705029', 'https://assets.hardcover.app/edition/30404363/81226ef1ad33c36b42fbbc3ed001e8f2c5ca6a92.jpeg', 'Magneto and Professor X. Superman and Lex Luthor. Victor Vale and Eli Ever. Sydney and Serena Clarke. Great partnerships, now soured on the vine.

But Marcella Riggins needs no one. Flush from her brush with death, she’s finally gained the control she’s always sought—and will use her new-found power to bring the city of Merit to its knees. She’ll do whatever it takes, collecting her own sidekicks, and leveraging the two most infamous EOs, Victor Vale and Eli Ever, against each other.

With Marcella''s rise, new enmities create opportunity--and the stage of Merit City will once again be set for a final, terrible reckoning.

A super-powered collision of extraordinary minds and vengeful intentions—#1 New York Times bestselling author V. E. Schwab returns with the thrilling follow-up to Vicious.', 478, null, 2018, 427871, (select id from series where hardcover_id = 2426), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dark Age', 'Pierce Brown', '9634195105', 'https://assets.hardcover.app/editions/30399300/3644584410675518.jpg', 'The #1 New York Times bestselling author of Morning Star returns to the Red Rising universe with the thrilling sequel to Iron Gold.

For a decade Darrow led a revolution against the corrupt color-coded Society. Now, outlawed by the very Republic he founded, he wages a rogue war on Mercury in hopes that he can still salvage the dream of Eo. But as he leaves death and destruction in his wake, is he still the hero who broke the chains? Or will another legend rise to take his place?

Lysander au Lune, the heir in exile, has returned to the Core. Determined to bring peace back to mankind at the edge of his sword, he must overcome or unite the treacherous Gold families of the Core and face down Darrow over the skies of war-torn Mercury.

But theirs are not the only fates hanging in the balance.

On Luna, Mustang, Sovereign of the Republic, campaigns to unite the Republic behind her husband. Beset by political and criminal enemies, can she outwit her opponents in time to save him?

Once a Red refugee, young Lyria now stands accused of treason, and her only hope is a desperate escape with unlikely new allies.

Abducted by a new threat to the Republic, Pax and Electra, the children of Darrow and Sevro, must trust in Ephraim, a thief, for their salvation—and Ephraim must look to them for his chance at redemption.

As alliances shift, break, and re-form—and power is seized, lost, and reclaimed—every player is at risk in a game of conquest that could turn the Rising into a new Dark Age.', 800, null, 2019, 427876, (select id from series where hardcover_id = 1033), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mistborn: Secret History', 'Brandon Sanderson', '6581339091', 'https://assets.hardcover.app/editions/30399304/9d841b1c-40c4-4a52-96bc-221d34dbfe7e-71ISjS3nFsL._AC_UF1000,1000_QL80_.jpg', 'Mistborn: Secret History is a companion story to the original Mistborn trilogy. As such, it contains HUGE SPOILERS for the books Mistborn (The Final Empire), The Well of Ascension, and The Hero of Ages. It also contains very minor spoilers for the book The Bands of Mourning. Mistborn: Secret History builds upon the characterization, events, and worldbuilding of the original trilogy. Reading it without that background will be a confusing process at best. In short, this isn’t the place to start your journey into Mistborn. (Though if you have read the trilogy—but it has been a while—you should be just fine, so long as you remember the characters and the general plot of the books.) Saying anything more here risks revealing too much. Even knowledge of this story’s existence is, in a way, a spoiler. There’s always another secret.', 154, null, 2016, 427881, (select id from series where hardcover_id = 10001), 3.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Stone Sky', 'N. K. Jemisin', '0316229245', 'https://assets.hardcover.app/external_data/45573946/d5b057644853864759209c4edba6334d8887fd94.jpeg', 'The Moon will soon return. Whether this heralds the destruction of humankind or something worse will depend on two women.

Essun has inherited the power of Alabaster Tenring. With it, she hopes to find her daughter Nassun and forge a world in which every orogene child can grow up safe.

For Nassun, her mother''s mastery of the Obelisk Gate comes too late. She has seen the evil of the world, and accepted what her mother will not admit: that sometimes what is corrupt cannot be cleansed, only destroyed.', 464, null, 2017, 427884, (select id from series where hardcover_id = 1001), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of Ruin', 'Adrian Tchaikovsky', '1509865837', 'https://assets.hardcover.app/external_data/47712634/3fd0816a3c15dc8faf60ed9413e9c04f0ba9305a.jpeg', 'Sequel to Children of Time.', 592, null, 2019, 427910, (select id from series where hardcover_id = 1017), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Vicious', 'V. E. Schwab', '8417312978', 'https://assets.hardcover.app/external_data/39433699/c372ce6f65b0285ccb1b8a6c6ec5207fd5093a79.jpeg', '"In their senior year, a shared research interest in adrenaline, near-death experiences, and seemingly supernatural events reveals an intriguing possibility: that under the right conditions, someone could develop extraordinary abilities. But when their thesis moves from the academic to the experimental, things go horribly wrong.

Ten years later, Victor breaks out of prison, determined to catch up to his old friend (now foe), aided by a young girl whose reserved nature obscures a stunning ability. Meanwhile, Eli is on a mission to eradicate every other super-powered person that he can find—aside from his sidekick, an enigmatic woman with an unbreakable will. Armed with terrible power on both sides, driven by the memory of betrayal and loss, the archnemesis have set a course for revenge—but who will be left alive at the end?"-- Provided by Amazon', 364, null, 2013, 427912, (select id from series where hardcover_id = 2426), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Testaments', 'Margaret Atwood', '9044641883', 'https://assets.hardcover.app/external_data/61890236/42b53df0e91682f7485d9bb84a5a52951ce6b593.jpeg', 'More than fifteen years after the events of The Handmaid’s Tale, the theocratic regime of the Republic of Gilead maintains its grip on power, but there are signs it is beginning to rot from within. At this crucial moment, the lives of three radically different women converge, with potentially explosive results.

Two have grown up as part of the first generation to come of age in the new order. The testimonies of these two young women are joined by a third voice: a woman who wields power through the ruthless accumulation and deployment of secrets.

As Atwood unfolds The Testaments, she opens up the innermost workings of Gilead as each woman is forced to come to terms with who she is, and how far she will go for what she believes.', 320, null, 2019, 427917, (select id from series where hardcover_id = 1009), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cytonic', 'Brandon Sanderson', '8418037199', 'https://assets.hardcover.app/editions/30387678/4972867059537220.jpg', 'Spensa’s life as a Defiant Defense Force pilot has been far from ordinary. She proved herself one of the best starfighters in the human enclave of Detritus and she saved her people from extermination at the hands of the Krell—the enigmatic alien species that has been holding them captive for decades. What’s more, she traveled light-years from home as an undercover spy to infiltrate the Superiority, where she learned of the galaxy beyond her small, desolate planet home.

Now, the Superiority—the governing galactic alliance bent on dominating all human life—has started a galaxy-wide war. And Spensa has seen the weapons they plan to use to end it: the Delvers. Ancient, mysterious alien forces that can wipe out entire planetary systems in an instant. Spensa knows that no matter how many pilots the DDF has, there is no defeating this predator.

Except that Spensa is Cytonic. She faced down a Delver and saw something eerily familiar about it. And maybe, if she’s able to figure out what she is, she could be more than just another pilot in this unfolding war. She could save the galaxy.

The only way she can discover what she really is, though, is to leave behind all she knows and enter the Nowhere. A place from which few ever return.

To have courage means facing fear. And this mission is terrifying.', 415, null, 2018, 427923, (select id from series where hardcover_id = 999), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dawnshard', 'Brandon Sanderson', '1803361336', 'https://assets.hardcover.app/editions/30399386/5228262192790232.jpg', 'When a ghost ship is discovered, its crew presumed dead after trying to reach the storm-shrouded island Akinah, Navani Kholin must send an expedition to make sure the island hasn’t fallen into enemy hands. Knights Radiant who fly too near find their Stormlight suddenly
drained, so the voyage must be by sea.

Shipowner Rysn Ftori lost the use of her legs but gained the companionship of Chiri-Chiri, a Stormlight-ingesting winged larkin, a species once thought extinct. Now Rysn’s pet is ill, and any hope for Chiri-Chiri’s recovery can be found only at the ancestral home of the larkin: Akinah. With the help of Lopen, the formerly one-armed Windrunner, Rysn must accept Navani’s quest and sail into the perilous storm from which no one has returned alive. If the crew cannot uncover the secrets of the hidden island city before the wrath of its ancient guardians falls upon them, the fate of Roshar and the entire Cosmere hangs in the balance.', 213, null, 2020, 427945, (select id from series where hardcover_id = 997), 3.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shift', 'Hugh Howey', '8580576822', 'https://assets.hardcover.app/edition/30683920/835c0be1f9f75d06709c61ef4c674408e5ceef7e.jpeg', '"The technology has an almost limitless capacity for good—but in the wrong hands, it could have an equally boundless capacity for evil.

In the same year, the CBS network re-aired a program about the effects of propranolol on sufferers of extreme trauma. A simple pill, it had been discovered, could wipe out the memory of any traumatic event.

At almost the same moment in humanity’s broad history, mankind discovered the means for bringing about its utter downfall, and the ability to forget it ever happened. With this godlike power at their fingertips, can humanity be trusted to create a new—and better—world? Or is it doomed to bring about its own destruction?"-- Provided by Amazon', 579, null, 2013, 427963, (select id from series where hardcover_id = 1034), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bands of Mourning', 'Brandon Sanderson', '8419260304', 'https://assets.hardcover.app/edition/20771821/40fd57bc-2a56-415b-8710-2d16878316b8.jpg', 'Three hundred years after the events of the Mistborn trilogy, Scadrial is now on the verge of modernity, with railroads to supplement the canals, electric lighting in the streets and the homes of the wealthy, and the first steel-framed skyscrapers racing for the clouds.

The Bands of Mourning are the mythical metal minds owned by the Lord Ruler, said to grant anyone who wears them the powers that the Lord Ruler had at his command. Hardly anyone thinks they really exist. A kandra researcher has returned to Elendel with images that seem to depict the Bands, as well as writings in a language that no one can read. Waxillium Ladrian is recruited to travel south to the city of New Seran to investigate. Along the way he discovers hints that point to the true goals of his uncle Edwarn and the shadowy organization known as The Set.', 455, 756, 2016, 427966, (select id from series where hardcover_id = 10825), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('All Systems Red', 'Martha Wells', '1664466843', 'https://assets.hardcover.app/edition/31608045/3c51e2999ec8dc7e94fdd569d083d45f2d46dd3b.jpeg', 'In a corporate-dominated spacefaring future, planetary missions must be approved and supplied by the Company. Exploratory teams are accompanied by Company-supplied security androids, for their own safety.

But in a society where contracts are awarded to the lowest bidder, safety isn''t a primary concern.

On a distant planet, a team of scientists are conducting surface tests, shadowed by their Company-supplied ''droid -- a self-aware SecUnit that has hacked its own governor module, and refers to itself (though never out loud) as "Murderbot." Scornful of humans, all it really wants is to be left alone long enough to figure out who it is.

But when a neighboring mission goes dark, it''s up to the scientists and their Murderbot to get to the truth.', 176, 198, 2017, 427971, (select id from series where hardcover_id = 1053), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('We Are Legion (We Are Bob)', 'Dennis E. Taylor', '1680680323', 'https://assets.hardcover.app/edition/31651212/0f91da1379dc803e1a880cc526c86661808a6680.jpeg', 'Bob Johansson has just sold his software company and is looking forward to a life of leisure. There are places to go, books to read, and movies to watch. So it''s a little unfair when he gets himself killed crossing the street. Bob wakes up a century later to find that corpsicles have been declared to be without rights, and he is now the property of the state. He has been uploaded into computer hardware and is slated to be the controlling AI in an interstellar probe looking for habitable planets. The stakes are high: no less than the first claim to entire worlds. If he declines the honor, he''ll be switched off, and they''ll try again with someone else. If he accepts, he becomes a prime target. There are at least three other countries trying to get their own probes launched first, and they play dirty. The safest place for Bob is in space, heading away from Earth at top speed. Or so he thinks. Because the universe is full of nasties, and trespassers make them mad - very mad.', 299, 596, 2016, 427983, (select id from series where hardcover_id = 1107), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('All These Worlds', 'Dennis E. Taylor', '154366203X', 'https://assets.hardcover.app/edition/28912712/76b99f70-7807-471d-ae69-8d038f4b3ca6.jpg', '"Being a sentient spaceship really should be more fun. But after spreading out through space for almost a century, Bob and his clones just can''t stay out of trouble. They''ve created enough colonies so humanity shouldn''t go extinct. But political squabbles have a bad habit of dying hard, and the Brazilian probes are still trying to take out the competition. And the Bobs have picked a fight with an older, more powerful species with a large appetite and a short temper. Still stinging from getting their collective butts kicked in their first encounter with the Others, the Bobs now face the prospect of a decisive final battle to defend Earth and its colonies. But the Bobs are less disciplined than a herd of cats, and some of the younger copies are more concerned with their own local problems than defeating the Others. Yet salvation may come from an unlikely source. A couple of eighth-generation Bobs have found something out in deep space. All it will take to save the Earth and perhaps all of humanity is for them to get it to Sol - unless the Others arrive first.“—Goodreads.', 282, null, 2017, 427990, (select id from series where hardcover_id = 1107), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('For We Are Many', 'Dennis E. Taylor', '5041684081', 'https://assets.hardcover.app/edition/30407482/2715fec8-0b67-449d-bf61-327d57ecb4b8.jpg', 'Bob Johansson didn''t believe in an afterlife, so waking up after being killed in a car accident was a shock. To add to the surprise, he is now a sentient computer and the controlling intelligence for a Von Neumann probe. Bob and his copies have been spreading out from Earth for 40 years now, looking for habitable planets. But that''s the only part of the plan that''s still in one piece. A system-wide war has killed off 99.9% of the human race; nuclear winter is slowly making the Earth uninhabitable; a radical group wants to finish the job on the remnants of humanity; the Brazilian space probes are still out there, still trying to blow up the competition; And the Bobs have discovered a spacefaring species that sees all other life as food. Bob left Earth anticipating a life of exploration and blissful solitude. Instead he''s become a sky god to a primitive native species, the only hope for getting humanity to a new home, and possibly the only thing that can prevent every living thing in the local sphere from ending up as dinner.', 320, null, 2017, 427993, (select id from series where hardcover_id = 1107), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Exhalation', 'Ted Chiang', '2207136841', 'https://assets.hardcover.app/editions/26451239/0f1473e5-daee-434b-9194-c4dae3171647.jpeg', 'From the acclaimed author of Stories of Your Life and Others - the basis for the Academy Award nominated film Arrival - comes a groundbreaking second collection of short fiction: nine stunningly original, provocative, and poignant stories. 

In ''The Merchant and the Alchemist''s Gate'', a portal through time forces a fabric-seller in ancient Baghdad to grapple with past mistakes and the temptation of second chances. In the epistolary ''Exhalation'', an alien scientist makes a shocking discovery with ramifications not just for his own people, but for all of reality. And in ''The Lifecycle of Software Objects'', a woman cares for an artificial intelligence over twenty years, elevating a faddish digital pet into what might be a true living being. Also included are two previously unpublished stories: ''Omphalos'' and ''Anxiety Is the Dizziness of Freedom''. 

In Exhalation, Ted Chiang wrestles with the oldest questions on earth - What is the nature of the universe? What does it mean to be human? - and ones that no one else has even imagined. And, each in its own way, the stories prove that complex and thoughtful science fiction can rise to new heights of beauty, meaning, and compassion.', 350, null, 2014, 428001, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heaven''s River', 'Dennis E. Taylor', '3641280168', 'https://assets.hardcover.app/edition/28338001/d9febd1bc2f6332f39edc4d42352b4e0909f884c.jpeg', 'More than a hundred years ago, Bender set out for the stars and was never heard from again. There has been no trace of him despite numerous searches by his clone-mates. Now Bob is determined to organize an expedition to learn Bender’s fate—whatever the cost.

But nothing is ever simple in the Bobiverse. Bob’s descendants are out to the 24th generation now, and replicative drift has produced individuals who can barely be considered Bobs anymore. Some of them oppose Bob’s plan; others have plans of their own. The out-of-control moots are the least of the Bobiverse’s problems.

Undaunted, Bob and his allies follow Bender’s trail. But what they discover out in deep space is so unexpected and so complex that it could either save the universe—or pose an existential threat the likes of which the Bobiverse has never faced.', 632, null, 2020, 428002, (select id from series where hardcover_id = 1107), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Midnight Library', 'Matt Haig', '1443462810', 'https://assets.hardcover.app/external_data/30206313/f95c74793bcdd7925758f16a6f6f5f423a2ec81d.jpeg', 'Somewhere out beyond the edge of the universe there is a library that contains an infinite number of books, each one the story of another reality. One tells the story of your life as it is, along with another book for the other life you could have lived if you had made a different choice at any point in your life. While we all wonder how our lives might have been, what if you had the chance to go to the library and see for yourself? Would any of these other lives truly be better?

In The Midnight Library, Matt Haig''s enchanting blockbuster novel, Nora Seed finds herself faced with this decision. Faced with the possibility of changing her life for a new one, following a different career, undoing old breakups, realizing her dreams of becoming a glaciologist; she must search within herself as she travels through the Midnight Library to decide what is truly fulfilling in life, and what makes it worth living in the first place.', 304, 529, 2020, 428018, (select id from series where hardcover_id = 235486), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Priory of the Orange Tree', 'Samantha Shannon', '1408883430', 'https://assets.hardcover.app/edition/30399925/9c192bef-3c30-44ec-9f72-455ac19ff945.jpg', 'The House of Berethnet has ruled Inys for a thousand years. Still unwed, Queen Sabran the Ninth must conceive a daughter to protect her realm from destruction – but assassins are getting closer to her door.

Ead Duryan is an outsider at court. Though she has risen to the position of lady-in-waiting, she is loyal to a hidden society of mages. Ead keeps a watchful eye on Sabran, secretly protecting her with forbidden magic.

Across the dark sea, Tané has trained to be a dragonrider since she was a child, but is forced to make a choice that could see her life unravel.

Meanwhile, the divided East and West refuse to parley, and forces of chaos are rising from their sleep.', 848, 1552, 2019, 428024, (select id from series where hardcover_id = 17180), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Once and Future Witches', 'Alix E. Harrow', '1549186426', 'https://assets.hardcover.app/edition/1269497/10645952-L.jpg', 'In 1893, there''s no such thing as witches. There used to be, in the wild, dark days before the burnings began, but now witching is nothing but tidy charms and nursery rhymes. If the modern woman wants any measure of power, she must find it at the ballot box.

But when the Eastwood sisters―James Juniper, Agnes Amaranth, and Beatrice Belladonna―join the suffragists of New Salem, they begin to pursue the forgotten words and ways that might turn the women''s movement into the witch''s movement. Stalked by shadows and sickness, hunted by forces who will not suffer a witch to vote―and perhaps not even to live―the sisters will need to delve into the oldest magics, draw new alliances, and heal the bond between them if they want to survive.

There''s no such thing as witches. But there will be.

An homage to the indomitable power and persistence of women, The Once and Future Witches reimagines stories of revolution, motherhood, and women''s suffrage—the lost ways are calling.', 528, null, 2020, 428195, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Power', 'Naomi Alderman', '0316547654', 'https://assets.hardcover.app/book_mappings/7332541/38b918d7f1fac96da74b3bfda014524f8fe17e4b.jpeg', 'In The Power, the world is a recognizable place: there''s a rich Nigerian boy who lounges around the family pool; a foster kid whose religious parents hide their true nature; an ambitious American politician; a tough London girl from a tricky family.

But then a vital new force takes root and flourishes, causing their lives to converge with devastating effect. Teenage girls now have immense physical power: they can cause agonizing pain and even death. And, with this small twist of nature, the world drastically resets. From award-winning author Naomi Alderman, The Power is speculative fiction at its most ambitious and provocative, at once taking us on a thrilling journey to an alternate reality, and exposing our own world in bold and surprising ways.', 341, null, 2016, 428277, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Court of Thorns and Roses', 'Sarah J. Maas', '3423285877', 'https://assets.hardcover.app/external_data/50291833/4af7f88042d87ecc991f2fcb53e945d8daaabcfd.jpeg', 'When nineteen-year-old huntress Feyre kills a wolf in the woods, a beast-like creature arrives to demand retribution. Dragged to a treacherous magical land she only knows about from legends, Feyre discovers that her captor is not truly a beast, but one of the lethal, immortal faeries who once ruled their world.

As she dwells on his estate, her feelings for the faerie, Tamlin, transform from icy hostility into a fiery passion that burns through every lie and warning she’s been told about the beautiful, dangerous world of the Fae. But an ancient, wicked shadow over the faerie lands is growing, and Feyre must find a way to stop it . . . or doom Tamlin—and his world—forever.', 419, 360, 2014, 428290, (select id from series where hardcover_id = 1275), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of Blood and Bone', 'Tomi Adeyemi', '1250295440', 'https://assets.hardcover.app/book_mappings/7332567/344844ff3a5ece4e108919dab49d642cf34976a7.jpeg', 'They killed my mother.
They took our magic.
They tried to bury us.

Now we rise.

Zélie Adebola remembers when the soil of Orïsha hummed with magic. Burners ignited flames, Tiders beckoned waves, and Zélie’s Reaper mother summoned forth souls.

But everything changed the night magic disappeared. Under the orders of a ruthless king, maji were killed, leaving Zélie without a mother and her people without hope.

Now Zélie has one chance to bring back magic and strike against the monarchy. With the help of a rogue princess, Zélie must outwit and outrun the crown prince, who is hell-bent on eradicating magic for good.

Danger lurks in Orïsha, where snow leoponaires prowl and vengeful spirits wait in the waters. Yet the greatest danger may be Zélie herself as she struggles to control her powers and her growing feelings for an enemy.', 544, null, 2018, 428314, (select id from series where hardcover_id = 5459), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ten Thousand Doors of January', 'Alix E. Harrow', '0316421987', 'https://assets.hardcover.app/edition/30404870/content.jpeg', 'In a sprawling mansion filled with peculiar treasures, January Scaller is a curiosity herself. As the ward of the wealthy Mr. Locke, she feels little different from the artifacts that decorate the halls: carefully maintained, largely ignored, and utterly out of place.

Then she finds a strange book. A book that carries the scent of other worlds, and tells a tale of secret doors, of love, adventure, and danger. Each page turn reveals impossible truths about the world and January discovers a story increasingly entwined with her own.

Lush and richly imagined, a tale of impossible journeys, unforgettable love, and the enduring power of stories await in Alix E. Harrow''s spellbinding debut–step inside and discover its magic. ', 384, null, 2019, 428338, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mexican Gothic', 'Silvia Moreno-Garcia', '9791028114015', 'https://assets.hardcover.app/external_data/23195265/5e715ac598fd7eb8e81f4946fc39948b7f3425c9.jpeg', 'After receiving a frantic letter from her newly-wed cousin begging for someone to save her from a mysterious doom, Noemí Taboada heads to High Place, a distant house in the Mexican countryside. She’s not sure what she will find—her cousin’s husband, a handsome Englishman, is a stranger, and Noemí knows little about the region.   
 
Noemí is also an unlikely rescuer: She’s a glamorous debutante, and her chic gowns and perfect red lipstick are more suited for cocktail parties than amateur sleuthing. But she’s also tough and smart, with an indomitable will, and she is not afraid: Not of her cousin’s new husband, who is both menacing and alluring; not of his father, the ancient patriarch who seems to be fascinated by Noemí; and not even of the house itself, which begins to invade Noemi’s dreams with visions of blood and doom.
 
Her only ally in this inhospitable abode is the family’s youngest son. Shy and gentle, he seems to want to help Noemí, but might also be hiding dark knowledge of his family’s past. For there are many secrets behind the walls of High Place. The family’s once colossal wealth and faded mining empire kept them from prying eyes, but as Noemí digs deeper she unearths stories of violence and madness. 
 
And Noemí, mesmerized by the terrifying yet seductive world of High Place, may soon find it impossible to ever leave this enigmatic house behind.', 301, null, 2020, 428353, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Every Heart a Doorway', 'Seanan McGuire', '076538387X', 'https://assets.hardcover.app/external_data/4167374/33ee6d6879f83b6b004d410d5ab78f6fafe87056.png', 'Eleanor West’s Home for Wayward Children

No Solicitations
No Visitors
No Quests

Children have always disappeared under the right conditions; slipping through the shadows under a bed or at the back of a wardrobe, tumbling down rabbit holes and into old wells, and emerging somewhere... else.

But magical lands have little need for used-up miracle children.

Nancy tumbled once, but now she’s back. The things she’s experienced... they change a person. The children under Miss West’s care understand all too well. And each of them is seeking a way back to their own fantasy world.

But Nancy’s arrival marks a change at the Home. There’s a darkness just around each corner, and when tragedy strikes, it’s up to Nancy and her new-found schoolmates to get to the heart of the matter.

No matter the cost.', 174, null, 2018, 428383, (select id from series where hardcover_id = 1638), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Order of the Phoenix', 'J.K. Rowling, Mary GrandPré', '8650510272', 'https://assets.hardcover.app/editions/29262698/2170450621507933-58613451.jpg', 'The book that took the world by storm.... In his fifth year at Hogwart''s, Harry faces challenges at every turn, from the dark threat of He-Who-Must-Not-Be- Named and the unreliability of the government of the magical world to the rise of Ron Weasley as the keeper of the Gryffindor Quidditch Team. Along the way he learns about the strength of his friends, the fierceness of his enemies, and the meaning of sacrifice.', 896, null, 2003, 428465, (select id from series where hardcover_id = 1185), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Half-Blood Prince', 'J.K. Rowling, Mary GrandPré', '3867176566', 'https://assets.hardcover.app/editions/19724535/8038369521613846-58613345.jpg', 'The war against Voldemort is not going well; even the Muggles have been affected. Dumbledore is absent from Hogwarts for long stretches of time, and the Order of the Phoenix has already suffered losses.

And yet . . . As with all wars, life goes on. Sixth-year students learn to Apparate. Teenagers flirt and fight and fall in love. Harry receives some extraordinary help in Potions from the mysterious Half-Blood Prince. And with Dumbledore''s guidance, he seeks out the full, complex story of the boy who became Lord Voldemort -- and thus finds what may be his only vulnerability.', 672, null, 2005, 428506, (select id from series where hardcover_id = 1185), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Earthlings', 'Sayaka Murata, Ginny Tapley Takemori', '1094189065', 'https://assets.hardcover.app/edition/30402962/0f377dc504f355a32c1669d8fbae415a241b4c25.jpeg', 'PLEASE NOTE THE CONTENT WARNINGS FOR THIS BOOK

As a child, Natsuki doesn’t fit into her family. Her parents favor her sister, and her best friend is a plush toy hedgehog named Piyyut who has explained to her that he has come from the planet Popinpobopia on a special quest to help her save the Earth. Each summer, Natsuki counts down the days until her family drives into the mountains of Nagano to visit her grandparents in their wooden house in the forest, a place that couldn’t be more different from her grey commuter town. One summer, her cousin Yuu confides to Natsuki that he is an extraterrestrial and that every night he searches the sky for the spaceship that might take him back to his home planet. Natsuki wonders if she might be an alien too. Back in her city home, Natsuki is scolded or ignored and even preyed upon by a young teacher at her cram school. As she grows up in a hostile, violent world, she consoles herself with memories of her time with Yuu and discovers a surprisingly potent inner power. Natsuki seems forced to fit into a society she deems a “baby factory” but even as a married woman she wonders if there is more to this world than the mundane reality everyone else seems to accept. The answers are out there, and Natsuki has the power to find them.

Dreamlike, sometimes shocking, and always strange and wonderful, Earthlings asks what it means to be happy in a stifling world, and cements Sayaka Murata’s status as a master chronicler of the outsider experience and our own uncanny universe.', 247, null, 1983, 428541, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Southern Book Club''s Guide to Slaying Vampires', 'Grady Hendrix', '8551012576', 'https://assets.hardcover.app/editions/310234/4666634139214332.jpg', '"Her husband is a workaholic, her teenage kids have their own lives, her senile mother-in-law needs constant care, and she’s always a step behind on her endless to-do list. The only thing keeping her sane is her book club, a close-knit group of Charleston women united by their love of true crime. At these meetings they’re as likely to talk about the Manson family as they are about their own families.

One evening after book club, Patricia is viciously attacked by an elderly neighbor, bringing the neighbor''s handsome nephew, James Harris, into her life. James is well traveled and well read, and he makes Patricia feel things she hasn’t felt in years. But when children on the other side of town go missing, their deaths written off by local police, Patricia has reason to believe James Harris is more of a Bundy than a Brad Pitt. The real problem? James is a monster of a different kind—and Patricia has already invited him in. 
 
Little by little, James will insinuate himself into Patricia’s life and try to take everything she took for granted—including the book club—but she won’t surrender without a fight in this blood-soaked tale of neighborly kindness gone wrong."-- Provided by Amazon', 408, null, 2020, 428542, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Inheritance Games', 'Jennifer Lynn Barnes', '1549133527', 'https://assets.hardcover.app/editions/12972012/261130687709961-91oB1gHuiIL._SL1500_.jpg', '"But her fortunes change in an instant when billionaire Tobias Hawthorne dies and leaves Avery virtually his entire fortune. The catch? Avery has no idea why—or even who Tobias Hawthorne is.

To receive her inheritance, Avery must move into sprawling, secret passage-filled Hawthorne House, where every room bears the old man''s touch—and his love of puzzles, riddles, and codes. Unfortunately for Avery, Hawthorne House is also occupied by the family that Tobias Hawthorne just dispossessed. 

This includes the four Hawthorne grandsons: dangerous, magnetic, brilliant boys who grew up with every expectation that one day, they would inherit billions. Heir apparent Grayson Hawthorne is convinced that Avery must be a conwoman, and he''s determined to take her down. His brother, Jameson, views her as their grandfather''s last hurrah: a twisted riddle, a puzzle to be solved. Caught in a world of wealth and privilege with danger around every turn, Avery will have to play the game herself just to survive."-- Provided by Amazon', 384, null, 2019, 428546, (select id from series where hardcover_id = 5593), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Winter''s Heart', 'Robert Jordan', '0312864256', 'https://assets.hardcover.app/edition/30930984/b2cc4ab8-9f02-4523-82af-524b896aefbc.png', 'Rand is on the run with Min, and in Cairhein, Cadsuane is trying to figure out where he is headed. Rand''s destination is, in fact, one she has never considered.

Mazrim Taim, leader of the Black Tower, is revealed to be a liar. But what is he up to?

Faile, with the Aiel Maidens, Bain and Chiad, and her companions, Queen Alliandre and Morgase, is prisoner of Savanna''s sept.

Perrin is desperately searching for Faile. With Elyas Machera, Berelain, the Prophet and a very mixed "army" of disparate forces, he is moving through country rife with bandits and roving Seanchan. The Forsaken are ever more present, and united, and the man called Slayer stalks Tel''aran''rhiod and the wolfdream.

In Ebou Dar, the Seanchan princess known as Daughter of the Nine Moons arrives--and Mat, who had been recuperating in the Tarasin Palace, is introduced to her. Will the marriage that has been foretold come about?

There are neither beginnings or endings to the turning of the Wheel of Time. But it is a beginning....', 624, null, 2000, 428605, (select id from series where hardcover_id = 1097), 9) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The City We Became', 'N. K. Jemisin', '1549119737', 'https://assets.hardcover.app/edition/30406256/b0cf003c-0221-4d6e-8a4a-4320f229189a.jpg', 'Three-time Hugo Award-winning and New York Times bestselling author N.K. Jemisin crafts her most incredible novel yet, a "glorious" story of culture, identity, magic, and myths in contemporary New York City.

In Manhattan, a young grad student gets off the train and realizes he doesn''t remember who he is, where he''s from, or even his own name. But he can sense the beating heart of the city, see its history, and feel its power.

In the Bronx, a Lenape gallery director discovers strange graffiti scattered throughout the city, so beautiful and powerful it''s as if the paint is literally calling to her.

In Brooklyn, a politician and mother finds she can hear the songs of her city, pulsing to the beat of her Louboutin heels.

And they''re not the only ones.

Every great city has a soul. Some are ancient as myths, and others are as new and destructive as children. New York? She''s got six.
', 448, null, 2020, 428719, (select id from series where hardcover_id = 1198), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Iron Widow', 'Xiran Jay Zhao', '8427224702', 'https://assets.hardcover.app/editions/4818537/7889481633509587.jpg', '"When 18-year-old Zetian offers herself up as a concubine-pilot, it''s to assassinate the ace male pilot responsible for her sister''s death. But when she gets her vengeance, it becomes clear that she is an Iron Widow, a rare kind of female pilot who can sacrifice males to power up Chrysalises instead.

To tame her frightening yet valuable mental strength, she is paired up with Li Shimin, the strongest male pilot in Huaxia, yet feared and ostracized for killing his father and brothers. But now that Zetian has had a taste of power, she will not cower so easily. She will take over instead, then leverage their combined strength to force her society to stop failing its women and girls. Or die trying."-- Provided by Amazon', 394, null, 2021, 428759, (select id from series where hardcover_id = 2217), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Court of Mist and Fury', 'Sarah J. Maas', '3423761822', 'https://assets.hardcover.app/edition/2090231/da5d3c1b-3786-432d-9eaf-4b2cc1731756.jpg', 'Feyre has undergone more trials than one human woman can carry in her heart.

Though she’s now been granted the powers and lifespan of the High Fae, she is haunted by her time Under the Mountain and the terrible deeds she performed to save the lives of Tamlin and his people.

As her marriage to Tamlin approaches, Feyre’s hollowness and nightmares consume her. She finds herself split into two different people: one who upholds her bargain with Rhysand, High Lord of the feared Night Court, and one who lives out her life in the Spring Court with Tamlin.

While Feyre navigates a dark web of politics, passion, and dazzling power, a greater evil looms. She might just be the key to stopping it, but only if she can harness her harrowing gifts, heal her fractured soul, and decide how she wishes to shape her future—and the future of a world in turmoil.', 626, 503, 2016, 428929, (select id from series where hardcover_id = 1275), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Assassin''s Blade', 'Sarah J. Maas', '841016373X', 'https://assets.hardcover.app/editions/31497359/3800131248933607.jpg', 'Celaena Sardothien is her kingdom’s most feared assassin. Though she works for the powerful Assassin’s Guild and its scheming master, Arobynn Hamel, she yields to no one and trusts only her fellow killer-for-hire, Sam. But when Arobynn dispatches her on missions that take her from remote islands to hostile deserts, Celaena finds herself acting independently of his wishes and questioning her own allegiance.

If she hopes to escape Arobynn’s clutches, Celaena will have to put her faith in her wits and her blade . . . knowing that if she fails, she’ll lose not just a chance at freedom but her life.

A prequel to the New York Times bestselling Throne of Glass, this collection of five novellas explores the history of this cunning assassin and her enthralling-and deadly-world.

Included in this volume:
The Assassin and the Pirate Lord
The Assassin and the Healer
The Assassin and the Desert
The Assassin and the Underworld
The Assassin and the Empire', 451, null, 2014, 428931, (select id from series where hardcover_id = 5509), 0.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Thunderhead', 'Neal Shusterman', '3733503651', 'https://assets.hardcover.app/edition/30509052/3d9c65f6ded393f08b6eefb952f756b1d22e8d0a.jpeg', 'Rowan has gone rogue, and has taken it upon himself to put the Scythedom through a trial by fire. Literally. In the year since Winter Conclave, he has gone off-grid, and has been striking out against corrupt scythes—not only in MidMerica, but across the entire continent. He is a dark folk hero now—“Scythe Lucifer”—a vigilante taking down corrupt scythes in flames.

Citra, now a junior scythe under Scythe Curie, sees the corruption and wants to help change it from the inside out, but is thwarted at every turn, and threatened by the “new order” scythes. Realizing she cannot do this alone—or even with the help of Scythe Curie and Faraday, she does the unthinkable, and risks being “deadish” so she can communicate with the Thunderhead—the only being on earth wise enough to solve the dire problems of a perfect world. But will it help solve those problems, or simply watch as perfection goes into decline?', 512, null, 2018, 428947, (select id from series where hardcover_id = 5557), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadow of the Gods', 'John Gwynne', '2493405528', 'https://assets.hardcover.app/editions/3509075/5156442469290046.jpg', 'The Shadow of the Gods begins a brand new Norse-inspired epic fantasy series from bestselling author John Gwynne, packed with action, magic and monsters.

After the gods warred and drove themselves to extinction, the cataclysm of their fall shattered the land of Vigrio.

Now a new world is rising, where power-hungry jarls feud and monsters stalk the woods and mountains. A world where the bones of the dead gods still hold great power for those brave - or desperate - enough to seek them out. Now, as whispers of war echo across the mountains and fjords, fate follows in the footsteps of three people: a huntress on a dangerous quest, a noblewoman who has rejected privilege in pursuit of battle fame, and a thrall who seeks vengeance among the famed mercenaries known as the Bloodsworn. All three will shape the fate of the world as it once more teeters on the edge of chaos.', 496, null, 2021, 428979, (select id from series where hardcover_id = 5874), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tower of Dawn', 'Sarah J. Maas', '9781408887', 'https://assets.hardcover.app/external_data/33691557/a705693b52b10c42bfeec287419fe5f3e30eef73.jpeg', 'Chaol Westfall and Nesryn Faliq have arrived in the shining city of Antica to forge an alliance with the Khagan of the Southern Continent, whose vast armies are Erilea’s last hope. But they have also come to Antica for another purpose: to seek healing at the famed Torre Cesme for the wounds Chaol received in Rifthold.

After enduring unspeakable horrors as a child at the hands of Adarlanian soldiers, Yrene Towers has no desire to help the young lord from Adarlan, let alone heal him. Yet she has sworn an oath to assist those in need, and she will honor it. But Lord Westfall carries his own dark past, and Yrene soon realizes that those shadows could engulf them both.

Chaol, Nesryn, and Yrene will have to draw on every scrap of their resilience to overcome the danger that surrounds them. But while they become entangled in the political webs of the khaganate, long-awaited answers slumber deep in the mountains, where warriors soar on legendary ruks. Answers that might offer their world a chance at survival . . . or doom them all.

The final battle looms in this sixth book in the #1 New York Times bestselling Throne of Glass series.', 664, null, 2017, 429015, (select id from series where hardcover_id = 5509), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kingdom of Ash', 'Sarah J. Maas', '8652143358', 'https://assets.hardcover.app/external_data/61236994/977131bd833b4a4de2424de518adbbb74dec2570.jpeg', 'Aelin Galathynius has vowed to save her people—but at a tremendous cost. Locked in an iron coffin by the Queen of the Fae, Aelin must draw upon her fiery will as she endures months of torture. The knowledge that yielding to Maeve will doom those she loves keeps her from breaking, but her resolve unravels with each passing day.

With Aelin captured, her friends and allies have scattered. Some bonds will grow even deeper, while others will be severed forever. But as destinies weave together at last, all must stand together if Erilea is to have any hope of salvation.

Sarah J. Maas’s #1 New York Times bestselling Throne of Glass series draws to an explosive conclusion as Aelin fights for her life, her people, and the promise of a better world.', 984, null, 2018, 429018, (select id from series where hardcover_id = 5509), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Black Sun', 'Rebecca Roanhorse', '1534437673', 'https://assets.hardcover.app/book_mappings/7332858/c7932f5d466a101153b9b0eeeccb38100363f8aa.jpeg', 'From the New York Times bestselling author of Star Wars: Resistance Reborn comes the first book in the Between Earth and Sky trilogy, inspired by the civilizations of the Pre-Columbian Americas and woven into a tale of celestial prophecies, political intrigue, and forbidden magic

 A god will return When the earth and sky converge Under the black sun In the holy city of Tova, the winter solstice is usually a time for celebration and renewal, but this year it coincides with a solar eclipse, a rare celestial event proscribed by the Sun Priest as an unbalancing of the world. Meanwhile, a ship launches from a distant city bound for Tova and set to arrive on the solstice. The captain of the ship, Xiala, is a disgraced Teek whose song can calm the waters around her as easily as it can warp a man’s mind. Her ship carries one passenger. Described as harmless, the passenger, Serapio, is a young man, blind, scarred, and cloaked in destiny. As Xiala well knows, when a man is described as harmless, he usually ends up being a villain. Crafted with unforgettable characters, Rebecca Roanhorse has created an epic adventure exploring the decadence of power amidst the weight of history and the struggle of individuals swimming against the confines of society and their broken pasts in the most original series debut of the decade.

NOMINATED FOR THE 2021 HUGO AWARDS AND THE 2020 NEBULA AWARDS FOR BEST NOVEL ', 464, null, 2020, 429027, (select id from series where hardcover_id = 2193), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Grace of Kings', 'Ken Liu', '103591624X', 'https://assets.hardcover.app/book_mappings/7333194/89d2883837d6d20cc78fd9907cefadbc572a254e.jpeg', 'Wily, charming Kuni Garu, a bandit, and stern, fearless Mata Zyndu, the son of a deposed duke, seem like polar opposites. Yet, in the uprising against the emperor, the two quickly become the best of friends after a series of adventures fighting against vast conscripted armies, silk-draped airships, and shapeshifting gods. 

Once the emperor has been overthrown, however, they each find themselves the leader of separate factions—two sides with very different ideas about how the world should be run and the meaning of justice. ', 640, null, 2015, 429039, (select id from series where hardcover_id = 1236), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Court of Silver Flames', 'Sarah J. Maas', '3423719222', 'https://assets.hardcover.app/external_data/31975800/2bbb080fea31fd0c1f457838f63210cbc3fbe3d8.jpeg', 'Nesta Archeron has always been prickly—proud, swift to anger, and slow to forgive. And ever since being forced into the Cauldron and becoming High Fae against her will, she’s struggled to find a place for herself within the strange, deadly world she inhabits. Worse, she can’t seem to move past the horrors of the war with Hybern and all she lost in it.

The one person who ignites her temper more than any other is Cassian, the battle-scarred warrior whose position in Rhysand and Feyre’s Night Court keeps him constantly in Nesta’s orbit. But her temper isn’t the only thing Cassian ignites. The fire between them is undeniable, and only burns hotter as they are forced into close quarters with each other.

Meanwhile, the treacherous human queens who returned to the Continent during the last war have forged a dangerous new alliance, threatening the fragile peace that has settled over the realms. And the key to halting them might very well rely on Cassian and Nesta facing their haunting pasts.

Against the sweeping backdrop of a world seared by war and plagued with uncertainty, Nesta and Cassian battle monsters from within and without as they search for acceptance—and healing—in each other’s arms.', 768, null, 2021, 429046, (select id from series where hardcover_id = 1275), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('One Last Stop', 'Casey McQuiston, Natalie Naudus', '1250244498', 'https://assets.hardcover.app/external_data/61388161/37387a4c918b64c64fe2dd6223ffb598f703d5bc.jpeg', 'From the New York Times bestselling author of Red, White & Royal Blue comes a new romantic comedy that will stop readers in their tracks...

For cynical twenty-three-year-old August, moving to New York City is supposed to prove her right: that things like magic and cinematic love stories don’t exist, and the only smart way to go through life is alone. She can’t imagine how waiting tables at a 24-hour pancake diner and moving in with too many weird roommates could possibly change that. And there’s certainly no chance of her subway commute being anything more than a daily trudge through boredom and electrical failures.

But then, there’s this gorgeous girl on the train.

Jane. Dazzling, charming, mysterious, impossible Jane. Jane with her rough edges and swoopy hair and soft smile, showing up in a leather jacket to save August’s day when she needed it most. August’s subway crush becomes the best part of her day, but pretty soon, she discovers there’s one big problem: Jane doesn’t just look like an old school punk rocker. She’s literally displaced in time from the 1970s, and August is going to have to use everything she tried to leave in her own past to help her. Maybe it’s time to start believing in some things, after all.

Casey McQuiston’s One Last Stop is a magical, sexy, big-hearted romance where the impossible becomes possible as August does everything in her power to save the girl lost in time.', null, null, 2021, 429051, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Caraval', 'Stephanie Garber', '8581638562', 'https://assets.hardcover.app/edition/30553803/939fdf42-8f11-4185-b0f7-c0318d268990.jpg', 'Scarlett has never left the tiny island where she and her beloved sister, Tella, live with their powerful and cruel father. Now Scarlett’s father has arranged a marriage for her, and Scarlett thinks her dreams of seeing Caraval, the far-away, once-a-year performance where the audience participates in the show, are over.

But this year, Scarlett''s long-dreamt-of invitation finally arrives. With the help of a mysterious sailor, Tella whisks Scarlett away to attend. Only, as soon as they arrive, Tella is kidnapped by Caraval’s mastermind organizer, Legend. It turns out that this season''s Caraval revolves around Tella, and whoever finds her first is the winner.

Scarlett has been told that everything that happens during Caraval is only an elaborate performance. But whether Caraval is real or not, she must find Tella before the five nights of the game are over, and her sister disappears forever.
', 416, null, 2000, 429055, (select id from series where hardcover_id = 4886), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Malice', 'John Gwynne', '031639971X', 'https://assets.hardcover.app/editions/3146515/1337347644345757.jpg', 'A black sun is rising …

Young Corban watches enviously as boys become warriors under King Brenin’s rule, learning the art of war. He yearns to wield his sword and spear to protect his king’s realm. But that day will come all too soon. Only when he loses those he loves will he learn the true price of courage.

The Banished Lands has a violent past where armies of men and giants clashed shields in battle, the earth running dark with their heartsblood. Although the giant-clans were broken in ages past, their ruined fortresses still scar the land. But now giants stir anew, the very stones weep blood and there are sightings of giant wyrms. Those who can still read the signs see a threat far greater than the ancient wars. Sorrow will darken the world, as angels and demons make it their battlefield. Then there will be a war to end all wars.

High King Aquilus summons his fellow kings to council, seeking an alliance in this time of need. Some are skeptical, fighting their own border skirmishes against pirates and giants. But prophesy indicates darkness and light will demand two champions, the Black Sun and the Bright Star. They would be wise to seek out both, for if the Black Sun gains ascendancy, mankind’s hopes and dreams will fall to dust.', 640, 1430, 2012, 429071, (select id from series where hardcover_id = 2438), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Sky and Breath', 'Sarah J. Maas, Elizabeth Evans', '1408884429', 'https://assets.hardcover.app/edition/30401166/81e0ff30-188a-467d-848b-443ecde71394.jpg', 'Bryce Quinlan and Hunt Athalar are trying to get back to normal—they may have saved Crescent City, but with so much upheaval in their lives lately, they mostly want a chance to relax. Slow down. Figure out what the future holds.

The Asteri have kept their word so far, leaving Bryce and Hunt alone. But with the rebels chipping away at the Asteri’s power, the threat the rulers pose is growing. As Bryce, Hunt, and their friends get pulled into the rebels’ plans, the choice becomes clear: stay silent while others are oppressed or fight for what’s right. And they’ve never been very good at staying silent.

In this sexy, action-packed sequel to the #1 bestseller House of Earth and Blood, Sarah J. Maas weaves a captivating story of a world about to explode—and the people who will do anything to save it.', 768, null, 2023, 429093, (select id from series where hardcover_id = 2211), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('From Blood and Ash', 'Jennifer L. Armentrout', '6063372385', 'https://assets.hardcover.app/edition/29984656/71784495ced6b827b22b949e1b86f3f947ac881e.jpeg', '"The life of the Maiden is solitary. Never to be touched. Never to be looked upon. Never to be spoken to. Never to experience pleasure. Waiting for the day of her Ascension, she would rather be with the guards, fighting back the evil that took her family, than preparing to be found worthy by the gods. But the choice has never been hers.

A Duty…

The entire kingdom’s future rests on Poppy’s shoulders, something she’s not even quite sure she wants for herself. Because a Maiden has a heart. And a soul. And longing. And when Hawke, a golden-eyed guard honor bound to ensure her Ascension, enters her life, destiny and duty become tangled with desire and need. He incites her anger, makes her question everything she believes in, and tempts her with the forbidden.

A Kingdom…

Forsaken by the gods and feared by mortals, a fallen kingdom is rising once more, determined to take back what they believe is theirs through violence and vengeance. And as the shadow of those cursed draws closer, the line between what is forbidden and what is right becomes blurred. Poppy is not only on the verge of losing her heart and being found unworthy by the gods, but also her life when every blood-soaked thread that holds her world together begins to unravel."-- Provided by Amazon', 615, null, 2020, 429099, (select id from series where hardcover_id = 1217), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Empire of the Vampire', 'Jay Kristoff, Bon Orthwick', '0008478988', 'https://assets.hardcover.app/editions/30548430/7973802927976714.jpg', 'It has been twenty-seven long years since the last sunrise.

Ever since, vampires have waged war against humanity building their eternal empire even as they tear down our own. Gabriel de León, half man, half monster, and last remaining silversaint – a sworn brother of the holy Silver Order dedicated to defending the realm from the creatures of the night – is all that stands between the world and its end.

Imprisoned by the very monsters he has vowed to destroy Gabriel is forced to tell his story – a story of legendary battles and forbidden love, of faith lost and friendships won, of the War of the Blood and the Forever King and the quest for humanity’s last remaining hope:
The Holy Grail.', 725, null, 2020, 429102, (select id from series where hardcover_id = 1215), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Crossroads of Twilight', 'Robert Jordan', '0312864590', 'https://assets.hardcover.app/edition/30499507/680bb461-388f-4c6d-8e07-0ab2b796c369.png', 'In the tenth book of The Wheel of Time from the New York Times #1 bestselling author Robert Jordan, the world and the characters stand at a crossroads, and the world approaches twilight, when the power of the Shadow grows stronger.

Fleeing from Ebou Dar with the kidnapped Daughter of the Nine Moons, whom he is fated to marry, Mat Cauthon learns that he can neither keep her nor let her go, not in safety for either of them, for both the Shadow and the might of the Seanchan Empire are in deadly pursuit.

Perrin Aybara seeks to free his wife, Faile, a captive of the Shaido, but his only hope may be an alliance with the enemy. Can he remain true to his friend Rand and to himself? For his love of Faile, Perrin is willing to sell his soul.

At Tar Valon, Egwene al''Vere, the young Amyrlin of the rebel Aes Sedai, lays siege to the heart of Aes Sedai power, but she must win quickly, with as little bloodshed as possible, for unless the Aes Sedai are reunited, only the male Asha''man will remain to defend the world against the Dark One, and nothing can hold the Asha''man themselves back from total power except the Aes Sedai and a unified White Tower.

In Andor, Elayne Trakland fights for the Lion Throne that is hers by right, but enemies and Darkfriends surround her, plotting her destruction. If she fails, Andor may fall to the Shadow, and the Dragon Reborn with it.

Rand al''Thor, the Dragon Reborn himself, has cleansed the Dark One''s taint from the male half of the True Source, and everything has changed. Yet nothing has, for only men who can channel believe that saidin is clean again, and a man who can channel is still hated and feared-even one prophesied to save the world. Now, Rand must gamble again, with himself at stake, and he cannot be sure which of his allies are really enemies.', 832, null, 2003, 429113, (select id from series where hardcover_id = 1097), 10) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Crown of Swords', 'Robert Jordan', '8382024882', 'https://assets.hardcover.app/edition/30930934/340a785c-097f-42f7-8295-a74a5e61eb6e.png', 'Incited by nobles seeking to reclaim their places of power, armies march against the Dragon Reborn. As Rand tries to restore order, he discovers a lack of loyalty even among the warrior Aiel, and still mistrusts the rebel Aes Sedai even though they swore allegiance.

But nothing can stop Rand and his Asha''man soldiers from storming the city of Illian to confront the Forsaken Sammael, and challenge him to a duel of the One Power with the winner taking the Crown of Swords...', 768, null, 1996, 429121, (select id from series where hardcover_id = 1097), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('I Have No Mouth and I Must Scream', 'Harlan Ellison', '0441363946', 'https://assets.hardcover.app/editions/816386/bed12fa2-c6f7-47cc-a33f-5c2c78b70b9c.jpg', 'This is a story set in a post-apocalyptic future. The Cold War progressed until it was too complicated for humans to manage, so the three major superpowers each developed a computer program to help run the war. When one of the programs becomes sentient it eliminates all of the human race except five persons, which it tortures for eternity.', 180, null, 1967, 429157, (select id from series where hardcover_id = 5881), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Allegiant', 'Veronica Roth', '1410467848', 'https://assets.hardcover.app/book_mappings/7332865/419210581e00bc85c6c474461ea9c0fe21275ddf.jpeg', 'The faction-based society that Tris Prior once believed in is shattered - fractured by violence and power struggles and scarred by loss and betrayal. So when offered a chance to explore the world past the limits she''s known, Tris is ready. Perhaps beyond the fence, she and Tobias will find a simple new life together, free from complicated lies, tangled loyalties, and painful memories.

But Tris''s new reality is even more alarming than the one she left behind. Old discoveries are quickly rendered meaningless. Explosive new truths change the hearts of those she loves. And once again, Tris must battle to comprehend the complexities of human nature - and of herself - while facing impossible choices about courage, allegiance, sacrifice and love.', 544, null, 2013, 429258, (select id from series where hardcover_id = 1489), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Harry Potter and the Chamber of Secrets', 'J.K. Rowling', '1338119869', 'https://assets.hardcover.app/editions/25614271/4833571895209920-lf.jpeg', 'The Dursleys were so mean and hideous that summer that all Harry Potter wanted was to get back to the Hogwarts School for Witchcraft and Wizardry. But just as he''s packing his bags, Harry receives a warning from a strange, impish creature named Dobby who says that if Harry Potter returns to Hogwarts, disaster will strike.

And strike it does. For in Harry''s second year at Hogwarts, fresh torments and horrors arise, including an outrageously stuck-up new professor, Gilderoy Lockhart, a spirit named Moaning Myrtle who haunts the girls'' bathroom, and the unwanted attentions of Ron Weasley''s younger sister, Ginny. But each of these seem minor annoyances when the real trouble begins, and someone, or something, starts turning Hogwarts students to stone. Could it be Draco Malfoy, a more poisonous rival than ever? Could it possibly be Hagrid, whose mysterious past is finally told? Or could it be the one everyone at Hogwarts most suspects: Harry Potter himself?', 332, null, 1998, 429306, (select id from series where hardcover_id = 1185), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lion, the Witch and the Wardrobe', 'C. S. Lewis, Pauline Baynes', '9991109382', 'https://assets.hardcover.app/editions/30400082/2444907221007209.jpg', 'Four adventurous siblings—Peter, Susan, Edmund, and Lucy Pevensie—step through a wardrobe door and into the land of Narnia, a land frozen in eternal winter and enslaved by the power of the White Witch. But when almost all hope is lost, the return of the Great Lion, Aslan, signals a great change . . . and a great sacrifice.

Journey into the land beyond the wardrobe! The Lion, the Witch and the Wardrobe is the second book in C. S. Lewis''s classic fantasy series, which has been captivating readers of all ages for over sixty years. This is a stand-alone novel, but if you would like journey back to Narnia, read The Horse and His Boy, the third book in The Chronicles of Narnia.', 131, null, 1950, 429356, (select id from series where hardcover_id = 5485), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Atlas Six', 'Olivie Blake', '9897775595', 'https://assets.hardcover.app/external_data/61249611/8734934643a0d2f90e70aace91004f2e17b237d9.jpeg', 'Those who earn a place among the Alexandrians will secure a life of wealth, power, and prestige beyond their wildest dreams, and each decade, only the six most uniquely talented magicians are selected to be considered for initiation. 

Enter the latest round of six: Libby Rhodes and Nico de Varona, unwilling halves of an unfathomable whole, who exert uncanny control over every element of physicality. Reina Mori, a naturalist, who can intuit the language of life itself. Parisa Kamali, a telepath who can traverse the depths of the subconscious, navigating worlds inside the human mind. Callum Nova, an empath easily mistaken for a manipulative illusionist, who can influence the intimate workings of a person’s inner self. Finally, there is Tristan Caine, who can see through illusions to a new structure of reality—an ability so rare that neither he nor his peers can fully grasp its implications. 

When the candidates are recruited by the mysterious Atlas Blakely, they are told they will have one year to qualify for initiation, during which time they will be permitted preliminary access to the Society’s archives and judged based on their contributions to various subjects of impossibility: time and space, luck and thought, life and death. Five, they are told, will be initiated. One will be eliminated.

The six potential initiates will fight to survive the next year of their lives, and if they can prove themselves to be the best among their rivals, most of them will. Most of them.', 470, null, 2020, 429366, (select id from series where hardcover_id = 5884), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wonderful Wizard of Oz', 'L. Frank Baum', '1851451358', 'https://assets.hardcover.app/edition/9104788/4c004e6c329f2297c7d5213b0b3654fb93b1cc89.jpeg', 'Over a century after its initial publication, The Wonderful Wizard of Oz is still captivating the hearts of countless readers. Come adventure with Dorothy and her three friends: the Scarecrow, the Tin Woodman, and the Cowardly Lion, as they follow the Yellow Brick Road to the Emerald City for an audience with the Great Oz, the mightiest Wizard in the land, and the only one that can return Dorothy to her home in Kansas.', 176, null, 1900, 429549, (select id from series where hardcover_id = 6023), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bad Beginning', 'Lemony Snicket', '8535900942', 'https://assets.hardcover.app/edition/30754245/f0186239a285494bb4b1f4156f76a552138f4bd2.jpeg', 'Dear Reader, The book you are holding in your hands is a short-lived edition of a book that will likely make your life shorter as well. The tale of three Baudelaire children, who find themselves thrown into an unhappy situation containing a treacherous villain with an evil scheme and bad manners, becomes more and more dreadful on each page, and everyone so foolhardy as to read it will find themselves weeping and moaning by the end of the book. This book is offered at an introductory price, but it introduces the reader to such unpleasantries as a disastrous fire, itchy clothing, a baby trapped in a cage, a plot to steal an enormous fortune, and dusty curtains. I made a solemn promise to write down these wretched tales, but you have no such promise, and if I were you I would put down a book this terrible, no matter how reasonably priced. With all due respect, Lemony Snicket', 188, null, 1999, 429795, (select id from series where hardcover_id = 1570), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lost World', 'Michael Crichton', '0034540288', 'https://assets.hardcover.app/external_data/61228040/3cfb340514f1e8e56d99c342f46332dd5f043f1a.jpeg', 'The Lost World is a 1995 techno-thriller novel written by Michael Crichton, and the sequel to his 1990 novel [Jurassic Park](https://openlibrary.org/works/OL46881W). It is his tenth novel under his own name and his twentieth overall, and it was published by Knopf. A paperback edition (ISBN 0-345-40288-X) followed in 1996. In 1997, both novels were re-published as a single book titled Michael Crichton''s Jurassic World, which is unrelated to the 2015 film of the same name.


Contains: 
[Lost World [2/2]](https://openlibrary.org/works/OL25311005W)

Also contained in:
[Michael Crichton''s Jurassic World](https://openlibrary.org/works/OL14950507W)', 393, null, 1995, 429831, (select id from series where hardcover_id = 5455), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Prince of Thorns', 'Mark Lawrence', '3453528255', 'https://assets.hardcover.app/book_mappings/7332968/cff2d0dfb9eaac7be05005be0e6e582ad36ba00c.jpeg', 'Before the thorns taught me their sharp lessons and bled weakness from me I had but one brother, and I loved him well. But those days are gone and what is left of them lies in my mother’s tomb. Now I have many brothers, quick with knife and sword, and as evil as you please. We ride this broken empire and loot its corpse. They say these are violent times, the end of days when the dead roam and monsters haunt the night. All that’s true enough, but there’s something worse out there, in the dark. Much worse.

From being a privileged royal child, raised by a loving mother, Jorg Ancrath has become the Prince of Thorns, a charming, immoral boy leading a grim band of outlaws in a series of raids and atrocities. The world is in chaos: violence is rife, nightmares everywhere. Jorg has the ability to master the living and the dead, but there is still one thing that puts a chill in him. Returning to his father’s castle Jorg must confront horrors from his childhood and carve himself a future with all hands turned against him.', 389, 537, 2011, 429870, (select id from series where hardcover_id = 5596), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hard-Boiled Wonderland and the End of the World', 'Haruki Murakami, Alfred Birnbaum', '4106006448', 'https://assets.hardcover.app/edition/12481743/13c3012a-3e61-4f5b-b0b4-5ab99bc756bf.jpg', 'Across two parallel narratives, Murakami draws readers into a mind-bending universe in which Lauren Bacall, Bob Dylan, a split-brained data processor, a deranged scientist, his shockingly undemure granddaughter, and various thugs, librarians, and subterranean monsters collide to dazzling effect. What emerges is a hyperkinetic novel that is at once hilariously funny and a deeply serious meditation on the nature and uses of the mind.', 416, null, 1985, 430705, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Glass Hotel', 'Emily St. John Mandel', '8025736490', 'https://assets.hardcover.app/edition/29271113/ea287c0553c26688cc8bf065dc78e3145506b87d.jpeg', 'Vincent is a bartender at the Hotel Caiette, a five-star lodging on the northernmost tip of Vancouver Island. On the night she meets Jonathan Alkaitis, a hooded figure scrawls a message on the lobby’s glass wall: Why don’t you swallow broken glass. High above Manhattan, a greater crime is committed: Alkaitis’s billion-dollar business is really nothing more than a game of smoke and mirrors. When his scheme collapses, it obliterates countless fortunes and devastates lives. Vincent, who had been posing as Jonathan’s wife, walks away into the night. Years later, a victim of the fraud is hired to investigate a strange occurrence: a woman has seemingly vanished from the deck of a container ship between ports of call.
 
In this captivating story of crisis and survival, Emily St. John Mandel takes readers through often hidden landscapes: campgrounds for the near-homeless, underground electronica clubs, service in luxury hotels, and life in a federal prison. Rife with unexpected beauty, The Glass Hotel is a captivating portrait of greed and guilt, love and delusion, ghosts and unintended consequences, and the infinite ways we search for meaning in our lives.', 307, null, 2020, 430721, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Persepolis Rising', 'James S. A. Corey', '0316332828', 'https://assets.hardcover.app/external_data/59806771/e888843b21c40c101519fe21fccd205b7669212f.jpeg', '"The seventh novel in James S.A. Corey''s New York Times bestselling Expanse series--now a major television series. AN OLD ENEMY RETURNS In the thousand-sun network of humanity''s expansion, new colony worlds are struggling to find their way. Every new planet lives on a knife edge between collapse and wonder, and the crew of the aging gunship Rocinante have their hands more than full keeping the fragile peace. In the vast space between Earth and Jupiter, the inner planets and belt have formed a tentative and uncertain alliance still haunted by a history of wars and prejudices. On the lost colony world of Laconia, a hidden enemy has a new vision for all of humanity and the power to enforce it. New technologies clash with old as the history of human conflict returns to its ancient patterns of war and subjugation. But human nature is not the only enemy, and the forces being unleashed have their own price. A price that will change the shape of humanity -- and of the Rocinante -- unexpectedly and forever ... Persepolis Rising is the seventh novel in the New York Times bestselling Expanse series"--', 549, null, 2017, 430938, (select id from series where hardcover_id = 1026), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Babylon''s Ashes', 'James S. A. Corey', '0356504263', 'https://assets.hardcover.app/edition/31626904/0f3a4b99d73c5433ca0a0bf95568b2eff4a1e801.jpeg', 'A revolution brewing for generations has begun in fire. It will end in blood. The Free Navy - a violent group of Belters in black-market military ships - has crippled the Earth and begun a campaign of piracy and violence among the outer planets. The colony ships heading for the thousand new worlds on the far side of the alien ring gates are easy prey, and no single navy remains strong enough to protect them. James Holden and his crew know the strengths and weaknesses of this new force better than anyone. Outnumbered and outgunned, the embattled remnants of the old political powers call on the Rocinante for a desperate mission to reach Medina Station at the heart of the gate network. But the new alliances are as flawed as the old, and the struggle for power has only just begun. As the chaos grows, an alien mystery deepens. Pirate fleets, mutiny, and betrayal may be the least of the Rocinante''s problems. And in the uncanny spaces past the ring gates, the choices of a few damaged and desperate people may determine the fate of more than just humanity', 541, null, 2016, 430940, (select id from series where hardcover_id = 1026), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Titan''s Curse', 'Rick Riordan', '0141919132', 'https://assets.hardcover.app/editions/9190622/6990422080815135-51JNWnz1zyL.jpg', 'When Percy Jackson gets an urgent distress call from his friend Grover, he immediately prepares for battle. He knows he will need his powerful demigod allies at his side, his trusty bronze sword Riptide, and… a ride from his mom.

The demigods rush to the rescue to find that Grover has made an important discovery: two powerful half-bloods whose parentage is unknown. But that’s not all that awaits them. The titan lord Kronos has devised his most treacherous plot yet, and the young heroes have just fallen prey.

They’re not the only ones in danger. An ancient monster has arisen — one rumored to be so powerful it could destroy Olympus — and Artemis, the only goddess who might know how to track it, is missing. Now Percy and his friends, along with the Hunters of Artemis, have only a week to find the kidnapped goddess and solve the mystery of the monster she was hunting. Along the way, they must face their most dangerous challenge yet: the chilling prophecy of the titan’s curse.', 352, null, 2007, 430941, (select id from series where hardcover_id = 5193), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Artemis Fowl', 'Eoin Colfer', '8501060887', 'https://assets.hardcover.app/edition/6806645/a9dd78dd-cc25-480c-9161-e8a556259c95.jpg', 'When a twelve-year-old evil genius tries to restore his family fortune by capturing a fairy and demanding a ransom in gold, the fairies fight back with magic, technology, and a particularly nasty troll.', 280, null, 2000, 430949, (select id from series where hardcover_id = 1374), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Abaddon''s Gate', 'James S. A. Corey', '0316573523', 'https://assets.hardcover.app/edition/23959925/848dec7bdddc84b912f8c46f605c04afeb7b31cc.jpeg', 'The third book in the NYT bestselling Expanse series, Abaddon''s Gate opens the door to the ruins of an alien gate network, and the crew of the Rocinante may hold the key to unlocking its secrets. Now a Prime Original series. For generations, the solar system -- Mars, the Moon, the Asteroid Belt -- was humanity''s great frontier. Until now. The alien artifact working through its program under the clouds of Venus has appeared in Uranus''s orbit, where it has built a massive gate that leads to a starless dark. Jim Holden and the crew of the Rocinante are part of a vast flotilla of scientific and military ships going out to examine the artifact. But behind the scenes, a complex plot is unfolding, with the destruction of Holden at its core. As the emissaries of the human race try to find whether the gate is an opportunity or a threat, the greatest danger is the one they brought with them. Abaddon''s Gate is a breakneck science fiction adventure following the critically acclaimed Caliban''s War. ', 576, null, 2013, 430976, (select id from series where hardcover_id = 1026), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tiamat''s Wrath', 'James S. A. Corey', '0356510360', 'https://assets.hardcover.app/book_mappings/7333086/adf69257a086b3c5493015d607fedb8add3bb9a1.jpeg', 'Thirteen hundred gates have opened to solar systems around the galaxy. But as humanity builds its interstellar empire in the alien ruins, the mysteries and threats grow deeper.

In the dead systems where gates lead to stranger things than alien planets, Elvi Okoye begins a desperate search to discover the nature of a genocide that happened before the first human beings existed, and to find weapons to fight a war against forces at the edge of the imaginable. But the price of that knowledge may be higher than she can pay.

At the heart of the empire, Teresa Duarte prepares to take on the burden of her father''s godlike ambition. The sociopathic scientist Paolo Cortázar and the Mephistophelian prisoner James Holden are only two of the dangers in a palace thick with intrigue, but Teresa has a mind of her own and secrets even her father the emperor doesn''t guess.

And throughout the wide human empire, the scattered crew of the Rocinante fights a brave rear-guard action against Duarte''s authoritarian regime. Memory of the old order falls away, and a future under Laconia''s eternal rule -- and with it, a battle that humanity can only lose - seems more and more certain. Because against the terrors that lie between worlds, courage and ambition will not be enough...', 534, null, 2019, 430977, (select id from series where hardcover_id = 1026), 8) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cibola Burn', 'James S. A. Corey', '954655636X', 'https://assets.hardcover.app/editions/30400882/6428519579048206.jpg', 'The fourth book in the NYT bestselling Expanse series, Cibola Burn sees the crew of the Rocinante on a new frontier, as the rush to colonize the new planets threatens to outrun law and order and give way to war and chaos. Now a Prime Original series. HUGO AWARD WINNER FOR BEST SERIES Enter a new frontier. ​ "An empty apartment, a missing family, that''s creepy. But this is like finding a military base with no one on it. Fighters and tanks idling on the runway with no drivers. This is bad juju. Something wrong happened here. What you should do is tell everyone to leave." The gates have opened the way to a thousand new worlds and the rush to colonize has begun. Settlers looking for a new life stream out from humanity''s home planets. Ilus, the first human colony on this vast new frontier, is being born in blood and fire. Independent settlers stand against the overwhelming power of a corporate colony ship with only their determination, courage, and the skills learned in the long wars of home. Innocent scientists are slaughtered as they try to survey a new and alien world. The struggle on Ilus threatens to spread all the way back to Earth. James Holden and the crew of his one small ship are sent to make peace in the midst of war and sense in the midst of chaos. But the more he looks at it, the more Holden thinks the mission was meant to fail. And the whispers of a dead man remind him that the great galactic civilization that once stood on this land is gone. And that something killed it. The Expanse Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath ​Leviathan Falls Memory''s Legion The Expanse Short Fiction Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers', 581, null, 2014, 431006, (select id from series where hardcover_id = 1026), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nemesis Games', 'James S. A. Corey', '1478903953', 'https://assets.hardcover.app/edition/30559887/edd95ca53432b9517c4a7a550d8a15cabafe0097.jpeg', 'The fifth book in the NYT bestselling Expanse series, Nemesis Games drives the crew of the Rocinante apart, and as they struggle to survive, the inner planets fall victim to an enemy''s catastrophic plan. Now a Prime Original series. A thousand worlds have opened, and the greatest land rush in human history has begun. As wave after wave of colonists leave, the power structures of the old solar system begin to buckle. Ships are disappearing without a trace. Private armies are being secretly formed. The sole remaining protomolecule sample is stolen. Terrorist attacks previously considered impossible bring the inner planets to their knees. The sins of the past are returning to exact a terrible price. And as a new human order is struggling to be born in blood and fire, James Holden and the crew of the Rocinante must struggle to survive and get back to the only home they have left. Nemesis Games is a breakneck science fiction adventure following the bestselling Cibola Burn. The Expanse Leviathan WakesCaliban''s WarAbaddon''s GateCibola BurnNemesis GamesBabylon''s AshesPersepolis RisingTiamat''s Wrath The Expanse Short Fiction The Butcher of Anderson StationGods of RiskThe ChurnThe Vital AbyssStrange Dogs', 532, null, 2015, 431010, (select id from series where hardcover_id = 1026), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Severance', 'Ling  Ma', '1427298610', 'https://assets.hardcover.app/book_mappings/7333047/faf9821d569a5343cb840862f257de9cf7ca8cb7.jpeg', 'Candace Chen, a millennial drone self-sequestered in a Manhattan office tower, is devoted to routine. With the recent passing of her Chinese immigrant parents, she’s had her fill of uncertainty. She’s content just to carry on: She goes to work, troubleshoots the teen-targeted Gemstone Bible, watches movies in a Greenpoint basement with her boyfriend.

So Candace barely notices when a plague of biblical proportions sweeps New York. Then Shen Fever spreads. Families flee. Companies cease operations. The subways screech to a halt. Her bosses enlist her as part of a dwindling skeleton crew with a big end-date payoff. Soon entirely alone, still unfevered, she photographs the eerie, abandoned city as the anonymous blogger NY Ghost.

Candace won’t be able to make it on her own forever, though. Enter a group of survivors, led by the power-hungry IT tech Bob. They’re traveling to a place called the Facility, where, Bob promises, they will have everything they need to start society anew. But Candace is carrying a secret she knows Bob will exploit. Should she escape from her rescuers?', 305, null, 2018, 431217, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Howl''s Moving Castle', 'Diana Wynne Jones', '0063416468', 'https://assets.hardcover.app/external_data/3712582/463194df8c826bdb85ccb460019cc7797e175116.jpeg', 'This entrancing classic fantasy novel is filled with surprises at every turn. An international bestseller, this much-loved book is the source for the Academy Award nominee for Best Animated Feature.

Sophie has the great misfortune of being the eldest of three daughters, destined to fail miserably should she ever leave home to seek her fate. But when she unwittingly attracts the ire of the Witch of the Waste, Sophie finds herself under a horrid spell that transforms her into an old lady. Her only chance at breaking it lies in the ever-moving castle in the hills: the Wizard Howl''s castle.

To untangle the enchantment, Sophie must handle the heartless Howl, strike a bargain with a fire demon, and meet the Witch of the Waste head-on. Along the way, she discovers that there''s far more to Howl—and herself—than first meets the eye.

In this giant jigsaw puzzle of a fantasy, people and things are never quite what they seem. Destinies are intertwined, identities exchanged, lovers confused. The Witch has placed a spell on Howl. Does the clue to breaking it lie in a famous poem? And what will happen to Sophie Hatter when she enters Howl''s castle?

All fans of classic fantasy books deserve the pleasure of reading those by Diana Wynne Jones, whose acclaim included the World Fantasy Award for Life Achievement. As Neil Gaiman stated, she was "quite simply the best writer for children of her generation."', 429, null, 1986, 431441, (select id from series where hardcover_id = 1381), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('She Who Became the Sun', 'Shelley Parker-Chan', '1250621801', 'https://assets.hardcover.app/external_data/25819319/5262f115bd5bee6c97582725bad9b056979c5062.jpeg', 'In 1345, China lies under harsh Mongol rule. For the starving peasants of the Central Plains, greatness is something found only in stories. When the Zhu family’s eighth-born son, Zhu Chongba, is given a fate of greatness, everyone is mystified as to how it will come to pass. The fate of nothingness received by the family’s clever and capable second daughter, on the other hand, is only as expected.

When a bandit attack orphans the two children, though, it is Zhu Chongba who succumbs to despair and dies. Desperate to escape her own fated death, the girl uses her brother''s identity to enter a monastery as a young male novice. There, propelled by her burning desire to survive, Zhu learns she is capable of doing whatever it takes, no matter how callous, to stay hidden from her fate.

After her sanctuary is destroyed for supporting the rebellion against Mongol rule, Zhu is flung back onto a collision course with her lethal fate. Her one chance of escape is to claim another future altogether: her brother''s abandoned greatness. Searching for a path to power, Zhu joins the rebellion—only to find it under existential threat from the Mongols’ most feared general: an enslaved eunuch whose beautiful female face conceals a heart as merciless as jade and ice.

For a monk with no martial skills, the front line of a war’s losing side is a bad place to be. And worse yet, Heaven is watching for any sign that Zhu might not be the true owner of the fate she has been audacious enough to claim…', 359, null, 2007, 431518, (select id from series where hardcover_id = 1334), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Space Between Worlds', 'Micaiah Johnson', '0593135067', 'https://assets.hardcover.app/external_data/48574938/d9a2e3cd740289f7a8ed05620e7385c1dfbd0090.jpeg', 'Multiverse travel is finally possible, but there’s just one catch: No one can visit a world where their counterpart is still alive. Enter Cara, whose parallel selves happen to be exceptionally good at dying—from disease, turf wars, or vendettas they couldn’t outrun. Cara’s life has been cut short on 372 worlds in total.

On this dystopian Earth, however, Cara has survived. Identified as an outlier and therefore a perfect candidate for multiverse travel, Cara is plucked from the dirt of the wastelands. Now what once made her marginalized has finally become an unexpected source of power. She has a nice apartment on the lower levels of the wealthy and walled-off Wiley City. She works—and shamelessly flirts—with her enticing yet aloof handler, Dell, as the two women collect off-world data for the Eldridge Institute. She even occasionally leaves the city to visit her family in the wastes, though she struggles to feel at home in either place. So long as she can keep her head down and avoid trouble, Cara is on a sure path to citizenship and security.

But trouble finds Cara when one of her eight remaining doppelgängers dies under mysterious circumstances, plunging her into a new world with an old secret. What she discovers will connect her past and her future in ways she could have never imagined—and reveal her own role in a plot that endangers not just her world but the entire multiverse.', 329, null, 2020, 431676, (select id from series where hardcover_id = 19142), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ghost Brigades', 'John Scalzi', '3453522680', 'https://assets.hardcover.app/book_mappings/7333178/f6f06bd109622c1cf5d1a1aa627204dd23113339.jpeg', 'The Ghost Brigades are the Special Forces of the Colonial Defense Forces, elite troops created from the DNA of the dead and turned into the perfect soldiers for the CDF''s toughest operations. They''re young, they''re fast and strong, and they''re totally without normal human qualms.

The universe is a dangerous place for humanity—and it''s about to become far more dangerous. Three races that humans have clashed with before have allied to halt our expansion into space. Their linchpin: the turncoat military scientist Charles Boutin, who knows the CDF''s biggest military secrets. To prevail, the CDF must find out why Boutin did what he did.

Jared Dirac is the only human who can provide answers -- a superhuman hybrid, created from Boutin''s DNA, Jared''s brain should be able to access Boutin''s electronic memories. But when the memory transplant appears to fail, Jared is given to the Ghost Brigades.

At first, Jared is a perfect soldier, but as Boutin''s memories slowly surface, Jared begins to intuit the reason''s for Boutin''s betrayal. As Jared desperately hunts for his "father," he must also come to grips with his own choices. Time is running out: The alliance is preparing its offensive, and some of them plan worse things than humanity''s mere military defeat…', 374, null, 2006, 431758, (select id from series where hardcover_id = 1048), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Exit Strategy', 'Martha Wells', '1664631380', 'https://assets.hardcover.app/external_data/28317885/6d679483b8d3f62ce170e56ef2b82b3997eadea9.jpeg', 'Murderbot wasn’t programmed to care. So, its decision to help the only human who ever showed it respect must be a system glitch, right?

Having traveled the width of the galaxy to unearth details of its own murderous transgressions, as well as those of the GrayCris Corporation, Murderbot is heading home to help Dr. Mensah―its former owner (protector? friend?)―submit evidence that could prevent GrayCris from destroying more colonists in its never-ending quest for profit.

But who’s going to believe a SecUnit gone rogue?', 172, 226, 2018, 432448, (select id from series where hardcover_id = 1053), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Under the Whispering Door', 'TJ Klune', '1250891876', 'https://assets.hardcover.app/book_mappings/7332906/00fc60d3d5c6fb317580c354cf9249a1b94e8838.jpeg', 'Welcome to Charon''s Crossing.
The tea is hot, the scones are fresh, and the dead are just passing through.

When a reaper comes to collect Wallace from his own funeral, Wallace begins to suspect he might be dead.

And when Hugo, the owner of a peculiar tea shop, promises to help him cross over, Wallace decides he’s definitely dead.

But even in death he’s not ready to abandon the life he barely lived, so when Wallace is given one week to cross over, he sets about living a lifetime in seven days.

Hilarious, haunting, and kind, Under the Whispering Door is an uplifting story about a life spent at the office and a death spent building a home.', 400, null, 2021, 432641, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cloud Cuckoo Land', 'Anthony Doerr', '6060971385', 'https://assets.hardcover.app/book_mappings/7332689/38e9dfefa5ef31828884a4c7146d0b2d38230eea.jpeg', 'On the New York Times bestseller list for over 20 weeks * A New York Times Notable Book * A National Book Award Finalist * Named a Best Book of the Year by Fresh Air, Time, Entertainment Weekly, Associated Press, and many more

“If you’re looking for a superb novel, look no further.” —The Washington Post

From the Pulitzer Prize–winning author of All the Light We Cannot See, comes the instant New York Times bestseller that is a “wildly inventive, a humane and uplifting book for adults that’s infused with the magic of childhood reading experiences” (The New York Times Book Review).

Among the most celebrated and beloved novels of recent times, Cloud Cuckoo Land is a triumph of imagination and compassion, a soaring story about children on the cusp of adulthood in worlds in peril, who find resilience, hope, and a book.

In the 15th century, an orphan named Anna lives inside the formidable walls of Constantinople. She learns to read, and in this ancient city, famous for its libraries, she finds what might be the last copy of a centuries-old book, the story of Aethon, who longs to be turned into a bird so that he can fly to a utopian paradise in the sky. Outside the walls is Omeir, a village boy, conscripted with his beloved oxen into the army that will lay siege to the city. His path and Anna’s will cross.

In the present day, in a library in Idaho, octogenarian Zeno rehearses children in a play adaptation of Aethon’s story, preserved against all odds through centuries. Tucked among the library shelves is a bomb, planted by a troubled, idealistic teenager, Seymour. This is another siege.

And in a not-so-distant future, on the interstellar ship Argos, Konstance is alone in a vault, copying on scraps of sacking the story of Aethon, told to her by her father.

Anna, Omeir, Seymour, Zeno, and Konstance are dreamers and outsiders whose lives are gloriously intertwined. Doerr’s dazzling imagination transports us to worlds so dramatic and immersive that we forget, for a time, our own.', 640, null, 2021, 432664, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Once Upon a Broken Heart', 'Stephanie Garber', '8582356471', 'https://assets.hardcover.app/edition/30827838/0035f28ce0daf3b66a5811a227e48c545bb3ad60.jpeg', 'For as long as she can remember, Evangeline Fox has believed in true love and happy endings . . . until she learns that the love of her life will marry another.

Desperate to stop the wedding and to heal her wounded heart, Evangeline strikes a deal with the charismatic, but wicked, Prince of Hearts. In exchange for his help, he asks for three kisses, to be given at the time and place of his choosing.

But after Evangeline’s first promised kiss, she learns that bargaining with an immortal is a dangerous game — and that the Prince of Hearts wants far more from her than she’d pledged. He has plans for Evangeline, plans that will either end in the greatest happily ever after, or the most exquisite tragedy.', 408, null, 2021, 432721, (select id from series where hardcover_id = 1411), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bird Box', 'Josh Malerman', '8380159691', 'https://assets.hardcover.app/external_data/678994/285bf4ee2eda94a33839fb452c4a47b47048c0f6.jpeg', 'Written with the narrative tension of The Road and the exquisite terror of classic Stephen King, Bird Box is a propulsive, edge-of-your-seat horror thriller, set in an apocalyptic near-future world—a masterpiece of suspense from the brilliantly imaginative Josh Malerman.

Something is out there . . .

Something terrifying that must not be seen. One glimpse and a person is driven to deadly violence. No one knows what it is or where it came from.

Five years after it began, a handful of scattered survivors remain, including Malorie and her two young children. Living in an abandoned house near the river, she has dreamed of fleeing to a place where they might be safe. Now, that the boy and girl are four, it is time to go. But the journey ahead will be terrifying: twenty miles downriver in a rowboat—blindfolded—with nothing to rely on but her wits and the children’s trained ears. One wrong choice and they will die. And something is following them. But is it man, animal, or monster?

Engulfed in darkness, surrounded by sounds both familiar and frightening, Malorie embarks on a harrowing odyssey—a trip that takes her into an unseen world and back into the past, to the companions who once saved her. Under the guidance of the stalwart Tom, a motely group of strangers banded together against the unseen terror, creating order from the chaos. But when supplies ran low, they were forced to venture outside—and confront the ultimate question: in a world gone mad, who can really be trusted?

Interweaving past and present, Josh Malerman’s breathtaking debut is a horrific and gripping snapshot of a world unraveled that will have you racing to the final page.', 400, 548, 2014, 432756, (select id from series where hardcover_id = 5913), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Knife of Dreams', 'Robert Jordan', '0312873077', 'https://assets.hardcover.app/edition/32416810/24a21bf3-ef64-4404-9681-4a134eaa44d0.png', 'The dead are walking, men die impossible deaths, and it seems as though reality itself has become unstable: All are signs of the imminence of Tarmon Gai''don, the Last Battle, when Rand al''Thor, the Dragon Reborn, must confront the Dark One as humanity''s only hope. But Rand dares not fight until he possesses all the surviving seals on the Dark One''s prison and has dealt with the Seanchan, who threaten to overrun all nations this side of the Aryth Ocean and increasingly seem too entrenched to be fought off. But his attempt to make a truce with the Seanchan is shadowed by treachery that may cost him everything. Whatever the price, though, he must have that truce. And he faces other dangers.

The winds of time have become a storm, and things that everyone believes are fixed in place forever are changing before their eyes. Even the White Tower itself is no longer a place of safety. Now Rand, Perrin and Mat, Egwene and Elayne, Nynaeve and Lan, and even Loial, must ride those storm winds, or the Dark One will triumph.', 832, null, 2005, 433103, (select id from series where hardcover_id = 1097), 11) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sirens of Titan', 'Kurt Vonnegut', '0795303068', 'https://assets.hardcover.app/edition/32794789/b072d9af-106b-4178-bffc-2f32aafa1f2c.jpg', '"His best book," Esquire wrote of Kurt Vonnegut''s 1959 novel The Sirens of Titan, adding, "he dares not only to ask the ultimate question about the meaning of life, but to answer it."  This novel fits into that aspect of the Vonnegut canon that might be classified as science fiction, a quality that once led Time to describe Vonnegut as "George Orwell, Dr. Caligari and Flash Gordon compounded into one writer ... a zany but moral mad scientist."

The Sirens of Titan was perhaps the novel that began the Vonnegut phenomenon with readers. The story is a fabulous trip, spinning madly through space and time in pursuit of nothing less than a fundamental understanding of the meaning of life. It takes place at a time in the future, when "only the human soul remained terra incognita ... the Nightmare Ages, falling roughly, give or take a few years, between the Second World War and the Third Great Depression."

The villainous and super rich Malachi Constant is offered a chance to journey into the far reaches of outer space, to eventually live on the planet Titan surrounded by three beautiful sirens. There is the proverbial "small print" with this incredible offer, which Constant turns down, setting in motion a fantastic chain of events that only Vonnegut could imagine. The result is an uproarious, freewheeling inquiry into the very reason we exist and about how we participate and matter in the scheme of the universe.

The Sirens of Titan is essential, fundamental Vonnegut, as entertaining as it is questing in search of answers to the mysteries of life.  As a work of fiction, it is a sure leap, in terms of craft, over his first novel, Player Piano. His writing here is pared down, more concentrated and graceful, richly in the service of his remarkable ideas. Vonnegut summons greatness for the first time in The Sirens of Titan, where the search for the meaning of existence looks and sounds like a kaleidoscopic dream but leaves the reader with a clear and challenging answer.', 152, null, 1959, 433144, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Last Argument of Kings', 'Joe Abercrombie', '1399604325', 'https://assets.hardcover.app/edition/15570228/e754d16a5fde232ce433aba834d3819c433e443d.jpeg', 'The King of the Union lies on his deathbed, the peasants revolt, and the nobles scramble to steal his crown. No one believes that the shadow of war is about to fall across the heart of the Union. Only the First of the Magi can save the world, but there are risks.', 642, null, 2008, 433213, (select id from series where hardcover_id = 1083), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Towers of Midnight', 'Robert Jordan, Brandon Sanderson', '0765364875', 'https://assets.hardcover.app/edition/30931095/1a24de9a-59be-4a88-932f-39df04a0af95.png', 'Now a major TV series on Prime Video The thirteenth novel in the Wheel of Time series - one of the most influential and popular fantasy epics ever published. The Last Battle has started. The seals on the Dark One''s prison are crumbling. The Pattern itself is unravelling, and the armies of the Shadow have begun to spill out of the Blight. Perrin Aybara is haunted by spectres from his past. To prevail, he must find a way to master the wolf within him or lose himself to it for ever. Meanwhile, Matrim Cauthon prepares for the most difficult challenge of his life. The Tower of Ghenjei awaits, and its secrets will reveal the fate of a friend long lost. The end draws near. It''s time to roll the dice. ''Epic in every sense'' Sunday Times ''With the Wheel of Time, Jordan has come to dominate the world that Tolkien began to reveal'' New York Times ''[The] huge ambitious Wheel of Time series helped redefine the genre'' George R. R. Martin ''A fantasy phenomenon'' SFX The Wheel of Time series: Book 1: The Eye of the World Book 2: The Great Hunt Book 3: The Dragon Reborn Book 4: The Shadow Rising Book 5: The Fires of Heaven Book 6: Lord of Chaos Book 7: A Crown of Swords Book 8: The Path of Daggers Book 9: Winter''s Heart Book 10: Crossroads of Twilight Book 11: Knife of Dreams Book 12: The Gathering Storm Book 13: Towers of Midnight Book 14: A Memory of Light Prequel: New Spring Look out for the companion book: The World of Robert Jordan''s The Wheel of Time', 976, null, 2010, 433227, (select id from series where hardcover_id = 1097), 13) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kings of Paradise', 'Richard Nell', null, 'https://assets.hardcover.app/edition/30396826/b1f6eb1c656398a3b27d65abf59b13abbdb2a868.jpeg', null, 591, 1531, null, 433544, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Unsouled', 'Will Wight', '1943363331', 'https://assets.hardcover.app/external_data/33692329/c9852033ebf1d9799fc302b212f79024a903d599.jpeg', 'Lindon is born Unsouled, the one person in his family unable to use the magical Paths of the sacred arts. He uses every trick and technique he can borrow or steal to improve his life, but it seems he will never be able to join the ranks of the truly powerful.

Until the heavens descend and show him the future.

When Lindon becomes the only one who sees the approaching doom, he must leave his homeland to save it... and to see how far he can go by walking his own Path.', 283, null, 2016, 433546, (select id from series where hardcover_id = 4968), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Legendborn', 'Tracy Deonn', '1665981997', 'https://assets.hardcover.app/external_data/25017149/d6cd690f82f406307d07e38708610a55dea07837.jpeg', 'A residential program for bright high schoolers at UNC–Chapel Hill seems like the perfect escape—until Bree witnesses a magical attack her very first night on campus.

A flying demon feeding on human energies.

A secret society of so called “Legendborn” students that hunt the creatures down.

And a mysterious teenage mage who calls himself a “Merlin” and who attempts—and fails—to wipe Bree’s memory of everything she saw.

The mage’s failure unlocks Bree’s own unique magic and a buried memory with a hidden connection: the night her mother died, another Merlin was at the hospital. Now that Bree knows there’s more to her mother’s death than what’s on the police report, she’ll do whatever it takes to find out the truth, even if that means infiltrating the Legendborn as one of their initiates.

She recruits Nick, a self-exiled Legendborn with his own grudge against the group, and their reluctant partnership pulls them deeper into the society’s secrets—and closer to each other. But when the Legendborn reveal themselves as the descendants of King Arthur’s knights and explain that a magical war is coming, Bree has to decide how far she’ll go for the truth and whether she should use her magic to take the society down—or join the fight.', 512, null, 2020, 433683, (select id from series where hardcover_id = 5604), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Queen of Nothing', 'Holly Black', '3570165299', 'https://assets.hardcover.app/editions/31501641/abe73989-5757-478f-970d-f381966b3062.jpg', 'Power is much easier to acquire than it is to hold onto. Jude learned this lesson when she released her control over the wicked king, Cardan, in exchange for immeasurable power.

Now as the exiled mortal Queen of Faerie, Jude is powerless and left reeling from Cardan''s betrayal. She bides her time determined to reclaim everything he took from her. Opportunity arrives in the form of her twin sister, Taryn, whose life is in peril.

Jude must risk venturing back into the treacherous Faerie Court, and confront her lingering feelings for Cardan, if she wishes to save her sister. But Elfhame is not as she left it. War is brewing. As Jude slips deep within enemy lines she becomes ensnared in the conflict''s bloody politics.

And, when a dormant yet powerful curse is unleashed, panic spreads throughout the land, forcing her to choose between her ambition and her humanity . . .', 321, null, 2019, 433721, (select id from series where hardcover_id = 5470), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Equal Rites', 'Terry Pratchett', '9985301773', 'https://assets.hardcover.app/edition/31705896/43f3b4336a463780ad5b1f7f1fa2e324f96a85d6.jpeg', '‘Persistently amusing, good-hearted and shrewd’ The Sunday Times The Discworld is very much like our own – if our own were to consist of a flat planet balanced on the back of four elephants which stand on the back of a giant turtle, that is . . . They say that a little knowledge is a dangerous thing, but it’s not half so bad as a lot of ignorance. The last thing the wizard Drum Billet did, before Death laid a bony hand on his shoulder, was to pass on his staff of power to the eighth son of an eighth son. Unfortunately for his colleagues in the chauvinistic (not to say misogynistic) world of magic, he failed to check that the baby in question was a son. Everybody knows that there''s no such thing as a female wizard. But now it''s gone and happened, there''s nothing much anyone can do about it. Let the battle of the sexes begin . . . ____________________ The Discworld novels can be read in any order but Equal Rites is the first book in the Witches series.', 288, null, 1987, 434155, (select id from series where hardcover_id = 1018), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Olympian', 'Rick Riordan', '8804616679', 'https://assets.hardcover.app/edition/28784756/cef2303f-e544-42d1-9e87-87effa27e1fd.jpg', 'All year the half-bloods have been preparing for battle against the Titans, knowing the odds of victory are grim. Kronos’s army is stronger than ever, and with every god and half-blood he recruits, the evil Titan’s power only grows.

While the Olympians struggle to contain the rampaging monster Typhon, Kronos begins his advance on New York City, where Mount Olympus stands virtually unguarded. Now it’s up to Percy Jackson and an army of young demigods to stop the Lord of Time. In this momentous final book in the New York Times best-selling Percy Jackson and the Olympians series, the long-awaited prophecy surrounding Percy’s sixteenth birthday unfolds. And as the battle for Western civilization rages on the streets of Manhattan, Percy faces a terrifying suspicion that he may be fighting against his own fate.', 381, null, 2009, 434268, (select id from series where hardcover_id = 5193), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Good Omens: The Nice and Accurate Prophecies of Agnes Nutter, Witch', 'Neil Gaiman, Terry Pratchett', '0552159840', 'https://assets.hardcover.app/edition/25781438/e82f7695d3fb5f077c3a997a1359c639fdf7f891.jpeg', 'Armageddon only happens once, you know. They don''t let you go around again until you get it right.

According to the Nice and Accurate Prophecies of Agnes Nutter, Witch - the world''s only totally reliable guide to the future, written in 1655, before she exploded - the world will end on a Saturday. 

Next Saturday, in fact. Just after tea...

People have been predicting the end of the world almost from its very beginning, so it''s only natural to be sceptical when a new date is set for Judgement Day.

This time though, the armies of Good and Evil really do appear to be massing. The four Bikers of the Apocalypse are hitting the road. But both the angels and demons - well, one fast-living demon and a somewhat fussy angel - would quite like the Rapture not to happen.

Oh, and someone seems to have misplaced the Antichrist...', 491, null, 1990, 434342, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Caliban''s War', 'James S. A. Corey', '3453529294', 'https://assets.hardcover.app/edition/30391596/871aff289f8526cba4147f4fd6bfbcc6b3ff576a.jpeg', 'We are not alone. On Ganymede, breadbasket of the outer planets, a Martian marine watches as her platoon is slaughtered by a monstrous supersoldier. On Earth, a high-level politician struggles to prevent interplanetary war from reigniting. And on Venus, an alien protomolecule has overrun the planet, wreaking massive, mysterious changes and threatening to spread out into the solar system. In the vast wilderness of space, James Holden and the crew of the Rocinante have been keeping the peace for the Outer Planets Alliance. When they agree to help a scientist search war-torn Ganymede for a missing child, the future of humanity rests on whether a single ship can prevent an alien invasion that may have already begun . . .', 443, 1260, 2012, 434434, (select id from series where hardcover_id = 1026), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Before They Are Hanged', 'Joe Abercrombie', '1478907827', 'https://assets.hardcover.app/external_data/24097142/fc9c943a47966922dc74e24b6af55046da8d7db4.jpeg', 'Bitter and merciless war is coming to the frozen north. It''s bloody and dangerous and the Union army, split by politics and hamstrung by incompetence, is utterly unprepared for the slaughter that''s coming. Lacking experience, training, and in some cases even weapons the army is scarcely equipped to repel Bethod''s scouts, let alone the cream of his forces. In the heat-ravaged south the Gurkish are massing to assault the city of Dagoska, defended by Inquisitor Glokta. The city is braced for the inevitable defeat and massacre to come, preparations are made to make the Gurkish pay for every inch of land . . . but a plot is festering to hand the city to its beseigers without a fight, and the previous Inquisitor of Dagoska vanished without trace. Threatened from within and without the city, Glokta needs answers, and he needs them soon. And to the east a small band of malefactors travel to the edge of the world to reclaim a device from history - a Seed, hidden for generations - with tremendous destructive potential. A device which could put a end to war, to the army of Eaters in the South, to the invasion of Shanka from the North - but only if it can be found, and only if its power can be controlled . . .', 441, null, 2007, 434460, (select id from series where hardcover_id = 1083), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('An Absolutely Remarkable Thing', 'Hank Green', '1524744131', 'https://assets.hardcover.app/editions/10829556/69fb9cc5-026f-48d9-bc9d-b8bc592e06f3.jpg', 'In Hank Green''s sweeping, cinematic debut novel, a young woman becomes an overnight celebrity before realizing she''s part of something bigger, and stranger, than anyone could have possibly imagine.

THE CARLS JUST APPEARED.

Roaming through New York City at three A.M., twenty-three-year-old April May stumbles across a giant sculpture. Delighted by its appearance and craftsmanship--like a ten-foot-tall Transformer wearing a suit of samurai armor--April and her best friend, Andy, make a video with it, which Andy uploads to YouTube. The next day, April wakes up to a viral video and a new life. News quickly spreads that there are Carls in dozens of cities around the world--from Beijing to Buenos Aires--and April, as their first documentarian, finds herself at the center of an intense international media spotlight.

Seizing the opportunity to make her mark on the world, April now has to deal with the consequences her new particular brand of fame has on her relationships, her safety, and her own identity. And all eyes are on April to figure out not just what the Carls are, but what they want from us.

Compulsively entertaining and powerfully relevant, *An Absolutely Remarkable Thing* grapples with big themes, including how the social internet is changing fame, rhetoric, and radicalization; how our culture deals with fear and uncertainty; and how vilification and adoration spring from the same dehumanization that follows a life in the public eye. The beginning of an exciting fiction career, *An Absolutely Remarkable Thing* is a bold and insightful novel of now.

This description comes from the publisher.', 343, null, 2018, 434963, (select id from series where hardcover_id = 1186), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Beartown', 'Fredrik Backman, Neil Smith', '1501160788', 'https://assets.hardcover.app/edition/30402545/788ac1cb1b32f4eebe528af5432f52241232c6a3.jpeg', 'A dazzling, profound novel about a small town with a big dream—and the price required to make it come true.

People say Beartown is finished. A tiny community nestled deep in the forest, it is slowly losing ground to the ever encroaching trees. But down by the lake stands an old ice rink, built generations ago by the working men who founded this town. And in that ice rink is the reason people in Beartown believe tomorrow will be better than today. Their junior ice hockey team is about to compete in the national semi-finals, and they actually have a shot at winning. All the hopes and dreams of this place now rest on the shoulders of a handful of teenage boys.

Being responsible for the hopes of an entire town is a heavy burden, and the semi-final match is the catalyst for a violent act that will leave a young girl traumatized and a town in turmoil. Accusations are made and, like ripples on a pond, they travel through all of Beartown, leaving no resident unaffected.

Beartown explores the hopes that bring a small community together, the secrets that tear it apart, and the courage it takes for an individual to go against the grain. In this story of a small forest town, Fredrik Backman has found the entire world', 418, null, 2014, 434983, (select id from series where hardcover_id = 1494), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Prelude to Foundation', 'Isaac Asimov', '8484500446', 'https://assets.hardcover.app/edition/31954481/9e3fe277-1783-4974-817e-bb1670f101c7.jpg', 'The first of two prequel novels in Isaac Asimov’s classic science-fiction masterpiece, the Foundation series THE EPIC SAGA THAT INSPIRED THE APPLE TV+ SERIES FOUNDATION It is the year 12,020 G.E. and Emperor Cleon I sits uneasily on the Imperial throne of Trantor. Here in the great multidomed capital of the Galactic Empire, forty billion people have created a civilization of unimaginable technological and cultural complexity. Yet Cleon knows there are those who would see him fall—those whom he would destroy if only he could read the future. Hari Seldon has come to Trantor to deliver his paper on psychohistory, his remarkable theory of prediction. Little does the young Outworld mathematician know that he has already sealed his fate and the fate of humanity. For Hari possesses the prophetic power that makes him the most wanted man in the Empire . . . the man who holds the key to the future—an apocalyptic power to be known forever after as the Foundation.', 432, null, 1988, 435146, (select id from series where hardcover_id = 5450), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fugitive Telemetry', 'Martha Wells', '1250765382', 'https://assets.hardcover.app/book_mappings/7333079/1dd5f1cc67a36104185d7cc0c9967729fc44bf18.jpeg', 'Having captured the hearts of readers across the globe (Annalee Newitz says it''s "one of the most humane portraits of a nonhuman I''ve ever read") Murderbot has also established Martha Wells as one of the great SF writers of today.

No, I didn''t kill the dead human. If I had, I wouldn''t dump the body in the station mall.

When Murderbot discovers a dead body on Preservation Station, it knows it is going to have to assist station security to determine who the body is (was), how they were killed (that should be relatively straightforward, at least), and why (because apparently that matters to a lot of people―who knew?)

Yes, the unthinkable is about to happen: Murderbot must voluntarily speak to humans!

Again!', 176, null, 2021, 435167, (select id from series where hardcover_id = 1053), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Authority', 'Jeff VanderMeer', '8806218298', 'https://assets.hardcover.app/edition/30769443/00a70122-9bb2-4674-85e9-1946f5e7ae35.jpg', '"Following the tumultuous twelfth expedition chronicled in Annihilation, the agency is in complete disarray.

John Rodriguez (aka “Control”) is the Southern Reach’s newly appointed head. Working with a distrustful but desperate team, a series of frustrating interrogations, a cache of hidden notes, and hours of profoundly troubling video footage, Control begins to penetrate the secrets of Area X. But with each discovery he must confront disturbing truths about himself and the agency he’s pledged to serve."-- Provided by Amazon', 352, null, 2014, 435907, (select id from series where hardcover_id = 1089), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ring Shout', 'P. Djèlí Clark', '6555984937', 'https://assets.hardcover.app/external_data/45047018/61933c04f62933194391f27ed5711c0178303d02.jpeg', 'IN AMERICA, DEMONS WEAR WHITE HOODS. 

In 1915, The Birth of a Nation cast a spell across America, swelling the Klan''s ranks and drinking deep from the darkest thoughts of white folk. All across the nation they ride, spreading fear and violence among the vulnerable. They plan to bring Hell to Earth. But even Ku Kluxes can die. 

Standing in their way is Maryse Boudreaux and her fellow resistance fighters, a foul-mouthed sharpshooter and a Harlem Hellfighter. Armed with blade, bullet, and bomb, they hunt their hunters and send the Klan''s demons straight to Hell. But something awful''s brewing in Macon, and the war on Hell is about to heat up. 

Can Maryse stop the Klan before it ends the world?', 176, null, 2020, 436085, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Before the Coffee Gets Cold', 'Toshikazu Kawaguchi, Geoffrey Trousselot', '5446116798', 'https://assets.hardcover.app/editions/24086923/8822767016251445-81GoE0na35L._AC_UF1000,1000_QL80_.jpg', 'In a small back alley in Tokyo, there is a café which has been serving carefully brewed coffee for more than one hundred years. Local legend says that this shop offers something else besides coffee - the chance to travel back in time. Over the course of one summer, four customers visit the cafe in the hopes of making that journey. But time travel isn''t so simple, and there are rules that must be followed. Most important, the trip can take only as long as it takes for the coffee to get cold.

Toshikazu Kawaguchi’s beautiful, moving story – translated from Japanese by Geoffrey Trousselot – explores the age-old question: what would you change if you could travel back in time?', 224, null, 2015, 436167, (select id from series where hardcover_id = 5944), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tender Is the Flesh', 'Agustina Bazterrica, Sarah Moses', '6073195206', 'https://assets.hardcover.app/edition/12261434/bd8f2cff-a620-415f-975d-69206e5c6d39.jpg', '"His wife has left him, his father is sinking into dementia, and Marcos tries not to think too hard about how he makes a living. After all, it happened so quickly. First, it was reported that an infectious virus has made all animal meat poisonous to humans. Then governments initiated the “Transition.” Now, eating human meat—“special meat”—is legal. Marcos tries to stick to numbers, consignments, processing.

Then one day he’s given a gift: a live specimen of the finest quality. Though he’s aware that any form of personal contact is forbidden on pain of death, little by little he starts to treat her like a human being. And soon, he becomes tortured by what has been lost—and what might still be saved."-- Provided by Amazon', 224, 404, 2017, 436338, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Short Stay in Hell', 'Steven L. Peck', '9791281631755', 'https://assets.hardcover.app/edition/32076091/1fb38c39-58fb-4af1-8960-5b0ff1b9cbb4.jpg', 'An ordinary family man, geologist, and Mormon, Soren Johansson has always believed he’ll be reunited with his loved ones after death in an eternal hereafter. Then, he dies. Soren wakes to find himself cast by a God he has never heard of into a Hell whose dimensions he can barely grasp: a vast library he can only escape from by finding the book that contains the story of his life.

In this haunting existential novella, author, philosopher, and ecologist Steven L. Peck explores a subversive vision of eternity, taking the reader on a journey through the afterlife of a world where everything everyone believed in turns out to be wrong.', 88, null, 2011, 436502, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The House in the Cerulean Sea', 'TJ Klune', '8328724960', 'https://assets.hardcover.app/editions/5283860/12700091-7330-4a7c-9348-6424da5ebdf0.jpg', 'Linus Baker leads a quiet, solitary life. At forty, he lives in a tiny house with a devious cat and his old records. As a Case Worker at the Department in Charge Of Magical Youth, he spends his days overseeing the well-being of children in government-sanctioned orphanages.

When Linus is unexpectedly summoned by Extremely Upper Management he''s given a curious and highly classified assignment: travel to Marsyas Island Orphanage, where six dangerous children reside: a gnome, a sprite, a wyvern, an unidentifiable green blob, a were-Pomeranian, and the Antichrist. Linus must set aside his fears and determine whether or not they’re likely to bring about the end of days.

But the children aren’t the only secret the island keeps. Their caretaker is the charming and enigmatic Arthur Parnassus, who will do anything to keep his wards safe. As Arthur and Linus grow closer, long-held secrets are exposed, and Linus must make a choice: destroy a home or watch the world burn.

An enchanting story, masterfully told, The House in the Cerulean Sea is about the profound experience of discovering an unlikely family in an unexpected place―and realizing that family is yours.', 393, 732, 2020, 436805, (select id from series where hardcover_id = 119124), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Miss Peregrine''s Home for Peculiar Children', 'Ransom Riggs', '8544102840', 'https://assets.hardcover.app/edition/26442710/40fe8f04593aa9e0803c5fbf2700964f0f22079b.jpeg', 'The #1 New York Times best-selling series. Includes an excerpt from Hollow City and an interview with author Ransom Riggs A mysterious island. An abandoned orphanage. A strange collection of very curious photographs. It all waits to be discovered in Miss Peregrine’s Home for Peculiar Children, an unforgettable novel that mixes fiction and photography in a thrilling reading experience. As our story opens, a horrific family tragedy sets sixteen-year-old Jacob journeying to a remote island off the coast of Wales, where he discovers the crumbling ruins of Miss Peregrine’s Home for Peculiar Children. As Jacob explores its abandoned bedrooms and hallways, it becomes clear that the children were more than just peculiar. They may have been dangerous. They may have been quarantined on a deserted island for good reason. And somehow—impossible though it seems—they may still be alive. A spine-tingling fantasy illustrated with haunting vintage photography, Miss Peregrine’s Home for Peculiar Children will delight adults, teens, and anyone who relishes an adventure in the shadows. “A tense, moving, and wondrously strange first novel. The photographs and text work together brilliantly to create an unforgettable story.”—John Green, New York Times best-selling author of The Fault in Our Stars “With its X-Men: First Class-meets-time-travel story line, David Lynchian imagery, and rich, eerie detail, it’s no wonder Miss Peregrine’s Home for Peculiar Children has been snapped up by Twentieth Century Fox. B+”—Entertainment Weekly “‘Peculiar’ doesn’t even begin to cover it. Riggs’ chilling, wondrous novel is already headed to the movies.”—People “You’ll love it if you want a good thriller for the summer. It’s a mystery, and you’ll race to solve it before Jacob figures it out for himself.”—Seventeen', 386, null, 2011, 438396, (select id from series where hardcover_id = 5477), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The House Of Hades', 'Rick Riordan', '0545838959', 'https://assets.hardcover.app/edition/30699199/16d990cbed5c1640971a4de96fe83d01e5c20e2c.jpeg', 'Hazel stands at a crossroads. She and the remaining crew of the Argo II could return home with the Athena Parthenos statue and try to stop Camp Half-Blood and Camp Jupiter from going to war. Or they could continue their quest to find the House of Hades, where they might be able to open the Doors of Death, rescue their friends Percy and Annabeth from Tartarus, and prevent monsters from being reincarnated in the mortal world. Whichever road they decide to take, they have to hurry, because time is running out. Gaea, the bloodthirsty Earth Mother, has set the date of August 1 for her rise to power.

Annabeth and Percy are overwhelmed. How will the two of them make it through Tartarus? Starving, thirsty, and in pain, they are barely able to stumble on in the dark and poisonous landscape that holds new horrors at every turn. They have no way of locating the Doors of Death. Even if they did, a legion of Gaea''s strongest monsters guards the Doors on the Tartarus side. Annabeth and Percy can''t exactly launch a frontal assault.

Despite the terrible odds, Hazel, Annabeth, Percy, and the other demigods of the prophecy know that there is only one choice: to attempt the impossible. Not just for themselves, but for everyone they love. Even though love can be the riskiest choice of all.

Join the demigods as they face their biggest challenges yet in The House of Hades, the hair-raising penultimate book in the best-selling Heroes of Olympus series.', 702, null, 2013, 438684, (select id from series where hardcover_id = 5670), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The City & The City', 'China Miéville', '8417347178', 'https://assets.hardcover.app/external_data/39454228/e80cfd9141e0f58880d9e85c6839deb027d2c31c.jpeg', 'When the body of a murdered woman is found in the extraordinary decaying city of Beszel, somewhere at the edge of Europe, it looks like a routine case for Inspector Tyador Borlú of the Extreme Crime Squad. But as he probes, the evidence begins to point to conspiracies far stranger, and more deadly, than anything he could have imagined. Soon his work puts him and those he cares for in danger. Borlú must travel to the only metropolis on Earth as strange as his own, across a border like no other.', 372, null, 2009, 438690, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Blood Of Olympus', 'Rick Riordan', '014133925X', 'https://assets.hardcover.app/external_data/36307168/df4e0712d73c58cda516e662286e32878e0efd19.jpeg', 'Though the Greek and Roman crewmembers of the Argo II have made progress in their many quests, they still seem no closer to defeating the earth mother, Gaea.  Her giants have risen—all of them, and they’re stronger than ever.  They must be stopped before the Feast of Spes, when Gaea plans to have two demigods sacrificed in Athens.  She needs their blood—the blood of Olympus—in order to wake.  The demigods are having more frequent visions of a terrible battle at Camp Half-Blood.  The Roman legion from Camp Jupiter, led by Octavian, is almost within striking distance.

Though it is tempting to take the Athena Parthenos to Athens to use as a secret weapon, the friends know that the huge statue belongs back on Long Island, where it might be able to stop a war between the two camps.  The Athena Parthenos will go west; the Argo II will go east.  The gods, still suffering from multiple personality disorder, are useless.  How can a handful of young demigods hope to persevere against Gaea’s army of powerful giants?  As dangerous as it is to head to Athens, they have no other option.  They have sacrificed too much already.  And if Gaea wakes, it is game over.', 544, null, 2014, 438710, (select id from series where hardcover_id = 5670), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Empire of Silence', 'Christopher Ruocchio', '8418431113', 'https://assets.hardcover.app/edition/31469029/5cc2901e-0010-4e7e-828f-27cc0082d0b1.jpg', 'It was not his war. On the wrong planet, at the right time, for the best reasons, Hadrian Marlowe started down a path that could only end in fire.

The galaxy remembers him as a hero: the man who burned every last alien Cielcin from the sky. They remember him as a monster: the devil who destroyed a sun, casually annihilating four billion human lives - even the emperor himself - against Imperial orders.

But Hadrian was not a hero. He was not a monster. He was not even a soldier. Fleeing his father and a future as a torturer, Hadrian finds himself stranded on a strange, backwater world.

Forced to fight as a gladiator and into the intrigues of a foreign planetary court, he will find himself fighting a war he did not start, for an empire he does not love, against an enemy he will never understand.', 800, null, 2018, 438798, (select id from series where hardcover_id = 6522), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Empress of Salt and Fortune', 'Nghi Vo', '1705246869', 'https://assets.hardcover.app/editions/31132532/1104709188233140.jpg', 'With the heart of an Atwood tale and the visuals of a classic Asian period drama, Nghi Vo’s The Empress of Salt and Fortune is a tightly and lushly written narrative about empire, storytelling, and the anger of women.

A young royal from the far north, is sent south for a political marriage in an empire reminiscent of imperial China. Her brothers are dead, her armies and their war mammoths long defeated and caged behind their borders. Alone and sometimes reviled, she must choose her allies carefully.

Rabbit, a handmaiden, sold by her parents to the palace for the lack of five baskets of dye, befriends the emperor’s lonely new wife and gets more than she bargained for. At once feminist high fantasy and an indictment of monarchy, this evocative debut follows the rise of the empress In-yo, who has few resources and fewer friends. She’s a northern daughter in a mage-made summer exile, but she will bend history to her will and bring down her enemies, piece by piece.', 121, null, 2020, 439353, (select id from series where hardcover_id = 2177), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Chapterhouse: Dune', 'Frank Herbert', '3453186885', 'https://assets.hardcover.app/external_data/31893320/efffef4e8411170a641893fa6b705ae35f3b7455.jpeg', 'The desert planet Arrakis, called Dune, has been destroyed. The remnants of the Old Empire have been consumed by the violent matriarchal cult known as the Honored Matres. Only one faction remains a viable threat to their total conquest--the Bene Gesserit, heirs to Dune''s power.

Under the leadership of Mother Superior Darwi Odrade, the Bene Gesserit have colonized a green world on the planet Chapterhouse and are turning it into a desert, mile by scorched mile. And once they''ve mastered breeding sandworms, the Sisterhood will control the production of the greatest commodity in the known galaxy--the spice melange. But their true weapon remains a man who has lived countless lifetimes--a man who served under the God Emperor Paul Muad''Dib....', 512, null, 1985, 439821, (select id from series where hardcover_id = 1150), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Home: Habitat, Range, Niche, Territory', 'Martha Wells', '125083886X', 'https://assets.hardcover.app/edition/27175138/88fbdf6b-bbfd-4b2a-8ca2-4a8c6d4474e4.jpg', '"Home: Habitat, Range, Niche, Territory" is a short story set in the world of Martha Well''s Murderbot Diaries. This story was originally given free to readers who pre-ordered Network Effect, the fifth entry in the series. The events of "Home: Habitat, Range, Niche, Territory" occur just after the fourth novella, Exit Strategy.', 20, null, 2021, 439935, (select id from series where hardcover_id = 1053), 4.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rivers of London', 'Ben Aaronovitch', '0575097582', 'https://assets.hardcover.app/book_mappings/7333353/b1dddfbd03770d4482ad89952c14ec63f55b178d.jpeg', 'Probationary Constable Peter Grant dreams of being a detective in London’s Metropolitan Police. Too bad his superior plans to assign him to the Case Progression Unit, where the biggest threat he’ll face is a paper cut. But Peter’s prospects change in the aftermath of a puzzling murder, when he gains exclusive information from an eyewitness who happens to be a ghost. Peter’s ability to speak with the lingering dead brings him to the attention of Detective Chief Inspector Thomas Nightingale, who investigates crimes involving magic and other manifestations of the uncanny. Now, as a wave of brutal and bizarre murders engulfs the city, Peter is plunged into a world where gods and goddesses mingle with mortals and a long-dead evil is making a comeback on a rising tide of magic.', 392, null, 2001, 440003, (select id from series where hardcover_id = 5126), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Network Effect', 'Martha Wells', '1250229863', 'https://assets.hardcover.app/book_mappings/7332803/487291b01ddc8783710e7f90bd42666090e43d9f.jpeg', 'When Murderbot''s human associates (not friends, never friends) are captured and another not-friend from its past requires urgent assistance, Murderbot must choose between inertia and drastic action.

Drastic action it is, then.', 352, 768, 2018, 440171, (select id from series where hardcover_id = 1053), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('John Dies at the End', 'David Wong', '1250035953', 'https://assets.hardcover.app/edition/5505545/ba84bac70e6d96134e471722356c92520711f9f0.jpeg', 'NOW A MAJOR MOTION PICTURE STOP. You should not have touched this book with your bare hands. NO, don’t put it down. It’s too late. They’re watching you. My name is David Wong. My best friend is John. Those names are fake. You might want to change yours. You may not want to know about the things you’ll read on these pages, about the sauce, about Korrok, about the invasion, and the future. But it’s too late. You touched the book. You’re in the game. You’re under the eye. The only defense is knowledge. You need to read this book, to the end. Even the part with the bratwurst. Why? You just have to trust me. The important thing is this: The drug is called Soy Sauce and it gives users a window into another dimension. John and I never had the chance to say no. You still do. Unfortunately for us, if you make the right choice, we’ll have a much harder time explaining how to fight off the otherworldly invasion currently threatening to enslave humanity. I’m sorry to have involved you in this, I really am. But as you read about these terrible events and the very dark epoch the world is about to enter as a result, it is crucial you keep one thing in mind: None of this is was my fault.', 480, null, 2010, 440233, (select id from series where hardcover_id = 6228), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Master of Djinn', 'P. Djèlí Clark, Mathilde Montier', '1250807735', 'https://assets.hardcover.app/editions/30405763/5335274566339030.jpg', 'Nebula, Locus, and Alex Award-winner P. Djèlí Clark goes full-length for the first time in his dazzling debut novel, A Master of Djinn.

Cairo, 1912: Though Fatma el-Sha’arawi is the youngest woman working for the Ministry of Alchemy, Enchantments and Supernatural Entities, she’s certainly not a rookie, especially after preventing the destruction of the universe last summer.

So when someone murders a secret brotherhood dedicated to one of the most famous men in history, al-Jahiz, Agent Fatma is called onto the case. Al-Jahiz transformed the world forty years ago when he opened up the veil between the magical and mundane realms, before vanishing into the unknown. This murderer claims to be al-Jahiz, returned to condemn the modern age for its social oppressions. His dangerous magical abilities instigate unrest in the streets of Cairo that threaten to spill over onto the global stage.

Alongside her Ministry colleagues and a familiar person from her past, Agent Fatma must unravel the mystery behind this imposter to restore peace to the city―or face the possibility he could be exactly who he seems…', 475, null, 2019, 440947, (select id from series where hardcover_id = 2347), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bear and the Nightingale', 'Katherine Arden', '6068811638', 'https://assets.hardcover.app/edition/30400414/4abb6f42-516f-41d7-98e7-7fc506ef36f8.jpg', 'Winter lasts most of the year at the edge of the Russian wilderness, and in the long nights, Vasilisa and her siblings love to gather by the fire to listen to their nurse’s fairy tales. Above all, Vasya loves the story of Frost, the blue-eyed winter demon. Wise Russians fear him, for he claims unwary souls, and they honor the spirits that protect their homes from evil.

Then Vasya’s widowed father brings home a new wife from Moscow. Fiercely devout, Vasya’s stepmother forbids her family from honoring their household spirits, but Vasya fears what this may bring. And indeed, misfortune begins to stalk the village.

But Vasya’s stepmother only grows harsher, determined to remake the village to her liking and to groom her rebellious stepdaughter for marriage or a convent. As the village’s defenses weaken and evil from the forest creeps nearer, Vasilisa must call upon dangerous gifts she has long concealed—to protect her family from a threat sprung to life from her nurse’s most frightening tales.', 322, null, 2017, 441036, (select id from series where hardcover_id = 5539), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blindness', 'José Saramago, Giovanni Pontiero, زهره افتخاری', '9722110217', 'https://assets.hardcover.app/edition/30402238/09d8201dca8f836ab7dc29d555a22ea063cf708c.jpeg', 'A city is hit by an epidemic of "white blindness" which spares no one. Authorities confine the blind to an empty mental hospital, but there the criminal element holds everyone captive, stealing food rations and raping women. There is one eyewitness to this nightmare who guides seven strangers—among them a boy with no mother, a girl with dark glasses, a dog of tears—through the barren streets, and the procession becomes as uncanny as the surroundings are harrowing. A magnificent parable of loss and disorientation, Blindness has swept the reading public with its powerful portrayal of our worst appetites and weaknesses—and humanity''s ultimately exhilarating spirit.', 328, null, 1995, 441615, (select id from series where hardcover_id = 5742), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('New Moon', 'Stephenie Meyer', '9895574460', 'https://assets.hardcover.app/edition/2923550/a24f25e8f8188ff8a569341c0ba983f9ba55c54a.jpeg', 'Love stories. Horror fiction. Now in a Special Trade Demy Paperback Edition. The dramatic sequel to TWILIGHT, following the tale of Bella, a teenage girl whose love for a vampire gets her into trouble. I stuck my finger under the edge of the paper and jerked it under the tape. ''Shoot, '' I muttered when the paper sliced my finger. A single drop of blood oozed from the tiny cut. It all happened very quickly then. ''No!'' Edward roared ... Dazed and disorientated, I looked up from the bright red blood pulsing out of my arm - and into the fevered eyes of the six suddenly ravenous vampires. For Bella Swan, there is one thing more important than life itself: Edward Cullen. But being in love with a vampire is more dangerous than Bella ever could have imagined. Edward has already rescued Bella from the clutches of an evil vampire but now, as their daring relationship threatens all that is near and dear to them, they realise their troubles may just be beginning.', 497, null, 2005, 444639, (select id from series where hardcover_id = 5451), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Scorch Trials', 'James Dashner', '0553538225', 'https://assets.hardcover.app/edition/8458702/f2aa440306bb7e16d84cbdbf6e72a9323c433c1c.jpeg', 'Solving the Maze was supposed to be the end.
 
Thomas was sure that escape from the Maze would mean freedom for him and the Gladers. But WICKED isn’t done yet. Phase Two has just begun. The Scorch.
 
There are no rules. There is no help. You either make it or you die.
 
The Gladers have two weeks to cross through the Scorch—the most burned-out section of the world. And WICKED has made sure to adjust the variables and stack the odds against them.
 
Friendships will be tested. Loyalties will be broken. All bets are off.
 
There are others now. Their survival depends on the Gladers’ destruction—and they’re determined to survive.', 370, null, 2010, 444942, (select id from series where hardcover_id = 1073), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Psalm for the Wild-Built', 'Becky Chambers', '1250236215', 'https://assets.hardcover.app/editions/28452919/1694923853483346.jpg', 'It’s been centuries since the robots of Panga gained self-awareness and laid down their tools; centuries since they wandered, en masse, into the wilderness, never to be seen again; centuries since they faded into myth and urban legend.

One day, the life of a tea monk is upended by the arrival of a robot, there to honor the old promise of checking in. The robot cannot go back until the question of “what do people need?” is answered.

But the answer to that question depends on who you ask, and how. They’re going to need to ask it a lot.', 147, null, 2021, 445011, (select id from series where hardcover_id = 62841), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blood of Elves', 'Andrzej Sapkowski, Danusia Stok', '5171218609', 'https://assets.hardcover.app/edition/26907699/e2b630fa-a2fb-405c-adf8-e79dad622ffc.jpg', 'For over a century, humans, dwarves, gnomes, and elves have lived together in relative peace. But times have changed, the uneasy peace is over, and now the races are fighting once again. The only good elf, it seems, is a dead elf. Geralt of Rivia, the cunning hunter known as the Witcher, has been waiting for the birth of a prophesied child. This child has the power to change the world for good--or for evil. 

As the threat of war hangs over the land and the child is hunted for her extraordinary powers, it will become Geralt''s responsibility to protect them all. And the Witcher never accepts defeat.', 368, null, 1994, 445065, (select id from series where hardcover_id = 1808), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sword of Destiny', 'Andrzej Sapkowski, David   French', '8090091253', 'https://assets.hardcover.app/edition/30538244/578e953d-dc4e-4359-87a4-48dc71d8d8e9.jpg', 'Geralt the Witcher battles monsters, demons and prejudices alike in Sword of Destiny, the second collection of adventures in Andrzej Sapkowski’s groundbreaking epic fantasy series that inspired the Netflix show and the hit video games. 

Geralt is a Witcher, a man whose magic powers, enhanced by long training and a mysterious elixir, have made him a brilliant fighter and a merciless hunter. Yet he is no ordinary killer: his targets are the multifarious monsters and vile fiends that ravage the land and attack the innocent. 

Sword of Destiny is the follow up to The Last Wish, and together they are the perfect introduction to a one of a kind fantasy world. ', 416, null, 1992, 445143, (select id from series where hardcover_id = 1808), 0.7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Black Company', 'Glen Cook', '8373010718', 'https://assets.hardcover.app/edition/32349247/92193a3d-ebca-429e-bd0d-1e916c32f24e.png', 'Some feel the Lady, newly risen from centuries in thrall, stands between humankind and evil. Some feel she is evil itself. The hard-bitten men of the Black Company take their pay and do what they must, burying their doubts with their dead. Until the prophesy: The White Rose has been reborn, somewhere, to embody good once more. There must be a way for the Black Company to find her... So begins one of the greatest fantasy epics of our age—Glen Cook''s Chronicles of the Black Company.', 288, null, 1984, 445457, (select id from series where hardcover_id = 4910), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Yellow Wallpaper', 'Charlotte Perkins Gilman', '3488013383', 'https://assets.hardcover.app/external_data/1883579/e1db42aaa41391d3f0d3ed0fd9a252cd38523c46.jpeg', 'The Yellow Wallpaper (original title: "The Yellow Wall-paper. A Story") is a 6,000-word short story by the American writer Charlotte Perkins Gilman, first published in January 1892 in The New England Magazine. It is regarded as an important early work of American feminist literature, illustrating attitudes in the 19th century toward women''s health, both physical and mental.

Presented in the first person, the story is a collection of journal entries written by a woman whose physician husband (John) has rented an old mansion for the summer. The entries display a spiral into psychosis as the writer tried to solve the mystery of the yellow wallpaper.', 24, null, 1892, 445491, (select id from series where hardcover_id = 142108), 42) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Promise of Blood', 'Brian McClellan', '0316219045', 'https://assets.hardcover.app/edition/20780968/cdc3e2a83703ee85e2130b68143242ab9210358c.jpeg', 'The Age of Kings is dead . . . and I have killed it. 

It''s a bloody business overthrowing a king...
Field Marshal Tamas'' coup against his king sent corrupt aristocrats to the guillotine and brought bread to the starving. But it also provoked war with the Nine Nations, internal attacks by royalist fanatics, and the greedy to scramble for money and power by Tamas''s supposed allies: the Church, workers unions, and mercenary forces.

Stretched to his limit, Tamas is relying heavily on his few remaining powder mages, including the embittered Taniel, a brilliant marksman who also happens to be his estranged son, and Adamat, a retired police inspector whose loyalty is being tested by blackmail.

But when gods are involved...
Now, as attacks batter them from within and without, the credulous are whispering about omens of death and destruction. Just old peasant legends about the gods waking to walk the earth. No modern educated man believes that sort of thing. But they should...

In a rich, distinctive world that mixes magic with technology, who could stand against mages that control gunpowder and bullets? PROMISE OF BLOOD is the start of a new epic fantasy series from Brian McClellan.', 545, null, 2013, 445576, (select id from series where hardcover_id = 2962), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadow of What Was Lost', 'James Islington', '1097270785', 'https://assets.hardcover.app/edition/22194126/e8ed24b048e641f5562f48be628928e2ca2f1811.jpeg', 'It has been twenty years since the god-like Augurs were overthrown and killed. Now, those who once served them the Gifted are spared only because they have accepted the rebellion''s Four Tenets, vastly limiting their own powers. As a young Gifted, Davian suffers the consequences of a war lost before he was even born. He and his friends are despised beyond their school walls for the magical power they wield: a power that Davian, despite his best efforts, cannot seem to control. Worse, with his final test approaching and the consequences of failure severe, time to overcome his struggles is fast running out. But when Davian discovers he wields the forbidden power of the Augurs, he unwittingly sets in motion a chain of events that will change his life and shake the entire world.', 608, null, 2014, 445584, (select id from series where hardcover_id = 5982), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sword of Kaigen', 'M.L. Wang', '1955252386', 'https://assets.hardcover.app/external_data/60995599/70a353439c86d10ef028a55455e6ca9afae491da.jpeg', 'Better to die sharp in war than rust through a time of peace. A mother struggling to repress her violent past, A son struggling to grasp his violent future, A father blind to the danger that threatens them all. When the winds of war reach their peninsula, will the Matsuda family have the strength to defend their empire? Or will they tear each other apart before the true enemies even reach their shores?

High on a mountainside at the edge of the Kaigenese Empire live the most powerful warriors in the world, superhumans capable of raising the sea and wielding blades of ice. For hundreds of years, the fighters of the Kusanagi Peninsula have held the Empire''s enemies at bay, earning their frozen spit of land the name ''The Sword of Kaigen.''

Born into Kusanagi''s legendary Matsuda family, fourteen-year-old Mamoru has always known his purpose: to master his family''s fighting techniques and defend his homeland. But when an outsider arrives and pulls back the curtain on Kaigen''s alleged age of peace, Mamoru realizes that he might not have much time to become the fighter he was bred to be. Worse, the empire he was bred to defend may stand on a foundation of lies.

Misaki told herself that she left the passions of her youth behind when she married into the Matsuda house. Determined to be a good housewife and mother, she hid away her sword, along with everything from her days as a fighter in a faraway country. But with her growing son asking questions about the outside world, the threat of an impending invasion looming across the sea, and her frigid husband grating on her nerves, Misaki finds the fighter in her clawing its way back to the surface.', 698, null, 2018, 445706, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('We', 'Yevgeny Zamyatin, Clarence Brown', '6074570647', 'https://assets.hardcover.app/external_data/3325437/92e99163e7daf837a0605148193417c3bed973ca.jpeg', 'Yevgeny Zamyatin''s We is a powerfully inventive vision that has influenced writers from George Orwell to Ayn Rand. In a glass-enclosed city of absolute straight lines, ruled over by the all-powerful ''Benefactor'', the citizens of the totalitarian society of OneState live out lives devoid of passion and creativity - until D-503, a mathematician who dreams in numbers, makes a discovery: he has an individual soul. Set in the twenty-sixth century AD, We is the classic dystopian novel and was the forerunner of works such as George Orwell''s 1984 and Aldous Huxley''s Brave New World. It was suppressed for many years in Russia and remains a resounding cry for individual freedom, yet is also a powerful, exciting and vivid work of science fiction. Clarence Brown''s brilliant translation is based on the corrected text of the novel, first published in Russia in 1988 after more than sixty years'' suppression.', 258, null, 1924, 445735, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Oryx and Crake', 'Margaret Atwood', '569906639X', 'https://assets.hardcover.app/editions/6878129/447340833598340.jpg', 'Oryx and Crake is at once an unforgettable love story and a compelling vision of the future. Snowman, known as Jimmy before mankind was overwhelmed by a plague, is struggling to survive in a world where he may be the last human, and mourning the loss of his best friend, Crake, and the beautiful and elusive Oryx whom they both loved. In search of answers, Snowman embarks on a journey–with the help of the green-eyed Children of Crake–through the lush wilderness that was so recently a great city, until powerful corporations took mankind on an uncontrolled genetic engineering ride. Margaret Atwood projects us into a near future that is both all too familiar and beyond our imagining.', 402, null, 2002, 445738, (select id from series where hardcover_id = 1851), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ship of Magic', 'Robin Hobb', '0606192905', 'https://assets.hardcover.app/edition/30422765/6775422ee4060c5f7c6febcfec391d9de0d82509.jpeg', 'Bingtown is a hub of exotic trade and home to a merchant nobility famed for its liveships—rare vessels carved from wizardwood, which ripens magically into sentient awareness. Now the fortunes of one of Bingtown’s oldest families rest on the newly awakened liveship Vivacia. 
 
For Althea Vestrit, the ship is her rightful legacy. For Althea’s young nephew, wrenched from his religious studies and forced to serve aboard the ship, the Vivacia is a life sentence. But the fate of the ship—and the Vestrits—may ultimately lie in the hands of an outsider: the ruthless buccaneer captain Kennit, who plans to seize power over the Pirate Isles by capturing a liveship and bending it to his will.', 896, null, 1997, 445824, (select id from series where hardcover_id = 5991), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Jade War', 'Fonda Lee', '1549126768', 'https://assets.hardcover.app/edition/9062035/a916152da1df8a991570e068d46c0e287724c713.jpeg', 'On the island of Kekon, the Kaul family is locked in a violent feud for control of the capital city and the supply of magical jade that endows trained Green Bone warriors with supernatural powers they alone have possessed for hundreds of years. Beyond Kekon''s borders, war is brewing. Powerful foreign governments and mercenary criminal kingpins alike turn their eyes on the island nation. Jade, Kekon''s most prized resource, could make them rich - or give them the edge they''d need to topple their rivals. Faced with threats on all sides, the Kaul family is forced to form new and dangerous alliances, confront enemies in the darkest streets and the tallest office towers, and put honor aside in order to do whatever it takes to ensure their own survival - and that of all the Green Bones of Kekon. Jade War is the second book of the Green Bone Saga, an epic trilogy about family, honour and those who live and die by the ancient laws of blood and jade.', 624, null, 2019, 445841, (select id from series where hardcover_id = 1085), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Journey to the Center of the Earth', 'Jules Verne', '1406554111', 'https://assets.hardcover.app/external_data/4206721/2c207b701731d247ba9e037f40a1edb106169425.jpeg', 'An adventurous geology professor chances upon a manuscript in which a 16th-century explorer claims to have found a route to the earth''s core. Professor Lidenbrock can''t resist the opportunity to investigate, and with his nephew Axel, he sets off across Iceland in the company of Hans Bjelke, a native guide.

The expedition descends into an extinct volcano toward a sunless sea, where they encounter a subterranean world of luminous rocks, antediluvian forests, and fantastic marine life — a living past that holds the secrets to the origins of human existence.', 191, null, 1864, 445859, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Reaper Man', 'Terry Pratchett', '0575066563', 'https://assets.hardcover.app/editions/28714778/4f05ae68-a753-4195-a614-292f9912cf59.jpg', 'They say there are only two things you can count on ...But that was before DEATH started pondering the existential. Of course, the last thing anyone needs is a squeamish Grim Reaper and soon his Discworld bosses have sent him off with best wishes and a well-earned gold watch. Now DEATH is having the time of his life, finding greener pastures where he can put his scythe to a whole new use.
But like every cutback in an important public service, DEATH''s demise soon leads to chaos and unrest -- literally, for those whose time was supposed to be up, like Windle Poons. The oldest geezer in the entire faculty of Unseen University -- home of magic, wizardry, and big dinners -- Windle was looking forward to a wonderful afterlife, not this boring been-there-done-that routine. To get the fresh start he deserves, Windle and the rest of Ankh-Morpork''s undead and underemployed set off to find DEATH and save the world for the living (and everybody else, of course).', 305, null, 1991, 446078, (select id from series where hardcover_id = 1018), 11) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Men at Arms', 'Terry Pratchett', '0753122561', 'https://assets.hardcover.app/edition/31582374/88771cf4b1e616acba40d01f1019e7436746395a.jpeg', 'Second book of the original and best CITY WATCH series, now reinterpreted in BBC''s The Watch ''Funny, wise and mock heroic . . . The funniest and best crafted book I have read all year'' Sunday Express The Discworld is very much like our own - if our own were to consist of a flat planet balanced on the back of four elephants which stand on the back of a giant turtle, that is . . . __________________ ''What''s so hard about pulling a sword out of a stone? The real work''s already been done. You ought to make yourself useful and find the man who put the sword in the stone in the first place.'' The City Watch needs MEN! But what it''s got includes Corporal Carrot (technically a dwarf), Lance-constable Cuddy (really a dwarf), Lance-constable Detritus (a troll), Lance-constable Angua (a woman... most of the time) and Corporal Nobbs (disqualified from the human race for shoving). And they need all the help they can get, because someone in Ankh-Morpork has been getting dangerous ideas - about crowns and legendary swords, and destiny. And the problem with destiny is, of course, that she is not always careful where she points her finger. One minute you might be minding your own business on a normal if not spectacular career path, the next you might be in the frame for the big job, like saving the world . . .', 377, null, 1993, 446110, (select id from series where hardcover_id = 1018), 15) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Guards! Guards!', 'Terry Pratchett', '9652867071', 'https://assets.hardcover.app/edition/30693529/6944e11475daa9879449c47560db2405d15033cd.jpeg', 'Insurrection is in the air in the city of Ankh-Morpork. The Haves and Have-Nots are about to face off. Again.

It’s old news to Captain Sam Vimes of the city’s ramshackle Night Watch. But this time, something is different—the Have-Nots have found the key to a dormant, lethal weapon that even they can’t fully control, and they’re about to unleash a campaign of terror on the city.

Long believed extinct, a draco nobilis can now be seen patrolling the skies above Discworld''s greatest city. Not only does this unwelcome visitor have a nasty habit of charbroiling everything in its path, but it’s also soon crowned King.

Can Vimes, Captain Carrot, and the rest of the Ankh-Morpork City Watch restore order (before it''s burned to a crisp)?

The Discworld novels can be read in any order but Guards! Guards! is the first book in the City Watch collection.', 432, null, 1989, 446212, (select id from series where hardcover_id = 1018), 8) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Starsight', 'Brandon Sanderson', '8417347763', 'https://assets.hardcover.app/editions/31386302/2015435559880658.jpg', 'All her life, Spensa''s dreamed of becoming a pilot. Of proving she''s a hero like her father. She made it to the sky, but the truths she learned about her father were crushing. The rumors of his cowardice are true—he deserted his flight during battle against the Krell. Worse, though, he turned against his team and attacked them.

Spensa is sure that there''s more to the story. And she''s sure that whatever happened to her father in his starship could happen to her. When she made it outside the protective shell of her planet, she heard the stars—and it was terrifying. Everything Spensa has been taught about her world is a lie.

But Spensa also discovered a few other things about herself—and she''ll travel to the end of the galaxy to save humankind if she needs to.', 461, null, 2019, 446511, (select id from series where hardcover_id = 999), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Carl''s Doomsday Scenario', 'Matt Dinniman', '3748087330', 'https://assets.hardcover.app/editions/31544885/72ed6606-0392-4666-a23e-a331365814a2.jpg', 'The ratings and views are off the chart. The fans just can''t get enough. The dungeon gets more dangerous each day. But in a grinder designed to chew up and spit out crawlers by the millions, Carl and Princess Donut need to work harder than ever just to survive.

They call it the Over City. A sprawling, once-thriving metropolis devastated by a mysterious calamity. But these streets are far from abandoned. An undead circus trawls the ruins. Murdered prostitutes rain from the sky. An ancient spell is finally ready to reveal its dark purpose.

Carl still has no pants.

They call it Dungeon Crawler World. For Carl and Donut, it''s anything but a game.', 385, 688, 2021, 446680, (select id from series where hardcover_id = 12717), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dungeon Crawler Carl', 'Matt Dinniman, Will Staehle', '2100906924', 'https://assets.hardcover.app/edition/31601422/3a01ea07-01f4-45a2-9940-6fc7e00e0d08.jpeg', 'A man. His ex-girlfriend''s cat. A sadistic game show unlike anything in the universe: a dungeon crawl where survival depends on killing your prey in the most entertaining way possible.

In a flash, every human-erected construction on Earth—from Buckingham Palace to the tiniest of sheds—collapses in a heap, sinking into the ground.

The buildings and all the people inside have all been atomized and transformed into the dungeon: an 18-level labyrinth filled with traps, monsters, and loot. A dungeon so enormous, it circles the entire globe.

Only a few dare venture inside. But once you''re in, you can''t get out. And what''s worse, each level has a time limit. You have but days to find a staircase to the next level down, or it''s game over. In this game, it''s not about your strength or your dexterity. It''s about your followers, your views. Your clout. It''s about building an audience and killing those goblins with style.

You can''t just survive here. You gotta survive big.

You gotta fight with vigor, with excitement. You gotta make them stand up and cheer. And if you do have that "it" factor, you may just find yourself with a following. That''s the only way to truly survive in this game—with the help of the loot boxes dropped upon you by the generous benefactors watching from across the galaxy.

They call it Dungeon Crawler World. But for Carl, it''s anything but a game.', 465, 811, 2020, 446681, (select id from series where hardcover_id = 12717), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gate of the Feral Gods', 'Matt Dinniman', '9798520410171', 'https://assets.hardcover.app/edition/31943704/04d5cb18-1725-4b03-9303-b6e9ee14942d.jpg', 'New Achievement! Total, Utter Failure.

You failed a quest less than five minutes after you received it. Now that’s talent.

A floating fortress occupied by warrior gnomes. A castle made of sand. A derelict submarine guarded by malfunctioning machines. A haunted crypt surrounded by lethal traps.

It was supposed to be easy. One bubble. Four castles. Fifteen days. Capture each one, and the stairwell is unlocked.

Here''s the thing. It''s never easy. Carl and his team can''t go it alone. Not this time. They must rely on the help of the low-level, I-can''t-believe-these-idiots-are-still-alive crawlers trapped in the bubble with them. But can they be trusted?

Welcome, Crawler. Welcome to the fifth floor of the dungeon.', 589, 1083, 2021, 446722, (select id from series where hardcover_id = 12717), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dungeon Anarchist''s Cookbook', 'Matt Dinniman', '8410466163', 'https://assets.hardcover.app/edition/30407849/4b70ed0d-fb89-4d2c-9e33-23def79d50a4.jpg', 'The top ten list is populated. The sponsorship program is open. The difficulty is ramping up. The first three floors were nothing compared to what Carl and Donut now face.

The Iron Tangle. An impossibly-complicated subway system built out of the world''s subterranean railway systems, all combined and then tied together into a knot. Up is down. Down is up. Close is far. The cars are filled with monsters, the railway stations are less than safe, and the exit is always just a few stops away.

But there is hope. For the first time, the crawlers are all working together. The loot is better than ever. And the secret to unraveling it all may be hidden in the pages of a seemingly-useless book. Welcome, crawlers. Welcome to the fourth floor of the dungeon.', 532, 1014, 2021, 446730, (select id from series where hardcover_id = 12717), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Black Prism', 'Brent Weeks', '0316087548', 'https://assets.hardcover.app/external_data/39801458/c36b3efa685aa2c9170d6445fbad87e6f4a51069.jpeg', 'Gavin Guile is the Prism, the most powerful man in the world. He is high priest and emperor, a man whose power, wit, and charm are all that preserves a tenuous peace. But Prisms never last, and Guile knows exactly how long he has left to live: Five years to achieve five impossible goals.
But when Guile discovers he has a son, born in a far kingdom after the war that put him in power, he must decide how much he''s willing to pay to protect a secret that could tear his world apart.', 739, null, 2010, 446963, (select id from series where hardcover_id = 5547), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Light From Uncommon Stars', 'Ryka Aoki', '1250824478', 'https://assets.hardcover.app/edition/30623243/06a7867d-458c-41dc-a22e-6ce0199dfdb3.jpg', 'Shizuka Satomi made a deal with the devil: to escape damnation, she must entice seven other violin prodigies to trade their souls for success. She has already delivered six.

When Katrina Nguyen, a young transgender runaway, catches Shizuka''s ear with her wild talent, Shizuka can almost feel the curse lifting. She''s found her final candidate.

But in a donut shop off a bustling highway in the San Gabriel Valley, Shizuka meets Lan Tran, retired starship captain, interstellar refugee, and mother of four. Shizuka doesn''t have time for crushes or coffee dates, what with her very soul on the line, but Lan''s kind smile and eyes like stars might just redefine a soul''s worth. And maybe something as small as a warm donut is powerful enough to break a curse as vast as the California coastline.

As the lives of these three women become entangled by chance and fate, a story of magic, identity, curses, and hope begins, and a family worth crossing the universe for is found.', 384, null, 2021, 449040, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('In the Lives of Puppets', 'TJ Klune', '3453321456', 'https://assets.hardcover.app/edition/31492040/33c4a4a10555865db6bf99fdcd8d51bfd02eb550.jpeg', 'In a strange little home built into the branches of a grove of trees, live three robots--fatherly inventor android Giovanni Lawson, a pleasantly sadistic nurse machine, and a small vacuum desperate for love and attention. Victor Lawson, a human, lives there too. They''re a family, hidden and safe.

The day Vic salvages and repairs an unfamiliar android labelled "HAP," he learns of a shared dark past between Hap and Gio-a past spent hunting humans.

When Hap unwittingly alerts robots from Gio''s former life to their whereabouts, the family is no longer hidden and safe. Gio is captured and taken back to his old laboratory in the City of Electric Dreams. So together, the rest of Vic''s assembled family must journey across an unforgiving and otherworldly country to rescue Gio from decommission, or worse, reprogramming.

Along the way to save Gio, amid conflicted feelings of betrayal and affection for Hap, Vic must decide for himself: Can he accept love with strings attached?', 432, null, 2022, 454539, (select id from series where hardcover_id = 151075), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sea of Tranquility', 'Emily St. John Mandel', '5041623082', 'https://assets.hardcover.app/edition/30448568/a39e8ab0-6ef7-485e-8a50-c1a70e77b8cf.jpg', 'A novel of art, time travel, love, and plague that takes the reader from Vancouver Island in 1912 to a dark colony on the moon five hundred years later, unfurling a story of humanity across centuries and space.

Edwin St. Andrew is eighteen years old when he crosses the Atlantic by steamship, exiled from polite society following an ill-conceived diatribe at a dinner party. He enters the forest, spellbound by the beauty of the Canadian wilderness, and suddenly hears the notes of a violin echoing in an airship terminal--an experience that shocks him to his core.

Two centuries later a famous writer named Olive Llewellyn is on a book tour. She''s traveling all over Earth, but her home is the second moon colony, a place of white stone, spired towers, and artificial beauty. Within the text of Olive''s best-selling pandemic novel lies a strange passage: a man plays his violin for change in the echoing corridor of an airship terminal as the trees of a forest rise around him.

When Gaspery-Jacques Roberts, a detective in the black-skied Night City, is hired to investigate an anomaly in the North American wilderness, he uncovers a series of lives upended: The exiled son of an earl driven to madness, a writer trapped far from home as a pandemic ravages Earth, and a childhood friend from the Night City who, like Gaspery himself, has glimpsed the chance to do something extraordinary that will disrupt the timeline of the universe.

A virtuoso performance that is as human and tender as it is intellectually playful, Sea of Tranquility is a novel of time travel and metaphysics that precisely captures the reality of our current moment.''', 272, 347, 2022, 454688, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gallant', 'V. E. Schwab', '2371023361', 'https://assets.hardcover.app/external_data/60205544/516e52d70de9ab9707218948c371af3e4aa7094d.jpeg', '#1 New York Times–bestselling author V. E. Schwab weaves a dark and original tale about the place where the world meets its shadow, and the young woman beckoned by both sides. The Secret Garden meets Crimson Peak in this stand-alone novel perfect for readers of Holly Black and Neil Gaiman.

Olivia Prior has grown up in Merilance School for Girls, and all she has of her past is her mother’s journal—which seems to unravel into madness. Then, a letter invites Olivia to come home to Gallant. Yet when Olivia arrives, no one is expecting her. But Olivia is not about to leave the first place that feels like home; it doesn’t matter if her cousin Matthew is hostile, or if she sees half-formed ghouls haunting the hallways.

Olivia knows that Gallant is hiding secrets, and she is determined to uncover them. When she crosses a ruined wall at just the right moment, Olivia finds herself in a place that is Gallant—but not. The manor is crumbling, the ghouls are solid, and a mysterious figure rules over all. Now Olivia sees what has unraveled generations of her family, and where her father may have come from.

Olivia has always wanted to belong somewhere, but will she take her place as a Prior, protecting our world against the Master of the House? Or will she take her place beside him?

New York Times–bestselling author V. E. Schwab crafts a vivid and lush novel that grapples with the demons that are often locked behind closed doors. An eerie, stand-alone saga about life, death, and the young woman beckoned by both. Readers of Neil Gaiman, Holly Black, Melissa Albert, and Garth Nixwill quickly lose themselves in this novel with crossover appeal for all ages.', 384, null, 2022, 455319, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('There Is No Antimemetics Division', 'qntm', '3453275535', 'https://assets.hardcover.app/external_data/193765/b3af02e08dc537afe1627e9cc6a20131874e056d.jpeg', 'They’re all around us, hiding in plain sight.

One could be in the room with you now, just to your left. You could be seeing it right now—but from this second to the next, you’ll forget that you did. If you managed to jot down a note, the paper would look blank to you afterward.

These entities can feed on your most cherished memories, the things that make you you—and you’ll never even know anything changed.

They can turn you into a living ghost—make it so you’re standing next to your spouse, screaming in their ear, and they won’t know you’re there.

They’re predators equipped with the ultimate camouflage, living black holes for information, able to consume our very memories of their existence.

And they aren’t just feeding on us. They’re invading.

But how do you fight an enemy when you can never even know that you’re at war? How do you contain something you can’t record or remember?

Welcome to the Antimemetics Division.

No, this is not your first day.', 272, null, 2020, 455735, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Spear Cuts Through Water', 'Simon Jimenez', '1837861870', 'https://assets.hardcover.app/editions/30410428/911947569584637.jpg', '"The people suffer under the centuries-long rule of the Moon Throne. The royal family—the despotic emperor and his monstrous sons, the Three Terrors—hold the countryside in their choking grip. They bleed the land and oppress the citizens with the frightful powers they inherited from the god locked under their palace.

But that god cannot be contained forever.

With the aid of Jun, a guard broken by his guilt-stricken past, and Keema, an outcast fighting for his future, the god escapes from her royal captivity and flees from her own children, the triplet Terrors who would drag her back to her unholy prison. And so it is that she embarks with her young companions on a five-day pilgrimage in search of freedom—and a way to end the Moon Throne forever. The journey ahead will be more dangerous than any of them could have imagined."-- Provided by Amazon', 400, null, 2022, 455897, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nettle & Bone', 'T. Kingfisher', '1004105223', 'https://assets.hardcover.app/edition/30766119/c5fbdec67a798c95d8893ff85df87874331f7cb5.jpeg', 'After years of seeing her sisters suffer at the hands of an abusive prince, Marra—the shy, convent-raised, third-born daughter—has finally realized that no one is coming to their rescue. No one, except for Marra herself.

Seeking help from a powerful gravewitch, Marra is offered the tools to kill a prince—if she can complete three impossible tasks. But, as is the way in tales of princes, witches, and daughters, the impossible is only the beginning.

On her quest, Marra is joined by the gravewitch, a reluctant fairy godmother, a strapping former knight, and a chicken possessed by a demon. Together, the five of them intend to be the hand that closes around the throat of the prince and frees Marra''s family and their kingdom from its tyrannous ruler at last.', 256, null, 2022, 455976, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('How High We Go in the Dark', 'Sequoia Nagamatsu', '8410198142', 'https://assets.hardcover.app/external_data/61595697/c24633f28bb401f0be3919927acfc3385c819e36.jpeg', 'Dr. Cliff Miyashiro arrives in the Arctic Circle to continue his recently deceased daughter''s research, only to discover a virus, newly unearthed from melting permafrost. The plague unleashed reshapes life on earth for generations. Yet even while struggling to counter this destructive force, humanity stubbornly persists in myriad moving and ever inventive ways.

Among those adjusting to this new normal are an aspiring comedian, employed by a theme park designed for terminally ill children, who falls in love with a mother trying desperately to keep her son alive; a scientist who, having failed to save his own son from the plague, gets a second chance at fatherhood when one of his test subjects-a pig-develops human speech; a man who, after recovering from his own coma, plans a block party for his neighbours who have also woken up to find that they alone have survived their families; and a widowed painter and her teenaged granddaughter who must set off on cosmic quest to locate a new home planet.

From funerary skyscrapers to hotels for the dead, How High We Go in the Dark follows a cast of intricately linked characters spanning hundreds of years as humanity endeavours to restore the delicate balance of the world. This is a story of unshakable hope that crosses literary lines to give us a world rebuilding itself through an endless capacity for love, resilience and reinvention. Wonderful and disquieting, dreamlike and all too possible.', 304, null, 2022, 456455, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Carmilla', 'J. Sheridan Le Fanu', '1941360416', 'https://assets.hardcover.app/editions/3910455/9bd4c571-daf3-43c0-9ecb-63d966d25d50.jpg', '“To this hour the image of Carmilla returns to my memory with ambiguous alternations—sometimes the playful, languid, beautiful girl; sometimes the writhing fiend I saw in the ruined church. Sometimes, I start from a reverie, certain I heard the light step of Carmilla at the drawing-room door.”

Isolated in a remote mansion in a central European forest, Laura longs for companionship—until a carriage accident brings another young woman into her life: the secretive and sometimes erratic Carmilla. As Carmilla’s actions become more puzzling and volatile, Laura develops bizarre symptoms, and as her health goes into decline, Laura and her father discover something monstrous.

Joseph Sheridan Le Fanu’s compelling tale of a young woman’s seduction by a female vampire was a source of influence for Bram Stoker’s Dracula, which it predates by over a quarter century. Carmilla was originally serialized from 1871 to 1872 and went on to inspire adaptations in film, opera, and beyond, including the cult classic web series by the same name.', 114, null, 1872, 456589, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Court of Wings and Ruin', 'Sarah J. Maas', '3423762063', 'https://assets.hardcover.app/external_data/48713106/c66cf9dd4f24d33d3ce338a24b6dd6d90ac222bb.jpeg', 'Feyre has returned to the Spring Court, determined to gather information on Tamlin''s actions and learn what she can about the invading king threatening to bring her land to its knees. But to do so she must play a deadly game of deceit. One slip could bring doom not only for Feyre, but for everything-and everyone-she holds dear.

As war bears down upon them all, Feyre endeavors to take her place amongst the High Fae of the land, balancing her struggle to master her powers-both magical and political-and her love for her court and family. Amidst these struggles, Feyre and Rhysand must decide whom to trust amongst the cunning and lethal High Lords, and hunt for allies in unexpected places.

In this thrilling third book in the #1 bestselling series from Sarah J. Maas, the fate of Feyre''s world is at stake as armies grapple for power over the one thing that could destroy it.', 720, 1509, 2017, 458947, (select id from series where hardcover_id = 1275), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Oathbringer', 'Brandon Sanderson', '057509334X', 'https://assets.hardcover.app/edition/30455612/1deeb21c2576843fe4556815fea2eb784e406908.jpeg', 'In Oathbringer, the third volume of the New York Times bestselling Stormlight Archive, humanity faces a new Desolation with the return of the Voidbringers, a foe with numbers as great as their thirst for vengeance.

Dalinar Kholin''s Alethi armies won a fleeting victory at a terrible cost: The enemy Parshendi summoned the violent Everstorm, which now sweeps the world with destruction, and in its passing awakens the once peaceful and subservient parshmen to the horror of their millennia-long enslavement by humans. While on a desperate flight to warn his family of the threat, Kaladin Stormblessed must come to grips with the fact that the newly kindled anger of the parshmen may be wholly justified.

Nestled in the mountains high above the storms, in the tower city of Urithiru, Shallan Davar investigates the wonders of the ancient stronghold of the Knights Radiant and unearths dark secrets lurking in its depths. And Dalinar realizes that his holy mission to unite his homeland of Alethkar was too narrow in scope. Unless all the nations of Roshar can put aside Dalinar''s blood-soaked past and stand together--and unless Dalinar himself can confront that past--even the restoration of the Knights Radiant will not prevent the end of civilization.', 1243, 3306, 2017, 459452, (select id from series where hardcover_id = 997), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Court of Frost and Starlight', 'Sarah J. Maas', '3423762519', 'https://assets.hardcover.app/edition/30391916/f4a094648601f72409260159d5867cbecccc394f.jpeg', 'Feyre, Rhysand, and their friends are still busy rebuilding the Night Court and the vastly altered world beyond, recovering from the war that changed everything. But Winter Solstice is finally approaching, and with it, the joy of a hard-earned reprieve.

Yet even the festive atmosphere can''t keep the shadows of the past from looming. As Feyre navigates her first Winter Solstice as High Lady, her concern for those dearest to her deepens. They have more wounds than she anticipated-scars that will have a far-reaching impact on the future of their court.

Bridging the events of A Court of Wings and Ruin with the later books in the series, A Court of Frost and Starlight explores the far-reaching effects of a devastating war and the fierce love between friends.', 272, null, 2018, 459744, (select id from series where hardcover_id = 1275), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Prayer for the Crown-Shy', 'Becky Chambers', '8835736919', 'https://assets.hardcover.app/editions/30501405/6462135535022699.jpeg', 'After touring the rural areas of Panga, Sibling Dex (a Tea Monk of some renown) and Mosscap (a robot sent on a quest to determine what humanity really needs) turn their attention to the villages and cities of the little moon they call home.

They hope to find the answers they seek, while making new friends, learning new concepts, and experiencing the entropic nature of the universe.

Becky Chambers''s new series continues to ask: in a world where people have what they want, does having more even matter?', 160, null, 2022, 460092, (select id from series where hardcover_id = 62841), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('System Collapse', 'Martha Wells', '1250826985', 'https://assets.hardcover.app/editions/30845693/9ef45cef-6b2b-44a8-9d1c-1b625bb863fd.jpg', 'Everyone''s favorite lethal SecUnit is back.

Following the events in Network Effect, the Barish-Estranza corporation has sent rescue ships to a newly-colonized planet in peril, as well as additional SecUnits. But if there’s an ethical corporation out there, Murderbot has yet to find it, and if Barish-Estranza can’t have the planet, they’re sure as hell not leaving without something. If that something just happens to be an entire colony of humans, well, a free workforce is a decent runner-up prize.

But there’s something wrong with Murderbot; it isn’t running within normal operational parameters. ART’s crew and the humans from Preservation are doing everything they can to protect the colonists, but with Barish-Estranza’s SecUnit-heavy persuasion teams, they’re going to have to hope Murderbot figures out what’s wrong with itself, and fast!

Yeah, this plan is... not going to work.', 256, null, 2023, 462038, (select id from series where hardcover_id = 1053), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nona the Ninth', 'Tamsyn Muir', '8418037709', 'https://assets.hardcover.app/edition/30413195/d33585d4c8b7aeb0ba3e5ea4eca577a9961fd77b.jpeg', 'Her city is under siege. The zombies are coming back. And all Nona wants is a birthday party.
In many ways, Nona is like other people. She lives with her family, has a job at her local school, and loves walks on the beach and meeting new dogs. But Nona''s not like other people. Six months ago she woke up in a stranger''s body, and she''s afraid she might have to give it back.
The whole city is falling to pieces. A monstrous blue sphere hangs on the horizon, ready to tear the planet apart. Blood of Eden forces have surrounded the last Cohort facility and wait for the Emperor Undying to come calling. Their leaders want Nona to be the weapon that will save them from the Nine Houses. Nona would prefer to live an ordinary life with the people she loves, with Pyrrha and Camilla and Palamedes, but she also knows that nothing lasts forever.
And each night, Nona dreams of a woman with a skull-painted face...', 480, null, 2022, 462513, (select id from series where hardcover_id = 2759), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Daughter of the Moon Goddess', 'Sue Lynn Tan, Kuri Huang', '6069072928', 'https://assets.hardcover.app/edition/31486644/1d99b1aae57f28f6d44471db5a94a6ecadd6df9b.jpeg', 'But when Xingyin’s magic flares and her existence is discovered, she is forced to flee her home, leaving her mother behind.

Alone, powerless, and afraid, she makes her way to the Celestial Kingdom, a land of wonder and secrets. Disguising her identity, she seizes an opportunity to learn alongside the emperor’s son, mastering archery and magic, even as passion flames between her and the prince.

To save her mother, Xingyin embarks on a perilous quest, confronting legendary creatures and vicious enemies. But when treachery looms and forbidden magic threatens the kingdom, she must challenge the ruthless Celestial Emperor for her dream—striking a dangerous bargain in which she is torn between losing all she loves or plunging the realm into chaos.', 512, null, 2022, 463051, (select id from series where hardcover_id = 59902), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Leviathan Falls', 'James S. A. Corey', '0316332917', 'https://assets.hardcover.app/external_data/61060142/760e8b23dacb01e08619c997a72cc02c493a4d18.jpeg', 'The Laconian Empire has fallen, setting the thirteen hundred solar systems free from the rule of Winston Duarte. But the ancient enemy that killed the gate builders is awake, and the war against our universe has begun again. In the dead system of Adro, Elvi Okoye leads a desperate scientific mission to understand what the gate builders were and what destroyed them, even if it means compromising herself and the half-alien children who bear the weight of her investigation. Through the wide-flung systems of humanity, Colonel Aliana Tanaka hunts for Duarte''s missing daughter. . . and the shattered emperor himself. And on the Rocinante, James Holden and his crew struggle to build a future for humanity out of the shards and ruins of all that has come before. As nearly unimaginable forces prepare to annihilate all human life, Holden and a group of unlikely allies discover a last, desperate chance to unite all of humanity, with the promise of a vast galactic civilization free from wars, factions, lies, and secrets if they win. But the price of victory may be worse than the cost of defeat', 528, null, 2021, 463439, (select id from series where hardcover_id = 1026), 9) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Kaiju Preservation Society', 'John Scalzi', '844501479X', 'https://assets.hardcover.app/edition/30736444/659fdc805a0cec3fd5dc90d77d3f3e375099247d.jpeg', 'When COVID-19 sweeps through New York City, Jamie Gray is stuck as a dead-end driver for food delivery apps. That is, until Jamie makes a delivery to an old acquaintance, Tom, who works at what he calls “an animal rights organization.” Tom’s team needs a last-minute grunt to handle things on their next field visit. Jamie, eager to do anything, immediately signs on.

What Tom doesn''t tell Jamie is that the animals his team cares for are not here on Earth. Not our Earth, at least. In an alternate dimension, massive dinosaur-like creatures named Kaiju roam a warm, human-free world. They''re the universe''s largest and most dangerous panda and they''re in trouble.

It''s not just the Kaiju Preservation Society who have found their way to the alternate world. Others have, too. And their carelessness could cause millions back on our Earth to die.', 264, null, 2022, 463689, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Earth and Blood', 'Sarah J. Maas', '3423762969', 'https://assets.hardcover.app/external_data/37374512/a568a05f05a9f6cd37a96e14662b846b45acd29b.jpeg', 'Bryce Quinlan had the perfect life—working hard all day and partying all night—until a demon murdered her closest friends, leaving her bereft, wounded, and alone. When the accused is behind bars but the crimes start up again, Bryce finds herself at the heart of the investigation. She’ll do whatever it takes to avenge their deaths.

Hunt Athalar is a notorious Fallen angel, now enslaved to the Archangels he once attempted to overthrow. His brutal skills and incredible strength have been set to one purpose—to assassinate his boss’s enemies, no questions asked. But with a demon wreaking havoc in the city, he’s offered an irresistible deal: help Bryce find the murderer, and his freedom will be within reach.

As Bryce and Hunt dig deep into Crescent City’s underbelly, they discover a dark power that threatens everything and everyone they hold dear, and they find, in each other, a blazing passion—one that could set them both free, if they’d only let it.

With unforgettable characters, sizzling romance, and page-turning suspense, this richly inventive new fantasy series by #1 New York Times bestselling author Sarah J. Maas delves into the heartache of loss, the price of freedom—and the power of love.', 803, null, 2020, 465201, (select id from series where hardcover_id = 2211), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Tower of the Swallow', 'Andrzej Sapkowski, David French', '5171026513', 'https://assets.hardcover.app/book/467479/d15df3e8-e93a-4803-85d1-2010285cb0a4.jpg', 'Ciri, the child of prophecy, has vanished. Hunted by friends and foes alike, she has taken on the guise of a petty bandit and lives free for the first time in her life. But the net around her is closing.

Geralt, the Witcher, has assembled a group of allies determined to rescue her. Both sides of the war have sent brutal mercenaries to hunt her down. Her crimes have made her famous. There is only one place left to run. The tower of the swallow is waiting...', 528, null, 1997, 467479, (select id from series where hardcover_id = 1808), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mickey7', 'Edward Ashton', '8076841216', 'https://assets.hardcover.app/external_data/98232/7a70434ccc5735e8332660151180fa3a952f8860.jpeg', 'The Martian meets Dark Matter in Edward Ashton''s high concept science fiction thriller, in which Mickey7, an "expendable," refuses to let his replacement clone Mickey8 take his place. Dying isn''t any fun...but at least it''s a living. Mickey7 is an Expendable: a disposable employee on a human expedition sent to colonize the ice world Niflheim. Whenever there''s a mission that''s too dangerous--even suicidal--the crew turns to Mickey. After one iteration dies, a new body is regenerated with most of his memories intact. After six deaths, Mickey7 understands the terms of his deal...and why it was the only colonial position unfilled when he took it. On a fairly routine scouting mission, Mickey7 goes missing and is presumed dead. By the time he returns to the colony base, surprisingly helped back by native life, Mickey7''s fate has been sealed. There''s a new clone, Mickey8, reporting for Expendable duties. The idea of duplicate Expendables is universally loathed, and if caught, they will likely be thrown into the recycler for protein. Mickey7 must keep his double a secret from the rest of the colony. Meanwhile, life on Niflheim is getting worse. The atmosphere is unsuitable for humans, food is in short supply, and terraforming is going poorly. The native species are growing curious about their new neighbors, and that curiosity has Commander Marshall very afraid. Ultimately, the survival of both lifeforms will come down to Mickey7. That is, if he can just keep from dying for good.', 320, null, 2022, 469442, (select id from series where hardcover_id = 14472), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fairy Tale', 'Stephen King', '3453273990', 'https://assets.hardcover.app/edition/30445662/0c91093569488c3b6ffed7b9fafa10cbf9ea0ccf.jpeg', 'Charlie Reade looks like a regular high school kid, great at baseball and football, a decent student. But he carries a heavy load. His mom was killed in a hit-and-run accident when he was ten, and grief drove his dad to drink. Charlie learned how to take care of himself—and his dad. When Charlie is seventeen, he meets a dog named Radar and her aging master, Howard Bowditch, a recluse in a big house at the top of a big hill, with a locked shed in the backyard. Sometimes strange sounds emerge from it.

Charlie starts doing jobs for Mr. Bowditch and loses his heart to Radar. Then, when Bowditch dies, he leaves Charlie a cassette tape telling a story no one would believe. What Bowditch knows, and has kept secret all his long life, is that inside the shed is a portal to another world.

King’s storytelling in Fairy Tale soars. This is a magnificent and terrifying tale in which good is pitted against overwhelming evil, and a heroic boy—and his dog—must lead the battle.

Early in the Pandemic, King asked himself: “What could you write that would make you happy?”

“As if my imagination had been waiting for the question to be asked, I saw a vast deserted city—deserted but alive. I saw the empty streets, the haunted buildings, a gargoyle head lying overturned in the street. I saw smashed statues (of what I didn’t know, but I eventually found out). I saw a huge, sprawling palace with glass towers so high their tips pierced the clouds. Those images released the story I wanted to tell.”', 608, null, 2022, 469768, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wind-Up Bird Chronicle', 'Haruki Murakami, Jay Rubin', '030776270X', 'https://assets.hardcover.app/editions/30387653/7f3a72c2-328a-494c-bfea-0c884f8fcf47.jpg', 'Japan''s most highly regarded novelist now vaults into the first ranks of international fiction writers with this heroically imaginative novel, which is at once a detective story, an account of a disintegrating marriage, and an excavation of the buried secrets of World War II.

In a Tokyo suburb a young man named Toru Okada searches for his wife''s missing cat. Soon he finds himself looking for his wife as well in a netherworld that lies beneath the placid surface of Tokyo. As these searches intersect, Okada encounters a bizarre group of allies and antagonists: a psychic prostitute; a malevolent yet mediagenic politician; a cheerfully morbid sixteen-year-old-girl; and an aging war veteran who has been permanently changed by the hideous things he witnessed during Japan''s forgotten campaign in Manchuria.

Gripping, prophetic, suffused with comedy and menace, The Wind-Up Bird Chronicle is a tour de force equal in scope to the masterpieces of Mishima and Pynchon.', 607, null, 1994, 469816, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shards of Earth', 'Adrian Tchaikovsky', '8076840953', 'https://assets.hardcover.app/external_data/60821998/5c9cd55096ff1cc426c8fcee3d3c99cc56cbeb8f.jpeg', 'Eighty years ago, Earth was destroyed by an alien ''Architect''. Some escaped, but millions more died. So to protect its colonies, humanity shaped the minds of Idris and others into weapons and sent them into battle. But the Architects disappeared, and heroes like Idris were forgotten. However, he''s glad of it. This particular living weapon would rather retire to a shabby salvage vessel then be anyone''s ammunition. Then this small ship makes a huge discovery.', 592, null, 2021, 470676, (select id from series where hardcover_id = 6015), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Our Wives Under the Sea', 'Julia Armfield', '1250229898', 'https://assets.hardcover.app/edition/30394770/4fcfdf58019c960afa21f6782caacb08091216f4.jpeg', 'Miri thinks she has got her wife back, when Leah finally returns after a deep sea mission that ended in catastrophe. It soon becomes clear, though, that Leah may have come back wrong. Whatever happened in that vessel, whatever it was they were supposed to be studying before they were stranded on the ocean floor, Leah has carried part of it with her, onto dry land and into their home.

To have the woman she loves back should mean a return to normal life, but Miri can feel Leah slipping from her grasp. Memories of what they had before – the jokes they shared, the films they watched, all the small things that made Leah hers – only remind Miri of what she stands to lose. Living in the same space but suddenly separate, Miri comes to realize that the life that they had might be gone.

Our Wives Under The Sea is the debut novel from the critically acclaimed author of salt slow. It’s a story of falling in love, loss, grief, and what life there is in the deep, deep sea.', 240, null, 2022, 473719, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Master and Margarita', 'Mikhail Bulgakov, Katherine Tiernan O''Connor, Diana Lewis Burgin, Ellendea Proffer', '0880047550', 'https://assets.hardcover.app/edition/30461159/3f334c2b-9b69-4f92-bf0d-1f4e3b083318.jpg', 'An audacious revision of the stories of Faust and Pontius Pilate, The Master and Margarita is recognized as one of the essential classics of modern Russian literature. The novel’s vision of Soviet life in the 1930s is so ferociously accurate that it could not be published during its author’s lifetime and appeared only in a censored edition in the 1960s. Its truths are so enduring that its language has become part of the common Russian speech.

One hot spring, the devil arrives in Moscow, accompanied by a retinue that includes a beautiful naked witch and an immense talking black cat with a fondness for chess and vodka. The visitors quickly wreak havoc in a city that refuses to believe in either God or Satan. But they also bring peace to two unhappy Muscovites: one is the Master, a writer pilloried for daring to write a novel about Christ and Pontius Pilate; the other is Margarita, who loves the Master so deeply that she is willing to literally go to hell for him.

What ensues is a novel of inexhaustible energy, humor, and philosophical depth.', 432, null, 1967, 473854, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Blacktongue Thief', 'Christopher Buehlman', '3608119299', 'https://assets.hardcover.app/editions/30395155/9986773646988730.jpg', 'Kinch Na Shannack owes the Takers Guild a small fortune for his education as a thief, which includes (but is not limited to) lock-picking, knife-fighting, wall-scaling, fall-breaking, lie-weaving, trap-making, plus a few small magics. His debt has driven him to lie in wait by the old forest road, planning to rob the next traveler that crosses his path.

But today, Kinch Na Shannack has picked the wrong mark.

Galva is a knight, a survivor of the brutal goblin wars, and handmaiden of the goddess of death. She is searching for her queen, missing since a distant northern city fell to giants.

Unsuccessful in his robbery and lucky to escape with his life, Kinch now finds his fate entangled with Galva''s. Common enemies and uncommon dangers force thief and knight on an epic journey where goblins hunger for human flesh, krakens hunt in dark waters, and honor is a luxury few can afford.', 413, null, 2021, 474056, (select id from series where hardcover_id = 177347), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Legends & Lattes', 'Travis Baldree', '3423263563', 'https://assets.hardcover.app/editions/30396420/4372639752917043.jpg', 'Legends & Lattes is a cosy, heartwarming slice-of-life fantasy about found families and fresh starts - perfect for fans of TJ Klune, Katherine Addison and T. Kingfisher. High fantasy, low stakes - with a double-shot of coffee. After decades of adventuring, Viv the orc barbarian is finally hanging up her sword for good. Now she sets her sights on a new dream - for she plans to open the first coffee shop in the city of Thune. Even though no one there knows what coffee actually is.

 If Viv wants to put the past behind her, she can''t go it alone. And help might arrive from unexpected quarters. Yet old rivals and new stand in the way of success. And Thune''s shady underbelly could make it all too easy for Viv to take up the blade once more. 

But the true reward of the uncharted path is the travellers you meet along the way. Whether bound by ancient magic, delicious pastries or a freshly brewed cup, they may become something deeper than Viv ever could have imagined.

 ''This is a warm hug of a book, a place to retreat from the world for a little while, drink a coffee, and come out a little better'' - T. Kingfisher, bestselling author of Nettle & Bone', 304, 439, 2022, 475214, (select id from series where hardcover_id = 39578), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Amber Spyglass', 'Philip Pullman', '0613462505', 'https://assets.hardcover.app/editions/16913314/4463346300750242-283870.jpg', 'Will is the bearer of the knife. Now, accompanied by angels, his task is to deliver that powerful, dangerous weapon to Lord Asriel - by the command of his dying father.

But how can he go looking for Lord Asriel when Lyra is gone? Only with her help can he fathom the myriad plots and intrigues that beset him.', 548, null, 1999, 477834, (select id from series where hardcover_id = 1025), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tomorrow, and Tomorrow, and Tomorrow', 'Gabrielle Zevin', '8203452272', 'https://assets.hardcover.app/edition/30535150/2efdfd508a803c89913fd6e987f69048a17c89c6.jpeg', '"He calls her name. For a moment, she pretends she hasn’t heard him, but then, she turns, and a game begins: a legendary collaboration that will launch them to stardom.

These friends, intimates since childhood, borrow money, beg favors, and, before even graduating college, they have created their first blockbuster, Ichigo. Overnight, the world is theirs. 

Not even twenty-five years old, Sam and Sadie are brilliant, successful, and rich, but these qualities won’t protect them from their own creative ambitions or the betrayals of their hearts.

Spanning thirty years, from Cambridge, Massachusetts, to Venice Beach, California, and lands in between and far beyond, Gabrielle Zevin’s Tomorrow, and Tomorrow, and Tomorrow examines the multifarious nature of identity, disability, failure, the redemptive possibilities in play, and above all, our need to connect: to be loved and to love."-- Provided by Amazon', 496, null, 2022, 479910, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Flowers for Algernon', 'Daniel Keyes', '0898123305', 'https://assets.hardcover.app/edition/116801/3d46aa36-501a-4609-a744-1500713078f9.jpg', 'Flowers for Algernon is the beloved, classic story of a mentally disabled man whose experimental quest for intelligence mirrors that of Algernon, an extraordinary lab mouse. In poignant diary entries, Charlie tells how a brain operation increases his IQ and changes his life. As the experimental procedure takes effect, Charlie''s intelligence expands until it surpasses that of the doctors who engineered his metamorphosis. The experiment seems to be a scientific breakthrough of paramount importance--until Algernon begins his sudden, unexpected deterioration. Will the same happen to Charlie?', 311, 538, 1959, 480139, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Upgrade', 'Blake Crouch', '6555606339', 'https://assets.hardcover.app/external_data/59914457/6d05bef9020342f3438d865b650b76f4989b8408.jpeg', '"At first, Logan Ramsay isn’t sure if anything’s different. He just feels a little . . . sharper. Better able to concentrate. Better at multitasking. Reading a bit faster, memorizing better, needing less sleep.

But before long, he can’t deny it: Something’s happening to his brain. To his body. He’s starting to see the world, and those around him—even those he loves most—in whole new ways.

The truth is, Logan’s genome has been hacked. And there’s a reason he’s been targeted for this upgrade. A reason that goes back decades to the darkest part of his past, and a horrific family legacy.

Worse still, what’s happening to him is just the first step in a much larger plan, one that will inflict the same changes on humanity at large—at a terrifying cost.

Because of his new abilities, Logan’s the one person in the world capable of stopping what’s been set in motion. But to have a chance at winning this war, he’ll have to become something other than himself. Maybe even something other than human.

And even as he’s fighting, he can’t help wondering: what if humanity’s only hope for a future really does lie in engineering our own evolution?

Intimate in scale yet epic in scope, Upgrade is an intricately plotted, lightning-fast tale that charts one man’s thrilling transformation, even as it asks us to ponder the limits of our humanity—and our boundless potential."-- Provided by Goodreads', 337, null, 2022, 480253, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('What Moves the Dead', 'T. Kingfisher', '8412821149', 'https://assets.hardcover.app/edition/31486904/0271f3b4f812baf6d3ce0476201e1a52011f7157.jpeg', 'When Alex Easton, a retired soldier, receives word that their childhood friend Madeline Usher is dying, they race to the ancestral home of the Ushers in the remote countryside of Ruritania.

What they find there is a nightmare of fungal growths and possessed wildlife, surrounding a dark, pulsing lake. Madeline sleepwalks and speaks in strange voices at night, and her brother Roderick is consumed with a mysterious malady of the nerves.

Aided by a redoubtable British mycologist and a baffled American doctor, Alex must unravel the secret of the House of Usher before it consumes them all.', 165, null, 2022, 482831, (select id from series where hardcover_id = 43357), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Between Two Fires', 'Christopher Buehlman', '1483060772', 'https://assets.hardcover.app/editions/30423309/5478029573138530.jpg', 'Thomas, a disgraced knight, has found a young girl alone in a dead Norman village. An orphan of the Black Death, and an almost unnerving picture of innocence, she tells Thomas that plague is only part of a larger cataclysm—that the fallen angels under Lucifer are rising in a second war on heaven, and that the world of men has fallen behind the lines of conflict.

Is it delirium or is it faith? She believes she has seen the angels of God. She believes the righteous dead speak to her in dreams. And now she has convinced the faithless Thomas to shepherd her across a depraved landscape to Avignon. There, she tells Thomas, she will fulfill her mission to confront the evil that has devastated the earth, and to restore to this betrayed, murderous knight the nobility and hope of salvation he long abandoned.

As hell unleashes its wrath, and as the true nature of the girl is revealed, Thomas will find himself on a macabre battleground of angels and demons, saints, and the risen dead, and in the midst of a desperate struggle for nothing less than the soul of man.', 436, null, 2012, 482996, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Very Secret Society of Irregular Witches', 'Sangu Mandanna', '0593590848', 'https://assets.hardcover.app/external_data/61614583/f9cbe04ab5cf75bc687eb8b9dd01ab95453d73ae.jpeg', 'As one of the few witches in Britain, Mika Moon knows she has to hide her magic, keep her head down, and stay away from other witches so their powers don’t mingle and draw attention. And as an orphan who lost her parents at a young age and was raised by strangers, she’s used to being alone and she follows the rules…with one exception: an online account, where she posts videos “pretending” to be a witch. She thinks no one will take it seriously.
 
But someone does. An unexpected message arrives, begging her to travel to the remote and mysterious Nowhere House to teach three young witches how to control their magic. It breaks all of the rules, but Mika goes anyway, and is immediately tangled up in the lives and secrets of not only her three charges, but also an absent archaeologist, a retired actor, two long-suffering caretakers, and…Jamie. The handsome and prickly librarian of Nowhere House would do anything to protect the children, and as far as he’s concerned, a stranger like Mika is a threat. An irritatingly appealing threat.
 
As Mika begins to find her place at Nowhere House, the thought of belonging somewhere begins to feel like a real possibility. But magic isn’t the only danger in the world, and when peril comes knocking at their door, Mika will need to decide whether to risk everything to protect a found family she didn’t know she was looking for….', 318, null, 2022, 495137, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Babel, or The Necessity of Violence: An Arcane History of the Oxford Translators'' Revolution', 'R.F. Kuang', '8379648633', 'https://assets.hardcover.app/book_mappings/7332611/bbb44be9ff044379e6934ceae26be2405e3efdd6.jpeg', '1828. Robin Swift, orphaned by cholera in Canton, is brought to London by the mysterious Professor Lovell. There, he trains for years in Latin, Ancient Greek, and Chinese, all in preparation for the day he''ll enroll in Oxford University''s prestigious Royal Institute of Translation--also known as Babel. 

Babel is the world''s center for translation and, more importantly, magic. Silver working--the art of manifesting the meaning lost in translation using enchanted silver bars--has made the British unparalleled in power, as its knowledge serves the Empire''s quest for colonization. 

For Robin, Oxford is a utopia dedicated to the pursuit of knowledge. But knowledge obeys power, and as a Chinese boy raised in Britain, Robin realizes serving Babel means betraying his motherland. As his studies progress, Robin finds himself caught between Babel and the shadowy Hermes Society, an organization dedicated to stopping imperial expansion. When Britain pursues an unjust war with China over silver and opium, Robin must decide... Can powerful institutions be changed from within, or does revolution always require violence?', 560, 1306, 2022, 496492, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('I Who Have Never Known Men', 'Jacqueline Harpman', '6171517445', 'https://assets.hardcover.app/edition/30584481/30b8077a24fe1e99055ff4e2c9a0fc0f73104b4a.jpeg', 'As the burn of electric light merges day into night and numberless years pass, a young girl—the fortieth prisoner—sits alone and outcast in the corner. Soon she will show herself to be the key to the others'' escape and survival in the strange world that awaits them above ground.

Jacqueline Harpman was born in Etterbeek, Belgium, in 1929, and fled to Casablanca with her family during WWII. Informed by her background as a psychoanalyst and her youth in exile, I Who Have Never Known Men is a haunting, heartbreaking post-apocalyptic novel of female friendship and intimacy, and the lengths people will go to maintain their humanity in the face of devastation. Back in print for the first time since 1997, Harpman’s modern classic is an important addition to the growing canon of feminist speculative literature.', 208, 370, 1995, 498097, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Twisted Love', 'Ana Huang', '9180007228', 'https://assets.hardcover.app/edition/30803588/9e88e0bc66c8fd950454d2034c38163bab97ca51.jpeg', 'Alex Volkov is a devil blessed with the face of an angel and cursed with a past he can’t escape.

Driven by a tragedy that has haunted him for most of his life, his ruthless pursuits for success and vengeance leave little room for matters of the heart.

But when he’s forced to look after his best friend’s sister, he starts to feel something in his chest:

A crack.
A melt.
A fire that could end his world as he knew it.

***

Ava Chen is a free spirit trapped by nightmares of a childhood she can’t remember.

But despite her broken past, she’s never stopped seeing the beauty in the world…including the heart beneath the icy exterior of a man she shouldn’t want.

Her brother’s best friend.
Her neighbor.
Her savior and her downfall.

Theirs is a love that was never supposed to happen—but when it does, it unleashes secrets that could destroy them both…and everything they hold dear.', 343, null, 2021, 506453, (select id from series where hardcover_id = 17079), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('One Dark Window', 'Rachel Gillig', '8410163853', 'https://assets.hardcover.app/edition/31828939/9cf81169b82316d77a84c61e95c7edee0ca281b2.jpeg', 'Elspeth Spindle needs more than luck to stay safe in the eerie, mist-locked kingdom she calls home—she needs a monster. She calls him the Nightmare, an ancient, mercurial spirit trapped in her head. He protects her. He keeps her secrets. 

But nothing comes for free, especially magic. 

When Elspeth meets a mysterious highwayman on the forest road, her life takes a drastic turn. Thrust into a world of shadow and deception, she joins a dangerous quest to cure the kingdom of the dark magic infecting it. Except the highwayman just so happens to be the King’s own nephew, Captain of the Destriers…and guilty of high treason. 

He and Elspeth have until Solstice to gather twelve Providence Cards—the keys to the cure. But as the stakes heighten and their undeniable attraction intensifies, Elspeth is forced to face her darkest secret yet: the Nightmare is slowly, darkly, taking over her mind. And she might not be able to stop him. 

For fans of Uprooted and For the Wolf comes a dark, lushly gothic fantasy about a maiden who must unleash the monster within to save her kingdom—but the monster in her head isn’t the only threat lurking.', 421, null, 2022, 514157, (select id from series where hardcover_id = 36763), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Witch King', 'Martha Wells', '1250826802', 'https://assets.hardcover.app/external_data/61061243/90ea25b0daf857f9d652f746560a5ce313c11a81.jpeg', 'From the breakout SFF superstar author of Murderbot comes a remarkable story of power and friendship, of trust and betrayal, and of the families we choose. Kai-Enna is the Witch King, though he hasn’t always been, and he hasn’t even always been Kai-Enna! After being murdered, his consciousness dormant and unaware of the passing of time while confined in an elaborate water trap, Kai wakes to find a lesser mage attempting to harness Kai’s magic to his own advantage. That was never going to go well. But why was Kai imprisoned in the first place? What has changed in the world since his assassination? And why does the Rising World Coalition appear to be growing in influence? Kai will need to pull his allies close and draw on all his pain magic if he is to answer even the least of these questions. He’s not going to like the answers. WITCH KING is Martha Wells’s first new fantasy in over a decade, drawing together her signature ability to create characters we adore and identify with, alongside breathtaking action and adventure, and the wit and charm we’ve come to expect from one of the leading writers of her generation.', 448, null, 2023, 514917, (select id from series where hardcover_id = 122592), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hell Bent', 'Leigh Bardugo', '1250889243', 'https://assets.hardcover.app/external_data/61253793/2825f7628df8468c1a6f79eb07480c3fd2f1c9b5.jpeg', 'Find a gateway to the underworld. Steal a soul out of hell. A simple plan, except people who make this particular journey rarely come back. But Galaxy “Alex” Stern is determined to break Darlington out of purgatory―even if it costs her a future at Lethe and at Yale.

Forbidden from attempting a rescue, Alex and Dawes can’t call on the Ninth House for help, so they assemble a team of dubious allies to save the gentleman of Lethe. Together, they will have to navigate a maze of arcane texts and bizarre artifacts to uncover the societies’ most closely guarded secrets, and break every rule doing it. But when faculty members begin to die off, Alex knows these aren’t just accidents. Something deadly is at work in New Haven, and if she is going to survive, she’ll have to reckon with the monsters of her past and a darkness built into the university’s very walls.', 496, null, 2022, 550554, (select id from series where hardcover_id = 1145), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blood Over Bright Haven', 'M.L. Wang', '8410365405', 'https://assets.hardcover.app/edition/30513794/12f48168-cda6-4a8e-b9a9-1781352d0f65.jpg', 'For twenty years, Sciona has devoted every waking moment to the study of magic, fueled by a mad desire to achieve the impossible: to be the first woman ever admitted to the High Magistry at the University of Magics and Industry.

When Sciona finally passes the qualifying exam and becomes a highmage, she finds her challenges have just begun. Her new colleagues are determined to make her feel unwelcome—and, instead of a qualified lab assistant, they give her a janitor.

What neither Sciona nor her peers realize is that her taciturn assistant was not always a janitor. Ten years ago, he was a nomadic hunter who lost his family on their perilous journey from the wild plains to the city. But now he sees the opportunity to understand the forces that decimated his tribe, drove him from his homeland, and keep the privileged in power.

At first, mage and outsider have a fractious relationship. But working together, they uncover an ancient secret that could change the course of magic forever—if it doesn’t get them killed first.', 429, null, 2023, 554760, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Chain-Gang All-Stars', 'Nana Kwame Adjei-Brenyah', '1529920566', 'https://assets.hardcover.app/edition/30550475/19d44f36e3e73f4df22591b24faeb292c34337b8.jpeg', 'Loretta Thurwar and Hamara “Hurricane Staxxx” Stacker are the stars of the Chain-Gang All-Stars, the cornerstone of CAPE, or Criminal Action Penal Entertainment, a highly popular, highly controversial profit-raising program in America’s increasingly dominant private prison industry. It’s the return of the gladiators, and prisoners are com­peting for the ultimate prize: their freedom.
 
In CAPE, prisoners travel as Links in Chain-Gangs, competing in death matches before packed arenas with righteous protestors at the gates. Thur­war and Staxxx, both teammates and lovers, are the fan favorites. And if all goes well, Thurwar will be free in just a few matches, a fact she carries as heavily as her lethal hammer. As she prepares to leave her fellow Links, Thurwar considers how she might help preserve their humanity, in defiance of these so-called games. But CAPE’s corporate own­ers will stop at nothing to protect their status quo, and the obstacles they lay in Thurwar’s path have devastating consequences.', 384, null, 2022, 584785, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Adventures of Amina Al-Sirafi', 'S. A. Chakraborty', '0008621209', 'https://assets.hardcover.app/external_data/61177867/9f323ac78bddd7163b651748b10e9fef4220dc0f.jpeg', 'Amina al-Sirafi should be content. After a storied and scandalous career as one of the Indian Ocean’s most notorious pirates, she’s survived backstabbing rogues, vengeful merchant princes, several husbands, and one actual demon to retire peacefully with her family to a life of piety, motherhood, and absolutely nothing that hints of the supernatural.

But when she’s tracked down by the obscenely wealthy mother of a former crewman, she’s offered a job no bandit could refuse: retrieve her comrade’s kidnapped daughter for a kingly sum. The chance to have one last adventure with her crew, do right by an old friend, and win a fortune that will secure her family’s future forever? It seems like such an obvious choice that it must be God’s will.

Yet the deeper Amina dives, the more it becomes alarmingly clear there’s more to this job, and the girl’s disappearance, than she was led to believe. For there’s always risk in wanting to become a legend, to seize one last chance at glory, to savor just a bit more power…and the price might be your very soul.', 496, null, 2023, 584786, (select id from series where hardcover_id = 29140), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of Memory', 'Adrian Tchaikovsky', '152908721X', 'https://assets.hardcover.app/external_data/59685108/046f6acdb00687c18d5e7d9c013dfd8936e42338.jpeg', 'From the acclaimed, award-winning author of Children of Time comes an unparalleled narrative of alien contact and human discovery in this follow-up to Children of Ruin.', 501, null, 2022, 584791, (select id from series where hardcover_id = 1017), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Weyward', 'Emilia Hart, Enrica Budetta', '8419030252', 'https://assets.hardcover.app/edition/30550494/e38635091c5f0e564af0f3abb90fd6a12b0c2539.jpeg', 'I am a Weyward, and wild inside.

2019: Under cover of darkness, Kate flees London for ramshackle Weyward Cottage, inherited from a great aunt she barely remembers. With its tumbling ivy and overgrown garden, the cottage is worlds away from the abusive partner who tormented Kate. But she begins to suspect that her great aunt had a secret. One that lurks in the bones of the cottage, hidden ever since the witch-hunts of the 17th century.

1619: Altha is awaiting trial for the murder of a local farmer who was stampeded to death by his herd. As a girl, Altha’s mother taught her their magic, a kind not rooted in spell casting but in a deep knowledge of the natural world. But unusual women have always been deemed dangerous, and as the evidence for witchcraft is set out against Altha, she knows it will take all of her powers to maintain her freedom.

1942: As World War II rages, Violet is trapped in her family''s grand, crumbling estate. Straitjacketed by societal convention, she longs for the robust education her brother receives––and for her mother, long deceased, who was rumored to have gone mad before her death. The only traces Violet has of her are a locket bearing the initial W and the word weyward scratched into the baseboard of her bedroom.

Weaving together the stories of three extraordinary women across five centuries, Emilia Hart''s Weyward is an enthralling novel of female resilience and the transformative power of the natural world.', 404, null, 2023, 584796, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Will of the Many', 'James Islington', '8410163942', 'https://assets.hardcover.app/edition/30615590/1fe836a2-7004-4378-add0-dc78b96b2d17.jpg', 'AUDI. VIDE. TACE.

The Catenan Republic—the Hierarchy—may rule the world now, but they do not know everything.

I tell them my name is Vis Telimus. I tell them I was orphaned after a tragic accident three years ago, and that good fortune alone has led to my acceptance into their most prestigious school. I tell them that once I graduate, I will gladly join the rest of civilised society in allowing my strength, my drive and my focus—what they call Will—to be leeched away and added to the power of those above me, as millions already do. As all must eventually do.

I tell them that I belong, and they believe me.

But the truth is that I have been sent to the Academy to find answers. To solve a murder. To search for an ancient weapon. To uncover secrets that may tear the Republic apart.

And that I will never, ever cede my Will to the empire that executed my family.

To survive, though, I will still have to rise through the Academy’s ranks. I will have to smile, and make friends, and pretend to be one of them and win. Because if I cannot, then those who want to control me, who know my real name, will no longer have any use for me.

And if the Hierarchy finds out who I truly am, they will kill me. ', 640, null, 2023, 594985, (select id from series where hardcover_id = 35077), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tress of the Emerald Sea', 'Brandon Sanderson, Howard Lyon', '6073825005', 'https://assets.hardcover.app/external_data/60564134/fc31b11ae8f367e5717cf7916e557846dbc356f7.jpeg', 'The only life Tress has known on her island home in an emerald-green ocean has been a simple one, with the simple pleasures of collecting cups brought by sailors from faraway lands and listening to stories told by her friend Charlie.

But when Charlie''s father takes him on a voyage to find a bride and disaster strikes, Tress must stow away on a ship and seek the Sorceress of the deadly Midnight Sea. Amid the spore oceans where pirates abound, can Tress leave her simple life behind and make her own place sailing a sea where a single drop of water can mean instant death?', 384, 747, 2023, 602482, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Light Bringer', 'Pierce Brown', '6069611799', 'https://assets.hardcover.app/edition/30411196/22b4dc2f6745ce1341d52bbd3dbc0555a4d8ffe3.jpeg', 'The Reaper is a legend, more myth than man: the savior of worlds, the leader of the Rising, the breaker of chains.

But the Reaper is also Darrow, born of the red soil of Mars: a husband, a father, a friend.

Marooned far from home after a devastating defeat on the battlefields of Mercury, Darrow longs to return to his wife and sovereign, Virginia, to defend Mars from its bloodthirsty would-be conqueror Lysander.

Lysander longs to destroy the Rising and restore the supremacy of Gold, and will raze the worlds to realize his ambitions.

The worlds once needed the Reaper. But now they need Darrow, and Darrow needs the people he loves—Virginia, Cassius, Sevro—in order to defend the Republic.

So begins Darrow’s long voyage home, an interplanetary adventure where old friends will reunite, new alliances will be forged, and rivals will clash on the battlefield.

Because Eo’s dream is still alive—and after the dark age will come a new age: of light, of victory, of hope.', 704, null, 2023, 620124, (select id from series where hardcover_id = 1033), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bookshops & Bonedust', 'Travis Baldree', '3423263792', 'https://assets.hardcover.app/editions/30599331/7462847827989860.jpg', 'Viv''s career with the notorious mercenary company Rackam''s Ravens isn''t going as planned.

Wounded during the hunt for a powerful necromancer, she''s packed off against her will to recuperate in the sleepy beach town of Murk—so far from the action that she worries she''ll never be able to return to it.

What''s a thwarted soldier of fortune to do?

Spending her hours at a beleaguered bookshop in the company of its foul-mouthed proprietor is the last thing Viv would have predicted, but it may be both exactly what she needs and the seed of changes she couldn''t possibly imagine.

Still, adventure isn''t all that far away. A suspicious traveler in gray, a gnome with a chip on her shoulder, a summer fling, and an improbable number of skeletons prove Murk to be more eventful than Viv could have ever expected.', 352, null, 2023, 624232, (select id from series where hardcover_id = 39578), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Frugal Wizard''s Handbook for Surviving Medieval England', 'Brandon Sanderson', '8418037903', 'https://assets.hardcover.app/external_data/61336010/5e7eff725a15ddbd267099fc6eff505cc825428b.jpeg', 'From #1 New York Times bestselling author Brandon Sanderson—creator of The Stormlight Archive, the Mistborn Saga, and countless bestselling works of science fiction and fantasy—comes this captivating standalone adventure that meshes Jason Bourne, epic fantasy, and time travel.

A man awakes in a clearing in what appears to be medieval England with no memory of who he is, where he came from, or why he is there. Chased by a group from his own time, his sole hope for survival lies in regaining his missing memories, making allies among the locals, and perhaps even trusting in their superstitious boasts. His only help from the “real world” should have been a guidebook entitled The Frugal Wizard’s Handbook for Surviving Medieval England, except his copy exploded during transit. The few fragments he managed to save provide clues to his situation, but can he figure them out in time to survive?', 366, null, 2023, 630615, (select id from series where hardcover_id = 72559), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Butcher''s Masquerade', 'Matt Dinniman', '0241829828', 'https://assets.hardcover.app/editions/32004303/0e11e113-fd6c-4363-9a68-da8999b886f5.jpeg', 'A lush jungle teeming with danger. Savage dinosaurs seeking blood. A fallen princess intent on vengeance. A mysterious, end-of-floor celebration for the top crawlers, dubbed “The Butcher''s Masquerade.” 

The sixth floor. The Hunting Grounds. 

As the remaining crawlers battle for their lives, a new, terrible threat looms. Outside tourists are finally allowed to enter the game, and they are here and ready to hunt. Among them is Vrah, a famed and veteran hunter, intent on collecting the biggest trophy of her career. 

But their prey is far from harmless, and this season they are fighting back. 

Dungeon Crawler Carl and Princess Donut return in book five of the acclaimed litrpg series.', 707, 1413, 2022, 637867, (select id from series where hardcover_id = 12717), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wind and Truth', 'Brandon Sanderson', '8419260568', 'https://assets.hardcover.app/editions/30395755/5517573796567974.jpg', 'Dalinar Kholin has challenged the evil god Odium to a contest of champions, and the Knights Radiant and the nations of Roshar have a mere 10 days to prepare for the worst. The fate of the entire world―and the Cosmere at large―hangs in the balance.', 1344, null, 2024, 665261, (select id from series where hardcover_id = 997), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Book That Wouldn’t Burn', 'Mark Lawrence', '0593437934', 'https://assets.hardcover.app/editions/30671705/6339926388290658.jpg', 'A boy has lived his whole life trapped within a vast library, older than empires and larger than cities.

A girl has spent hers in a tiny settlement out on the Dust where nightmares stalk and no one goes.

The world has never even noticed them. That''s about to change.

Their stories spiral around each other, across worlds and time. This is a tale of truth and lies and hearts, and the blurring of one into another. A journey on which knowledge erodes certainty, and on which, though the pen may be mightier than the sword, blood will be spilled and cities burned.', 559, null, 2023, 684408, (select id from series where hardcover_id = 39794), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Divine Rivals', 'Rebecca Ross', '6585348168', 'https://assets.hardcover.app/edition/30714450/a76220ea-33dd-4ca9-99a9-99bbaa15bcfb.jpg', 'After centuries of sleep, the gods are warring again. But eighteen-year-old Iris Winnow just wants to hold her family together. Her mother is suffering from addiction and her brother is missing from the front lines. Her best bet is to win the columnist promotion at the Oath Gazette.

To combat her worries, Iris writes letters to her brother and slips them beneath her wardrobe door, where they vanish―into the hands of Roman Kitt, her cold and handsome rival at the paper. When he anonymously writes Iris back, the two of them forge a connection that will follow Iris all the way to the front lines of battle: for her brother, the fate of mankind, and love.

Shadow and Bone meets Lore in Rebecca Ross''s Divine Rivals, an epic enemies-to-lovers fantasy novel filled with hope and heartbreak, and the unparalleled power of love.', 356, null, 2023, 686110, (select id from series where hardcover_id = 43358), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Seven Year Slip', 'Ashley Poston', '059333650X', 'https://assets.hardcover.app/editions/30675763/599822310698746-TheSevenYearSlip.jpg', 'An overworked book publicist with a perfectly planned future hits a snag when she falls in love with her temporary roommate…only to discover he lives seven years in the past, in this witty and wise new novel from the New York Times bestselling author of The Dead Romantics.

Sometimes, the worst day of your life happens, and you have to figure out how to live after it.

So Clementine forms a plan to keep her heart safe: work hard, find someone decent to love, and try to remember to chase the moon. The last one is silly and obviously metaphorical, but her aunt always told her that you needed at least one big dream to keep going. And for the last year, that plan has gone off without a hitch. Mostly. The love part is hard because she doesn’t want to get too close to anyone—she isn’t sure her heart can take it.

And then she finds a strange man standing in the kitchen of her late aunt’s apartment. A man with kind eyes and a Southern drawl and a taste for lemon pies. The kind of man that, before it all, she would’ve fallen head-over-heels for. And she might again.

Except, he exists in the past. Seven years ago, to be exact. And she, quite literally, lives seven years in his future.

Her aunt always said the apartment was a pinch in time, a place where moments blended together like watercolors. And Clementine knows that if she lets her heart fall, she’ll be doomed.

After all, love is never a matter of time—but a matter of timing.', 326, null, 2023, 688466, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Powerless', 'Lauren  Roberts', '8419688932', 'https://assets.hardcover.app/editions/30688686/6273918086013675.jpg', '"Only the extraordinary belong in the kingdom of Ilya—the exceptional, the empowered, the Elites. The powers these Elites have possessed for decades were graciously gifted to them by the Plague, though not all were fortunate enough to both survive the sickness and reap the reward. Those born Ordinary are just that—ordinary. And when the king decreed that all Ordinaries be banished to preserve his Elite society, lacking an ability suddenly became a crime—making Paedyn Gray a felon by fate and a thief by necessity.

Surviving in the slums as an Ordinary is no simple task, and Paedyn knows this better than most. Having been trained by her father to be keenly observant since she was a child, Paedyn poses as a Psychic in the crowded city, blending in with the Elites as best she can to stay alive and out of trouble…easier said than done.

When Paeydn unsuspectingly saves one of Ilya’s princes, she finds herself thrown into the Purging Trials. The brutal competition exists to showcase the Elites’ powers—the very thing Paedyn lacks. If the Trials and the opponents within them don’t kill her, the prince she’s fighting feelings for certainly will if he discovers what she is…completely Ordinary."-- Provided by Amazon', 523, null, 2023, 699614, (select id from series where hardcover_id = 53122), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Assistant to the Villain', 'Hannah Nicole Maehrer', '6585348265', 'https://assets.hardcover.app/edition/31484624/0a0e79fd-f966-48b0-95c2-a9edb843bbb3.jpg', 'ASSISTANT WANTED: 
Notorious, high-ranking villain seeks loyal, levelheaded assistant for unspecified office duties, supporting staff for random mayhem, terror, and other Dark Things In General. Discretion a must. Excellent benefits. 

With ailing family to support, Evie Sage''s employment status isn''t just important, it''s vital. So when a mishap with Rennedawn’s most infamous Villain results in a job offer—naturally, she says yes. 

No job is perfect, of course, but even less so when you develop a teeny crush on your terrifying, temperamental, and undeniably hot boss. Don’t find evil so attractive, Evie. 

But just when she’s getting used to severed heads suspended from the ceiling and the odd squish of an errant eyeball beneath her heel, Evie suspects this dungeon has a huge rat...and not just the literal kind. Because something rotten is growing in the kingdom of Rennedawn, and someone wants to take the Villain—and his entire nefarious empire—out. 

Now Evie must not only resist drooling over her boss but also figure out exactly who is sabotaging his work...and ensure he makes them pay. After all, a good job is hard to find.', 342, null, 2019, 706234, (select id from series where hardcover_id = 65547), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fourth Wing', 'Rebecca Yarros', '0349436991', 'https://assets.hardcover.app/editions/30707731/3559167047761380.jpeg', '"Twenty-year-old Violet Sorrengail was supposed to enter the Scribe Quadrant, living a quiet life among books and history. Now, the commanding general―also known as her tough-as-talons mother―has ordered Violet to join the hundreds of candidates striving to become the elite of Navarre: dragon riders.

But when you’re smaller than everyone else and your body is brittle, death is only a heartbeat away...because dragons don’t bond to “fragile” humans. They incinerate them.

With fewer dragons willing to bond than cadets, most would kill Violet to better their own chances of success. The rest would kill her just for being her mother’s daughter―like Xaden Riorson, the most powerful and ruthless wingleader in the Riders Quadrant.

She’ll need every edge her wits can give her just to see the next sunrise.

Yet, with every day that passes, the war outside grows more deadly, the kingdom''s protective wards are failing, and the death toll continues to rise. Even worse, Violet begins to suspect leadership is hiding a terrible secret."-- Provided by Amazon', 517, 1282, 2023, 714600, (select id from series where hardcover_id = 41764), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Flame and Shadow', 'Sarah J. Maas', '1639732985', 'https://assets.hardcover.app/edition/30743751/c64638218349a262dae7fba4e8cde8a0444629f7.jpeg', 'Bryce Quinlan never expected to see a world other than Midgard, but now that she has, all she wants is to get back. Everything she loves is in Midgard: her family, her friends, her mate. Stranded in a strange new world, she''s going to need all her wits about her to get home again. And that''s no easy feat when she has no idea who to trust.

Hunt Athalar has found himself in some deep holes in his life, but this one might be the deepest of all. After a few brief months with everything he ever wanted, he''s in the Asteri''s dungeons again, stripped of his freedom and without a clue as to Bryce''s fate. He''s desperate to help her, but until he can escape the Asteri''s leash, his hands are quite literally tied.

In this sexy, breathtaking sequel to the #1 bestsellers House of Earth and Blood and House of Sky and Breath, Sarah J. Maas''s Crescent City series reaches new heights as Bryce and Hunt''s world is brought to the brink of collapse—with its future resting on their shoulders.', 838, null, 2024, 746152, (select id from series where hardcover_id = 2211), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Iron Flame', 'Rebecca Yarros', '9897778578', 'https://assets.hardcover.app/edition/31265393/4104bc2a10d4f5b793e5134e22e0afba1209059f.jpeg', 'Everyone expected Violet Sorrengail to die during her first year at Basgiath War College, Violet included. But Threshing was only the first impossible test meant to weed out the weak-willed, the unworthy, and the unlucky.

Now the real training begins, and Violet''s already wondering how she''ll get through. It''s not just that it''s grueling and maliciously brutal, or even that it''s designed to stretch the riders'' capacity for pain beyond endurance. It''s the new vice commandant, who''s made it his personal mission to teach Violet exactly how powerless she is - unless she betrays the man she loves.

Although Violet''s body might be weaker and frailer than everyone else''s, she still has her wits, and a will of iron. And leadership is forgetting the most important lesson Basgiath has taught her: Dragon riders make their own rules.

But a determination to survive won''t be enough this year.

Because Violet knows the real secret hidden for centuries at Basgiath War College - and nothing, not even dragon fire, may be enough to save them in the end.', 623, 698, 2023, 747398, (select id from series where hardcover_id = 41764), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Long Way to a Small, Angry Planet', 'Becky Chambers', '1473619793', 'https://assets.hardcover.app/editions/30403894/3494270170561911.jpg', 'When Rosemary Harper joins the crew of the Wayfarer, she isn''t expecting much. The Wayfarer, a patched-up ship that''s seen better days, offers her everything she could possibly want: a small, quiet spot to call home for a while, adventure in far-off corners of the galaxy, and distance from her troubled past.

But Rosemary gets more than she bargained for with the Wayfarer. The crew is a mishmash of species and personalities, from Sissix, the friendly reptilian pilot, to Kizzy and Jenks, the constantly sparring engineers who keep the ship running. Life on board is chaotic, but more or less peaceful - exactly what Rosemary wants.
Until the crew are offered the job of a lifetime: the chance to build a hyperspace tunnel to a distant planet.', 464, 941, 2014, 748620, (select id from series where hardcover_id = 1092), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Parable of the Sower', 'Octavia E. Butler', '1538765497', 'https://assets.hardcover.app/edition/30746776/3c6e51d5-12d8-4a5c-80b0-218305fea787.jpg', 'From the pioneering New York Times bestselling science fiction author of Kindred.

The radically speculative odyssey of a young Black woman in a post-apocalyptic America and the community she cultivates despite the horrors of climate change and social inequality

The time is 2025. The place is California, where small, walled communities must protect themselves from hordes of desperate scavengers and roaming bands of people addicted to a drug that activates an orgasmic desire to burn, rape, and murder.

When one small community is overrun, Lauren Olamina, an 18-year-old Black woman with the hereditary train of “hyperempathy”—which causes her to feel others’ pain as her own—sets off on foot along the dangerous coastal highways, moving north into the unknown.', 400, null, 1993, 748661, (select id from series where hardcover_id = 5461), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('One Hundred Years of Solitude', 'Gabriel García Márquez', '9583007846', 'https://assets.hardcover.app/edition/31690057/1072e91e67d3953a7d35bbb0ac44138a8bc600c8.jpeg', 'Gabriel García Márquez''s great masterpiece is the story of seven generations of the Buendía family and of Macondo, the town they have built. Though little more than a settlement surrounded by mountains, Macondo has its wars and disasters, even its wonders and miracles. A microcosm of Columbian life, its secrets lie hidden, encoded in a book and only Aureliano Buendía can fathom its mysteries and reveal its shrouded destiny. Blending political reality with magic realism, fantasy with comic invention, One Hundred Years of Solitude is one of the most daringly original works of the twentieth century.', 496, 840, 1967, 762271, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Yumi and the Nightmare Painter', 'Brandon Sanderson', '8419260029', 'https://assets.hardcover.app/edition/30607196/1843637c1e8bb0c49077d12f3f03e0afce1f149c.jpeg', 'Yumi comes from a land of gardens, meditation, and spirits, while Painter lives in a world of darkness, technology, and nightmares. 

When their lives suddenly become intertwined in strange ways, can they put aside their differences and work together to uncover the mysteries of their situation and save each other''s communities from certain disaster?', 365, null, 2023, 763207, (select id from series where hardcover_id = 222406), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Tainted Cup', 'Robert Jackson Bennett', '1399725378', 'https://assets.hardcover.app/editions/30774097/5279737640186273-ttce1.jpg', 'Even here at the Empire’s borders, where contagions abound and the blood of the leviathans works strange magical changes, it’s a death both terrifying and impossible.

Assigned to investigate is Ana Dolabra, a detective whose reputation for brilliance is matched only by her eccentricities. Rumor has it that she wears a blindfold at all times, and that she can solve impossible cases without even stepping outside the walls of her home.

At her side is her new assistant, Dinios Kol, magically altered in ways that make him the perfect aide to Ana’s brilliance. Din is at turns scandalized, perplexed, and utterly infuriated by his new superior—but as the case unfolds and he watches Ana’s mind leap from one startling deduction to the next, he must admit that she is, indeed, the Empire’s greatest detective.

As the two close in on a mastermind and uncover a scheme that threatens the Empire itself, Din realizes he’s barely begun to assemble the puzzle that is Ana Dolabra—and wonders how long he’ll be able to keep his own secrets safe from her piercing intellect.', 406, 831, 2024, 772009, (select id from series where hardcover_id = 46710), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Starter Villain', 'John Scalzi', '1509835423', 'https://assets.hardcover.app/editions/30775702/91783396510554-61885029.jpg', 'Following the bestselling The Kaiju Preservation Society, John Scalzi returns with another unique sci-fi caper set in the strangest of all worlds, present-day Earth. Inheriting your mysterious uncle''s supervillain business is more complicated than you might imagine. Sure, there are the things you''d expect. The undersea volcano lairs. The minions. The plots to take over the world. The international networks of rivals who want you dead. Much harder to get used to . . . are the the sentient, language-using, computer-savvy cats. And the fact that in the overall organization, they''re management . . .', 262, null, 2023, 773299, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Orbital', 'Samantha Harvey', '1529934095', 'https://assets.hardcover.app/edition/30778685/6a4034584ba9f0e359119f7503f42ee66c270772.jpeg', 'A team of astronauts in the International Space Station collect meteorological data, conduct scientific experiments and test the limits of the human body. But mostly they observe. Together they watch their silent blue planet, circling it sixteen times, spinning past continents and cycling through seasons, taking in glaciers and deserts, the peaks of mountains and the swells of oceans. Endless shows of spectacular beauty witnessed in a single day.

Yet although separated from the world they cannot escape its constant pull. News reaches them of the death of a mother, and with it comes thoughts of returning home. They look on as a typhoon gathers over an island and people they love, in awe of its magnificence and fearful of its destruction.

The fragility of human life fills their conversations, their fears, their dreams. So far from earth, they have never felt more part - or protective - of it. They begin to ask, what is life without earth? What is earth without humanity?', 207, null, 2023, 775856, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bride', 'Ali Hazelwood', '9798217190829', 'https://assets.hardcover.app/edition/30809259/e874780d512034e7deffd7cd66a4e3767c804554.jpeg', '"Her days of living in anonymity among the Humans are over: she has been called upon to uphold a historic peacekeeping alliance between the Vampyres and their mortal enemies, the Weres, and she sees little choice but to surrender herself in the exchange—again...

Weres are ruthless and unpredictable, and their Alpha, Lowe Moreland, is no exception. He rules his pack with absolute authority, but not without justice. And, unlike the Vampyre Council, not without feeling. It’s clear from the way he tracks Misery’s every movement that he doesn’t trust her. If only he knew how right he was….

Because Misery has her own reasons to agree to this marriage of convenience, reasons that have nothing to do with politics or alliances, and everything to do with the only thing she''s ever cared about. And she is willing to do whatever it takes to get back what’s hers, even if it means a life alone in Were territory…alone with the wolf."-- Provided by Amazon', 400, null, 2024, 801806, (select id from series where hardcover_id = 168625), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Eye of the Bedlam Bride', 'Matt Dinniman', '8396866400', 'https://assets.hardcover.app/editions/30829594/3f43c2b5-94bd-4d1b-9e64-35daa4e94b42.jpg', 'A pantheon of forgotten gods. An old grudge between a talk show host, an heiress, and the man they shattered along the way. A rapidly deteriorating AI system. An inconvenient tiara upon the head of a friend.

It is bedlam on the eighth floor.
As management reels from the unexpected conclusion of the seventh level, the surviving crawlers stumble onto the eighth and find themselves scattered. It’s a map based on Earth’s final days before the collapse, where ethereal, intangible ghosts of humanity go about their lives, oblivious of the impending doom. Living amongst these ghosts are monsters based in Earth lore. “Legendary” creatures tied to the geographical location they inhabit.

Each team of crawlers is given a task: find and capture six of these beasts. The captured monsters will be turned into cards. Cards that can be summoned into battle again and again. The stronger, the deadlier, the better.

At the end of the floor, the bad guys will also have decks, and they will have some of the most powerful cards available. So it’s crucial to assemble the toughest squad possible.

But, like always, there is a catch. There’s always a catch.

As Carl and Donut know all too well, just because someone is captured, it doesn’t mean they have been tamed.

Her name is Shi Maria. She’s easily the most powerful monster in their area. If they want to survive, they must capture her. But she is no ordinary beast. She’s intelligent. She was once married to a god, a god who is now missing. Her special attack is known to drive one insane. They call her the Bedlam Bride.

“Beware, beware. Beware the Eye of the Bedlam Bride”', 832, 1606, 2023, 818989, (select id from series where hardcover_id = 12717), 6) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Strength of the Few', 'James Islington', '3985852480', 'https://assets.hardcover.app/edition/30836340/6923cac7-42de-42ce-994c-c5eaf8d5c586.jpg', 'The Hierarchy still call me Vis Telimus. Still hail me as Catenicus. They still, as one, believe they know who I am.

But with all that has happened—with what I fear is coming—I am not sure it matters anymore.

I am no longer one. I won the Iudicium, and lost everything—and now, impossibly, the ancient device beyond the Labyrinth has replicated me across three separate worlds. A different version of myself in each of Obiteum, Luceum, and Res. Three different bodies, three different lives. I have to hide; fight; play politics. I have to train; trust; lie. I have to kill; heal; prove myself again, and again, and again.

I am loved, and hated, and entirely alone.

Above all, though, I need to find answers before it’s too late. To understand the nature of what has happened to me, and why.

I need to find a way to stop the coming Cataclysm, because if all I have learned is true, I may be the only one who can.', 723, null, 2025, 824777, (select id from series where hardcover_id = 35077), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Familiar', 'Leigh Bardugo', '2928377233976', 'https://assets.hardcover.app/editions/30891049/5545502854486628.png', ' But when her scheming mistress discovers the lump of a servant cowering in the kitchen is actually hiding a talent for little miracles, she demands Luzia use those gifts to better the family''s social position.

What begins as simple amusement for the bored nobility takes a perilous turn when Luzia garners the notice of Antonio Pérez, the disgraced secretary to Spain''s king. Still reeling from the defeat of his armada, the king is desperate for any advantage in the war against England''s heretic queen—and Pérez will stop at nothing to regain the king''s favor.

Determined to seize this one chance to better her fortunes, Luzia plunges into a world of seers and alchemists, holy men and hucksters, where the line between magic, science, and fraud is never certain. But as her notoriety grows, so does the danger that her Jewish blood will doom her to the Inquisition''s wrath. She will have to use every bit of her wit and will to survive—even if that means enlisting the help of Guillén Santangel, an embittered immortal familiar whose own secrets could prove deadly for them both.', 380, null, 2024, 873268, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sunlit Man', 'Brandon Sanderson', '9798228496873', 'https://assets.hardcover.app/edition/30607198/28184332798c392429b246efd09dd2d21ed5f52e.jpeg', '#1 New York Times Bestselling author Brandon Sanderson shows us a future in the Cosmere Universe where a perpetual planetary wanderer must decide whether to keep running, or stay and make a difference on a struggling planet. 

Years ago he had comrades in arms and a cause to believe in, but now the man who calls himself Nomad knows only a life on the run. Forced to hop from world to world in the Cosmere whenever the relentless Night Brigade gets too close, Nomad lands on a new planet and is instantly caught up in the struggle between a tyrant and the rebels who want only to escape being turned into mindless slaves-all under the constant threat of a sunrise whose heat will melt the very stones. 

Unable to understand the language, can he navigate the conflict and gain enough power to leap offworld before his mind or body pay the ultimate price? ', 385, null, 2023, 889484, (select id from series where hardcover_id = 72559), 4) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Butcher & Blackbird', 'Brynne Weaver', '1638931747', 'https://assets.hardcover.app/editions/30984895/8439175321212713.jpeg', 'When a chance encounter sparks an unlikely bond between rival murderers Sloane and Rowan, they find something elusive—the friendship of two like-minded, pitch-black souls who just happen to enjoy killing other serial killers.

From small-town West Virginia to upscale California, and from downtown Boston to rural Texas, the two hunters collide in an annual game of blood and suffering, one that pits them against the most dangerous monsters in the country.

But as their friendship develops into something more, the restless ghosts left in their wake are only a few steps behind, ready to claim more than just their newfound love.

Can Rowan and Sloane dig themselves out of a game of graves?
Or have they finally met their match?', 355, null, 2023, 959904, (select id from series where hardcover_id = 57397), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mercy of Gods', 'James S. A. Corey', '2330206593', 'https://assets.hardcover.app/edition/31103022/eb1f5d59e1dce085739447bf87fb0aa14d2c9036.jpeg', '"The Carryx – part empire, part hive – have waged wars of conquest for centuries, destroying or enslaving species across the galaxy.  Now, they are facing a great and deathless enemy. The key to their survival may rest with the humans of Anjiin.  

Caught up in academic intrigue and affairs of the heart, Dafyd Alkhor is pleased just to be an assistant to a brilliant scientist and his celebrated research team.  Then the Carryx ships descend, decimating the human population and taking the best and brightest of Anjiin society away to serve on the Carryx homeworld, and Dafyd is swept along with them.

They are dropped in the middle of a struggle they barely understand, set in a competition against the other captive species with extinction as the price of failure.  Only Dafyd and a handful of his companions see past the Darwinian contest to the deeper game that they must play to survive: learning to understand – and manipulate – the Carryx themselves.

With a noble but suicidal human rebellion on one hand and strange and murderous enemies on the other, the team pays a terrible price to become the trusted servants of their new rulers.

Dafyd Alkhor is a simple man swept up in events that are beyond his control and more vast than his imagination.  He will become the champion of humanity and its betrayer, the most hated man in history and the guardian of his people.

This is where his story begins."-- Provided by Amazon', 422, null, 2024, 1078966, (select id from series where hardcover_id = 52808), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Devils', 'Joe Abercrombie', '3453274989', 'https://assets.hardcover.app/edition/31112851/e65049688dd26b231b520382441c3a02e643722b.jpeg', 'Brother Diaz has been summoned to the Sacred City, where he is certain a commendation and grand holy assignment awaits him. But his new flock is made up of unrepentant murderers, practitioners of ghastly magic, and outright monsters. The mission he is tasked with will require bloody measures from them all in order to achieve its righteous ends.

Elves lurk at our borders and hunger for our flesh, while greedy princes care for nothing but their own ambitions and comfort. With a hellish journey before him, it''s a good thing Brother Diaz has the devils on his side.', 547, null, 2025, 1088816, (select id from series where hardcover_id = 174829), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ministry of Time', 'Kaliane Bradley', '8368158796', 'https://assets.hardcover.app/external_data/61136896/24267950b6b867ef240904272bdc664dbbd33556.jpeg', '"A recently established government ministry is gathering “expats” from across history to establish whether time travel is feasible—for the body, but also for the fabric of space-time.

She is tasked with working as a “bridge”: living with, assisting, and monitoring the expat known as “1847” or Commander Graham Gore. As far as history is concerned, Commander Gore died on Sir John Franklin’s doomed 1845 expedition to the Arctic, so he’s a little disoriented to be living with an unmarried woman who regularly shows her calves, surrounded by outlandish concepts such as “washing machines,” “Spotify,” and “the collapse of the British Empire.” But with an appetite for discovery, a seven-a-day cigarette habit, and the support of a charming and chaotic cast of fellow expats, he soon adjusts.

Over the next year, what the bridge initially thought would be, at best, a horrifically uncomfortable roommate dynamic, evolves into something much deeper. By the time the true shape of the Ministry’s project comes to light, the bridge has fallen haphazardly, fervently in love, with consequences she never could have imagined. Forced to confront the choices that brought them together."-- Provided by Amazon', 352, null, 2024, 1119185, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Katabasis', 'R.F. Kuang', '0063442078', 'https://assets.hardcover.app/editions/31147378/6272729711218434.jpg', 'Dante’s Inferno meets Susanna Clarke’s Piranesi in this all-new dark academia fantasy from R. F. Kuang, the #1 New York Times bestselling author of Babel and Yellowface, in which two graduate students must put aside their rivalry and journey to Hell to save their professor’s soul—perhaps at the cost of their own. 

Katabasis, noun, Ancient Greek:

The story of a hero’s descent to the underworld

Alice Law has only ever had one goal: to become one of the brightest minds in the field of Magick. She has sacrificed everything to make that a reality: her pride, her health, her love life, and most definitely her sanity. All to work with Professor Jacob Grimes at Cambridge, the greatest magician in the world.

That is, until he dies in a magical accident that could possibly be her fault.

Grimes is now in Hell, and she’s going in after him. Because his recommendation could hold her very future in his now incorporeal hands and even death is not going to stop the pursuit of her dreams….

Nor will the fact that her rival, Peter Murdoch, has come to the very same conclusion.

With nothing but the tales of Orpheus and Dante to guide them, enough chalk to draw the Pentagrams necessary for their spells, and the burning desire to make all the academic trauma mean anything, they set off across Hell to save a man they don’t even like.

But Hell is not like the storybooks say, Magick isn’t always the answer, and there’s something in Alice and Peter’s past that could forge them into the perfect allies…or lead to their doom.', 560, null, 2025, 1123366, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Isles of the Emberdark', 'Brandon Sanderson', '8419260584', 'https://assets.hardcover.app/editions/31204382/892b77dd-ffc7-4c72-95af-915738b6e7af.png', 'All his life, Sixth of the Dusk has been a traditional trapper of Aviar—the supernatural birds his people bond with—on the deadly island of Patji. Then one fateful night he propels his people into a race to modernize before they can be conquered by the Ones Above, invaders from the stars who want to exploit the Aviar.

But it’s a race they’re losing, and Dusk fears his people will lose themselves in the effort. When a chance comes to sail into the expanse of the emberdark beyond a mystical portal, Dusk sets off to find his people’s salvation with only a canoe, his birds, and all the grit and canniness of a Patji trapper.

Elsewhere in the emberdark is a young dragon chained in human form: Starling of the starship Dynamic. She and her ragtag crew of exiles are deep in debt and on the brink of losing their freedom. So when she finds an ancient map to a hidden portal between the emberdark and the physical realm, she seizes the chance at a lucrative discovery.

These unlikely allies might just be the solution to each other’s crisis. In their search for independence, Dusk and Starling face perilous bargains, poisonous politics, and the destructive echo of a dead god.', 465, null, 2025, 1179741, (select id from series where hardcover_id = 72559), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Onyx Storm', 'Rebecca Yarros', '0349437092', 'https://assets.hardcover.app/edition/31924195/ae56c549dc746e14273905b3a7ee11d0e1f199a1.jpeg', 'After nearly eighteen months at Basgiath War College, Violet Sorrengail knows there’s no more time for lessons.

No more time for uncertainty.

Because the battle has truly begun; and with enemies closing in from outside their walls and within their ranks, it’s impossible to know who to trust.

Now Violet must journey beyond the failing Aretian wards to seek allies from unfamiliar lands to stand with Navarre.

The trip will test every bit of her wit, luck, and strength, but she will do anything to save what she loves - her dragons, her family, her home, and him.

Even if it means keeping a secret so big, it could destroy everything.

They need an army.
They need power.
They need magic.

And they need the one thing only Violet can find—the truth.

But a storm is coming... and not everyone can survive its wrath.', 527, null, 2025, 1197328, (select id from series where hardcover_id = 41764), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Girl with the Dragon Tattoo', 'Stieg Larsson', '8901116154', 'https://assets.hardcover.app/books/379085/9274740-L.jpg', 'It''s about the disappearance 40 years ago of Harriet Vanger, a young scion of one of the wealthiest families in Sweden...and about her octogenarian uncle, determined to know the truth about what he believes was her murder.

It''s about Mikael Blomkvist, a crusading journalist recently at the wrong end of a libel case, hired to get to the bottom of Harriet''s disappearance...and about Lisbeth Salander, a 24-year-old, pierced and tattooed genius hacker possessed of the hard-earned wisdom of someone twice her age, who assists Blomkvist with the investigation.

This unlikely team discovers a vein of nearly unfathomable iniquity running through the Vanger family, astonishing corruption in the highest echelons of Swedish industrialism - and an unexpected connection between themselves.', 465, 981, 2005, 1218611, (select id from series where hardcover_id = 2115), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Emily Wilde''s Encyclopaedia of Faeries', 'Heather Fawcett', '8027522927', 'https://assets.hardcover.app/editions/30590667/1785565836815120.jpg', '"She is a genius scholar and a meticulous researcher who is writing the world’s first encyclopaedia of faerie lore. But Emily Wilde is not good at people. She could never make small talk at a party—or even get invited to one. And she prefers the company of her books, her dog, Shadow, and the Fair Folk to other people.

So when she arrives in the hardscrabble village of Hrafnsvik, Emily has no intention of befriending the gruff townsfolk. Nor does she care to spend time with another new arrival: her dashing and insufferably handsome academic rival Wendell Bambleby, who manages to charm the townsfolk, muddle Emily’s research, and utterly confound and frustrate her.

But as Emily gets closer and closer to uncovering the secrets of the Hidden Ones—the most elusive of all faeries—lurking in the shadowy forest outside the town, she also finds herself on the trail of another mystery: Who is Wendell Bambleby, and what does he really want? To find the answer, she’ll have to unlock the greatest mystery of all—her own heart."-- Provided by Amazon', 354, null, 2022, 1244658, (select id from series where hardcover_id = 32465), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heir of Fire', 'Sarah J. Maas', '3423765321', 'https://assets.hardcover.app/edition/30432118/7be2fd1c-ec1f-482b-872e-a88ede019c74.jpg', 'Celaena Sardothien has survived deadly contests and shattering heartbreak, but now she must travel to a new land to confront her darkest truth. That truth could change her life-and her future-forever.

Meanwhile, monstrous forces are gathering on the horizon, intent on enslaving her world. To defeat them, Celaena will need the strength not only to fight the evil that is about to be unleashed but also to harness her inner demons. If she is to win this battle, she must find the courage to face her destiny-and burn brighter than ever before.

The third book in the #1 New York Times bestselling Throne of Glass series continues Celaena’s epic journey from woman to warrior.', 565, null, 2014, 1363844, (select id from series where hardcover_id = 5509), 3) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sunrise on the Reaping', 'Suzanne Collins', '9000397251', 'https://assets.hardcover.app/editions/31416911/2580982385827096.jpg', 'As the day dawns on the fiftieth annual Hunger Games, fear grips the districts of Panem. This year, in honor of the Quarter Quell, twice as many tributes will be taken from their homes.

Back in District 12, Haymitch Abernathy is trying not to think too hard about his chances. All he cares about is making it through the day and being with the girl he loves.

When Haymitch’s name is called, he can feel all his dreams break. He’s torn from his family and his love, shuttled to the Capitol with the three other District 12 tributes: a young friend who’s nearly a sister to him, a compulsive oddsmaker, and the most stuck-up girl in town. As the Games begin, Haymitch understands he’s been set up to fail. But there’s something in him that wants to fight . . . and have that fight reverberate far beyond the deadly arena.', 382, 767, 2025, 1389888, (select id from series where hardcover_id = 1015), 0.5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Time of Contempt', 'Andrzej Sapkowski, David French', '5171222258', 'https://assets.hardcover.app/book/445147/6c371a78-3712-4283-9c76-c8cad3d38fb1.jpg', 'To protect his ward, Ciri, Geralt of Rivia sends her away from the home of the Witchers to train with the sorceress Yennefer. But all is not well within the Wizard''s Guild in the second book of the NYT bestselling series that inspired the blockbuster video games. 

Geralt is a witcher: guardian of the innocent; protector of those in need; a defender, in dark times, against some of the most frightening creatures of myth and legend. His task, now, is to protect Ciri. A child of prophecy, she will have the power to change the world for good or for ill -- but only if she lives to use it.', 400, null, 1995, 1408508, (select id from series where hardcover_id = 1808), 2) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Quicksilver', 'Callie Hart', '3328604200', 'https://assets.hardcover.app/external_data/2313198/2bcec6476f66958e78faacfc8e14c31143ef0cde.jpeg', 'Twenty-four-year-old Saeris Fane is good at keeping secrets. No one knows about the strange powers she possesses, or the fact that she has been picking pockets and stealing from the Undying Queen’s reservoirs for as long as she can remember. In the land of the unforgiving desert, there isn’t much a girl wouldn’t do for a glass of water. But a secret is like a knot. Sooner or later, it is bound to come undone.

When Saeris comes face-to-face with Death himself, she inadvertently reopens a gateway between realms and is transported to a land of ice and snow. The Fae have always been the stuff of myth, of legend, of nightmares…but it turns out they’re real, and Saeris has landed right in the middle of a centuries-long conflict that might just get her killed.

The first of her kind to tread the frozen mountains of Yvelia in over a thousand years, Saeris mistakenly binds herself to Kingfisher, a handsome Fae warrior, who has secrets and nefarious agendas of his own. He will use her Alchemist’s magic to protect his people, no matter what it costs him… or her. Death has a name. It is Kingfisher of the Ajun Gate. His past is murky. His attitude stinks. And he’s the only way Saeris is going to make it home.', 624, null, 2024, 1421303, (select id from series where hardcover_id = 125748), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fire & Blood', 'George R.R. Martin, Doug Wheatley', '3641233399', 'https://assets.hardcover.app/edition/31508299/4043384b-1870-4dae-bd1f-389c98d8f6d9.jpg', 'The first volume of a definitive two-part history of the Targaryens in Westeros is set centuries before the events of "A Game of Thrones" and answers key questions about the dynasty''s origins, conflicts and relationships with dragons.', 706, null, 2014, 1463951, (select id from series where hardcover_id = 1106), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('This Inevitable Ruin', 'Matt Dinniman, Erik Wilson', '0241829933', 'https://assets.hardcover.app/edition/32042174/54ee7e48-38e1-4303-824a-7da6156f5bfe.png', 'They call it Faction Wars.
The ninth floor.

Nine armies, each led by rich and powerful aliens from across the galaxy. Each team has one objective: to capture and hold the castle at the very center of the battlefield. Strategy, alliances, pitched battles, and, of course, betrayal... It all makes for great fun and even greater television.

After all, none of these powerful aliens really die when they’re playing war.

Except this time. This time, winner takes all. Those who fall, stay in the ground.

As the AI continues its rapid decline, Carl and company take advantage of the chaos. For the first time ever, the crawlers are fighting back. They are now one of the nine teams. And this season, there’s a tenth army on the playing field. The NPCs, who are normally used as nothing but cannon fodder, have become fully self-aware and formed a team of their own.

For Donut and Katia, the stakes are even higher. Only one of them will be allowed to leave this level.

If they all want to survive, they’re going to need a little help from a veteran or two.

This is it.
This is what they’ve been fighting toward.
This is war.

This inevitable ruin.', 880, 1720, 2024, 1464466, (select id from series where hardcover_id = 12717), 7) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Circle', 'Dave Eggers', '0385351399', 'https://assets.hardcover.app/edition/3967697/8489009-L.jpg', 'When Mae Holland is hired to work for the Circle, the world''s most powerful internet company, she feels she''s been given the opportunity of a lifetime. The Circle, run out of a sprawling California campus, links users'' personal emails, social media, banking, and purchasing with their universal operating system, resulting in one online identity and a new age of civility and transparency. As Mae tours the open-plan office spaces, the towering glass dining facilities, the cozy dorms for those who spend nights at work, she is thrilled with the company''s modernity and activity. There are parties that last through the night, there are famous musicians playing on the lawn, there are athletic activities and clubs and brunches, and even an aquarium of rare fish retrieved from the Marianas Trench by the CEO. Mae can''t believe her luck, her great fortune to work for the most influential company in the world--even as life beyond the campus grows distant, even as a strange encounter with a colleague leaves her shaken, even as her role at the Circle becomes increasingly public.

What begins as the captivating story of one woman''s ambition and idealism soon becomes a heart-racing novel of suspense, raising questions about memory, history, privacy, democracy, and the limits of human knowledge.', 493, null, 2013, 1540937, (select id from series where hardcover_id = 5456), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Atmosphere: A Love Story', 'Taylor Jenkins Reid', '1804941433', 'https://assets.hardcover.app/edition/31625541/d80d0f61-d2a6-488f-a93c-a5dfc5a32faa.jpg', 'Joan Goodwin has been obsessed with the stars for as long as she can remember. Thoughtful and reserved, Joan is content with her life as a professor of physics and astronomy at Rice University and as aunt to her precocious niece, Frances. That is, until she comes across an advertisement seeking the first women scientists to join NASA''s Space Shuttle program. Suddenly, Joan burns to be one of the few people to go to space.

Selected from a pool of thousands of applicants in the summer of 1980, Joan begins training at Houston''s Johnson Space Center, alongside an exceptional group of fellow candidates: Top Gun pilots Hank Redmond and John Griffin, who are kind and easy going even when the stakes are highest; mission specialist Lydia Danes, who has worked too hard to play nice; warm-hearted Donna Fitzgerald, who is navigating her own secrets; and Vanessa Ford, the magnetic and mysterious aeronautical engineer, who can fix any engine and fly any plane.

As the new astronauts become unlikely friends and prepare for their first flights, Joan finds a passion and a love she never imagined. In this new light, Joan begins to question everything she thinks she knows about her place in the observable universe.

Then, in December of 1984, on mission STS-LR9, everything changes in an instant.

Fast paced, thrilling, and emotional, Atmosphere is Taylor Jenkins Reid at her best: transporting readers to iconic times and places, with complex protagonists, telling a passionate and soaring story about the transformative power of love, this time among the stars.', 352, null, 2025, 1561653, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Serpent and the Wings of Night', 'Carissa Broadbent', '8556512038', 'https://assets.hardcover.app/external_data/60687109/d35fc864053dac9e00d75b78846acb8e453c2e78.jpeg', 'The adopted human daughter of the Nightborn vampire king, Oraya carved her place in a world designed to kill her. Her only chance to become something more than prey is entering the Kejari: a legendary tournament held by the goddess of death herself.

But winning won’t be easy amongst the most vicious warriors from all three vampire houses. To survive, Oraya is forced to make an alliance with a mysterious rival.

Everything about Raihn is dangerous. He is a ruthless vampire, an efficient killer, an enemy to her father’s crown… and her greatest competition. Yet, what terrifies Oraya most of all is that she finds herself oddly drawn to him.

But there’s no room for compassion in the Kejari. War for the House of Night brews, shattering everything that Oraya thought she knew about her home. And Raihn may understand her more than anyone – but their blossoming attraction could be her downfall, in a kingdom where nothing is more deadly than love.', 502, null, 2022, 1643361, (select id from series where hardcover_id = 29270), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Frankenstein: The 1818 Text', 'Mary Shelley', '1524705705', 'https://assets.hardcover.app/edition/32275247/049351bf-f6c8-477a-9555-100b7998602d.jpg', 'The original 1818 text of Frankenstein preserves the hard-hitting and politically-charged aspects of Shelley’s original writing, as well as her unflinching wit and strong female voice. This edition also emphasizes Shelley’s relationship with her mother—trailblazing feminist Mary Wollstonecraft, who penned A Vindication of the Rights of Woman—and demonstrates her commitment to carrying forward her mother’s ideals, placing her in the context of a feminist legacy rather than the sole female in the company of male poets, including Percy Shelley and Lord Byron.', 399, null, 1818, 1661894, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The 7 1/2 Deaths of Evelyn Hardcastle', 'Stuart Turton', '9511348515', 'https://assets.hardcover.app/edition/30385617/30dc1a93-b2a9-4499-a0be-f5ae3641bc05.png', '''Somebody''s going to be murdered at the ball tonight. It won''t appear to be a murder, and so the murderer won''t be caught. Rectify that injustice, and I''ll show you the way out.''

It is meant to be a celebration, but it ends in tragedy. As fireworks explode overhead, Evelyn Hardcastle, the young and beautiful daughter of the house, is killed.

But Evelyn will not die just once. Until Aiden – one of the guests summoned to Blackheath for the party – can solve her murder, the day will repeat itself, over and over again. Every time ending with the fateful pistol shot.

The only way to break this cycle is to identify the killer. But each time the day begins again, Aiden wakes in the body of a different guest. And someone is determined to prevent him from ever escaping Blackheath...', 480, null, 2001, 1708426, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Parade of Horribles', 'Matt Dinniman', '9798217190065', 'https://assets.hardcover.app/edition/32462067/40a20ed0-0786-4425-b775-0af66472e853.jpg', 'As chaos and mass panic spread outside the dungeon in the wake of Faction Wars, Carl and Donut find themselves on the tenth floor, where they’re forced to compete in a surprisingly normal set of tasks. Well, normal for the dungeon.

Races. Get from point A to point B, and don’t come in last. After each race, they pick an upgrade for their vehicle and the track gets more challenging. It all seems a little too normal, a little too simple.

Ignore those strange glitches that are occurring with increasing frequency. Don’t listen to those whispers about what’s happening on the mysterious eleventh floor, something the system AI calls A Parade of Horribles. Nobody, not even the showrunners, knows what that means. Just that the AI has ominously dubbed it “a coming-out party for the ages.”

Everything is fine, Crawler. I repeat, everything is fine.

Carl hates that it’s business as usual. The rules of this floor have taken away his agency. That just will not do.

So Carl is planning a party of his own. It’s a plan so dangerous, so insane, he can’t even consult his friends lest the AI put a stop to it. Because if it goes wrong, it’s not just the end of Carl and Donut. No. The stakes are higher than they’ve ever been.', 688, null, 2026, 1817542, (select id from series where hardcover_id = 12717), 8) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Monk and Robot', 'Becky Chambers', '8412661710', 'https://assets.hardcover.app/edition/32029216/f5cbdd15-260e-4136-9d89-9238a411b32d.jpg', 'Becky Chambers'' two award-winning, bestselling, beloved, and uplifting Monk and Robot stories, A Psalm for the Wild-Built and A Prayer for the Crown-Shy, together in trade paperback for the first time! Becky Chambers'' delightful, post-Utopian, Hugo Award-winning series gives us hope for the future. It''s been centuries since the robots of Panga gained self-awareness and laid down their tools; centuries since they wandered, en masse, into the wilderness, never to be seen again; centuries since they faded into myth and urban legend. One day, the life of a tea monk is upended by the arrival of a robot, there to honor the old promise of checking in. The robot cannot go back until the question of "what do people need?" is answered. But the answer to that question depends on who you ask, and how. They''re going to need to ask it a lot. Becky Chambers'' series asks: in a world where people have what they want, does having more matter? This book includes both A Psalm for the Wild-Built and A Prayer for the Crown-Shy in paperback for the first time!', 304, null, 2023, 1888706, (select id from series where hardcover_id = 62841), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Operation Bounce House', 'Matt Dinniman', '0241804043', 'https://assets.hardcover.app/edition/32676767/2d125cce-af17-447e-8a57-7dabbd18933f.jpg', 'All colonist Oliver Lewis ever wanted to do was run the family ranch with his sister, maybe play a gig or two with his band, and keep his family’s aging fleet of intelligent agriculture bots ticking as long as possible. He figures it will be a good thing when the transfer gate finally opens all the way and restores instant travel and full communication between Earth and his planet, New Sonora. But there’s a complication.

Even though the settlers were promised they’d be left in peace, Earth’s government now has other plans. The colossal Apex Industries is hired to commence an “eviction action.” But maximizing profits will always be Apex’s number one priority. Why spend money printing and deploying AI soldiers when they can turn it into a game? Why not charge bored Earthers for the opportunity to design their own war machines and remotely pilot them from the comfort of their homes?

The game is called Operation Bounce House.

Oliver and his friends soon find themselves fighting for their lives against machines piloted by gamers who’ve paid a premium for the privilege. With the help of an old book from his grandfather and a bucket of rusty parts, Oliver is determined to defend the only home he’s ever known.', 445, null, 2026, 1896373, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Six of Crows', 'Leigh Bardugo', '1432896938', 'https://assets.hardcover.app/edition/30399477/8fbcdad6-5240-4e0e-9eb5-b691b0745f01.jpg', 'Ketterdam: a bustling hub of international trade where anything can be had for the right price–and no one knows that better than criminal prodigy Kaz Brekker. Kaz is offered a chance at a deadly heist that could make him rich beyond his wildest dreams. But he can’t pull it off alone…

A convict with a thirst for revenge.
A sharpshooter who can’t walk away from a wager.
A runaway with a privileged past.
A spy known as the Wraith.
A Heartrender using her magic to survive the slums.
A thief with a gift for unlikely escapes.

Six dangerous outcasts. One impossible heist. Kaz’s crew is the only thing that might stand between the world and destruction—if they don’t kill each other first.', 480, 904, 2015, 1898835, (select id from series where hardcover_id = 1061), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Origin', 'Dan Brown', '0525563695', 'https://assets.hardcover.app/editions/24692174/8509515428193068.jpeg', 'Robert Langdon, Harvard professor of symbology, arrives at the ultramodern Guggenheim Museum Bilbao to attend the unveiling of a discovery that “will change the face of science forever.” The evening’s host is Edmond Kirsch, a forty-year-old billionaire and futurist, and one of Langdon’s first students.

But the meticulously orchestrated evening suddenly erupts into chaos, and Kirsch’s precious discovery teeters on the brink of being lost forever. Facing an imminent threat, Langdon is forced to flee. With him is Ambra Vidal, the elegant museum director who worked with Kirsch. They travel to Barcelona on a perilous quest to locate a cryptic password that will unlock Kirsch’s secret.

Navigating the dark corridors of hidden history and extreme re­ligion, Langdon and Vidal must evade an enemy whose all-knowing power seems to emanate from Spain’s Royal Palace. They uncover clues that ultimately bring them face-to-face with Kirsch’s shocking discovery . . . and the breathtaking truth that has long eluded us.', 461, null, 2013, 1938541, (select id from series where hardcover_id = 1084), 5) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Perfume', 'Patrick Süskind, John E. Woods - translator, Nigel Patterson', '8850215150', 'https://assets.hardcover.app/editions/31881611/8694740378727077.jpg', 'An erotic masterpiece of twentieth century fiction - a tale of sensual obsession and bloodlust in eighteenth century Paris ''An astonishing tour de force both in concept and execution'' Guardian In eighteenth-century France there lived a man who was one of the most gifted and abominable personages in an era that knew no lack of gifted and abominable personages. His name was Jean-Baptiste Grenouille, and if his name has been forgotten today. It is certainly not because Grenouille fell short of those more famous blackguards when it came to arrogance, misanthropy, immorality, or, more succinctly, wickedness, but because his gifts and his sole ambition were restricted to a domain that leaves no traces in history: to the fleeting realm of scent . . . ''A fantastic tale of murder and twisted eroticism controlled by a disgusted loathing of humanity . .. Clever, stylish, absorbing and well worth reading'' Literary Review ''A meditation on the nature of death, desire and decay . . . A remarkable début'' Peter Ackroyd, The New York Times Book Review ''Unlike anything else one has read. A phenomenon . . . [It] will remain unique in contemporary literature'' Figaro ''An ingenious and totally absorbing fantasy'' Daily Telegraph ''Witty, stylish and ferociously absorbing'' Observer', null, null, 1985, 2010782, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Strange Case of Dr Jekyll and Mr Hyde', 'Robert Louis Stevenson, Richard Armitage', '2501008804', 'https://assets.hardcover.app/edition/31705400/3df6290d-08ca-4623-b676-6c953c648f80.jpg', 'Set in the backdrop later Victorian London, this book can be told as belonging to the category of science fiction, psychological thriller and suspense thriller. Dr Jekyll, a famous and notable scientist seems to be somehow linked with Mr Hyde, a most-wanted criminal. Mr Utterson, a good renown lawyer of the period as well as Jekyll''s good friend, tries connecting the dots to find out the truth, a most-shocking truth.', null, null, 1886, 2332122, (select id from series where hardcover_id = 201493), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights with Monsters', 'Shirtaloon', '1774248182', 'https://assets.hardcover.app/edition/31147086/61e5f0383ff5f3a1805e5f1c41041d28d3c72a62.jpeg', 'Survive an alternate universe and jump into the first installment of the witty and magic-fueled HE WHO FIGHTS WITH MONSTERS series—now with a bonus short story exclusive to this deluxe hardcover edition.

What’s it like to wake up in a mysterious world of magic and monsters?

It’s not easy.

For Jason, making the career jump from office-supplies-store middle manager to heroic interdimensional adventurer is surreal. Jason tries to be heroic, but it''s hard to be good when all your powers are evil.

He’ll face off against cannibals, cultists, wizards, monsters...and that’s just on the first day.

Jason’s a stranger in a strange land, and if he’s going to survive, he’ll have to find something inside himself he never knew was there.

He’s going to need courage, he’s going to need wit, and he’s going to need some magic powers of his own. But first, he’s going to need pants.', 678, 1736, 2021, 2371526, (select id from series where hardcover_id = 12723), 1) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hobbit, or There and Back Again', 'J.R.R. Tolkien', '5170267096', 'https://assets.hardcover.app/edition/17456445/d34448a9-bf3f-441d-93f2-1cd32dd3867c.jpg', '<i>"In a hole in the ground there lived a hobbit." </i>So begins one of the most beloved and delightful tales in the English language. Set in the imaginary world of Middle-earth, at once a classic myth and a modern fairy tale, The Hobbit is one of literature''s most enduring and well-loved high fantasy novels.

Bilbo Baggins is a hobbit who enjoys a comfortable, unambitious life, rarely traveling any farther than his pantry or cellar. But his contentment is disturbed when the wizard Gandalf and a company of dwarves arrive on his doorstep one day to whisk him away on an adventure. They have launched a plot to raid the treasure hoard guarded by Smaug the Magnificent, a large and very dangerous dragon. 

Bilbo reluctantly joins their epic quest, unaware that on his journey to the Lonely Mountain he will encounter both a magic ring and a frightening creature known as Gollum.', 320, 684, 1937, 2459845, null, null) on conflict (hardcover_id) do nothing;
